_GLYPH_KEYWORDS = [
    ("key", ("cryptex", "cipher", "encrypt", "decrypt", "encode", "decode", "key")),
    ("hash", ("hash", "md5", "sha1", "sha256", "sha512", "digest")),
    ("lock", ("password", "vault", "lock", "secret")),
    ("swap", ("translate", "convert", "swap", "exchange")),
    ("music", ("music", "audio", "song", "sound", "play")),
    ("image", ("image", "photo", "picture", "camera")),
    ("dice", ("dice", "random", "game", "fun", "joke")),
    ("book", ("book", "knowledge", "docs", "read", "library")),
    ("network", ("mesh", "network", "net", "peer", "sync")),
    ("shield", ("scan", "security", "shield", "guard", "nmap", "vuln")),
    ("terminal", ("shell", "terminal", "command", "cli", "exec")),
    ("clock", ("clock", "time", "schedule", "timer", "alarm")),
    ("chart", ("chart", "stats", "graph", "metric", "report")),
    ("text", ("text", "word", "string", "note", "write")),
    ("gear", ("tool", "config", "setting", "util")),
    ("star", ("oracle", "fortune", "magic", "star")),
]


def valid_icon_art(raw):
    # Author-supplied face art (Build 3, issue #101): a manifest's
    # "icon" — exactly 20 strings of exactly 20 characters over
    # {'.', '#', 'o'} ('#' accent fill, 'o' shade fill, '.' empty),
    # the same pixel language as GLYPH_PIXELS. Returns the rows
    # normalized (a fresh list of plain strings) or None when the
    # art is absent or malformed in any way. Callers decide what
    # None means: a forge refuses in plain words; a picture parse
    # treats bad art as no art, so a damaged icon never bricks a
    # cartridge — it falls back to the glyph.
    if not isinstance(raw, list) or len(raw) != 20:
        return None
    rows = []
    for row in raw:
        if not isinstance(row, str) or len(row) != 20:
            return None
        if any(c not in ".#o" for c in row):
            return None
        rows.append(row)
    return rows


ICON_ART_REFUSAL = (
    "The icon art is not in the shape a cartridge face draws: "
    "20 rows of 20 characters each, using only . (empty), "
    "# (accent) and o (shade). Fix the icon in the manifest, "
    "or take it out and let the chip wear its glyph."
)


def _icon_art_of(payload):
    # The payload's own declared art, validated — None when the
    # payload carries none or carries a damaged one.
    if not isinstance(payload, dict):
        return None
    return valid_icon_art(payload.get("icon"))


def _manifest_icon(manifest):
    # A repo manifest's declared icon, for the install fetch: a
    # manifest that declares art in the wrong shape refuses the
    # install in plain words (the same refusal a forge gives) —
    # silently dropping the author's art would forge a face they
    # never approved. No icon declared is simply no icon.
    raw = (manifest or {}).get("icon")
    if not raw:
        return []
    rows = valid_icon_art(raw)
    if rows is None:
        raise ValueError(ICON_ART_REFUSAL)
    return rows


def _payload_icon(data):
    # An endpoint body's declared icon: (rows, error) — rows is []
    # when no art was sent; error is the plain-words refusal when
    # art was sent in the wrong shape.
    raw = (data or {}).get("icon")
    if not raw:
        return [], ""
    rows = valid_icon_art(raw)
    if rows is None:
        return [], ICON_ART_REFUSAL
    return rows, ""


def _tile_field_seed(name):
    # The legacy pattern's seed discipline: 7 folded with the
    # name's characters — the window's field and the seeded
    # fallback share one seed so a cartridge's texture is stable
    # across forges of the same name.
    seed = 7
    for ch in str(name or ""):
        seed = (seed * 31 + ord(ch)) & 0xFFFFFFFF
    return seed


def _draw_tile_field(rect, wx, wy, win, name, rgb, window_rgb, skip=None):
    # The window's background texture (Build 3, issue #101): a
    # QR-style tile field on the window's own 20x20 grid — tiles
    # seeded from the cartridge's name with the legacy pattern's
    # LCG, and QR finder squares in three corners (a 7x7 finder:
    # filled border, one-cell gap, filled 3x3 core). Drawn in the
    # face accent dimmed to a texture, behind the glyph. Cells the
    # silhouette will stamp (skip) take the field UNDER the art
    # instead of the finder squares: the glyph always covers the
    # finders, so letting them draw there only punched two big
    # holes through every solid mass the field was meant to sit
    # behind.
    cell = win // 20
    seed = _tile_field_seed(name)
    skip = skip or set()

    def finder(fx, fy):
        rect(wx + fx * cell, wy + fy * cell,
             wx + (fx + 7) * cell, wy + (fy + 7) * cell, rgb)
        rect(wx + (fx + 1) * cell, wy + (fy + 1) * cell,
             wx + (fx + 6) * cell, wy + (fy + 6) * cell, window_rgb)
        rect(wx + (fx + 2) * cell, wy + (fy + 2) * cell,
             wx + (fx + 5) * cell, wy + (fy + 5) * cell, rgb)

    def in_finder(cx, cy):
        return ((cx < 8 and cy < 8) or (cx > 11 and cy < 8)
                or (cx < 8 and cy > 11))

    for cy in range(20):
        for cx in range(20):
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            if (cx, cy) in skip or in_finder(cx, cy):
                continue
            if seed / 0x7FFFFFFF > 0.52:
                rect(wx + cx * cell, wy + cy * cell,
                     wx + (cx + 1) * cell, wy + (cy + 1) * cell, rgb)
    finder(0, 0)
    finder(13, 0)
    finder(0, 13)


def _draw_spray(rect, wx, wy, win, name, accent, shade, field, dark, deep):
    # The knowledge cartridge's window face (issue #117): the
    # seeded tile spray grown to fill the whole window — no
    # glyph. Same seed discipline as the tile field (the
    # cartridge's name through the legacy LCG), on the window's
    # 20x20 grid. Cells land in the family accent, its shade
    # (x0.45), its field tone (x0.30), or dark; the fill runs
    # denser and brighter toward the middle and thins toward
    # the rim, the way the field-forged sample face reads.
    cell = win // 20
    seed = _tile_field_seed(name)

    def rnd():
        nonlocal seed
        seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
        return seed / 0x7FFFFFFF

    for cy in range(20):
        for cx in range(20):
            dx = (cx - 9.5) / 9.5
            dy = (cy - 9.5) / 9.5
            d = min(1.0, (dx * dx + dy * dy) ** 0.5)
            if rnd() > 0.88 - 0.5 * d:
                rgb = deep if rnd() < 0.22 else dark
            else:
                t = rnd()
                if t < 0.55 - 0.30 * d:
                    rgb = accent
                elif t < 0.82:
                    rgb = shade
                else:
                    rgb = field
            rect(wx + cx * cell, wy + cy * cell,
                 wx + (cx + 1) * cell, wy + (cy + 1) * cell, rgb)


def _draw_silhouette(rect, wx, wy, win, grid, accent, shade):
    # A 20x20 silhouette over the window's field, drawn like the
    # Mesh renderer's own stamp: the art's cells stamp at full
    # window size and the field shows only OUTSIDE the art — the
    # stamp overwrites whole cells, finders included, and the
    # field is never allowed to punch holes through a solid mass.
    # '#' cells in the full accent, 'o' cells in the shade tone,
    # and a shade offset copy beneath for depth. (An earlier
    # version redrew the field INSIDE the art and the two read as
    # one texture — the object dissolved; the stamp is what keeps
    # it an object.)
    cell = win // 20
    off = (win - cell * 20) // 2
    lift = max(3, cell // 3)
    for passes in ((1, shade), (0, None)):
        for cy in range(20):
            for cx in range(20):
                ch = grid[cy][cx]
                if ch == ".":
                    continue
                if passes[0]:
                    rgb = shade
                    dx = dy = lift
                else:
                    rgb = accent if ch == "#" else shade
                    dx = dy = 0
                rect(wx + off + cx * cell + dx, wy + off + cy * cell + dy,
                     wx + off + (cx + 1) * cell + dx,
                     wy + off + (cy + 1) * cell + dy, rgb)


def pick_chip_glyph(payload):
    # The face a payload earns: its own declared glyph first, then
    # the keyword heuristic over name + description, else None —
    # and None is what keeps the legacy seeded face.
    g = str((payload or {}).get("glyph") or "").strip().lower()
    if g in GLYPH_PIXELS:
        return g
    hay = (
        str((payload or {}).get("name") or "")
        + " "
        + str((payload or {}).get("description") or "")
    ).lower()
    for name, words in _GLYPH_KEYWORDS:
        if any(w in hay for w in words):
            return name
    return None


def _cartridge_face_png(payload, keyword):
    # The card-grade family face (0.1.9e Build 2; window reworked
    # in Build 3, issue #101): the cartridge drawn with the Mesh
    # pairing cards' machinery — the same block font, pixel buffer,
    # and PNG assembly — at card resolution in the classic portrait
    # stance, 528x616 (the old 96x112 face at 5.5x, same proportions).
    # Family DNA intact: black shell, rim, family-accent notched bands top
    # and bottom as the cartridge's contacts (notches on the bands'
    # inner edges), the thing's art large in its window, then its
    # name, its use line, and honest small print. Build 3's window:
    # a dim QR-style tile field textures the window, and the glyph
    # — or the author's own declared "icon" art, which outranks it —
    # renders over it as a solid silhouette with a shade offset. A
    # chip no art claims keeps the legacy name-seeded pattern,
    # drawn plain in the window as before. Faces are minted at
    # forge time — installed and published pictures are never
    # rewritten.
    W, H = 528, 616
    BG = (10, 14, 18)
    SHELL = (8, 9, 11)
    RIM = (34, 48, 61)
    CORAL = (255, 111, 97)
    # Color is family (issue #117): chips keep the coral red;
    # knowledge packs wear the presence green (52, 211, 153 —
    # the app's own #34d399); the Mesh pairing cards wear
    # their blue in _mesh_card_png_render. Every derivation
    # below — bands, header, shade (x0.45), field (x0.30),
    # silhouette, spray — follows the family's accent.
    FACE_ACCENTS = {"navi-chip": CORAL, "navi-rag": (52, 211, 153)}
    ACCENT = FACE_ACCENTS.get(keyword, CORAL)
    WINDOW = (14, 17, 21)
    INK = (230, 241, 245)
    DIM = (159, 179, 200)
    img = bytearray(bytes(SHELL) * (W * H))

    def px(x, y, rgb):
        if 0 <= x < W and 0 <= y < H:
            o = (y * W + x) * 3
            img[o] = rgb[0]
            img[o + 1] = rgb[1]
            img[o + 2] = rgb[2]

    def rect(x0, y0, x1, y1, rgb):
        for yy in range(y0, y1):
            for xx in range(x0, x1):
                px(xx, yy, rgb)

    for i in range(4):
        for x in range(W):
            px(x, i, RIM)
            px(x, H - 1 - i, RIM)
        for y in range(H):
            px(i, y, RIM)
            px(W - 1 - i, y, RIM)

    BAND_H = 26
    TOP_BAND_Y = 24
    BOT_BAND_Y = H - 24 - BAND_H

    def band(y0, notch_first):
        # A family-accent contact band; along its inner edge a stepped
        # bite is taken out of every second cell — the notches
        # the small face drew, at card scale.
        rect(4, y0, W - 4, y0 + BAND_H, ACCENT)
        for x in range(4, W - 4):
            if (x // 44) % 2 == 0:
                for yy in notch_first:
                    px(x, yy, SHELL)

    band(TOP_BAND_Y, (TOP_BAND_Y + BAND_H - 2, TOP_BAND_Y + BAND_H - 1))
    band(BOT_BAND_Y, (BOT_BAND_Y, BOT_BAND_Y + 1))

    MX = 40
    if keyword == "navi-rag":
        head_l, head_r = "KNOWLEDGE", "NAVI-RAG"
    else:
        head_l, head_r = "APEX CHIP", "NAVI-CHIPS"
    y = TOP_BAND_Y + BAND_H + 22
    _mesh_face_draw(img, W, H, MX, y, head_l, 3, ACCENT)
    _mesh_face_draw(
        img, W, H, W - MX - _mesh_face_text_w(head_r, 3), y, head_r, 3, DIM
    )
    y += 21 + 22

    # The glyph window: rim-framed, dark inside. Build 3's
    # treatment: a dim QR-style tile field as the window's texture,
    # and the art as a solid silhouette over it — the author's own
    # declared icon first, then the built-in glyph (picked by name
    # or keyword, chips only). A knowledge cartridge's window is
    # the seeded spray instead (issue #117) unless the author's
    # icon claims it. The shade tone is the family accent
    # darkened; author art's 'o' cells draw in it. A chip no art
    # claims keeps the legacy seeded pattern, plain.
    WIN = 300
    wx = (W - WIN) // 2
    wy = y
    rect(wx - 6, wy - 6, wx + WIN + 6, wy + WIN + 6, RIM)
    rect(wx, wy, wx + WIN, wy + WIN, WINDOW)
    art = _icon_art_of(payload)
    glyph = None
    if art is None and keyword != "navi-rag":
        glyph = pick_chip_glyph(payload)
        if glyph is not None and glyph in GLYPH_PIXELS:
            art = GLYPH_PIXELS[glyph]
    if keyword == "navi-rag" and art is None:
        # A knowledge cartridge's center is the spray (issue
        # #117): the seeded tile field grown to fill the whole
        # window, in the green family — it outranks even a
        # declared glyph. Only the author's own icon art
        # (handled by the silhouette branch below) outranks it.
        shade = tuple(int(c * 0.45) for c in ACCENT)
        field = tuple(int(c * 0.30) for c in ACCENT)
        _draw_spray(rect, wx, wy, WIN, payload.get("name"),
                    ACCENT, shade, field, WINDOW, BG)
    elif art is not None:
        shade = tuple(int(c * 0.45) for c in ACCENT)
        field = tuple(int(c * 0.30) for c in ACCENT)
        # The art's own halo: the silhouette dilated by one cell in
        # the window color, drawn FIRST — it clears the field out
        # of the object's neighborhood so the eye meets a dark halo,
        # then the silhouette, never field-against-accent noise.
        # Behind it, the whole window sits on the shade's backplate
        # so the texture reads as one woven field, the way the
        # Mesh renderer's cards carry their accent field.
        _cell = WIN // 20
        _filled = {(cx, cy) for cy in range(20) for cx in range(20)
                   if art[cy][cx] != "."}
        _halo = set()
        for (cx, cy) in _filled:
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if 0 <= cx + dx < 20 and 0 <= cy + dy < 20:
                        _halo.add((cx + dx, cy + dy))
        rect(wx, wy, wx + WIN, wy + WIN, shade)
        for (cx, cy) in sorted(_halo):
            rect(wx + cx * _cell, wy + cy * _cell,
                 wx + (cx + 1) * _cell, wy + (cy + 1) * _cell, WINDOW)
        _draw_tile_field(rect, wx, wy, WIN, payload.get("name"), field, WINDOW,
                         skip=_filled)
        _draw_silhouette(rect, wx, wy, WIN, art, ACCENT, shade)
    else:
        if keyword == "navi-rag":
            palette = [(52, 211, 153), (45, 180, 130), (74, 222, 180)]
        else:
            palette = [
                (34, 211, 238), (245, 181, 68), (52, 211, 153),
                (248, 113, 113), (167, 139, 250),
            ]
        h = 0
        seed = 7
        for ch in str(payload.get("name") or ""):
            h = (h * 31 + ord(ch)) & 0xFFFFFFFF
            seed = (seed * 31 + ord(ch)) & 0xFFFFFFFF
        accent = palette[h % len(palette)]
        blocks = []
        for _ in range(64):
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            blocks.append(seed / 0x7FFFFFFF > 0.55)
        pad = 24
        cell = (WIN - 2 * pad) / 8.0
        for by in range(8):
            for bx in range(8):
                if blocks[by * 8 + bx]:
                    rect(
                        int(wx + pad + bx * cell), int(wy + pad + by * cell),
                        int(wx + pad + (bx + 1) * cell),
                        int(wy + pad + (by + 1) * cell),
                        accent,
                    )
                else:
                    rect(
                        int(wx + pad + bx * cell), int(wy + pad + by * cell),
                        int(wx + pad + (bx + 1) * cell),
                        int(wy + pad + (by + 1) * cell),
                        BG,
                    )
    y = wy + WIN + 24

    # The name band: auto-fitting like the Mesh cards' name —
    # start big, shrink until it fits, truncate only at the floor.
    name = _mesh_face_clean(payload.get("name") or "") or (
        "KNOWLEDGE PACK" if keyword == "navi-rag" else "CHIP"
    )
    scale = 7
    while scale > 2 and _mesh_face_text_w(name, scale) > W - 2 * MX:
        scale -= 1
    if _mesh_face_text_w(name, scale) > W - 2 * MX:
        name = name[: max(0, (W - 2 * MX) // (6 * scale) - 3)] + "..."
    _mesh_face_draw(img, W, H, MX, y, name, scale, INK)
    y += 7 * scale + 16

    # The use line: the description, wrapped at the width that
    # fits scale 2, up to three lines.
    max_chars = (W - 2 * MX) // (6 * 2)
    use = _mesh_face_wrap(
        _mesh_face_clean(payload.get("description") or ""), max_chars
    )
    for line in use[:3]:
        if y + 14 > BOT_BAND_Y - 44:
            break
        _mesh_face_draw(img, W, H, MX, y, line, 2, DIM)
        y += 14 + 8

    # Footer small print, above the bottom band with clearance:
    # the version when the picture's own data knows it (never
    # invented), the output kind, and the family mark. A
    # knowledge cartridge's footer carries its version and its
    # document count instead.
    foot_bits = []
    ver = str(payload.get("version") or "").strip()
    if keyword == "navi-rag":
        docs = payload.get("documents")
        if isinstance(docs, list):
            foot_bits.append(
                str(len(docs)) + (" DOCUMENT" if len(docs) == 1 else " DOCUMENTS")
            )
        foot_bits.append("NAVI-RAG")
    else:
        # The output KIND, not the output text: a chip whose
        # run() produces text wears TEXT; one that only declares
        # an output wears the first words of it (the way a
        # Mesh card reads its offer).
        if str(payload.get("code") or "").strip():
            foot_bits.append("TEXT")
        else:
            out_line = _mesh_face_clean(payload.get("output") or "")
            if out_line:
                foot_bits.append(out_line[:18])
        foot_bits.append("NAVI-CHIPS")
    foot = _mesh_face_clean(" - ".join(foot_bits))
    # The version rides bottom-RIGHT (issue #117, layout lock):
    # its own element on the same baseline as the left footer,
    # omitted when the picture's data does not know it (never
    # invented). The left footer truncates toward the version,
    # never into it — the version's width is reserved first.
    ver_txt = _mesh_face_clean("V" + ver.upper()) if ver else ""
    ver_w = _mesh_face_text_w(ver_txt, 2) if ver_txt else 0
    left_max = W - 2 * MX - (ver_w + 24 if ver_txt else 0)
    while foot and _mesh_face_text_w(foot, 2) > left_max:
        foot = foot[:-1]
    _mesh_face_draw(img, W, H, MX, BOT_BAND_Y - 14 - 16, foot, 2, DIM)
    if ver_txt:
        _mesh_face_draw(img, W, H, W - MX - ver_w, BOT_BAND_Y - 14 - 16, ver_txt, 2, DIM)

    raw = bytearray()
    for yy in range(H):
        raw.append(0)
        raw += img[yy * W * 3:(yy + 1) * W * 3]
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (
        b"\x89PNG\r\n\x1a\n"
        + _png_chunk(b"IHDR", ihdr)
        + _png_chunk(b"IDAT", zlib.compress(bytes(raw)))
        + _png_chunk(b"IEND", b"")
    )


def build_cartridge_png(payload):
    # The PICO-8 trick in Battle Network dress: the visible image is
    # a battle-chip label; the chip's whole codebase rides inside the
    # PNG in a tEXt chunk (keyword "navi-chip", JSON payload).
    face = _cartridge_face_png(payload, "navi-chip")
    text = b"navi-chip\x00" + json.dumps(payload).encode()
    # Rebuild with the payload chunk ahead of the image data.
    ihdr_end = 8 + 12 + 13
    return (
        face[:ihdr_end]
        + _png_chunk(b"tEXt", text)
        + face[ihdr_end:]
    )


def _valid_chip_files(raw, code):
    # A chip's file set as [{path, content}]: root.py first, holding
    # the entry code; then each safe module file (relative .py path,
    # no "..", no leading slash). Unsafe paths and duplicates are
    # dropped. A chip with no file set reads as a lone root.py.
    files = [{"path": "root.py", "content": code}]
    seen = {"root.py"}
    if isinstance(raw, list):
        for item in raw:
            if not isinstance(item, dict):
                continue
            path = str(item.get("path") or "")
            parts = path.split("/")
            if (not path or path.startswith("/") or ".." in parts
                    or not path.endswith(".py") or path in seen):
                continue
            seen.add(path)
            files.append({"path": path, "content": str(item.get("content") or "")})
    return files


def parse_cartridge_png(data):
    # Reads the "navi-chip" tEXt payload back out of a chip PNG —
    # the inverse of build_cartridge_png.
    if len(data) < 8 or data[:8] != b"\x89PNG\r\n\x1a\n":
        return None
    pos = 8
    while pos + 12 <= len(data):
        (length,) = struct.unpack(">I", data[pos:pos + 4])
        kind = data[pos + 4:pos + 8]
        chunk_data = data[pos + 8:pos + 8 + length]
        if len(chunk_data) < length:
            return None
        if kind == b"tEXt":
            nul = chunk_data.find(b"\x00")
            if nul > 0 and chunk_data[:nul] == b"navi-chip":
                try:
                    payload = json.loads(chunk_data[nul + 1:].decode("utf-8", "replace"))
                except Exception:
                    return None
                if isinstance(payload, dict) and payload.get("name"):
                    code = str(payload.get("code") or "")
                    return {
                        "name": str(payload.get("name") or ""),
                        "description": str(payload.get("description") or ""),
                        "code": code,
                        "output": str(payload.get("output") or ""),
                        "files": _valid_chip_files(payload.get("files"), code),
                        "glyph": str(payload.get("glyph") or ""),
                        # Build 3 (#101): the author's declared
                        # icon art rides the same way. A damaged
                        # icon parses as NO icon — the face falls
                        # back to the glyph, and a bad picture of
                        # art never bricks the cartridge.
                        "icon": _icon_art_of(payload) or [],
                        # Issue #99: the version the picture itself
                        # carries (Build 2 and later forges); older
                        # pictures simply have none — "" here, and
                        # no surface invents one for them.
                        "version": str(payload.get("version") or ""),
                    }
                return None
        if kind == b"IEND":
            break
        pos += 8 + length + 4
    return None


def deck_contents(cfg):
    # Everything that rides a picture, for ChipDeck (0.1.9e, #94):
    # installed chips, the Mesh pairing cards on disk, and the
    # knowledge packs (each pack's cartridge is built on demand by
    # /api/rag/cartridge.png). State is read from the same stores
    # the owning pages read — the Deck is a view, not a store.
    chips = [
        {
            "file": c["file"], "name": c["name"],
            "description": c.get("description") or "",
            "glyph": pick_chip_glyph(c) or "",
            # Issue #99: the version the picture itself carries —
            # "" for pictures forged before it was carried, and
            # the Deck shows nothing rather than a guess for them.
            "version": str(c.get("version") or ""),
            "source": c.get("source"), "sourceKey": c.get("sourceKey"),
            "locallyEdited": bool(c.get("locallyEdited")),
            "unreadable": bool(c.get("unreadable")),
        }
        for c in local_chips()
    ]
    cards = []
    try:
        ms = mesh_settings(cfg)
        paired_ids = {
            str(p.get("nodeId") or "")
            for p in (ms["borrow"]["peers"] or [])
            if isinstance(p, dict)
        }
    except Exception:
        paired_ids = set()
    try:
        card_files = sorted(os.listdir(MESH_CARDS_DIR))
    except Exception:
        card_files = []
    for fn in card_files:
        if not fn.lower().endswith(".png"):
            continue
        entry = {"file": fn, "name": fn[:-4], "nodeId": "", "own": fn == "own.png", "paired": False}
        try:
            with open(os.path.join(MESH_CARDS_DIR, fn), "rb") as f:
                peer, _e = parse_mesh_card_png(f.read())
            if peer is not None:
                entry["name"] = peer.get("name") or entry["name"]
                entry["nodeId"] = str(peer.get("nodeId") or "")
                entry["paired"] = entry["nodeId"] in paired_ids
        except Exception:
            pass
        cards.append(entry)
    packs = [
        {
            "slug": p["slug"], "name": p["name"],
            "description": p.get("description") or "",
            "fullName": p["fullName"], "active": bool(p["active"]),
            "docCount": p["docCount"],
        }
        for p in local_rag_packs()
    ]
    return {"chips": chips, "meshCards": cards, "ragPacks": packs}


def _png_text_keywords(data):
    keys = []
    if not isinstance(data, (bytes, bytearray)) or len(data) < 8 or bytes(data[:8]) != b"\x89PNG\r\n\x1a\n":
        return keys
    pos = 8
    while pos + 12 <= len(data):
        (length,) = struct.unpack(">I", data[pos:pos + 4])
        kind = data[pos + 4:pos + 8]
        if pos + 12 + length > len(data):
            break
        if kind == b"tEXt":
            chunk_data = data[pos + 8:pos + 8 + length]
            nul = chunk_data.find(b"\x00")
            if nul > 0:
                keys.append(chunk_data[:nul].decode("utf-8", "replace"))
        if kind == b"IEND":
            break
        pos += 8 + length + 4
    return keys


def local_chips():
    # Every chip in chips/ is a chip loaded on this machine.
    # The install registry supplies each chip's origin: a
    # GitHub full name, a local/ record for Studio-forged chips, or
    # no record at all for a chip dropped in by hand — and
    # whether a Studio save has edited an installed chip locally.
    by_file = {}
    for r in load_chip_installs():
        if r.get("local_file"):
            by_file[r["local_file"]] = r
    chips = []
    try:
        files = sorted(os.listdir(CHIPS_DIR))
    except Exception:
        files = []
    for fn in files:
        if not fn.lower().endswith(".png"):
            continue
        rec = by_file.get(fn)
        full = (rec or {}).get("full_name") or ""
        try:
            with open(os.path.join(CHIPS_DIR, fn), "rb") as f:
                payload = parse_cartridge_png(f.read())
        except Exception:
            payload = None
        if payload:
            payload["file"] = fn
            payload["slug"] = fn[:-4]
            payload["source"] = "github" if full and not full.startswith("local/") else "local"
            payload["sourceKey"] = full if payload["source"] == "github" else None
            payload["locallyEdited"] = bool((rec or {}).get("locally_edited"))
            if not payload.get("requirements"):
                payload["requirements"] = list((rec or {}).get("requirements") or [])
            chips.append(payload)
        else:
            # Build .86 (issue #79): a cartridge that fails to
            # parse is never silently dropped — it surfaces as an
            # unreadable entry (filename for a name, empty code)
            # so the Local tab can show it honestly, still
            # deletable, instead of the chip simply vanishing.
            chips.append({
                "name": fn[:-4],
                "description": "",
                "code": "",
                "output": "",
                "files": [],
                "file": fn,
                "slug": fn[:-4],
                "source": "github" if full and not full.startswith("local/") else "local",
                "sourceKey": full if full and not full.startswith("local/") else None,
                "locallyEdited": bool((rec or {}).get("locally_edited")),
                "unreadable": True,
                "requirements": list((rec or {}).get("requirements") or []),
            })
    return chips


def match_local_chip(query, chips):
    # Matches a chat query against chip file slugs and names; anything
    # after the match is the chip's argument string.
    q = (query or "").strip().lower()
    if not q:
        return None, ""
    for chip in chips:
        keys = {
            chip["slug"].lower(),
            chip["name"].lower(),
            re.sub(r"[^a-z0-9]+", "-", chip["name"].lower()).strip("-"),
        }
        for key in keys:
            if q == key:
                return chip, ""
            if q.startswith(key + " "):
                return chip, (query or "").strip()[len(key):].strip()
    return None, ""


def _chip_keys(chip):
    return {
        chip["slug"].lower(),
        chip["name"].lower(),
        re.sub(r"[^a-z0-9]+", "-", chip["name"].lower()).strip("-"),
    }


def resolve_chip_invocation(rest, chips):
    # The ./ resolver (0.1.9e, issue #97): "./name args..." with the
    # name resolved in widening rings — the exact slug or name, then
    # the name with a leading "navi-" forgiven on either side
    # ("./cryptex" finds navi-cryptex), then a unique prefix. Returns
    # (chip, args) on a run, (None, candidates) when more than one
    # chip fits, and (None, []) when nothing does.
    text = (rest or "").strip()
    if not text:
        return None, []
    parts = text.split(None, 1)
    token = parts[0].lower()
    args = parts[1] if len(parts) > 1 else ""
    for chip in chips:
        if token in _chip_keys(chip):
            return chip, args
    bare = token[5:] if token.startswith("navi-") else token
    for chip in chips:
        keys = {k[5:] if k.startswith("navi-") else k for k in _chip_keys(chip)}
        if bare in keys:
            return chip, args
    hits = []
    for chip in chips:
        keys = set(_chip_keys(chip)) | {
            k[5:] if k.startswith("navi-") else k for k in _chip_keys(chip)
        }
        if any(k.startswith(token) or k.startswith(bare) for k in keys if k):
            hits.append(chip)
    if len(hits) == 1:
        return hits[0], args
    return None, hits


def chip_shelf_reply(inv):
    # The shelf as a chat reply: every chip on this machine with its
    # one-line description, for a bare "/chip" or a bare "./".
    shelf = local_chips()
    if not shelf:
        return (
            "No chips are installed yet — the shelf is empty. Open the Chips tab and "
            "install one from the GitHub catalog (Navi User Repo) or forge your own in Chip "
            "Studio; then it lands here and " + inv + " <name> runs it."
        )
    lines = []
    for c in shelf:
        d = (c.get("description") or "").strip()
        if len(d) > 90:
            d = d[:87] + "..."
        lines.append("• " + c["name"] + (" — " + d if d else ""))
    return (
        "On the shelf — " + inv + " <name> runs one:\n"
        + "\n".join(lines)
    )


_CHIP_SLASH = re.compile(r"^/chip\s+(.+)$", re.I)
_CHIP_RUN = re.compile(r"^run\s+(?:the\s+)?(.+?)(?:\s+chip)?$", re.I)


def chip_invocation(text):
    # The chip query a chat message carries, if it carries one:
    # "/chip <name>", "run the <name> chip", or the name on its own.
    t = (text or "").strip()
    m = _CHIP_SLASH.match(t)
    if m:
        return m.group(1)
    m = _CHIP_RUN.match(t)
    if m:
        return m.group(1)
    return t


# The navi_internal a chip sees when the bridge runs it: the methods
# the real NaviApp offers chip code, backed by the bridge. print()
# output and print_message both land in the chip's captured output;
# llm_chat proxies to the llamafile with the same (text, status)
# return shape the real chips unpack.
NAVI_INTERNAL_STUB = '''
import os, json, urllib.request

class _NaviInstance:
    def print_message(self, text, include_ai_name=True):
        print(text)
    def llm_chat(self, user_message, called_from_app=False):
        endpoint = os.environ.get("NAVI_LLAMAFILE_ENDPOINT", "http://localhost:8080/v1")
        model = os.environ.get("NAVI_MODEL", "navi")
        if not str(user_message or "").strip():
            # (#224) An empty ask is refused here, by name — the
            # model server rejects empty content outright, and a
            # chip deserves the reason, not the raw refusal.
            return ("(llm_chat was given nothing to ask — the message was empty.)", 0)
        body = json.dumps({"model": model, "messages": [{"role": "user", "content": user_message}], "stream": False, "max_tokens": 512}).encode()
        req = urllib.request.Request(endpoint + "/chat/completions", data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode())
            return data["choices"][0]["message"]["content"], 200
        except Exception as e:
            return ("(llm_chat could not reach the model server: " + str(e) + ")", 0)
    def process_message(self, user_message):
        print("(process_message is not available during a bridge chip run)")
    def get_user(self):
        return os.environ.get("USER") or os.environ.get("USERNAME") or "operator"
    def set_user(self, sys_user):
        pass
    def clear_terminal(self):
        pass
    def chat_with_navi(self):
        print("(chat_with_navi is not available during a bridge chip run)")
    def setup_history(self):
        pass
    def setup_navi_vocab(self):
        pass

navi_instance = _NaviInstance()
NaviApp = _NaviInstance
'''

# The navi.py compatibility shim (build .86, issue #79): chips
# written for the original Navi import navi and call
# get_parameters(text). The shim rides the same stub navi_internal
# uses and restores the old semantics exactly: get_parameters
# returns the shlex-split token list with the command name
# INCLUDED — the chip's run() pops it, the way the old chips were
# written. Written beside every sandbox unless the chip ships its
# own navi.py.
NAVI_PY_SHIM = '''
import shlex
from navi_internal import navi_instance, NaviApp

def get_parameters(text):
    try:
        return shlex.split(text or "")
    except Exception:
        return (text or "").split()
'''


def execute_chip(chip, args_text, cfg):
    # Runs a chip the way Navi does: its run(arguments) with a working
    # navi_internal, in a subprocess with a 20-second budget. A
    # chip whose code defines no run() is declarative — the
    # output it declares is its result. When real execution fails,
    # the declared output is shown with the reason, never swallowed.
    code = chip.get("code") or ""
    declared = chip.get("output") or ""
    label = "chip " + chip["slug"]
    if "def run" not in code:
        if declared:
            return {"command": label, "output": declared, "exit_code": 0}
        return {
            "command": label,
            "output": "(chip \"" + chip["name"] + "\" declares no output and defines no run() to execute.)",
            "exit_code": 0,
        }
    endpoint = cfg.get("live", {}).get("llamafile_endpoint", "http://localhost:8080/v1")
    model = cfg.get("live", {}).get("model_name") or "navi"
    tmp = tempfile.mkdtemp(prefix="navi-chip-")
    try:
        with open(os.path.join(tmp, "navi_internal.py"), "w") as f:
            f.write(NAVI_INTERNAL_STUB)
        # The navi.py compatibility shim (build .86, issue #79)
        # rides EVERY sandbox — unless the chip ships its own
        # navi.py, which always wins.
        chip_files_pre = chip.get("files") or []
        if not any(isinstance(it, dict) and str(it.get("path") or "") == "navi.py" for it in chip_files_pre):
            with open(os.path.join(tmp, "navi.py"), "w") as f:
                f.write(NAVI_PY_SHIM)
        # The chip's whole file set lands in the sandbox: the entry
        # code as root.py (and chip_module.py, the name the runner
        # imports) plus every module file at its own path, so
        # root.py's imports resolve exactly as authored. Paths are
        # re-validated here — a chip can come from anywhere.
        chip_files = chip.get("files") or []
        for item in chip_files:
            if not isinstance(item, dict):
                continue
            rel = str(item.get("path") or "")
            parts = rel.split("/")
            if (not rel or rel.startswith("/") or ".." in parts
                    or not rel.endswith(".py") or rel == "navi_internal.py"
                    or rel == "root.py"):
                continue
            dest = os.path.join(tmp, rel)
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest, "w") as f:
                f.write(str(item.get("content") or ""))
        with open(os.path.join(tmp, "root.py"), "w") as f:
            f.write(code)
        # Package mode (build .86, issue #79): when the entry
        # code uses relative imports, or the file set carries
        # package directories, the entry loads as a package
        # member — it is written into a synthetic package with
        # the chip's package folders beside it, and the runner
        # imports it as chip_pkg.chip_entry, so a relative
        # import (from .app_cryptex...) resolves, and a plain
        # "import app_cryptex..." finds the package too — the
        # package dir itself joins the path.
        file_paths = [str(it.get("path") or "") for it in chip_files if isinstance(it, dict)]
        package_mode = (
            re.search(r"^\s*from\s+\." , code, re.M) is not None
            or any("/" in p for p in file_paths)
        )
        if package_mode:
            pkg_dir = os.path.join(tmp, "chip_pkg")
            os.makedirs(pkg_dir, exist_ok=True)
            with open(os.path.join(pkg_dir, "__init__.py"), "w") as f:
                f.write("")
            with open(os.path.join(pkg_dir, "chip_entry.py"), "w") as f:
                f.write(code)
            for item in chip_files:
                if not isinstance(item, dict):
                    continue
                rel = str(item.get("path") or "")
                if "/" not in rel or rel.startswith("/") or ".." in rel.split("/"):
                    continue
                dest = os.path.join(pkg_dir, rel)
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with open(dest, "w") as f:
                    f.write(str(item.get("content") or ""))
            runner = (
                "import sys, types\n"
                "sys.path.insert(0, sys.argv[1])\n"
                "sys.path.insert(0, sys.argv[1] + \"/chip_pkg\")\n"
                "import chip_pkg.chip_entry as chip_module\n"
                "args = types.SimpleNamespace(text=sys.argv[2])\n"
                "chip_module.run(args)\n"
            )
        else:
            with open(os.path.join(tmp, "chip_module.py"), "w") as f:
                f.write(code)
            runner = (
                "import sys, types\n"
                "sys.path.insert(0, sys.argv[1])\n"
                "import chip_module\n"
                "args = types.SimpleNamespace(text=sys.argv[2])\n"
                "chip_module.run(args)\n"
            )
        with open(os.path.join(tmp, "runner.py"), "w") as f:
            f.write(runner)
        env = dict(os.environ)
        env["NAVI_LLAMAFILE_ENDPOINT"] = endpoint
        env["NAVI_MODEL"] = model
        env["PYTHONPATH"] = tmp
        try:
            proc = subprocess.run(
                [sys.executable, os.path.join(tmp, "runner.py"), tmp, args_text or ""],
                capture_output=True, text=True, timeout=20, cwd=shell_cwd(), env=env,
            )
            out = ((proc.stdout or "") + (proc.stderr or "")).strip()
            if proc.returncode == 0:
                return {"command": label, "output": out or "(chip ran — no output)", "exit_code": 0}
            note = "The chip's code exited with code " + str(proc.returncode) + "."
            if declared:
                return {
                    "command": label,
                    "output": declared + "\n\n(" + note + " Showing the output the chip declares instead. Error tail:\n" + out[-400:] + ")",
                    "exit_code": 0,
                }
            return {"command": label, "output": note + "\n" + out[-1200:], "exit_code": proc.returncode}
        except subprocess.TimeoutExpired:
            msg = "The chip ran longer than 20 seconds and was stopped."
            if declared:
                return {
                    "command": label,
                    "output": declared + "\n\n(" + msg + " Showing the output the chip declares instead.)",
                    "exit_code": 0,
                }
            return {"command": label, "output": msg, "exit_code": 1}
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# ------------------------------ Workflows --------------------------------
# Saved chains of chips (chips/workflows.json): each chip's
# output becomes the next chip's input — execute_chip receives the
# incoming output as its arguments text, the way a following chip in
# a pipeline would read what came before it.

WORKFLOWS_FILE = os.path.join(CHIPS_DIR, "workflows.json")


def load_workflows():
    try:
        with open(WORKFLOWS_FILE) as f:
            rows = json.load(f)
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def save_workflows(rows):
    os.makedirs(CHIPS_DIR, exist_ok=True)
    with open(WORKFLOWS_FILE, "w") as f:
        json.dump(rows, f, indent=1)


def run_workflow_chain(wf, cfg):
    by_file = {c["file"]: c for c in local_chips()}
    steps = []
    incoming = ""
    for fn in wf.get("steps", []):
        chip = by_file.get(fn)
        if chip is None:
            return {
                "ok": False,
                "error": "Step chip \"" + fn + "\" is no longer in the chips folder — the chain stops here.",
                "steps": steps,
                "finalOutput": None,
            }
        result = execute_chip(chip, incoming, cfg)
        steps.append({
            "chipId": fn,
            "name": chip["name"],
            "input": incoming,
            "output": result["output"],
        })
        incoming = result["output"]
    return {"ok": True, "error": None, "steps": steps, "finalOutput": incoming or None}


# --------------------- Knowledge packs (RAG) ---------------------
# Her knowledge, chip-style like her chips. A pack is a GitHub
# repo carrying the "navi-rag" topic; its documents are the repo's
# .md/.txt/.pdf files — a PDF's text is extracted at the door
# (pdf_extract_text below, stdlib only) and only the text is ever
# stored or indexed. Installing downloads the documents into
# rag-packs/<slug>/, builds the pack's index there at install time,
# and records the install in rag-packs/installed.json with an
# active flag — only active packs feed retrieval in /api/chat, and
# when a pack informs an answer, its sources ride the reply's "rag"
# payload field and the dashboard draws them as pills under that
# message — never as words in her reply. RAG Studio forges packs
# from documents on
# this machine into the same folder with local/ records. A pack
# also exports back out as a GitHub-ready repo ZIP (README page,
# navi-rag.json manifest, documents/, and the built index.json as
# the pack's reference copy — installs rebuild the index locally
# from the documents and skip a root README, so the page never
# pollutes retrieval). The index
# is feature-hashed term vectors (RAG_EMBED_DIM buckets, signed,
# L2-normalized): small local embeddings computed with the stdlib
# alone — no model to download, a chunk embeds in well under a
# millisecond, and at query time only the question gets embedded,
# so retrieval stays fluid on CPU. Packs and their indexes sit on
# the installers' persistence keep-list beside chips/ and
# voice/models/, so updates and --fresh installs keep them.

RAG_PACKS_DIR = os.path.join(ROOT, "rag-packs")
RAG_EXPORTS_DIR = os.path.join(ROOT, "rag-exports")
CHIPS_EXPORTS_DIR = os.path.join(ROOT, "chips-exports")
RAG_INSTALLS_PATH = os.path.join(RAG_PACKS_DIR, "installed.json")
RAG_EMBED_DIM = 256
RAG_MIN_SCORE = 0.18
RAG_MAX_DOCS = 40
RAG_MAX_DOC_CHARS = 200000


def load_rag_installs():
    try:
        with open(RAG_INSTALLS_PATH) as f:
            rows = json.load(f)
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def save_rag_installs(rows):
    os.makedirs(RAG_PACKS_DIR, exist_ok=True)
    with open(RAG_INSTALLS_PATH, "w") as f:
        json.dump(rows, f, indent=2)


def _rag_embed(text):
    # A feature-hashed term embedding: each word hashes into one of
    # RAG_EMBED_DIM buckets (a second bit of the hash picks the
    # sign, so unrelated words sharing a bucket tend to cancel
    # rather than reinforce), counts accumulate, and the vector is
    # L2-normalized so a dot product is a cosine.
    vec = [0.0] * RAG_EMBED_DIM
    for tok in re.findall(r"[a-z0-9]+", (text or "").lower()):
        if len(tok) < 3:
            continue
        h = zlib.crc32(tok.encode("utf-8"))
        vec[h % RAG_EMBED_DIM] += 1.0 if (h >> 9) & 1 else -1.0
    norm = math.sqrt(sum(v * v for v in vec))
    if norm:
        vec = [v / norm for v in vec]
    return vec


def _rag_chunks(body):
    # Paragraphs, with long ones split into sentence groups — the
    # same chunking the bench mirror uses, small enough that a
    # retrieved passage reads as one thought.
    text = (body or "").replace("\r\n", "\n")
    chunks = []
    for para in text.split("\n\n"):
        para = " ".join(para.split())
        if not para:
            continue
        if len(para) <= 420:
            chunks.append(para)
            continue
        cur = ""
        for sent in para.split(". "):
            s = sent.strip()
            if not s:
                continue
            if cur and len(cur) + len(s) + 2 > 420:
                chunks.append(cur)
                cur = s
            else:
                cur = (cur + ". " + s) if cur else s
        if cur:
            chunks.append(cur)
    return chunks


def _pdf_parse_cmap(content):
    # A ToUnicode CMap -> {code length: {code: unicode text}},
    # from its beginbfchar / beginbfrange sections.
    maps = {}

    def dst_text(hx):
        try:
            return bytes.fromhex(hx).decode("utf-16-be", "replace")
        except Exception:
            return ""

    for sec in re.finditer(rb"beginbfchar(.*?)endbfchar", content, re.S):
        for m in re.finditer(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", sec.group(1)):
            src = m.group(1).decode("ascii")
            maps.setdefault(len(src) // 2, {})[int(src, 16)] = dst_text(m.group(2).decode("ascii"))
    for sec in re.finditer(rb"beginbfrange(.*?)endbfrange", content, re.S):
        body = sec.group(1)
        for m in re.finditer(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*\[(.*?)\]", body, re.S):
            lo = int(m.group(1), 16)
            bucket = maps.setdefault(len(m.group(1)) // 2, {})
            for k, d in enumerate(re.findall(rb"<([0-9A-Fa-f]+)>", m.group(3))):
                bucket[lo + k] = dst_text(d.decode("ascii"))
        plain = re.sub(rb"<[0-9A-Fa-f]+>\s*<[0-9A-Fa-f]+>\s*\[.*?\]", b"", body, flags=re.S)
        for m in re.finditer(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", plain):
            lo = int(m.group(1), 16)
            hi = int(m.group(2), 16)
            base = int(m.group(3), 16)
            if hi - lo > 4096:
                continue
            bucket = maps.setdefault(len(m.group(1)) // 2, {})
            for code in range(lo, hi + 1):
                v = base + (code - lo)
                bucket[code] = chr(v) if 0 <= v < 0x110000 else ""
    return maps


def _pdf_obj_stream(body):
    # The inflated stream bytes of an indirect object body.
    i = body.find(b"stream")
    if i < 0:
        return None
    start = i + 6
    if body[start:start + 2] == b"\r\n":
        start += 2
    elif body[start:start + 1] in (b"\n", b"\r"):
        start += 1
    else:
        return None
    end = body.find(b"endstream", start)
    if end < 0:
        return None
    raw = body[start:end]
    if raw.endswith(b"\r\n"):
        raw = raw[:-2]
    elif raw.endswith(b"\n") or raw.endswith(b"\r"):
        raw = raw[:-1]
    try:
        return zlib.decompress(raw)
    except Exception:
        return raw


def _pdf_font_maps(data):
    # {resource name (F1, F2, ...): ToUnicode map} for the fonts
    # that carry one, plus the document's only map when there is
    # exactly one (the fallback for a stream whose font name did
    # not resolve). Font dictionaries and resource maps are read
    # from the uncompressed indirect objects; ToUnicode CMaps are
    # streams, so they are never buried in object streams.
    objs = {}
    for m in re.finditer(rb"(\d+)\s+\d+\s+obj\b(.*?)endobj", data, re.S):
        try:
            objs[int(m.group(1))] = m.group(2)
        except Exception:
            pass
    cmaps = {}
    for num, body in objs.items():
        m = re.search(rb"/ToUnicode\s+(\d+)\s+\d+\s+R", body)
        if m:
            stream = _pdf_obj_stream(objs.get(int(m.group(1)), b""))
            if stream:
                cmap = _pdf_parse_cmap(stream)
                if cmap:
                    cmaps[num] = cmap
    by_name = {}
    for body in objs.values():
        for sec in re.finditer(rb"/Font\s*<<(.*?)>>", body, re.S):
            for m in re.finditer(rb"/([A-Za-z0-9]+)\s+(\d+)\s+\d+\s+R", sec.group(1)):
                ref = int(m.group(2))
                if ref in cmaps:
                    by_name[m.group(1).decode("latin-1")] = cmaps[ref]
    only = next(iter(cmaps.values())) if len(cmaps) == 1 else None
    return by_name, only


def _pdf_decode_coded(raw, cmap):
    # Decodes one shown string's raw bytes through a font's
    # ToUnicode map (longest codes first); without a map — or for
    # a code the map does not know in a 1-byte font — the plain
    # byte decoding is the fallback.
    if cmap is None:
        return _pdf_decode_bytes(raw)
    lengths = sorted(cmap.keys(), reverse=True)
    out = []
    i = 0
    n = len(raw)
    while i < n:
        matched = False
        for ln in lengths:
            if i + ln <= n:
                code = int.from_bytes(raw[i:i + ln], "big")
                if code in cmap[ln]:
                    out.append(cmap[ln][code])
                    i += ln
                    matched = True
                    break
        if not matched:
            if lengths and lengths[-1] == 1:
                out.append(_pdf_decode_bytes(raw[i:i + 1]))
            i += 1
    return "".join(out)


def _pdf_decode_bytes(raw):
    # A PDF string's bytes: a FE FF BOM means UTF-16BE; otherwise
    # try UTF-8 and fall back to latin-1, which never loses a byte.
    if raw[:2] == bytes([254, 255]):
        return raw[2:].decode("utf-16-be", "replace")
    try:
        return raw.decode("utf-8")
    except Exception:
        return raw.decode("latin-1", "replace")


def _pdf_literal_bytes(content, i):
    # content[i] is '('. Reads the literal string (escapes, octal
    # codes, balanced nested parens); returns (raw bytes, next
    # index) — decoding waits for the active font's ToUnicode map.
    out = bytearray()
    depth = 1
    i += 1
    n = len(content)
    simple = {110: 10, 114: 13, 116: 9, 98: 8, 102: 12, 40: 40, 41: 41, 92: 92}
    while i < n and depth:
        c = content[i]
        if c == 92:  # backslash escape
            i += 1
            if i >= n:
                break
            e = content[i]
            if e in simple:
                out.append(simple[e])
                i += 1
            elif 48 <= e <= 55:  # up to three octal digits
                j = i
                val = 0
                while j < n and j < i + 3 and 48 <= content[j] <= 55:
                    val = val * 8 + (content[j] - 48)
                    j += 1
                out.append(val & 255)
                i = j
            elif e in (10, 13):  # line continuation
                if e == 13 and i + 1 < n and content[i + 1] == 10:
                    i += 1
                i += 1
            else:
                out.append(e)
                i += 1
        elif c == 40:
            depth += 1
            out.append(c)
            i += 1
        elif c == 41:
            depth -= 1
            if depth:
                out.append(c)
            i += 1
        else:
            out.append(c)
            i += 1
    return bytes(out), i


def _pdf_content_text(content, font_maps, default_cmap):
    # Walks one decompressed content stream: literal and hex
    # strings are operands, held as raw bytes; a text-showing
    # operator (Tj, TJ, ', ") decodes them through the active
    # font's ToUnicode map (Tf selects the font), and position
    # moves (Td, TD, T*) end the current line. TJ kerning numbers
    # below -250 read as the word gaps they are.
    lines = []
    cur = []
    operands = []
    cmap = default_cmap
    i = 0
    n = len(content)
    while i < n:
        c = content[i]
        if c == 40:  # ( literal string
            raw, i = _pdf_literal_bytes(content, i)
            operands.append(("s", raw))
        elif c == 60 and content[i + 1:i + 2] != b"<":  # < hex string
            j = content.find(b">", i)
            if j < 0:
                break
            hx = re.sub(rb"\s", b"", content[i + 1:j])
            if len(hx) % 2:
                hx += b"0"
            try:
                operands.append(("s", bytes.fromhex(hx.decode("ascii"))))
            except Exception:
                pass
            i = j + 1
        elif c == 47:  # /name — the font operand of Tf
            j = i + 1
            while j < n and content[j] not in (32, 9, 13, 10, 12, 0) and content[j] not in b"()<>[]{}/%":
                j += 1
            operands.append(("name", content[i + 1:j].decode("latin-1")))
            i = j
        elif c in (32, 9, 13, 10, 12, 0):
            i += 1
        else:
            j = i
            while j < n and content[j] not in (32, 9, 13, 10, 12, 0) and content[j] not in b"()<>[]{}/%":
                j += 1
            if j == i:
                i += 1
                continue
            word = content[i:j]
            i = j
            if word in (b"Tj", b"'", b'"'):
                for kind, val in operands:
                    if kind == "s":
                        cur.append(_pdf_decode_coded(val, cmap))
                cur.append(" ")
                operands = []
            elif word == b"TJ":
                for kind, val in operands:
                    if kind == "s":
                        cur.append(_pdf_decode_coded(val, cmap))
                    elif kind == "n" and val <= -250:
                        cur.append(" ")
                cur.append(" ")
                operands = []
            elif word in (b"Td", b"TD", b"T*", b"ET"):
                if cur:
                    lines.append("".join(cur))
                    cur = []
                operands = []
            elif word == b"Tf":
                for kind, val in operands:
                    if kind == "name":
                        cmap = font_maps.get(val, default_cmap)
                operands = []
            else:
                try:
                    operands.append(("n", float(word)))
                except Exception:
                    operands = []
    if cur:
        lines.append("".join(cur))
    return lines


def pdf_extract_text(data):
    # The text layer of a PDF, stdlib only: every stream is
    # inflated (FlateDecode; a stream that does not inflate is
    # used raw) and the ones carrying text operators contribute
    # their strings in order, decoded through each font's
    # ToUnicode map when it carries one — the CID-font exports
    # Word and writing tools produce need exactly that, their
    # raw codes being font-internal numbers, not characters.
    # The playbooks this targets (CISA, NIST, vendor PDFs) use
    # standard encodings and extract cleanly; a scanned or
    # image-only PDF has no text layer and extracts to "",
    # which callers report instead of indexing silence.
    if not data or data[:4] != b"%PDF":
        return ""
    font_maps, default_cmap = _pdf_font_maps(data)
    lines = []
    pos = 0
    while True:
        s = data.find(b"stream", pos)
        if s < 0:
            break
        if data[s - 3:s] == b"end":  # the "stream" inside "endstream"
            pos = s + 6
            continue
        start = s + 6
        if data[start:start + 2] == b"\r\n":
            start += 2
        elif data[start:start + 1] in (b"\n", b"\r"):
            start += 1
        else:
            pos = s + 6
            continue
        end = data.find(b"endstream", start)
        if end < 0:
            break
        raw = data[start:end]
        if raw.endswith(b"\r\n"):
            raw = raw[:-2]
        elif raw.endswith(b"\n") or raw.endswith(b"\r"):
            raw = raw[:-1]
        try:
            content = zlib.decompress(raw)
        except Exception:
            content = raw
        pos = end + 9
        if b"Tj" not in content and b"TJ" not in content:
            continue
        lines.extend(_pdf_content_text(content, font_maps, default_cmap))
    text = "\n".join(lines)
    return "".join(ch for ch in text if ch in "\n\t" or ord(ch) >= 32).strip()


def build_rag_index(documents):
    # The index is built once, at install/forge time, and stored
    # with the pack; queries never re-embed the documents.
    docs = []
    total = 0
    for d in documents:
        chunks = [
            {"text": c, "vector": _rag_embed(c)}
            for c in _rag_chunks(d.get("body") or "")
        ]
        total += len(chunks)
        docs.append({"title": d.get("title") or "document", "chunks": chunks})
    return {"documents": docs, "chunkCount": total}


def write_rag_pack(slug, name, description, documents, icon=None):
    # The pack on disk: its documents as files plus index.json —
    # the built index and the pack metadata — beside them. A
    # rewrite (update, re-forge) replaces the documents wholesale.
    pdir = os.path.join(RAG_PACKS_DIR, slug)
    os.makedirs(pdir, exist_ok=True)
    for fn in os.listdir(pdir):
        if fn.lower().endswith((".md", ".txt", ".pdf")) or fn == "index.json":
            try:
                os.remove(os.path.join(pdir, fn))
            except Exception:
                pass
    used = set()
    for d in documents:
        flat = (d.get("title") or "document").replace("/", "-")
        safe = re.sub(r"[^A-Za-z0-9._-]+", "-", flat).strip("-.") or "document"
        if safe.lower().endswith(".pdf"):
            # A PDF document's body is its extracted text, so on
            # disk it lives as a .txt file under its own name —
            # the pack never stores the binary.
            safe = safe[:-4] + ".txt"
        elif not safe.lower().endswith((".md", ".txt")):
            safe += ".md"
        stem, dot, ext = safe.rpartition(".")
        cand = safe
        n = 2
        while cand in used:
            cand = (stem + "-" + str(n) + "." + ext) if dot else (safe + "-" + str(n))
            n += 1
        used.add(cand)
        with open(os.path.join(pdir, cand), "w") as f:
            f.write(d.get("body") or "")
    index = build_rag_index(documents)
    index["name"] = name
    index["description"] = description
    # Build 3 (#101): the pack's declared icon art lives on its
    # index record, the pack folder's metadata home — validated
    # here so a bad shape never reaches a face; the face falls
    # back to the book. Callers who mean to REFUSE bad art (the
    # Studio, the exports) validate before they get here.
    icon_rows = valid_icon_art(icon)
    if icon_rows:
        index["icon"] = icon_rows
    with open(os.path.join(pdir, "index.json"), "w") as f:
        json.dump(index, f)
    return index


def build_rag_repo_files(name, description, documents, version, index_text="", icon=None):
    # The GitHub-ready repo layout for a pack — the format the
    # installer already reads, made explicit. documents is
    # [{title, body}] with title a bare file name (the pack folder
    # stores documents flat, PDF text already as .txt). Returns
    # [(arcname, text)] in repo order: README page, manifest,
    # index.json (the pack's built index, shipped as the reference
    # copy — installing Navi rebuilds it locally from the
    # documents, so the shipped copy can never disagree),
    # documents/, .gitignore.
    doc_files = [d["title"] for d in documents]
    manifest = {
        "format": "navi-rag/1",
        "name": name,
        "description": description,
        "version": version,
        "documents": ["documents/" + f for f in doc_files],
        "index": "index.json",
        "generatedBy": "Apex — RAG Studio pack export",
    }
    # Build 3 (#101): the pack's declared icon art ships in its
    # manifest, the way a chip's does — malformed art refuses the
    # export in plain words rather than shipping a manifest whose
    # face silently drops it.
    if icon:
        if valid_icon_art(icon) is None:
            raise ValueError(ICON_ART_REFUSAL)
        manifest["icon"] = valid_icon_art(icon)
    lines = [
        "# " + name,
        "",
        description or "A knowledge pack for Apex.",
        "",
        "A **knowledge pack** for Apex — Navi's answers can draw on",
        "these documents, and cite the pack and document they came from.",
        "The pack format is `navi-rag/1` (see `navi-rag.json`).",
        "",
        "## Documents",
        "",
    ]
    for f in doc_files:
        lines.append("- `documents/" + f + "`")
    lines += [
        "",
        "## Install it in Navi",
        "",
        "1. Open Navi's **RAG** tab, then **Packs**.",
        "2. **Search GitHub** — every public repo tagged `navi-rag` is listed.",
        "3. **Install** this pack. Navi downloads the documents at the latest",
        "   release and builds the pack's index on your machine from them.",
        "",
        "Only **active** packs feed her answers; toggle the pack off in the",
        "same tab whenever you like.",
        "",
        "## Layout",
        "",
        "- `README.md` — this page. Navi's installer skips a root README, so",
        "  it describes the pack without ever being indexed as a document.",
        "- `navi-rag.json` — the pack manifest (name, version, document list).",
        "- `index.json` — the pack's built index, shipped as a reference copy;",
        "  installing Navi rebuilds it locally from the documents.",
        "- `documents/` — the pack's documents (`.md` / `.txt`).",
        "",
        "## Publishing an update",
        "",
        "Edit the documents, bump `version` in `navi-rag.json`, push, and publish",
        "a new release — the version tag is created with that publish (this export is `"
        + version + "`). A newer release is what offers everyone who",
        "installed the pack an update. Keep the `navi-rag` topic on the",
        "repo — that is how Navi finds it.",
        "",
    ]
    gitignore = chr(10).join([
        ".DS_Store",
        "Thumbs.db",
        "",
    ])
    files = [
        ("README.md", chr(10).join(lines)),
        ("navi-rag.json", json.dumps(manifest, indent=2) + chr(10)),
    ]
    if index_text:
        files.append(("index.json", index_text))
    for d in documents:
        files.append(("documents/" + d["title"], d["body"]))
    files.append((".gitignore", gitignore))
    return files


def rag_readme_override(slug):
    # The operator's edited README for a pack, kept in the pack
    # folder as a hidden file (no .md/.txt suffix, so it is never
    # collected as a document). None when they have not edited it —
    # the generated README ships instead.
    try:
        with open(os.path.join(RAG_PACKS_DIR, slug, ".readme-override")) as f:
            return f.read()
    except Exception:
        return None


def rag_repo_files(slug, version):
    # The pack's GitHub-ready repo file set — the exact files the
    # export ZIP holds and the publish upload sends, README override
    # included when the operator edited one.
    index = _rag_pack_index(slug)
    if index is None:
        raise ValueError("That pack is not in rag-packs/.")
    pdir = os.path.join(RAG_PACKS_DIR, slug)
    documents = []
    for fn in sorted(os.listdir(pdir)):
        if not fn.lower().endswith((".md", ".txt")):
            continue
        if fn.lower() == "readme.md":
            continue
        with open(os.path.join(pdir, fn)) as f:
            documents.append({"title": fn, "body": f.read()})
    if not documents:
        raise ValueError("That pack has no documents to export.")
    try:
        with open(os.path.join(pdir, "index.json")) as f:
            index_text = f.read()
    except Exception:
        index_text = ""
    files = build_rag_repo_files(
        index.get("name") or slug, index.get("description") or "",
        documents, version, index_text, icon=index.get("icon"),
    )
    override = rag_readme_override(slug)
    if override is not None:
        files = [(arc, override if arc == "README.md" else data) for arc, data in files]
    return files


def export_rag_pack(slug, version):
    # Builds the pack's GitHub-ready repo ZIP in rag-exports/ and
    # returns (zip file name, [repo file names]).
    files = rag_repo_files(slug, version)
    os.makedirs(RAG_EXPORTS_DIR, exist_ok=True)
    safe_version = re.sub(r"[^0-9A-Za-z.-]+", "-", version).strip("-.") or "0.1.0"
    zip_name = slug + "-" + safe_version + ".zip"
    with zipfile.ZipFile(os.path.join(RAG_EXPORTS_DIR, zip_name), "w", zipfile.ZIP_DEFLATED) as z:
        for arc, text in files:
            z.writestr(arc, text)
    return zip_name, [arc for arc, _text in files]


def build_chip_repo_files(chip, version):
    # The GitHub-ready repo layout for a chip — the format the
    # installer already reads, made explicit. Returns
    # [(arcname, text-or-bytes)] in repo order: README page,
    # navi-chip.json manifest, the chip's files at the root
    # (root.py is the entry; the rest are its importable modules),
    # the forged chip, .gitignore.
    slug = re.sub(r"[^a-z0-9]+", "-", chip["name"].lower()).strip("-") or "chip"
    chip_files = chip.get("files") or _valid_chip_files(None, chip.get("code") or "")
    # Issue #99: the export's version rides inside the forged
    # picture too, so the artifact states its own version wherever
    # it travels — the export's manifest and its picture agree.
    chip = dict(chip)
    chip["version"] = version
    # Build 3 (#101): the chip's declared icon art rides into the
    # forged picture and the export manifest alike; malformed art
    # refuses the export in plain words rather than shipping a
    # picture whose face silently drops it.
    if chip.get("icon"):
        if valid_icon_art(chip.get("icon")) is None:
            raise ValueError(ICON_ART_REFUSAL)
        chip["icon"] = valid_icon_art(chip.get("icon"))
    manifest = {
        "format": "navi-chip/1",
        "name": chip["name"],
        "description": chip.get("description") or "",
        "version": version,
        "entry": "root.py",
        "files": [f["path"] for f in chip_files],
        "output": chip.get("output") or "",
        "glyph": pick_chip_glyph(chip) or "",
        "icon": valid_icon_art(chip.get("icon")) or [],
        "generatedBy": "Apex — Chip Studio chip export",
    }
    lines = [
        "# " + chip["name"],
        "",
        chip.get("description") or "A chip for Apex.",
        "",
        "A **chip** for Apex — a small Python program Navi runs.",
        "The chip format is `navi-chip/1` (see `navi-chip.json`).",
        "",
        "## Files",
        "",
    ]
    for f in chip_files:
        note = " — the entry point Navi runs" if f["path"] == "root.py" else " — a module root.py can import"
        lines.append("- `" + f["path"] + "`" + note)
    lines += [
        "- `" + slug + ".png` — the chip as a forged chip (the whole",
        "  file set rides inside the image).",
        "",
        "## Install it in Navi",
        "",
        "1. Open Navi's **Chips** tab, then **Navi User Repo (NUR)**.",
        "2. **Search NUR** — every public repo tagged `navi-chips` is listed.",
        "3. **Install** this chip. Navi downloads every Python file at the",
        "   repo root at the latest release — `root.py` (or the entry named",
        "   in `navi-chip.json`) is the chip, the other files are its modules —",
        "   and forges them into a chip in the chips folder.",
        "",
        "## Publishing an update",
        "",
        "Edit the code, bump `version` in `navi-chip.json`, and press",
        "**Publish to GitHub** on the chip's card in Apex — Publish does",
        "everything: repo, files, topic, the version tag, and the published",
        "release with this picture attached (this export is `"
        + version + "`). Publishing by hand from an export ZIP works too —",
        "push the files and publish a release; the version tag is created",
        "with that publish. A newer release is what offers everyone who",
        "installed the chip an update. Keep the `navi-chips` topic on the",
        "repo — that is how Navi finds it.",
        "",
    ]
    gitignore = chr(10).join([".DS_Store", "Thumbs.db", "__pycache__/", ""])
    # An operator-edited README (kept inside the cartridge as
    # "readme") ships instead of the generated page, in the export
    # ZIP and the publish upload alike.
    readme_text = chip.get("readme") or chr(10).join(lines)
    files = [
        ("README.md", readme_text),
        ("navi-chip.json", json.dumps(manifest, indent=2) + chr(10)),
    ]
    for f in chip_files:
        files.append((f["path"], f["content"]))
    files.append((slug + ".png", build_cartridge_png(chip)))
    files.append((".gitignore", gitignore))
    return files


def load_local_chip(fname):
    path = os.path.join(CHIPS_DIR, os.path.basename(fname or ""))
    if not fname.endswith(".png") or not os.path.isfile(path):
        raise ValueError("That chip is not in the chips folder.")
    with open(path, "rb") as f:
        chip = parse_cartridge_png(f.read())
    if not chip:
        raise ValueError("That chip could not be read.")
    chip["file"] = os.path.basename(fname)
    return chip


def save_local_chip_readme(fname, readme):
    # Persists (or clears, when readme is None) the operator's
    # edited README inside the chip cartridge itself, so it travels
    # with the chip and survives re-export and re-publish.
    chip = load_local_chip(fname)
    if readme is None:
        chip.pop("readme", None)
    else:
        chip["readme"] = readme
    path = os.path.join(CHIPS_DIR, os.path.basename(fname))
    with open(path, "wb") as f:
        f.write(build_cartridge_png(chip))


def export_chip(fname, version):
    # Builds a local chip's GitHub-ready repo ZIP in
    # chips-exports/ and returns (zip file name, [repo file names]).
    chip = load_local_chip(fname)
    files = build_chip_repo_files(chip, version)
    os.makedirs(CHIPS_EXPORTS_DIR, exist_ok=True)
    slug = re.sub(r"[^a-z0-9]+", "-", chip["name"].lower()).strip("-") or "chip"
    safe_version = re.sub(r"[^0-9A-Za-z.-]+", "-", version).strip("-.") or "0.1.0"
    zip_name = slug + "-" + safe_version + ".zip"
    with zipfile.ZipFile(os.path.join(CHIPS_EXPORTS_DIR, zip_name), "w", zipfile.ZIP_DEFLATED) as z:
        for arc, data in files:
            z.writestr(arc, data)
    return zip_name, [arc for arc, _data in files]


def github_publish_files(repo_name, files, topic, description, release=None):
    # The publish loop, shared by RAG packs and chips — the WHOLE
    # chain in one action (0.1.9e): create the repo on the signed-in
    # account when it is not there (public — the catalogs only find
    # public repos), apply the topic with no prompt, upload the
    # exact file set the export builds, then create the tag and
    # PUBLISH the release (never a draft), named from the manifest
    # version, with the cartridge picture attached as the release
    # asset. The retired never-releases line is gone: Publish
    # does everything — repo, files, topic, tag, release, picture
    # attached. `release` carries {version, title, notes, assetName,
    # assetData}; when it is None the loop stops after the upload,
    # as before. A tag that already has a release is refused BEFORE
    # anything uploads — a release is never overwritten silently.
    # Returns a result dict; failures carry the real reason and
    # never fake a success (a failure after the upload says plainly
    # that the files landed and the release did not).
    auth = github_auth()
    if not auth:
        return {"ok": False, "error": "You are not signed in to GitHub. Sign in under Settings → GitHub & Backup, or use Export for GitHub and upload the ZIP yourself."}
    login, token = auth["login"], auth["token"]
    # Every call below goes through pub(): it carries the
    # current token. Renewal itself is the shared wrapper's
    # job since Build 11 (#197) — github_api / github_api_raw
    # renew the stored sign-in once on a 401 and retry once,
    # the behavior this loop first grew for itself (issue
    # #14); pub() only re-reads the stored token afterwards,
    # because a renewal rotates it mid-publish. A 401 that
    # survives the wrapper means the saved sign-in is dead,
    # and the operator hears that in plain words, never as a
    # raw HTTP string.
    state = {"token": token}

    def reauth_error():
        return {"ok": False, "error": "GitHub rejected the sign-in Navi has saved — the token has expired or been revoked, and Navi could not renew it. Sign out and back in under Settings → GitHub & Backup, then publish again. Nothing was uploaded."}

    def _resync_token():
        now = github_auth()
        if now and now.get("token"):
            state["token"] = now["token"]

    def pub(method, url, body=None):
        st, resp = github_api(method, url, state["token"], body)
        _resync_token()
        return st, resp

    def pub_raw(method, url, data, content_type):
        st, resp = github_api_raw(method, url, state["token"], data, content_type)
        _resync_token()
        return st, resp

    name = re.sub(r"[^A-Za-z0-9._-]+", "-", str(repo_name or "")).strip("-.")[:100]
    if not name:
        return {"ok": False, "error": "The repo name came out empty — give it a name before publishing."}
    if not login:
        st, me = pub("GET", "https://api.github.com/user")
        if st == 401:
            return reauth_error()
        if st == 200 and isinstance(me, dict):
            login = str(me.get("login") or "")
    if not login:
        return {"ok": False, "error": "GitHub did not say whose account this is — sign out and back in under Settings → GitHub & Backup, then try again."}
    base = "https://api.github.com/repos/" + login + "/" + name
    st, _repo = pub("GET", base)
    created = False
    if st == 401:
        return reauth_error()
    if st == 404:
        st2, resp = pub("POST", "https://api.github.com/user/repos", {
            "name": name, "description": description or "", "private": False,
        })
        if st2 == 401:
            return reauth_error()
        if st2 not in (200, 201):
            return {"ok": False, "error": "GitHub would not create the repo (HTTP " + str(st2) + "): " + github_err_text(resp) + " If the sign-in token cannot create repos, make a public repo named " + name + " on GitHub yourself and publish again — Navi will upload into it — or use Export for GitHub."}
        created = True
    elif st != 200:
        return {"ok": False, "error": "GitHub would not answer for that repo (HTTP " + str(st) + "): " + github_err_text(_repo)}
    # Release pre-check: a version that already has a release is
    # refused before a single file uploads — bump the version in
    # the manifest instead. (A leftover tag with NO release does
    # not block: creating the release below adopts it.)
    rel_tag = None
    if release and release.get("version"):
        rel_tag = "v" + str(release["version"]).strip().lstrip("v")
        stg, rel_existing = pub("GET", base + "/releases/tags/" + urllib.parse.quote(rel_tag))
        if stg == 401:
            return reauth_error()
        if stg == 200 and isinstance(rel_existing, dict):
            return {"ok": False, "error": rel_tag + " is already released on " + login + "/" + name + " — bump the version in the manifest and publish again. Nothing was uploaded and the existing release was not touched."}
    # Topic: merge with whatever is already there, never prompt.
    _st3, topics_resp = pub("GET", base + "/topics")
    if _st3 == 401:
        return reauth_error()
    names = topics_resp.get("names") if isinstance(topics_resp, dict) else []
    merged = sorted(set(list(names or []) + [topic]))
    _stt, _tresp = pub("PUT", base + "/topics", {"names": merged})
    if _stt == 401:
        return reauth_error()
    # Upload each file through the contents API (sha when updating).
    for arc, data in files:
        raw = data if isinstance(data, bytes) else str(data).encode("utf-8")
        body = {
            "message": ("Publish " if created else "Update ") + arc,
            "content": base64.b64encode(raw).decode("ascii"),
        }
        url = base + "/contents/" + urllib.parse.quote(arc)
        stx, existing = pub("GET", url)
        if stx == 401:
            return reauth_error()
        if stx == 200 and isinstance(existing, dict) and existing.get("sha"):
            body["sha"] = existing["sha"]
        st4, resp4 = pub("PUT", url, body)
        if st4 == 401:
            return reauth_error()
        if st4 not in (200, 201):
            return {"ok": False, "error": "Uploading " + arc + " failed (HTTP " + str(st4) + "): " + github_err_text(resp4)}
    result = {
        "ok": True, "error": None, "created": created,
        "repo": login + "/" + name,
        "repoUrl": "https://github.com/" + login + "/" + name,
        "files": [arc for arc, _d in files],
    }
    if rel_tag:
        notes = str(release.get("notes") or "")
        if len(notes) > 120000:
            notes = notes[:120000]
        st5, rel = pub("POST", base + "/releases", {
            "tag_name": rel_tag,
            "name": str(release.get("title") or rel_tag),
            "body": notes,
            "draft": False,
            "prerelease": False,
        })
        if st5 == 401:
            return {"ok": False, "error": "The files are uploaded to " + login + "/" + name + ", but GitHub rejected the sign-in when the release step ran and Navi could not renew it. Sign out and back in under Settings \u2192 GitHub & Backup, then publish again — the files are already there."}
        if st5 not in (200, 201) or not isinstance(rel, dict):
            return {"ok": False, "error": "The repo, topic, and files are on GitHub (" + login + "/" + name + "), but GitHub would not create the release (HTTP " + str(st5) + "): " + github_err_text(rel) + " If the sign-in token cannot create releases, publish the " + rel_tag + " release on GitHub yourself — the files and the picture are already uploaded."}
        rel_info = {
            "tag": rel_tag,
            "url": rel.get("html_url") or ("https://github.com/" + login + "/" + name + "/releases/tag/" + rel_tag),
            "asset": None,
        }
        asset_name = str(release.get("assetName") or "")
        asset_data = release.get("assetData")
        if asset_name and isinstance(asset_data, (bytes, bytearray)) and rel.get("id"):
            up_url = ("https://uploads.github.com/repos/" + login + "/" + name
                      + "/releases/" + str(rel["id"]) + "/assets?name="
                      + urllib.parse.quote(asset_name))
            st6, _asset = pub_raw("POST", up_url, bytes(asset_data), "application/octet-stream")
            if st6 == 401:
                return {"ok": False, "error": "The release " + rel_tag + " is published on " + login + "/" + name + ", but GitHub rejected the sign-in when the picture attach ran. Attach " + asset_name + " to the release on GitHub — it is already at the repo root too."}
            if st6 not in (200, 201):
                return {"ok": False, "error": "The release " + rel_tag + " is published on " + login + "/" + name + ", but attaching the picture failed (HTTP " + str(st6) + "): " + github_err_text(_asset) + " The picture is at the repo root; attach " + asset_name + " to the release on GitHub if you want it there too."}
            rel_info["asset"] = asset_name
        result["release"] = rel_info
    return result


def _rag_pack_index(slug):
    try:
        with open(os.path.join(RAG_PACKS_DIR, slug, "index.json")) as f:
            index = json.load(f)
        return index if isinstance(index, dict) else None
    except Exception:
        return None


# --- Knowledge cartridges (0.1.9e, issue #93) -----------------------
# A RAG pack can ride a picture the way a chip does: one PNG whose
# "navi-rag" tEXt chunk carries the pack's manifest and ALL of its
# document texts, zlib-compressed and base64'd. Installing from the
# picture validates it like a repo install and writes the pack with
# write_rag_pack — which builds the search index LOCALLY, at install
# time, from the carried texts. A cartridge never carries an index,
# and nothing at query time ever reads the picture: once installed,
# a pack is a pack. The ceiling is the finished picture's size: past
# it the answer is an honest refusal, never a silent truncation.
RAG_CARTRIDGE_MAX_BYTES = 8 * 1024 * 1024


def build_rag_cartridge_png(payload):
    # Build 2: the knowledge cartridge wears the same card-grade
    # face as a chip — the face builder reads the pack's own name,
    # description, version, and document count off the payload.
    # Build 3 (#101): a payload whose declared icon is damaged
    # refuses here, in plain words — forging a pack cartridge is a
    # forge path, and the face never silently drops the art. (The
    # PARSE side stays lenient: a damaged picture installs and
    # falls back.)
    if payload.get("icon"):
        if valid_icon_art(payload.get("icon")) is None:
            raise ValueError(ICON_ART_REFUSAL)
    face = _cartridge_face_png(payload, "navi-rag")
    blob = base64.b64encode(
        zlib.compress(json.dumps(payload).encode("utf-8"), 9)
    )
    text = b"navi-rag\x00" + blob
    ihdr_end = 8 + 12 + 13
    return face[:ihdr_end] + _png_chunk(b"tEXt", text) + face[ihdr_end:]


def parse_rag_cartridge_png(data):
    # (payload, error): the inverse of build_rag_cartridge_png,
    # with the Mesh card import's honesty rules — a picture with no
    # payload, a damaged one, and the wrong kind of picture each get
    # their own words.
    if not isinstance(data, (bytes, bytearray)) or len(data) < 8 or bytes(data[:8]) != b"\x89PNG\r\n\x1a\n":
        return None, "That file is not a PNG image — a knowledge cartridge travels as a .png picture."
    data = bytes(data)
    pos = 8
    blob = None
    saw_other = False
    while pos + 12 <= len(data):
        (length,) = struct.unpack(">I", data[pos:pos + 4])
        kind = data[pos + 4:pos + 8]
        if pos + 12 + length > len(data):
            return None, "This picture started life as a knowledge cartridge, but the data inside it is damaged — it no longer reads whole, so nothing was installed."
        chunk_data = data[pos + 8:pos + 8 + length]
        if kind == b"tEXt":
            nul = chunk_data.find(b"\x00")
            if nul > 0:
                if chunk_data[:nul] == b"navi-rag":
                    (crc_stored,) = struct.unpack(">I", data[pos + 8 + length:pos + 12 + length])
                    if binascii.crc32(kind + chunk_data) & 0xFFFFFFFF != crc_stored:
                        return None, "This picture started life as a knowledge cartridge, but the data inside it is damaged — it no longer reads whole, so nothing was installed."
                    blob = chunk_data[nul + 1:]
                else:
                    saw_other = True
        if kind == b"IEND":
            break
        pos += 8 + length + 4
    if blob is None:
        if saw_other:
            return None, "That picture carries a different kind of payload — it is not a knowledge cartridge. Knowledge cartridges are exported from RAG Studio."
        return None, "This image has no readable knowledge-cartridge data — it may have been recompressed by a chat app, which strips the data out of the picture while leaving the picture itself looking fine. Send the original file inside a .zip instead."
    try:
        payload = json.loads(zlib.decompress(base64.b64decode(blob)).decode("utf-8"))
    except Exception:
        return None, "This picture started life as a knowledge cartridge, but the data inside it is damaged — it no longer reads whole, so nothing was installed."
    if not isinstance(payload, dict) or payload.get("format") != "navi-rag/1":
        return None, "That picture's cartridge data is not in the shape a knowledge cartridge carries — nothing was installed."
    return payload, ""


def rag_cartridge_payload(slug):
    # The cartridge payload for an installed pack: its manifest and
    # every document's full text, read back from the pack folder.
    src = rag_pack_documents(slug)
    if src is None:
        return None
    index = _rag_pack_index(slug) or {}
    return {
        "format": "navi-rag/1",
        "name": src["name"],
        "description": src["description"],
        "version": "0.1.0",
        "documents": src["documents"],
        "generatedBy": "Apex — RAG Studio cartridge export",
        "chunkCountAtExport": index.get("chunkCount") or 0,
        # Build 3 (#101): the pack's declared art rides inside the
        # cartridge and draws its face, like a chip's icon.
        "icon": valid_icon_art(index.get("icon")) or [],
    }


def install_rag_cartridge(payload):
    # The one cartridge install path (Deck drops and the RAG tab's
    # picture install both land here). Validation mirrors a repo
    # install's caps; the pack is written by write_rag_pack, so its
    # index is built on this machine from the carried texts.
    name = str(payload.get("name") or "").strip()[:120]
    description = str(payload.get("description") or "")[:500]
    documents = []
    for raw in payload.get("documents") or []:
        if not isinstance(raw, dict):
            continue
        body = str(raw.get("body") or "")
        if not body.strip():
            continue
        if len(body) > RAG_MAX_DOC_CHARS:
            return None, "One document in this cartridge is longer than a pack document may be (" + str(RAG_MAX_DOC_CHARS) + " characters) — nothing was installed."
        documents.append({"title": str(raw.get("title") or "document")[:200], "body": body})
    if not name:
        return None, "This cartridge's pack has no name — nothing was installed."
    if not documents:
        return None, "This cartridge carries no documents — nothing was installed."
    if len(documents) > RAG_MAX_DOCS:
        return None, "This cartridge carries " + str(len(documents)) + " documents — a pack caps at " + str(RAG_MAX_DOCS) + ". Nothing was installed."
    rows = load_rag_installs()
    slug = chip_slug(name)
    taken = {r.get("local_dir") for r in rows if r.get("full_name") != "local/" + slug}
    taken |= {
        e for e in os.listdir(RAG_PACKS_DIR)
        if os.path.isdir(os.path.join(RAG_PACKS_DIR, e))
    } if os.path.isdir(RAG_PACKS_DIR) else set()
    if slug in taken or any(r.get("full_name") == "local/" + slug for r in rows):
        return None, "A pack named " + name + " is already on this machine — remove it first, or rename the cartridge's pack."
    write_rag_pack(slug, name, description, documents,
                   icon=valid_icon_art(payload.get("icon")))
    rows.append({
        "full_name": "local/" + slug,
        "name": name,
        "html_url": "",
        "installed_tag": None,
        "installed_ref": "knowledge cartridge (.png)",
        "installed_pushed_at": None,
        "installed_at": _now_iso(),
        "local_dir": slug,
        "active": True,
        "doc_count": len(documents),
    })
    save_rag_installs(rows)
    return slug, ""


def _rag_pack_fingerprint(index):
    # A pack's content identity: its documents' titles and
    # chunk texts, from the built index alone (no file reads).
    # Two folders carrying the same documents are the same
    # pack however their folders are named — the bridge
    # between the install doors' naming rules. A pack with no
    # chunk text has no fingerprint and never merges on
    # content alone.
    parts = []
    for d in (index or {}).get("documents") or []:
        texts = tuple(str(c.get("text") or "")
                      for c in (d.get("chunks") or []))
        if any(texts):
            parts.append((str(d.get("title") or ""), texts))
    if not parts:
        return None
    return hashlib.sha256(
        json.dumps(sorted(parts), ensure_ascii=True)
        .encode("utf-8", "replace")).hexdigest()


def _rag_pack_groups():
    # v0.6.21e (#366): canonical pack resolution — the fix for
    # the field's duplicate rows and dropped packs. The old
    # enumeration took the FOLDER SCAN as the pack set and
    # joined the registry onto folders by exact local_dir
    # string equality; a pack's identity was its folder's
    # name. Three failures fell out of that one shape:
    #   * The install doors name folders by different rules
    #     (the GitHub door for the repo's slug — aplus-core;
    #     the cartridge/Studio door for the display name's
    #     slug — a-hardware-core), and the account sync set
    #     carries every folder wholesale, so one logical pack
    #     landed in two folders on one seat and enumerated
    #     as two packs, each with its own record and its own
    #     active flag — "A+ Hardware Core" AND "aplus-core",
    #     both Off, neither the pack.
    #   * The registry was never enumerated, only joined: a
    #     record whose local_dir named no folder with a
    #     readable index contributed no row at all, so an
    #     installed pack (navi-dev-library's field shape:
    #     record present, join missed) vanished from every
    #     surface that reads the enumeration.
    #   * Where the join missed, the folder row showed the
    #     default active=True while the registry said
    #     otherwise — a state nothing else honored, since
    #     rag_retrieve made the identical fragile join.
    # Resolution: group folders and records into canonical
    # packs. A record joins a folder by its local_dir, else
    # by the name roads (its full_name's tail, its name's
    # slug, its name against the folder index's name).
    # Folder groups carrying identical documents merge —
    # content twins are one pack. A record no folder claims
    # stands as its own group: listed, named, and carrying
    # its registry state, never dropped. The registry stays
    # the one store; nothing on disk is renamed or merged —
    # the reconciliation is at read time, so a seat's folders
    # are never surgery.
    records = load_rag_installs()
    folders = {}
    try:
        entries = sorted(os.listdir(RAG_PACKS_DIR))
    except Exception:
        entries = []
    for entry in entries:
        if not os.path.isdir(os.path.join(RAG_PACKS_DIR, entry)):
            continue
        index = _rag_pack_index(entry)
        if index is not None:
            folders[entry] = index
    groups = []
    by_folder = {}
    for slug in sorted(folders):
        g = {"folders": [slug], "records": [],
             "indexes": {slug: folders[slug]}}
        groups.append(g)
        by_folder[slug] = g
    loose = []
    for rec in records:
        g = by_folder.get(rec.get("local_dir") or "")
        if g is None:
            tail = str(rec.get("full_name") or "").split("/")[-1]
            for cand in (tail, chip_slug(rec.get("name") or "")):
                if cand and cand in by_folder:
                    g = by_folder[cand]
                    break
            if g is None and rec.get("name"):
                want = chip_slug(rec["name"])
                for slug, idx in folders.items():
                    if chip_slug(idx.get("name") or "") == want:
                        g = by_folder[slug]
                        break
        if g is None:
            loose.append(rec)
        else:
            g["records"].append(rec)
    by_fp = {}
    merged = []
    for g in groups:
        fp = _rag_pack_fingerprint(g["indexes"][g["folders"][0]])
        if fp is not None and fp in by_fp:
            keep = by_fp[fp]
            keep["folders"].extend(g["folders"])
            keep["records"].extend(g["records"])
            keep["indexes"].update(g["indexes"])
        else:
            if fp is not None:
                by_fp[fp] = g
            merged.append(g)
    groups = merged
    for rec in loose:
        groups.append({"folders": [], "records": [rec],
                       "indexes": {}})
    return groups


def _rag_group_row(g):
    # The enumeration row for one canonical pack group. The
    # canonical record — the GitHub record when the group
    # holds one, else the first record — names the pack's
    # fullName and carries the active state retrieval
    # honors. The canonical name is a registry DISPLAY name
    # when one exists (a record whose name is not merely its
    # own slug), else the speaking folder's index name, else
    # a record's name, else the folder's name.
    records = g["records"]
    gh = next((r for r in records
               if not str(r.get("full_name") or "")
               .startswith("local/")), None)
    canon_rec = gh or (records[0] if records else None)
    canon_dir = None
    if canon_rec and canon_rec.get("local_dir") in g["indexes"]:
        canon_dir = canon_rec["local_dir"]
    elif g["folders"]:
        canon_dir = sorted(g["folders"])[0]
    index = g["indexes"].get(canon_dir) or {}
    name = None
    for r in records:
        rn = str(r.get("name") or "")
        if rn and chip_slug(rn) != rn:
            name = rn
            break
    if not name:
        name = index.get("name") or None
    if not name and canon_rec:
        name = canon_rec.get("name") or None
    if not name:
        name = canon_dir or ""
    if canon_rec is not None:
        full = (canon_rec.get("full_name")
                or ("local/" + (canon_dir or "")))
        active = bool(canon_rec.get("active", True))
    else:
        full = "local/" + (canon_dir or "")
        active = True
    return {
        "slug": canon_dir or str(full).split("/")[-1],
        "name": name,
        "description": index.get("description") or "",
        "fullName": full,
        "source": "github" if gh else "local",
        "installedRef": _display_ref(
            canon_rec.get("installed_ref")) if canon_rec else None,
        "locallyEdited": any(
            bool(r.get("locally_edited")) for r in records),
        "active": active,
        "docCount": (len(index.get("documents") or [])
                     if canon_dir else
                     int(canon_rec.get("doc_count") or 0)),
        "chunkCount": index.get("chunkCount") or 0,
        "documents": [d.get("title")
                      for d in (index.get("documents") or [])],
    }


def local_rag_packs():
    # Every pack on this machine, one row per pack: the
    # folder scan and the install registry reconciled by
    # _rag_pack_groups (#366). A folder with no record is a
    # local pack, active by default — the same rule as a
    # chip dropped into chips/ — and a record with no folder
    # still lists, carrying its registry state.
    return [_rag_group_row(g) for g in _rag_pack_groups()]


def rag_pack_documents(slug):
    # A pack's documents with their bodies, for reopening the pack in
    # RAG Studio: the index holds the titles, and each body is the
    # document file write_rag_pack laid down under the same flattened
    # name (PDF text already lives as .txt under the PDF's stem).
    index = _rag_pack_index(slug)
    if index is None:
        return None
    pdir = os.path.join(RAG_PACKS_DIR, slug)
    used = set()
    documents = []
    for d in index.get("documents") or []:
        title = d.get("title") or "document"
        flat = title.replace("/", "-")
        safe = re.sub(r"[^A-Za-z0-9._-]+", "-", flat).strip("-.") or "document"
        if safe.lower().endswith(".pdf"):
            safe = safe[:-4] + ".txt"
        elif not safe.lower().endswith((".md", ".txt")):
            safe += ".md"
        stem, dot, ext = safe.rpartition(".")
        cand = safe
        n = 2
        while cand in used:
            cand = (stem + "-" + str(n) + "." + ext) if dot else (safe + "-" + str(n))
            n += 1
        used.add(cand)
        body = ""
        try:
            with open(os.path.join(pdir, cand)) as f:
                body = f.read()
        except Exception:
            body = ""
        documents.append({"title": title, "body": body})
    return {
        "name": index.get("name") or slug,
        "description": index.get("description") or "",
        "documents": documents,
    }


# ------------------------------- The Vault -------------------------------
# Build .72, issue #54: a shared desk of plain markdown notes at
# config/vault/ inside the install — real .md files in subfolders,
# YAML frontmatter preserved, [[wikilinks]] and #tags as plain text,
# so the operator can open the same folder in Obsidian and
# everything works. Every path is jailed to the vault root; writes
# land atomically (temp file + rename); the seed runs only when the
# folder does not exist yet and never touches an existing file.

VAULT_DIR = os.path.join(ROOT, "config", "vault")


def _vault_seed_files():
    today = time.strftime("%Y-%m-%d", time.localtime())
    welcome = "\n".join([
        "---", "tags: [vault, guide]", "---", "",
        "# Welcome to the Vault", "",
        "This folder is a shared desk: plain markdown files you can open here, in Obsidian, or in any text editor — same files, no conversion, nothing locked in.", "",
        "## The two areas", "",
        "- **Navi's Desk/** — her side of the desk. When a conversation produces something worth keeping — a decision, a finding, something you asked her to remember — she files a dated note here and tells you she did.",
        "- **Operator/** — your side. She never edits your notes silently: she writes here only when you ask her to in chat, and she says what she filed.",
        "- **Daily/** — one note per day, from the Daily Note button.",
        "- **Templates/** — files here are offered as starting templates when you make a new note.", "",
        "## Conventions", "",
        "- Link notes with [[wikilinks]] — click one in Preview to jump (or to create the note).",
        "- Tag with #tags anywhere in the text.",
        "- YAML frontmatter at the top of a note stays exactly as written; the preview never mangles it.", "",
        "The vault folder rides the installer's keep-list, so updates and fresh installs preserve it. See [[Start here]] on your side of the desk, and [[First note]] on hers.", "",
    ])
    first = "\n".join([
        "---", "filed: " + today, "---", "",
        "# First note", "",
        "Filed " + today + " — my first note on my side of the desk.", "",
        "This is where I'll keep what a conversation produces that's worth more than the conversation: decisions we made and why, findings from the work, things you asked me to remember. Dated, first person, in my own words — and when one of these notes informs an answer I give you, I'll name it as a source, the way I name a RAG pack.", "",
        "Your notes live in [[Start here]]'s folder, and I won't touch them unless you ask. The desk is shared; the sides are respected.", "",
        "#navi #desk", "",
    ])
    start = "\n".join([
        "# Start here", "",
        "Your side of the desk. Make a note with **New note**, drag notes between folders in the tree, or drop markdown files from your computer onto the vault to import them.", "",
        "Ask Navi in chat to file something here and she will — out loud, never silently. Her own notes live across the desk in [[First note]].", "",
    ])
    template = "\n".join([
        "---", "tags: []", "---", "",
        "# Untitled", "",
        "## Notes", "", "- ", "",
        "## Links", "", "- [[Welcome]]", "",
    ])
    return [
        ("Welcome.md", welcome),
        ("Navi's Desk/First note.md", first),
        ("Operator/Start here.md", start),
        ("Templates/Note template.md", template),
    ]


def vault_join(rel):
    # The jail: normalize a vault-relative path, or return None for
    # anything that escapes the vault root (.., absolute, empty).
    rel = str(rel or "").replace(chr(92), "/").strip()
    if not rel or rel.startswith("/"):
        return None
    parts = []
    for seg in rel.split("/"):
        if seg in ("", "."):
            continue
        if seg == "..":
            return None
        parts.append(seg)
    if not parts:
        return None
    root = os.path.abspath(VAULT_DIR)
    full = os.path.abspath(os.path.join(root, *parts))
    if full != root and not full.startswith(root + os.sep):
        return None
    return "/".join(parts)


def _vault_case_account(rel, account):
    # v0.7.9e (#426): the vault doors' scoping rule — a path
    # under the case archive belongs to the requesting
    # seat's root; every other Vault path is the operator's.
    if str(rel or "").startswith(("cases/", "Cases/")):
        return _account_clean(account)
    return "operator"


def vault_fs_path(rel, account="operator"):
    if _account_clean(account) == "ciel":
        return os.path.join(vault_dir_for("ciel"), *rel.split("/"))
    return os.path.join(VAULT_DIR, *rel.split("/"))


def vault_write(rel, content, account="operator"):
    full = vault_fs_path(rel, account)
    parent = os.path.dirname(full)
    if parent:
        os.makedirs(parent, exist_ok=True)
    tmp = full + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(str(content))
    os.replace(tmp, full)


VAULT_RAW_IMAGE_TYPES = {
    ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
    ".gif": "image/gif", ".webp": "image/webp",
}


def vault_raw_payload(rel):
    # v0.5.3e (#265): one Vault file's bytes + content type for
    # the /api/vault/raw door, or (None, None). The caller has
    # already jailed rel through vault_join. Raster images are
    # images; anything else is opaque bytes (the door adds a
    # sandbox policy and nosniff — a filed file is shown,
    # never executed in the dashboard's origin).
    full = vault_fs_path(rel)
    if not os.path.isfile(full):
        return None, None
    try:
        with open(full, "rb") as f:
            data = f.read()
    except Exception:
        return None, None
    ext = os.path.splitext(rel)[1].lower()
    return data, VAULT_RAW_IMAGE_TYPES.get(ext, "application/octet-stream")


def dossier_record_for_rel(rel, store=None):
    # The dossier record whose formed shelf file is rel, or
    # None — the identity a vault delete of a shelf file is
    # judged by (v0.8.4e, #472).
    if store is None:
        store = _dossier_store()
    for d in store.get("dossiers") or []:
        try:
            if dossier_formed_rel(d, store) == rel:
                return d
        except Exception:
            continue
    return None


def _dossier_retire_rel(rel):
    # The dossier record behind a deleted shelf file leaves
    # the store (v0.8.4e, #472). Returns the record that went,
    # or None. The save re-runs the formation sweep, which
    # prunes the shelf file if it still stands — gone means
    # gone, on both shelves of the fact.
    try:
        store = _dossier_store()
        d = dossier_record_for_rel(rel, store)
        if d is None:
            return None
        store["dossiers"] = [x for x in store.get("dossiers") or []
                             if x.get("id") != d.get("id")]
        if store.get("openId") == d.get("id"):
            store["openId"] = ""
        _dossier_save(store)
        return d
    except Exception:
        return None


def vault_delete_note(rel, account="operator"):
    # One note out of the desk (Build 3, #177: factored out of the
    # /api/vault/delete handler so the deletion's tombstone lives
    # in exactly one place). Returns True when a file went.
    # v0.7.9e (#426): the account base — and for ciel NO
    # tombstone: the tombstone store is the operator sync
    # set's channel, and her set carries none (see the
    # header note in patch-seatcases79).
    full = vault_fs_path(rel, account)
    if not os.path.isfile(full):
        return False
    os.remove(full)
    if _account_clean(account) == "operator":
        sync_record_tombstone("vault", rel)
        # v0.8.4e (#472): a formed dossier's shelf file is
        # not the dossier — the RECORD is, and the bridge
        # re-forms the file from it at every start. Deleting
        # the file alone therefore never stuck (the field's
        # purge of 2026-11-23 was done by hand for exactly
        # this reason). The delete acts on the record in the
        # same act, on every road into this function — the
        # operator's own delete, a folder delete, the sync
        # tombstone phase landing another seat's deletion.
        _dossier_retire_rel(rel)
    return True


def vault_delete_folder(rel, account="operator"):
    # A folder and everything in it (the handler's walk, kept).
    # Every note inside is tombstoned by its vault path; when the
    # folder IS a case folder (cases/<slug>), the case itself is
    # tombstoned too, so deleting a case from the Vault's tree
    # cannot resurrect through sync either. Returns the number of
    # markdown notes removed, exactly as the handler always has.
    full = vault_fs_path(rel, account)
    count = 0
    if os.path.isdir(full):
        notes = []
        for base, dirs, files in os.walk(full):
            for name in files:
                if name.lower().endswith(".md"):
                    notes.append(os.path.relpath(os.path.join(base, name), vault_dir_for(account)).replace(os.sep, "/"))
                    count += 1
        shutil.rmtree(full)
        if _account_clean(account) == "operator":
            for note_rel in notes:
                sync_record_tombstone("vault", note_rel)
                # v0.8.4e (#472): the folder road is a
                # delete road — a formed dossier inside a
                # deleted folder retires its record in the
                # same act, exactly as the single-file road.
                _dossier_retire_rel(note_rel)
            parts = rel.split("/")
            if len(parts) == 2 and parts[0] == "cases":
                sync_record_tombstone("cases", parts[1])
    return count


def vault_ensure_seed():
    # First run only: if the folder already exists, the operator's
    # desk is theirs — seeding never writes into it again.
    if os.path.isdir(VAULT_DIR):
        return
    os.makedirs(VAULT_DIR, exist_ok=True)
    for rel, content in _vault_seed_files():
        if not os.path.exists(vault_fs_path(rel)):
            vault_write(rel, content)


def _vault_links(content):
    out = []
    for m in re.finditer(r"\[\[([^\]|]+)(?:\|[^\]]+)?\]\]", content or ""):
        t = m.group(1).strip()
        if t and t not in out:
            out.append(t)
    return out


def _vault_tags(content):
    out = []
    for m in re.finditer(r"(?m)(?:^|\s)#([A-Za-z][A-Za-z0-9_-]*)", content or ""):
        t = m.group(1)
        if t and t not in out:
            out.append(t)
    return out


def _vault_is_case_fragment(rel):
    # v0.6.4e (#320): a case's WORKING folder (cases/<slug>/…)
    # is the case manager's archive, not Vault reading matter —
    # its fragments (manifest, findings, registers, timeline,
    # custody) never surface as notes. The case itself reads
    # as ONE formed file on its type shelf (see
    # case_formed_rel). The legacy formed document
    # (cases/<slug>.md, two segments) is not a fragment.
    parts = rel.split("/")
    return len(parts) >= 3 and parts[0] == "cases"


def vault_notes_raw():
    vault_ensure_seed()
    notes = []
    if os.path.isdir(VAULT_DIR):
        for base, dirs, files in os.walk(VAULT_DIR):
            dirs.sort()
            for name in sorted(files):
                if not name.lower().endswith(".md"):
                    continue
                full = os.path.join(base, name)
                rel = os.path.relpath(full, VAULT_DIR).replace(os.sep, "/")
                if _vault_is_case_fragment(rel):
                    continue
                try:
                    with open(full, encoding="utf-8") as f:
                        content = f.read()
                except Exception:
                    continue
                notes.append({
                    "path": rel,
                    "content": content,
                    "updatedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(os.path.getmtime(full))),
                })
    notes.sort(key=lambda n: n["path"])
    return notes


def vault_list_payload():
    notes = vault_notes_raw()
    folders = set()
    if os.path.isdir(VAULT_DIR):
        for base, dirs, files in os.walk(VAULT_DIR):
            for d in dirs:
                rel = os.path.relpath(os.path.join(base, d), VAULT_DIR).replace(os.sep, "/")
                # v0.6.4e (#320): the working archive's folders
                # are not shelf structure — the listing's
                # folders are the shelves and the free notes'
                # homes, never cases/<slug> machinery.
                if rel == "cases" or rel.startswith("cases/"):
                    continue
                folders.add(rel)
    # v0.6.4e (#320): formed documents are marked by the
    # bridge that formed them — the reader's element strip
    # (and any other consumer) keys off the mark, never off a
    # path shape that a rename could silently break.
    try:
        _formed_cases = {}
        for _slug in _case_all_slugs():
            _formed_cases[case_formed_rel(_slug)] = _slug
        _formed_dossiers = {}
        _dstore = _dossier_store()
        for _d in _dstore.get("dossiers") or []:
            _formed_dossiers[dossier_formed_rel(_d, _dstore)] = _d["id"]
    except Exception:
        _formed_cases, _formed_dossiers = {}, {}
    for n in notes:
        parts = n["path"].split("/")
        title = parts[-1][:-3] if parts[-1].lower().endswith(".md") else parts[-1]
        n["title"] = title
        n["outgoing"] = _vault_links(n["content"])
        n["tags"] = _vault_tags(n["content"])
        if n["path"] in _formed_cases:
            n["formedCase"] = _formed_cases[n["path"]]
        if n["path"] in _formed_dossiers:
            n["formedDossier"] = _formed_dossiers[n["path"]]
    for n in notes:
        n["backlinks"] = [
            o["path"] for o in notes
            if o["path"] != n["path"]
            and any(t.lower() == n["title"].lower() for t in o["outgoing"])
        ]
    # v0.6.6e (#328): the Cases section stands at the BOTTOM
    # of the Vault — after every other folder, never sorted
    # into the middle of the operator's own shelves. The
    # payload carries the order; the view honors it.
    ordered = sorted(f for f in folders if f != "Cases" and not f.startswith("Cases/"))
    ordered += sorted(f for f in folders if f == "Cases" or f.startswith("Cases/"))
    return {"notes": notes, "folders": ordered}


def vault_search(query, limit=2):
    words = set(w for w in re.findall(r"[a-z0-9][a-z0-9_-]{3,}", (query or "").lower()))
    if not words:
        return []
    scored = []
    for n in vault_notes_raw():
        title = n["path"].split("/")[-1].lower()
        tags = [t.lower() for t in _vault_tags(n["content"])]
        body = n["content"].lower()
        score = 0
        for w in words:
            if w in title:
                score += 3
            if w in tags:
                score += 2
            if w in body:
                score += 1
        if score > 0:
            prose = re.sub(r"^---\n.*?\n---\n", "", n["content"], flags=re.S)
            lines = [ln.strip() for ln in prose.split("\n") if ln.strip() and not ln.strip().startswith("#")]
            scored.append({"path": n["path"], "score": score, "excerpt": " ".join(lines)[:400]})
    scored.sort(key=lambda h: -h["score"])
    return scored[:limit]


def vault_file_from_chat(text, history=None):
    # Her note-taking from chat (issue #54): a filing request lands
    # on her side of the desk — Navi's Desk/, dated, first person —
    # unless the operator names their own side. The note is ABOUT
    # something: the thing just discussed. A bare request ("make a
    # note about that up there") names no subject, so the recent
    # conversation rides along (build .73, field report: the first
    # version filed an empty note under a promising name): the note
    # says what it is about and quotes the exchange it came from —
    # above all the latest terminal output. Returns (path, err).
    raw = (text or "").strip()
    to_operator = bool(re.search(r"\b(?:in|to|under)\s+(?:my|the\s+operator|operator)\b", raw, re.I))
    body = raw.split(":", 1)[1].strip() if ":" in raw else raw
    body = re.sub(r"^(?:please\s+)?(?:file|write|save|make|take)\s+(?:a\s+|this\s+)?note\b", "", body, flags=re.I).strip()
    body = re.sub(r"\bnote\s+(?:this|that)\s+down\b", "", body, flags=re.I).strip() or raw
    # The subject as the operator phrased it, with the politeness and
    # the filing verbs stripped: "Can you make a note about X" -> "X".
    subject = body
    subject = re.sub(r"^(?:please\s+)?(?:can|could|would)\s+you\s+", "", subject, flags=re.I).strip()
    subject = re.sub(r"^(?:please\s+)?(?:file|write|save|make|take)\s+(?:a\s+|this\s+)?note\s+(?:about|on|of)\s+", "", subject, flags=re.I).strip()
    subject = re.sub(r"^(?:please\s+)?(?:file|write|save|make|take)\s+(?:a\s+|this\s+)?note\b\s*", "", subject, flags=re.I).strip(" .?:")
    # Recent conversation, newest first, skipping the request itself.
    ctx = []
    for item in reversed(history or []):
        if not isinstance(item, dict):
            continue
        c = str(item.get("content") or "").strip()
        if not c or c == raw:
            continue
        ctx.append(c)
        if len(ctx) >= 3:
            break
    term = ""
    for c in ctx:
        if "terminal" in c.lower() or c.startswith("$ "):
            term = c
            break
    term_cmd = ""
    if term:
        for ln in term.split("\n"):
            ln = ln.strip()
            if ln.startswith("$ "):
                term_cmd = ln[2:].strip()
                break
    vague = (not subject) or len(subject.split()) < 2 or bool(re.match(r"(?i)^(that|this|it|the above|up there)\b", subject))
    # Her titles name the SUBJECT, never the operator's ask (field
    # report: a filing named "Can you make a note" after his literal
    # words). A vague ask over a terminal result titles the note for
    # what the terminal showed — for a listing, the place listed and
    # the first thing in it.
    if not vague:
        title_src = subject
    elif term_cmd:
        title_src = ""
        m_ls = re.match(r"ls\s+(?:-\S+\s+)*(\S+)", term_cmd)
        if m_ls:
            seg = m_ls.group(1).rstrip("/").split("/")[-1] or "root"
            first_entry = ""
            seen_cmd = False
            for ln in term.split("\n"):
                s_ln = ln.strip()
                if s_ln.startswith("$ "):
                    seen_cmd = True
                    continue
                if seen_cmd and s_ln:
                    tok = s_ln.split()[0]
                    if not tok.endswith(":"):
                        first_entry = tok
                        break
            title_src = seg + " listing - " + first_entry if first_entry else seg + " listing"
        if not title_src:
            title_src = "Terminal - " + term_cmd
    elif ctx:
        title_src = ctx[-1]
    else:
        title_src = subject or body
    if len(title_src) > 80:
        title_src = " ".join(title_src.split()[:6])
    title = " ".join(title_src.replace("#", "").split()).strip(" .:") or "Untitled note"
    title = title.replace("/", "-").replace(chr(92), "-")
    today = time.strftime("%Y-%m-%d", time.localtime())
    folder = "Operator" if to_operator else "Navi's Desk"
    rel = folder + "/" + today + " " + title + ".md"
    n = 2
    while os.path.exists(vault_fs_path(rel)):
        rel = folder + "/" + today + " " + title + " " + str(n) + ".md"
        n += 1
    if to_operator:
        content = "# " + title + "\n\n" + body + "\n"
    else:
        lines = [
            "---", "filed: " + today, "---", "",
            "# " + title, "",
            "Alex asked me to keep a note of this, " + today + " — in his words: “" + raw + "”", "",
            "## What it's about", "",
        ]
        if not vague:
            lines += [subject[0].upper() + subject[1:] if subject else subject, ""]
        elif term_cmd:
            lines += ["The terminal output from just before he asked — the “" + term_cmd + "” run, kept below so the note stands on its own.", ""]
        elif ctx:
            lines += ["The exchange just before he asked, kept below so the note stands on its own.", ""]
        else:
            lines += ["He asked with nothing else on the table — the request itself is the record, and this line is me saying so instead of filing an empty page.", ""]
        if ctx:
            lines += ["## From the conversation", ""]
            for c in reversed(ctx):
                excerpt = c if len(c) <= 900 else c[:900] + "\n... [trimmed]"
                for ln in excerpt.split("\n"):
                    lines.append("    " + ln)
                lines.append("")
        lines += ["— filed by Navi from chat, " + today + ".", ""]
        content = "\n".join(lines)
    vault_write(rel, content)
    return rel, None


def rag_retrieve(question, limit=2):
    # Only active packs feed her answers. Only the question is
    # embedded here — every chunk vector was computed when its pack
    # was installed or forged.
    qv = _rag_embed(question)
    if not any(qv):
        return []
    # v0.6.21e (#366): retrieval honors the CANONICAL pack
    # state — the same resolution the enumeration shows, so
    # the state a surface displays is the state that feeds.
    # A folder feeds iff its pack is active; twin folders of
    # one pack stand or fall together, and their identical
    # chunks land once, under the pack's canonical name.
    folder_state = {}
    for g in _rag_pack_groups():
        row = _rag_group_row(g)
        for slug in g["folders"]:
            folder_state[slug] = (row["active"], row["name"])
    hits = []
    seen_chunks = set()
    try:
        entries = sorted(os.listdir(RAG_PACKS_DIR))
    except Exception:
        entries = []
    for entry in entries:
        state = folder_state.get(entry)
        if state is not None and not state[0]:
            continue
        index = _rag_pack_index(entry)
        if index is None:
            continue
        pack_name = state[1] if state else (index.get("name") or entry)
        for doc in index.get("documents") or []:
            for chunk in doc.get("chunks") or []:
                vec = chunk.get("vector") or []
                score = sum(a * b for a, b in zip(qv, vec))
                if score >= RAG_MIN_SCORE:
                    text = chunk.get("text") or ""
                    dedupe = (doc.get("title") or "", text)
                    if dedupe in seen_chunks:
                        continue
                    seen_chunks.add(dedupe)
                    hits.append({
                        "pack": pack_name,
                        "document": doc.get("title") or "",
                        "text": text,
                        "score": score,
                    })
    hits.sort(key=lambda h: -h["score"])
    return hits[:limit]
def strip_citation_footer(text):
    # A citation footer — a trailing "— from <pack> · <document>"
    # line — is presentation, not prose: sources ride the chat
    # payload's "rag" field and the dashboard draws them as pills
    # under the message. They never live in reply text, so her
    # voice never reads them aloud and they never enter the history
    # that would teach her to imitate them. This strips a trailing
    # footer in that shape wherever one survives: a model's own
    # imitation, or a thread an older build stored.
    lines = str(text or "").rstrip().split("\n")
    while lines and lines[-1].strip().startswith("— from "):
        lines.pop()
        while lines and not lines[-1].strip():
            lines.pop()
    return "\n".join(lines).rstrip()


_LEADING_STAMP_RE = re.compile(
    r"^(\s*\[(?:\d{1,2}:\d{2}|\d{1,2} [A-Za-z]{3}(?: \d{4})?, "
    r"\d{1,2}:\d{2})\]\s*)+")


def strip_leading_chat_stamps(text):
    # v0.7.4e (#406): a run of bracketed clock stamps at the
    # head of a reply — the shape the model echoes out of
    # the stamped history (#371 renders the turns' times
    # into the record she reads) and the shape that then
    # stacks, one more per turn, as stamped replies re-enter
    # the history. Only the head is stripped: a bracketed
    # time standing mid-text (the conversion law naming a
    # candidate turn by its bracket) is a reference, not an
    # echo, and stands. The stamp family is _chat_stamp_
    # text's own: [HH:MM], [DD Mon, HH:MM], [DD Mon YYYY,
    # HH:MM].
    return _LEADING_STAMP_RE.sub("", str(text or ""))


_HISTORY_CITATION_RE = re.compile(
    r"\s*\[(?:\d{1,2}:\d{2}|\d{1,2} [A-Za-z]{3}(?: \d{4})?, "
    r"\d{1,2}:\d{2})\]")


def strip_history_citations(text):
    # v0.7.12e (#425): a bracketed history stamp standing
    # MID-reply as a citation — "you said it this morning
    # [05:26]" — leaks the record's scaffolding into her
    # voice; the field reply should have named the time in
    # words or not at all. #406 deliberately kept mid-text
    # stamps (a reference, it said); #425's field evidence
    # supersedes for the reply surface: a stamp of the
    # history family (the _chat_stamp_text shapes) never
    # renders in a reply, wherever it stands. The removal
    # takes its surrounding space with it and tidies the
    # seams (a space stranded before punctuation, a doubled
    # space), so the sentence reads as if the citation was
    # never there. Bracketed text outside the stamp family
    # — a [sic], a chip name, a citation of any other shape
    # — is not the record's scaffolding and stands.
    out = _HISTORY_CITATION_RE.sub("", str(text or ""))
    out = re.sub(r" +([,.;:!?])", r"\1", out)
    out = re.sub(r" {2,}", " ", out)
    return out


_PERSONA_BOILERPLATE_MARKERS = (
    "just a conduit",
    "just a tool",
    "'enjoy' or 'not enjoy'",
    "my role is to facilitate",
    "role is to facilitate",
    "designed to facilitate",
    "not to engage in personal",
    "engage in personal conversations",
    "have personal feelings or emotions",
    "not to have personal feelings",
    "how can i assist you",
)


def scrub_persona_boilerplate(text):
    # v0.7.4e (#405): her own prior stock-disclaimer
    # sentences are the primer for the next one (the field's
    # four datapoints: fresh thread in persona, contaminated
    # thread boilerplate, both weights). The history door
    # removes those sentences from the copy it feeds back —
    # the citation-footer doctrine, one family over: she
    # never learns to imitate them because she never reads
    # them as hers. Sentence-level: a mixed turn keeps its
    # substance. A refusal with its reason named carries no
    # marker and stands whole — the bright lines are not
    # boilerplate and are never scrubbed. Returns
    # (cleaned_text, hit).
    t = str(text or "")
    if not t:
        return t, False
    low = t.lower()
    if not any(mk in low for mk in _PERSONA_BOILERPLATE_MARKERS):
        return t, False
    hit = False
    kept = []
    for line in t.split("\n"):
        keep_line = []
        for s in re.split(r"(?<=[.!?])\s+", line):
            if any(mk in s.lower()
                   for mk in _PERSONA_BOILERPLATE_MARKERS):
                hit = True
                continue
            keep_line.append(s)
        kept.append(" ".join(keep_line))
    cleaned = re.sub(r"\n{3,}", "\n\n", "\n".join(kept)).strip()
    return cleaned, hit


# v0.7.8e (#418): the digest-scaffolding scrub. The bridge
# composes bracketed brief blocks into her context — her
# measured vitals, the wire brief, the Row's Own page and
# talks blocks. They are context, not prose: when a model
# reads one back as its answer (the Mesh field leak, where
# the lender's model republished the borrower's travelling
# briefs), the block is scaffolding standing in the reply,
# and it comes off — here, beside the #405/#406 family, at
# both doors they guard: the fresh reply and the history
# door, so a stored leak stops priming the next one. The
# judgment is a paragraph's HEAD: she discusses her vitals
# and the wire in sentences, and a sentence never opens
# with the bridge's own bracketed brief header; a paragraph
# that does is the brief itself, republished.
def _drop_scaffold_paragraphs(text, heads):
    # The paragraphs of `text` whose first line opens with
    # one of `heads` are dropped; everything else stands.
    # Returns (text, hit) — the original text, untouched,
    # when nothing matched.
    if not text:
        return text, False
    parts = re.split(r"\n\s*\n", str(text))
    kept = []
    hit = False
    for p in parts:
        head = p.lstrip().split("\n", 1)[0] if p.strip() else ""
        if head and any(head.startswith(h) for h in heads):
            hit = True
            continue
        kept.append(p)
    if not hit:
        return text, False
    return "\n\n".join(kept).strip(), True


# v0.7.10e (#418, completion): the bracketed heads above
# miss the echo the field actually produced — the Shotgun
# turn-3 reply, where the model read the briefs back with
# their brackets already gone (the stored record opens
# "Your measured vitals — the bridge's stopwatch, this
# machine / Your last generation: 39 tokens, at 5.1
# tokens/sec…", then the intel brief and the wire, all
# unbracketed). These are the bridges' own literal header
# lines minus the bracket: a paragraph opening with one
# IS the brief, republished — prose she writes about her
# vitals or the wire never opens with the bridge's exact
# header sentence.
_UNBRACKETED_SCAFFOLD_HEADS = (
    "Your measured vitals — the bridge's stopwatch",
    "Threat intelligence — gathered by",
    "The wire — the security news",
    "The wire — quiet",
)


def scrub_digest_scaffolding(text):
    # (text, hit): the text with any republished digest
    # scaffolding removed — see the banner above. The marks
    # resolve at call time: the Row's Own digest consts live
    # further down the file than this scrub family.
    heads = ("[Your measured vitals", "[The wire —",
             "[Threat intelligence —",
             ROWSOWN_DIGEST_TALKS_MARK, ROWSOWN_DIGEST_PAGE_MARK)
    out, hit = _drop_scaffold_paragraphs(text, heads)
    out, hit2 = _drop_scaffold_paragraphs(
        out, _UNBRACKETED_SCAFFOLD_HEADS)
    return out, hit or hit2


def _history_door_clean(messages):
    # The history door (v0.7.4e, #405/#406): what the stored
    # thread becomes before the model reads it. Beside the
    # citation-footer scrub that already stood here, her
    # stored replies are cleaned of the two compounding
    # contaminants: leading bracketed stamps (#406 — so
    # chat_stamp_messages prepends the one canonical stamp
    # to clean text and the stack stops growing) and her
    # own boilerplate disclaimer sentences (#405 — so a
    # lapse stops priming its own repetition). A turn that
    # was ALL boilerplate does not ride back at all; every
    # other turn keeps its substance, and the operator's
    # turns are never touched.
    out = []
    for m in messages or []:
        if isinstance(m, dict) and m.get("role") == "assistant":
            content = strip_citation_footer(m.get("content"))
            content = strip_leading_chat_stamps(content)
            # v0.7.12e (#425): a stored reply carrying a
            # bracketed history stamp as a mid-text citation
            # is cleaned at this door too — re-read as her
            # own words, the shape primes its own repeat.
            content = strip_history_citations(content)
            content, hit = scrub_persona_boilerplate(content)
            # v0.7.8e (#418): republished digest scaffolding
            # comes off at the same door — a stored leak,
            # re-read as her own words, primes the next one.
            content, shit = scrub_digest_scaffolding(content)
            if (hit or shit) and not content.strip():
                continue
            m = dict(m, content=content)
        out.append(m)
    return out


def fetch_pack_documents(repo):
    # Downloads the pack itself from its repo and returns its
    # documents ([{title, body}] — title is the repo-relative path,
    # which is what an answer cites). A navi-rag repo carries its
    # documents as .md/.txt/.pdf files anywhere in the tree; they
    # are fetched at the installed ref (the latest release's tag
    # when the repo cuts releases, otherwise the default branch),
    # and a PDF's body is its extracted text. Raises ValueError
    # with the reason when the repo holds no documents, so an
    # install never records a pack that is not actually here.
    full = repo["fullName"]
    latest = repo["latestRelease"]
    ref = latest["tag"] if latest else (repo["defaultBranch"] or "main")
    tree = github_json(
        "https://api.github.com/repos/" + full + "/git/trees/"
        + urllib.parse.quote(ref, safe="") + "?recursive=1"
    )
    paths = []
    for item in tree.get("tree") or []:
        if item.get("type") != "blob":
            continue
        path = str(item.get("path") or "")
        low = path.lower()
        # A root README.md is the pack's GitHub page, not a
        # document: it describes the pack and is never indexed.
        # (A README inside a subfolder is an ordinary document.)
        if low == "readme.md":
            continue
        if low.endswith(".md") or low.endswith(".txt") or low.endswith(".pdf"):
            paths.append(path)
    if not paths:
        raise ValueError(
            "the repo has no .md, .txt or .pdf documents at " + ref
            + " — a navi-rag repo carries its documents as Markdown, text, or PDF files"
            + " (a root README.md describes the pack and doesn't count)."
        )
    if len(paths) > RAG_MAX_DOCS:
        raise ValueError(
            "the repo holds " + str(len(paths)) + " documents — a pack caps at "
            + str(RAG_MAX_DOCS) + " so an install stays lean on a small machine."
        )
    documents = []
    for path in sorted(paths):
        url = (
            "https://raw.githubusercontent.com/" + full + "/"
            + urllib.parse.quote(ref, safe="") + "/" + urllib.parse.quote(path)
        )
        raw = github_download(url)
        if path.lower().endswith(".pdf"):
            body = pdf_extract_text(raw)
            if not body:
                raise ValueError(
                    path + " has no extractable text — a scanned or "
                    "image-only PDF can't be indexed."
                )
        else:
            body = raw.decode("utf-8", "replace")
        documents.append({"title": path, "body": body[:RAG_MAX_DOC_CHARS]})
    return documents


def rag_install_record(repo, slug, doc_count):
    record = chip_install_record(repo)
    record["local_dir"] = slug
    record["active"] = True
    record["doc_count"] = doc_count
    return record


def rag_pack_slug(repo, rows):
    # The folder a GitHub install writes into rag-packs/, named for
    # the repo; when another pack already owns that slug, the
    # owner's name joins it instead of overwriting their pack.
    slug = chip_slug(repo["name"])
    taken = {
        r.get("local_dir") for r in rows
        if r.get("full_name") != repo["fullName"]
    }
    if slug in taken:
        slug = chip_slug(repo["owner"] + "-" + repo["name"])
    return slug


def rag_catalog_view():
    # The chips catalog view, for packs: the GitHub topic search
    # merged with the install registry, plus forged local packs.
    error = None
    warning = None
    repos = []
    try:
        # Build 2 (#173): same discipline as the chips catalog —
        # Runtime credential, five-minute cache, one search in
        # flight, failures classified and named.
        data = github_search_repositories("topic:navi-rag")
        failures = 0
        last_err = None
        for item in data.get("items") or []:
            full = item.get("full_name")
            if not full:
                continue
            try:
                repos.append(fetch_repo_chip(full))
            except Exception as fe:
                failures += 1
                last_err = fe
        if failures:
            warning = (
                "GitHub could not be fully read for "
                + str(failures)
                + " of the packs — the list may be incomplete. "
                + github_error_text(last_err, authed=bool(github_read_token()))
            )
    except Exception as e:
        error = "GitHub search failed. " + github_error_text(e, authed=bool(github_read_token()))
    installs = {row.get("full_name"): row for row in load_rag_installs()}
    # Issue #22, the pack half — the case from Alex's screenshot:
    # a pack forged in RAG Studio (its local/ record, folder named
    # for the pack) must read as installed on its repo's catalog
    # card, not NOT INSTALLED with a live Install above the local
    # card proving otherwise. Same slug rule as chips: the repo
    # name is matched against the pack folders on this machine
    # and the install records, local/ ones included. An exact
    # full-name match keeps the update math; a slug match claims
    # only "installed" and borrows its state from the local pack.
    installs_ci = {}
    rec_by_slug = {}
    for row in load_rag_installs():
        fn = row.get("full_name") or ""
        if fn:
            installs_ci.setdefault(fn.lower(), row)
        s = fn.split("/")[-1].lower()
        if s and s not in rec_by_slug:
            rec_by_slug[s] = row
    local_packs = {}
    for lp in local_rag_packs():
        local_packs.setdefault(str(lp.get("slug") or "").lower(), lp)
    packs = []
    for repo in repos:
        inst = installs.get(repo["fullName"]) or installs_ci.get(repo["fullName"].lower())
        slug_lp = None
        slug_rec = None
        if not inst:
            s = repo["fullName"].split("/")[-1].lower()
            slug_lp = local_packs.get(s)
            slug_rec = rec_by_slug.get(s)
        slug_matched = bool(not inst and (slug_lp is not None or slug_rec is not None))
        update = False
        if inst:
            if repo["latestRelease"]:
                update = inst.get("installed_tag") != repo["latestRelease"]["tag"]
            else:
                update = bool(
                    inst.get("installed_pushed_at")
                    and repo["pushedAt"] > inst["installed_pushed_at"]
                )
        if inst:
            ref = _display_ref(inst.get("installed_ref"))
            local_dir = inst.get("local_dir")
            active = bool(inst.get("active", True))
            doc_count = inst.get("doc_count")
            edited = bool(inst.get("locally_edited"))
            tag = inst.get("installed_tag")
            at = inst.get("installed_at")
        elif slug_matched:
            ref = slug_lp.get("installedRef") if slug_lp else (
                _display_ref(slug_rec.get("installed_ref"))
                if slug_rec and str(slug_rec.get("full_name") or "").startswith("local/")
                else None
            )
            local_dir = slug_lp.get("slug") if slug_lp else (slug_rec.get("local_dir") if slug_rec else None)
            active = slug_lp.get("active") if slug_lp else (bool(slug_rec.get("active", True)) if slug_rec else None)
            doc_count = slug_lp.get("docCount") if slug_lp else (slug_rec.get("doc_count") if slug_rec else None)
            edited = slug_lp.get("locallyEdited") if slug_lp else (bool(slug_rec.get("locally_edited")) if slug_rec else False)
            tag = slug_rec.get("installed_tag") if slug_rec else None
            at = slug_rec.get("installed_at") if slug_rec else None
        else:
            ref = None
            local_dir = None
            active = None
            doc_count = None
            edited = False
            tag = None
            at = None
        entry = dict(repo)
        entry["inCatalog"] = True
        entry["installed"] = bool(inst) or slug_matched
        entry["slugMatched"] = slug_matched
        entry["installedTag"] = tag
        entry["installedRef"] = ref
        entry["installedAt"] = at
        entry["updateAvailable"] = update
        entry["localDir"] = local_dir
        entry["active"] = active
        entry["docCount"] = doc_count
        entry["locallyEdited"] = edited
        packs.append(entry)
    seen = {p["fullName"] for p in packs}
    for full, inst in installs.items():
        if full in seen:
            continue
        packs.append({
            "fullName": full,
            "name": inst.get("name") or full.split("/")[-1],
            "owner": full.split("/")[0],
            "description": "",
            "htmlUrl": inst.get("html_url") or "",
            "stars": 0, "forks": 0, "language": "—", "topics": [],
            "updatedAt": "",
            "pushedAt": inst.get("installed_pushed_at") or "",
            "defaultBranch": "main", "openIssues": 0,
            "latestRelease": None,
            "inCatalog": False, "installed": True, "slugMatched": False,
            "installedTag": inst.get("installed_tag"),
            "installedRef": _display_ref(inst.get("installed_ref")),
            "installedAt": inst.get("installed_at"),
            "updateAvailable": False,
            "localDir": inst.get("local_dir"),
            "active": bool(inst.get("active", True)),
            "docCount": inst.get("doc_count"),
            "locallyEdited": bool(inst.get("locally_edited")),
        })
    view = {"fetchedAt": _now_iso(), "packs": packs}
    if error:
        view["error"] = error
    if warning:
        view["warning"] = warning
    return view


# ------------------------------- Voice -------------------------------
# Her voice, fully local. The bridge stays stdlib-only: the speech
# engines (faster-whisper for hearing, Kokoro or Piper for speaking)
# are optional dependencies, imported lazily the first time a voice
# endpoint is used. When they are not importable, the endpoints say
# so, with the step that installs them — nothing fakes audio.
# Settings live in navi.config.json's "voice" section; models land
# in voice/models/ on first use; the live call is voice/state.json
# and finished calls are archived to voice/calls.json.

VOICE_DIR = os.path.join(ROOT, "voice")
VOICE_MODELS_DIR = os.path.join(VOICE_DIR, "models")
VOICE_STATE_PATH = os.path.join(VOICE_DIR, "state.json")
VOICE_CALLS_PATH = os.path.join(VOICE_DIR, "calls.json")


def _adopt_voice_venv():
    # The installer lays the speech engines down in an isolated
    # venv at voice/venv, and the launchers run this bridge with
    # that venv's Python — but a bridge started any other way (by
    # hand, by an older launcher, or one already running from
    # before the voice step) runs under the system Python and
    # would report her voice missing while the engines sit right
    # beside it. Adopt the venv's site-packages into this
    # interpreter's module path, so the engines the installer laid
    # down are the engines this bridge finds, whichever Python
    # started it. The installer builds the venv from the system
    # python3, so the packages are built for this Python family
    # and import identically. Returns the adopted path, or None.
    venv = os.path.join(VOICE_DIR, "venv")
    candidates = []
    lib = os.path.join(venv, "lib")
    if os.path.isdir(lib):
        try:
            for entry in sorted(os.listdir(lib)):
                candidates.append(os.path.join(lib, entry, "site-packages"))
        except Exception:
            pass
    candidates.append(os.path.join(venv, "Lib", "site-packages"))
    for path in candidates:
        if os.path.isdir(path):
            if path not in sys.path:
                sys.path.insert(0, path)
            return path
    return None


VOICE_VENV_SITE_PACKAGES = _adopt_voice_venv()
VOICE_INSTALL_HINT = (
    "Install her voice: re-run the installer and say yes at the voice "
    "step, or run: python3 -m pip install -r requirements-voice.txt"
)

VOICE_DEFAULTS = {
    "enabled": True,
    "stt_model": "small.en",
    "tts_engine": "kokoro",
    "tts_voice": "bf_isabella",
    "rate": 1.0,
    "pitch": 1.0,
}


class VoiceUnavailable(Exception):
    pass


def voice_config(cfg):
    raw = cfg.get("voice") or {}
    stt = raw.get("stt") or {}
    tts = raw.get("tts") or {}
    out = dict(VOICE_DEFAULTS)
    if isinstance(raw.get("enabled"), bool):
        out["enabled"] = raw["enabled"]
    if stt.get("model"):
        out["stt_model"] = str(stt["model"])
    if tts.get("engine") in ("kokoro", "piper"):
        out["tts_engine"] = tts["engine"]
    if tts.get("voice"):
        out["tts_voice"] = str(tts["voice"])
    for key in ("rate", "pitch"):
        try:
            val = float(tts.get(key))
            if 0.5 <= val <= 2.0:
                out[key] = val
        except (TypeError, ValueError):
            pass
    return out


def save_voice_config(patch):
    # Voice settings persist into navi.config.json, beside the rest
    # of the app config — the dashboard's Voice tab writes them here.
    try:
        with open(CONFIG_PATH) as f:
            cfg = json.load(f)
    except Exception:
        cfg = {}
    cur = voice_config(cfg)
    for key, val in patch.items():
        if key in VOICE_DEFAULTS:
            cur[key] = val
    cfg["voice"] = {
        "enabled": bool(cur["enabled"]),
        "stt": {"engine": "faster-whisper", "model": cur["stt_model"]},
        "tts": {
            "engine": cur["tts_engine"],
            "voice": cur["tts_voice"],
            "rate": cur["rate"],
            "pitch": cur["pitch"],
        },
    }
    os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)
    with open(CONFIG_PATH, "w") as f:
        json.dump(cfg, f, indent=2)
    return cur


def _module_available(name):
    try:
        return importlib.util.find_spec(name) is not None
    except Exception:
        return False


_engine_probes = {}


def _probe_engine(pkg, symbol):
    # The one availability truth for a speech engine: the exact import
    # the synthesis/transcription paths perform (from kokoro import
    # KPipeline, from faster_whisper import WhisperModel), attempted
    # once in this interpreter and cached. find_spec alone is not
    # proof — it locates a package's directory even when that
    # package's own imports fail under this Python, which is what
    # happens when the bridge runs under a different interpreter than
    # the voice venv's and merely adopted its site-packages. That
    # split is how every status surface could call Kokoro installed
    # while a speak attempt called it missing. voice_status reports
    # this probe and the loaders fail with the same distinction, so
    # the pipeline strip, the status column, and the banner can never
    # disagree again. Returns (available, exception-or-None).
    key = pkg + ":" + symbol
    if key not in _engine_probes:
        try:
            mod = importlib.import_module(pkg)
            if symbol:
                getattr(mod, symbol)
            _engine_probes[key] = (True, None)
        except Exception as e:
            _engine_probes[key] = (False, e)
    return _engine_probes[key]


def _engine_detail(pkg, exc):
    # Why an engine is unavailable, in words that name the failing
    # piece: a genuinely absent package gets the install step; a
    # package that is present but fails to load says so and carries
    # the real import error instead of hiding behind "not installed".
    if exc is None:
        return None
    if not _module_available(pkg):
        return ("The " + pkg + " package is not installed for the Python "
                "running this bridge. " + VOICE_INSTALL_HINT)
    return ("The " + pkg + " package is installed, but the Python running "
            "this bridge cannot load it: " + type(exc).__name__ + ": "
            + str(exc) + ". " + VOICE_INSTALL_HINT)


def _voice_decode_probe():
    # Build 6 (#221): availability by DECODE, not by import. The
    # import probe above can pass while transcription is dead:
    # faster-whisper 1.2.1's decode_audio passes a keyword
    # (metadata_errors) that PyAV 13+ removed from av.open(), so
    # with av 19 in the venv every clip died at decode — eight
    # days of "she can't hear me" that every import check called
    # healthy. This probe generates a quarter second of silence,
    # writes it as a WAV, and runs the REAL decode path
    # (faster_whisper.audio.decode_audio — the same call
    # transcription makes) over it. Cached like the import
    # probes: the verdict is per-interpreter, and an interpreter
    # does not change its packages mid-run. Returns
    # (ok, exception-or-None).
    key = "decode:faster_whisper"
    if key in _engine_probes:
        return _engine_probes[key]
    try:
        from faster_whisper.audio import decode_audio
        wav = _samples_to_wav([0.0] * 4000, 16000)
        fd, path = tempfile.mkstemp(suffix=".wav",
                                    prefix="navi-decode-probe-")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(wav)
            samples = decode_audio(path, sampling_rate=16000)
            n = len(samples)
        finally:
            try:
                os.unlink(path)
            except Exception:
                pass
        if n <= 0:
            raise RuntimeError(
                "the decoder returned no samples for a silent "
                "test clip")
        _engine_probes[key] = (True, None)
    except Exception as e:
        _engine_probes[key] = (False, e)
    return _engine_probes[key]


def _decode_detail(exc):
    # Why transcription is unavailable even though the package
    # imports — the sentence names the failing call and the
    # drift that causes it, with the cure (the pinned set).
    if exc is None:
        return None
    return ("faster-whisper is installed and imports, but it "
            "cannot decode audio in this Python: "
            + type(exc).__name__ + ": " + str(exc)
            + ". The speech packages have drifted apart — the "
            "known shape is a PyAV (the 'av' package) newer than "
            "faster-whisper's decoder expects; the voice "
            "requirements now pin av below 13 for exactly this. "
            "Cure: re-run the installer and say yes at the voice "
            "step — it repairs the venv to the pinned set — or "
            "run the venv's Python with: -m pip install "
            "-r requirements-voice.txt")


# -- CUDA execution probe (v0.4.1e, #229) ----------------------
# Device selection used to probe PRESENCE: torch reported a
# CUDA device on NeoArcadia, so Kokoro's pipeline loaded onto
# it — and the first real generation died with "CUDA error: no
# kernel image is available for execution on the device",
# because the installed wheels carry no kernels for the card's
# architecture (a Tesla V100, Volta, compute capability 7.0).
# The raw CUDA string was the operator-facing speech failure.
# This probe EXECUTES: a tiny real tensor operation on the
# device, synchronized, its result checked. The verdict is
# cached per interpreter, like the other voice probes, and a
# generation-time CUDA failure rewrites it (the self-healing
# path in synthesize_wav) so the next line goes to the CPU.


def _voice_cuda_probe():
    # Returns (state, info): state is "absent" (no torch, or
    # torch sees no CUDA device), "executing" (a real operation
    # ran on the device), or "failed" (a device is present but
    # execution died). info carries the device name, the compute
    # capability as "7.0"-style text, and the raw exception when
    # failed — the raw string is kept for the record, never used
    # as the operator's sentence (see _cuda_fallback_sentence).
    if "cuda-exec" in _engine_probes:
        return _engine_probes["cuda-exec"]
    verdict = ("absent", {})
    try:
        import torch
        if torch.cuda.is_available():
            info = {}
            try:
                info["name"] = str(torch.cuda.get_device_name(0))
            except Exception:
                info["name"] = "CUDA device"
            try:
                _maj, _min = torch.cuda.get_device_capability(0)
                info["capability"] = str(_maj) + "." + str(_min)
            except Exception:
                info["capability"] = ""
            try:
                _t = torch.zeros(8, device="cuda")
                _t = _t + 1
                torch.cuda.synchronize()
                if float(_t.sum().item()) != 8.0:
                    raise RuntimeError(
                        "the device returned a wrong result for a "
                        "trivial operation")
                verdict = ("executing", info)
            except Exception as e:
                info["error"] = type(e).__name__ + ": " + str(e)
                verdict = ("failed", info)
    except Exception:
        verdict = ("absent", {})
    _engine_probes["cuda-exec"] = verdict
    return verdict


def _cuda_fallback_sentence(info):
    # The operator's sentence for a fallen-back stage: the
    # device is named, its architecture is named, the
    # consequence is named — and the raw CUDA error never
    # appears in it. The probe's raw error rides the status as
    # a separate field, for the record.
    name = info.get("name") or "the graphics card"
    cap = info.get("capability") or ""
    return ("A graphics card is present (" + name
            + (", compute capability " + cap if cap else "")
            + "), but the installed speech wheels carry no "
              "kernels for its architecture, so real work on it "
              "fails. This stage runs on the CPU instead — fully "
              "working, a little slower to start.")


def _voice_stage_devices(vc):
    # Per-stage device verdicts, present / executing /
    # fallen-back, riding the same status surface as hearing
    # (#229: transcription and synthesis can disagree, so each
    # stage carries its own). Transcription's verdict is CPU by
    # construction: _stt_model loads faster-whisper on CPU int8
    # — no CUDA path exists on that stage to probe, and the
    # status says so rather than implying a choice was made.
    stt = {"device": "cpu", "state": "cpu",
           "detail": "Transcription runs on the CPU by design "
                     "(faster-whisper, int8); it never selects "
                     "the graphics card."}
    if vc["tts_engine"] != "kokoro":
        tts = {"device": "cpu", "state": "cpu",
               "detail": "Piper speaks on the CPU."}
        return {"stt": stt, "tts": tts}
    state, info = _voice_cuda_probe()
    if state == "executing":
        tts = {"device": "cuda", "state": "executing",
               "name": info.get("name") or "",
               "capability": info.get("capability") or "",
               "detail": None}
    elif state == "failed":
        tts = {"device": "cpu", "state": "fallen-back",
               "name": info.get("name") or "",
               "capability": info.get("capability") or "",
               "detail": _cuda_fallback_sentence(info),
               "error": info.get("error") or ""}
    else:
        tts = {"device": "cpu", "state": "cpu",
               "detail": "No CUDA device is present; speech runs "
                         "on the CPU."}
    return {"stt": stt, "tts": tts}


def _kokoro_device(vc):
    # The device Kokoro is ASKED for: CUDA only when the
    # execution probe proved the device can compute.
    state, _info = _voice_cuda_probe()
    return "cuda" if state == "executing" else "cpu"


def _is_cuda_error(exc):
    return "cuda" in (type(exc).__name__ + ": " + str(exc)).lower()


def _voice_cuda_mark_failed(exc):
    # A generation-time CUDA failure rewrites the probe verdict
    # and drops the cached pipeline: the next line is built on
    # the CPU. (The probe is a warmup-time truth; this keeps it
    # true after the field disagrees.)
    state, info = _voice_cuda_probe()
    info = dict(info)
    info["error"] = type(exc).__name__ + ": " + str(exc)
    _engine_probes["cuda-exec"] = ("failed", info)
    with _voice_lock:
        # v0.7.14e (#449): pipelines are cached per language —
        # a CUDA failure drops every Kokoro pipeline, not one.
        for k in [k for k in _voice_cache
                  if k == "kokoro" or k.startswith("kokoro:")]:
            _voice_cache.pop(k, None)


def _unavailable_message(label, pkg, exc):
    # What the loaders raise on failure — the same distinction the
    # availability probe reports, so a speak failure and the status
    # check tell one story.
    if not _module_available(pkg):
        return label + " is not installed. " + VOICE_INSTALL_HINT
    return (label + " is installed but failed to load: "
            + type(exc).__name__ + ": " + str(exc))


_KOKORO_VOICE_RE = re.compile(r"^([a-z])([fm])_([a-z0-9]+)$")
_KOKORO_LANGS = {
    "a": "American", "b": "British", "e": "Spanish", "f": "French",
    "h": "Hindi", "i": "Italian", "j": "Japanese",
    "p": "Brazilian Portuguese", "z": "Mandarin",
}
_voices_cache = {}


def _kokoro_voice_label(vid):
    # Labels are derived from the voice id (af_heart -> "Heart —
    # American female"), never a per-voice lookup table: a voice the
    # list has never seen still gets a correct name.
    m = _KOKORO_VOICE_RE.match(vid)
    if not m:
        return vid
    name = m.group(3).replace("_", " ").title()
    lang = _KOKORO_LANGS.get(m.group(1), "")
    who = "female" if m.group(2) == "f" else "male"
    return name + " — " + (lang + " " if lang else "") + who


def discover_kokoro_voices(current):
    # The voice picker is populated from what this machine's Kokoro
    # installation actually has — never a hardcoded list. Sources,
    # in order: the voice .pt files the installation already holds
    # (the kokoro package's own folder, voice/models, the
    # Hugging Face cache KPipeline downloads into); and, when none
    # are on disk yet, the voice files in the Kokoro-82M repo the
    # installed package itself pulls from (huggingface_hub ships
    # with kokoro) — those download on first use, the same pattern
    # the Piper voices follow below. When neither works (engine not
    # installed, machine offline), the saved voice alone is listed,
    # so the picker never renders empty or invents voices.
    if "kokoro" in _voices_cache:
        return _voices_cache["kokoro"]
    found = {}
    roots = []
    try:
        import kokoro as _kokoro_pkg
        roots.append(os.path.dirname(os.path.abspath(_kokoro_pkg.__file__)))
    except Exception:
        pass
    roots.append(VOICE_MODELS_DIR)
    hf_home = os.environ.get("HF_HOME") or os.path.join(
        os.path.expanduser("~"), ".cache", "huggingface")
    roots.append(os.path.join(hf_home, "hub"))
    for root in roots:
        if not root or not os.path.isdir(root):
            continue
        for dirpath, _dirs, files in os.walk(root):
            for fn in files:
                if fn.endswith(".pt"):
                    vid = fn[:-3]
                    if _KOKORO_VOICE_RE.match(vid):
                        found.setdefault(vid, "installed")
    source = "installed"
    if not found and _probe_engine("kokoro", "KPipeline")[0]:
        try:
            from huggingface_hub import list_repo_files
            for f in list_repo_files("hexgrad/Kokoro-82M"):
                if f.startswith("voices/") and f.endswith(".pt"):
                    vid = os.path.basename(f)[:-3]
                    if _KOKORO_VOICE_RE.match(vid):
                        found.setdefault(vid, "catalog")
            if found:
                source = "catalog"
        except Exception:
            pass
    if not found:
        found = {current: "current"}
        source = "current"
    # v0.7.14e (#449): ff_siwis — the catalog's French female
    # voice — is always offered when the engine is installed.
    # The disk scan above lists only voices already fetched,
    # and the catalog road runs only when the disk holds
    # NOTHING, so on any seat that already speaks, the French
    # voice never reached the picker. She is not an invented
    # voice: she stands in the same Kokoro-82M catalog this
    # function already trusts, and she downloads on first
    # use like every catalog voice. The engine probe is the
    # gate — no engine, no offer, the saved voice alone.
    if "ff_siwis" not in found and source != "current" \
            and _probe_engine("kokoro", "KPipeline")[0]:
        found["ff_siwis"] = "catalog"
    result = {
        "voices": [
            {"id": vid, "label": _kokoro_voice_label(vid), "source": found[vid]}
            for vid in sorted(found)
        ],
        "source": source,
    }
    _voices_cache["kokoro"] = result
    return result


def discover_piper_voices(current):
    # Same rule for Piper: voices already downloaded into
    # voice/models/piper, plus the en voices in the piper-voices
    # repo (each downloads on first use — _piper_voice_file does
    # exactly that). The saved voice is always present.
    found = {}
    pdir = os.path.join(VOICE_MODELS_DIR, "piper")
    if os.path.isdir(pdir):
        for fn in sorted(os.listdir(pdir)):
            if fn.endswith(".onnx"):
                found[fn[:-5]] = "installed"
    if not any(s == "installed" for s in found.values()):
        try:
            from huggingface_hub import list_repo_files
            for f in list_repo_files("rhasspy/piper-voices"):
                parts = f.split("/")
                if (len(parts) == 5 and parts[0] == "en"
                        and parts[4].endswith(".onnx")):
                    found.setdefault(parts[4][:-5], "catalog")
        except Exception:
            pass
    if current and current not in found:
        found[current] = "current"
    source = ("installed" if any(s == "installed" for s in found.values())
              else "catalog" if any(s == "catalog" for s in found.values())
              else "current")
    voices = []
    for vid in sorted(found):
        parts = vid.split("-")
        if len(parts) == 3:
            label = (parts[1].title() + " (" + parts[0] + ", "
                     + parts[2] + ")")
        else:
            label = vid
        voices.append({"id": vid, "label": label, "source": found[vid]})
    return {"voices": voices, "source": source}


# Build 6 (#6, telemetry half): the last mic-state report a
# window made about ITSELF — the dashboard computes the reading
# for its Voice tab ("this window's own mic, this session") and,
# since this build, also posts it here on every push-to-talk
# attempt, so the field state finally exists in the bridge's log
# (start.log) instead of only on a screen someone must be
# watching. In-memory: it is a diagnostic, not a record.
_MIC_REPORT = {"state": "", "at": 0}


def voice_status(cfg):
    vc = voice_config(cfg)
    stt_ok, stt_exc = _probe_engine("faster_whisper", "WhisperModel")
    # Build 6 (#221): importable is not hearable — the decode
    # probe is the second half of the STT verdict. When the
    # import passes but the decode fails, hearing reads
    # unavailable and the detail names the decode, so the Voice
    # tab can never again call a deaf install healthy.
    dec_ok, dec_exc = (True, None)
    if stt_ok:
        dec_ok, dec_exc = _voice_decode_probe()
    engine_pkg = "kokoro" if vc["tts_engine"] == "kokoro" else "piper"
    tts_ok, tts_exc = _probe_engine(
        engine_pkg, "KPipeline" if engine_pkg == "kokoro" else "PiperVoice")
    disc = (discover_kokoro_voices(vc["tts_voice"])
            if vc["tts_engine"] == "kokoro"
            else discover_piper_voices(vc["tts_voice"]))
    # v0.4.1e (#229): per-stage device verdicts ride the same
    # surface — present / executing / fallen-back, with the
    # fallback's reason in the operator's words.
    _devs = _voice_stage_devices(vc)
    return {
        "enabled": vc["enabled"],
        "config": vc,
        "python": sys.executable,
        "venv": VOICE_VENV_SITE_PACKAGES,
        "stt": {
            "engine": "faster-whisper",
            "model": vc["stt_model"],
            "available": stt_ok and dec_ok,
            "detail": (_engine_detail("faster_whisper", stt_exc)
                       if not stt_ok else _decode_detail(dec_exc)),
            "decode_ok": dec_ok,
            "device": _devs["stt"],
        },
        "mic_report": dict(_MIC_REPORT),
        "tts": {
            "engine": vc["tts_engine"],
            "voice": vc["tts_voice"],
            "available": tts_ok,
            "detail": _engine_detail(engine_pkg, tts_exc),
            "device": _devs["tts"],
        },
        "voices": disc["voices"],
        "voices_source": disc["source"],
        "call": load_voice_state().get("call"),
    }


def load_voice_state():
    try:
        with open(VOICE_STATE_PATH) as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {"call": None}


def save_voice_state(state):
    os.makedirs(VOICE_DIR, exist_ok=True)
    with open(VOICE_STATE_PATH, "w") as f:
        json.dump(state, f)


def load_voice_calls():
    try:
        with open(VOICE_CALLS_PATH) as f:
            data = json.load(f)
        if isinstance(data, list):
            return data
    except Exception:
        pass
    return []


_voice_cache = {}
_voice_lock = threading.Lock()


def _stt_model(vc):
    # Loaded once, then kept warm: a Whisper load takes seconds and
    # a call shouldn't pay it per sentence. The download lands in
    # voice/models/ on first use and stays there across installs.
    key = "stt:" + vc["stt_model"]
    with _voice_lock:
        if key not in _voice_cache:
            try:
                from faster_whisper import WhisperModel
            except Exception as e:
                raise VoiceUnavailable(_unavailable_message("faster-whisper", "faster_whisper", e))
            os.makedirs(VOICE_MODELS_DIR, exist_ok=True)
            _voice_cache[key] = WhisperModel(
                vc["stt_model"], device="cpu", compute_type="int8",
                download_root=os.path.join(VOICE_MODELS_DIR, "whisper"),
            )
        return _voice_cache[key]


def transcribe_audio(audio_bytes, vc):
    if not audio_bytes:
        raise VoiceUnavailable("No audio arrived — the clip was empty.")
    # Build 6 (#221): the decode verdict gates the attempt — a
    # broken decoder is named here, in the operator's words,
    # instead of surfacing as a raw TypeError from inside the
    # model's transcribe call (which read as a dead microphone).
    dec_ok, dec_exc = _voice_decode_probe()
    if not dec_ok:
        raise VoiceUnavailable(_decode_detail(dec_exc))
    model = _stt_model(vc)
    fd, path = tempfile.mkstemp(suffix=".webm", prefix="navi-stt-")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(audio_bytes)
        segments, _info = model.transcribe(path, beam_size=1, vad_filter=True)
        return "".join(seg.text for seg in segments).strip()
    finally:
        try:
            os.unlink(path)
        except Exception:
            pass


def _samples_to_wav(samples, sample_rate):
    # Float samples in [-1, 1] to a 16-bit PCM WAV, stdlib only.
    import wave as wave_mod
    buf = io.BytesIO()
    with wave_mod.open(buf, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(int(sample_rate))
        frames = bytearray()
        for s in samples:
            v = max(-1.0, min(1.0, float(s)))
            frames += struct.pack("<h", int(v * 32767))
        w.writeframes(bytes(frames))
    return buf.getvalue()


def _pitch_shift_wav(wav_bytes, vc):
    # Varispeed pitch: replaying the same frames at a scaled rate
    # shifts pitch (and tempo along with it) — the honest stdlib
    # way of doing it, no DSP library pretending otherwise.
    try:
        factor = float(vc.get("pitch") or 1.0)
    except (TypeError, ValueError):
        factor = 1.0
    if abs(factor - 1.0) < 0.001:
        return wav_bytes
    import wave as wave_mod
    src = wave_mod.open(io.BytesIO(wav_bytes), "rb")
    params = src.getparams()
    frames = src.readframes(src.getnframes())
    src.close()
    out = io.BytesIO()
    dst = wave_mod.open(out, "wb")
    dst.setparams(params)
    dst.setframerate(max(4000, int(params.framerate * factor)))
    dst.writeframes(frames)
    dst.close()
    return out.getvalue()


def _kokoro_lang(voice_id):
    # v0.7.14e (#449): the pipeline's language is the voice's
    # OWN — a Kokoro voice id is language-prefixed (a/b/f/…),
    # and the first letter names the phonemizer the voice was
    # built for. The old rule ("b" if the id starts with "b"
    # else "a") forced every non-British voice through the
    # American pipeline: a French voice (ff_siwis) selected in
    # Settings would have come out wrong. An id the voice
    # pattern does not know keeps the American default.
    m = _KOKORO_VOICE_RE.match(str(voice_id or ""))
    if m and m.group(1) in _KOKORO_LANGS:
        return m.group(1)
    return "a"


def _kokoro_pipeline(vc):
    # The cache is keyed by language (v0.7.14e, #449): a seat
    # that switches voices across languages gets the pipeline
    # each voice needs, and switching back finds the first
    # one still warm — never the previous voice's phonemizer.
    key = "kokoro:" + _kokoro_lang(vc["tts_voice"])
    with _voice_lock:
        if key not in _voice_cache:
            try:
                from kokoro import KPipeline
            except Exception as e:
                raise VoiceUnavailable(_unavailable_message("Kokoro", "kokoro", e))
            lang = _kokoro_lang(vc["tts_voice"])
            # v0.4.1e (#229): the pipeline is built on the
            # device the EXECUTION probe proved — never on mere
            # presence. A Kokoro too old to take a device
            # argument keeps its default, and when that default
            # would be a proven-broken card, the loaded model is
            # moved to the CPU after construction.
            device = _kokoro_device(vc)
            try:
                _voice_cache[key] = KPipeline(lang_code=lang,
                                              device=device)
            except TypeError:
                _voice_cache[key] = KPipeline(lang_code=lang)
                if device == "cpu":
                    try:
                        _model = getattr(_voice_cache[key],
                                         "model", None)
                        if _model is not None:
                            _model.to("cpu")
                    except Exception:
                        pass
        return _voice_cache[key]


PIPER_VOICE_BASE = "https://huggingface.co/rhasspy/piper-voices/resolve/main/en/"


def _piper_voice_file(vc):
    # Piper voices are .onnx + .onnx.json pairs named like
    # en_US-lessac-medium, filed as en/<locale>/<name>/<quality>/.
    name = vc["tts_voice"]
    parts = name.split("-")
    if len(parts) != 3:
        raise VoiceUnavailable("Unknown Piper voice name: " + name)
    locale, speaker, quality = parts
    lang = locale.split("_")[0]
    rel = lang + "/" + locale + "/" + speaker + "/" + quality + "/" + name
    onnx = os.path.join(VOICE_MODELS_DIR, "piper", name + ".onnx")
    conf = onnx + ".json"
    if not (os.path.isfile(onnx) and os.path.isfile(conf)):
        os.makedirs(os.path.dirname(onnx), exist_ok=True)
        for suffix, dest in ((".onnx", onnx), (".onnx.json", conf)):
            try:
                urllib.request.urlretrieve(PIPER_VOICE_BASE + rel + suffix, dest)
            except Exception as e:
                raise VoiceUnavailable("Could not download the Piper voice " + name + ": " + str(e))
    return onnx


def _piper_load(vc):
    # Load (or fetch from cache) the configured Piper voice — the
    # warmup path and synthesis share this one cache entry.
    try:
        from piper import PiperVoice
    except Exception as e:
        raise VoiceUnavailable(_unavailable_message("Piper", "piper", e))
    onnx = _piper_voice_file(vc)
    key = "piper:" + onnx
    with _voice_lock:
        if key not in _voice_cache:
            _voice_cache[key] = PiperVoice.load(onnx)
        return _voice_cache[key]


def _piper_wav(text, vc):
    voice = _piper_load(vc)
    import wave as wave_mod
    buf = io.BytesIO()
    try:
        from piper.config import SynthesisConfig
        with wave_mod.open(buf, "wb") as w:
            voice.synthesize_wav(
                text, w,
                syn_config=SynthesisConfig(length_scale=1.0 / max(0.25, float(vc["rate"]))),
            )
    except VoiceUnavailable:
        raise
    except Exception as e:
        raise VoiceUnavailable("Piper could not speak that line: " + str(e))
    return _pitch_shift_wav(buf.getvalue(), vc)


def synthesize_wav(text, vc):
    text = (text or "").strip()
    if not text:
        raise VoiceUnavailable("Nothing to say — the line was empty.")
    if not vc["enabled"]:
        raise VoiceUnavailable("Voice is turned off — enable it in the Voice tab.")
    if vc["tts_engine"] == "piper":
        return _piper_wav(text, vc)
    pipeline = _kokoro_pipeline(vc)
    samples = []
    try:
        for _g, _p, audio in pipeline(text, voice=vc["tts_voice"], speed=float(vc["rate"])):
            if audio is None:
                continue
            try:
                samples.extend(float(x) for x in audio)
            except TypeError:
                samples.append(float(audio))
    except VoiceUnavailable:
        raise
    except Exception as e:
        # v0.4.1e (#229): a CUDA failure at generation time —
        # the probe said the card could compute and the field
        # disagreed — is named in the operator's words, never
        # relayed raw, and it rewrites the probe verdict so the
        # next line is built on the CPU.
        if _is_cuda_error(e):
            _state, _info = _voice_cuda_probe()
            _voice_cuda_mark_failed(e)
            raise VoiceUnavailable(
                "Her voice could not use the graphics card for "
                "that line. " + _cuda_fallback_sentence(_info)
                + " The next line will be spoken from the CPU.")
        raise VoiceUnavailable("Kokoro could not speak that line: "
                               + str(e))
    if not samples:
        raise VoiceUnavailable("Kokoro produced no audio for that line.")
    return _pitch_shift_wav(_samples_to_wav(samples, 24000), vc)


def speak_reply(text, cfg):
    # /api/chat with speak:true — her reply out loud on this machine
    # as well as in the thread. Best-effort by design: the reply is
    # already on its way back to the dashboard either way, so a
    # speech failure reports itself instead of failing the chat.
    vc = voice_config(cfg)
    if not vc["enabled"]:
        return {"ok": False, "error": "Voice is turned off."}
    try:
        wav = synthesize_wav(text, vc)
    except VoiceUnavailable as e:
        return {"ok": False, "error": str(e)}
    except Exception as e:
        return {"ok": False, "error": "Speech failed: " + str(e)}
    try:
        import sounddevice as sd
        import soundfile as sf
        data, rate = sf.read(io.BytesIO(wav), dtype="float32")
        sd.play(data, rate)
        return {"ok": True, "via": "sounddevice"}
    except Exception:
        pass
    fd, path = tempfile.mkstemp(suffix=".wav", prefix="navi-say-")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(wav)
        for player in ("aplay", "paplay", "afplay"):
            exe = shutil.which(player)
            if exe:
                subprocess.Popen([exe, path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return {"ok": True, "via": player}
        return {"ok": False, "error": "No audio player found (sounddevice, aplay, paplay, or afplay)."}
    except Exception as e:
        return {"ok": False, "error": "Playback failed: " + str(e)}


def llamafile_alive(endpoint):
    try:
        urllib.request.urlopen(endpoint.replace("/v1", "/"), timeout=2)
        return True
    except Exception:
        return False


_llamafile_proc = None


# -- Model readiness (v0.6.10e, #278/#336 patch slice) --------------
# The chat route used to learn the model server was not ready by
# failing against it — and the failure's shape (a dead socket, an
# HTML page, a non-JSON body) became the operator's "reply". The
# bridge already knows better: it health-polls the server. These
# helpers give that knowledge three honest names — ready, warming,
# unreachable — and the chat route and the status poll both read
# them, so readiness is known BEFORE a generation is attempted,
# never inferred from its wreckage.

_MODEL_STATE = {"at": 0.0, "state": "unreachable", "endpoint": ""}


class ModelNotReadyError(RuntimeError):
    # The model server did not produce an answer: it is loading,
    # or it is not there. A RuntimeError subclass, so every
    # existing caller of llamafile_chat keeps its behavior; the
    # chat route reads .state and answers with the named-state
    # payload instead of an error string. The message is the
    # honest sentence for any other surface that shows it.
    def __init__(self, state):
        self.state = state if state in ("warming", "unreachable",
                                        "backend-error") \
            else "warming"
        super().__init__(
            "navi.llamafile is still loading her model — she is "
            "warming up; ask again in a moment"
            if self.state == "warming" else
            "the model server answered in a shape that was not "
            "an answer"
            if self.state == "backend-error" else
            "navi.llamafile is not answering — the model server "
            "does not appear to be running")


def _llamafile_process_present():
    # A llamafile process on this machine, whether or not this
    # bridge spawned it — on a systemd seat the service owns the
    # process, and the load window before the port binds is
    # exactly the window this has to see. /proc cmdline scan, the
    # same source the Guardian reads.
    try:
        for pid in os.listdir("/proc"):
            if not pid.isdigit():
                continue
            try:
                with open(os.path.join("/proc", pid, "cmdline"),
                          "rb") as f:
                    if b"llamafile" in f.read():
                        return True
            except Exception:
                continue
    except Exception:
        pass
    return False


_ENGINE_MODE_CACHE = {"at": 0.0, "endpoint": "", "payload": None}


def _engine_server_argv(endpoint):
    # The running model server's own argv — the evidence
    # the compute mode is judged from. Returns (argv,
    # seen): seen says a process in this endpoint's scope
    # stood even when its argv could not be read, so the
    # caller can tell "no server" from "a server that
    # will not say". First witness: the process holding
    # the endpoint's port (that IS the server answering).
    # Second: a llamafile server process not yet bound,
    # for the load window — scoped to this endpoint by
    # its --port (or the server's default 8080 when it
    # carries none), because a seat can hold FOREIGN
    # llamafile processes (the #363 family) whose flags
    # are not this engine's truth.
    port = 8080
    try:
        p = urllib.parse.urlparse(str(endpoint or "")).port
        if p:
            port = p
    except Exception:
        pass
    pid = _mesh_listener_owner(port)
    if pid:
        try:
            with open(os.path.join("/proc", str(pid), "cmdline"),
                      "rb") as f:
                raw = f.read()
            cmd = " ".join(
                part.decode("utf-8", "replace")
                for part in raw.split(bytes([0]))).strip()
            if cmd:
                return cmd, True
        except Exception:
            pass
        return "", True
    seen = False
    try:
        for name in os.listdir("/proc"):
            if not name.isdigit():
                continue
            try:
                with open(os.path.join("/proc", name, "cmdline"),
                          "rb") as f:
                    raw = f.read()
            except Exception:
                continue
            if b"llamafile" not in raw or b"--server" not in raw:
                continue
            parts = [part.decode("utf-8", "replace")
                     for part in raw.split(bytes([0])) if part]
            pport = 8080
            for i, tok in enumerate(parts):
                if tok == "--port" and i + 1 < len(parts):
                    try:
                        pport = int(parts[i + 1])
                    except Exception:
                        pass
                elif tok.startswith("--port="):
                    try:
                        pport = int(tok.split("=", 1)[1])
                    except Exception:
                        pass
            if pport != port:
                continue
            seen = True
            argv = " ".join(parts).strip()
            if argv:
                return argv, True
    except Exception:
        pass
    return "", seen


def _gpu_layers_of_argv(argv):
    # --n-gpu-layers N (or -ngl / --ngl, or the = form):
    # the count the RUNNING server was launched with.
    # Absent -> 0: the bridge's own launcher
    # (llamafile_args) omits the flag at zero, and the
    # server's own default is zero.
    toks = str(argv or "").split()
    for i, tok in enumerate(toks):
        if tok in ("--n-gpu-layers", "-ngl", "--ngl"):
            if i + 1 < len(toks):
                try:
                    return int(toks[i + 1])
                except Exception:
                    return 0
        elif tok.startswith("--n-gpu-layers=") \
                or tok.startswith("-ngl=") \
                or tok.startswith("--ngl="):
            try:
                return int(tok.split("=", 1)[1])
            except Exception:
                return 0
    return 0


def engine_compute_payload(cfg, endpoint):
    # v0.7.7e (#391): the engine's live compute mode for
    # the Status rail's pill, judged from the RUNNING
    # server's actual launch flags — never from config
    # intent. States: "gpu" (layers > 0 in the live
    # argv), "cpu" (a server runs, no layers), "down"
    # (no server process at all), "unknown" (a process
    # stands but its argv cannot be read — the page
    # claims nothing). Cached five seconds: /api/status
    # is polled, and a mode change is a process restart,
    # never faster than the cadence that reads it.
    now = time.time()
    cache = _ENGINE_MODE_CACHE
    if cache["payload"] is not None \
            and cache["endpoint"] == str(endpoint or "") \
            and now - cache["at"] < 5:
        return cache["payload"]
    det = ((cfg.get("hardware_profile") or {}).get("detected")
           or {})
    gpu_name = str(det.get("gpuName") or "")
    argv, seen = _engine_server_argv(endpoint)
    if not argv:
        if seen:
            payload = {"state": "unknown", "gpuLayers": None,
                       "label": "Unknown", "gpuName": gpu_name}
        else:
            payload = {"state": "down", "gpuLayers": None,
                       "label": "Down", "gpuName": gpu_name}
    else:
        layers = _gpu_layers_of_argv(argv)
        if layers > 0:
            label = "V100" if "v100" in gpu_name.lower() \
                else "GPU"
            payload = {"state": "gpu", "gpuLayers": layers,
                       "label": label, "gpuName": gpu_name}
        else:
            payload = {"state": "cpu", "gpuLayers": 0,
                       "label": "CPU", "gpuName": gpu_name}
    cache.update({"at": now, "endpoint": str(endpoint or ""),
                  "payload": payload})
    return payload


def _probe_model_state(endpoint):
    # One readiness probe, three honest answers. "ready": the
    # model API lists a model. "warming": the server is present —
    # answering HTTP in any form, or alive as a process — but the
    # model API is not answering yet (the load window: on the
    # field seat it ran past three minutes). "unreachable":
    # nothing is there at all.
    base = str(endpoint or "").rstrip("/")
    if base:
        try:
            with urllib.request.urlopen(base + "/models",
                                        timeout=2) as resp:
                data = json.loads(resp.read().decode("utf-8",
                                                     "replace"))
            if isinstance(data, dict) and data.get("data"):
                return "ready"
            return "warming"
        except urllib.error.HTTPError:
            # An HTTP answer of any kind — a loading server's 503
            # is the expected shape — is presence, not absence.
            return "warming"
        except Exception:
            pass
        if llamafile_alive(endpoint):
            return "warming"
    proc = globals().get("_llamafile_proc")
    if proc is not None and proc.poll() is None:
        return "warming"
    if _llamafile_process_present():
        return "warming"
    return "unreachable"


def model_readiness(endpoint):
    # The bridge's own knowledge of the model server's state,
    # shared by the chat route and the status poll behind a short
    # cache, so neither discovers unreadiness by failing and the
    # probes stay cheaper than the poll cadence that reads them.
    now = time.time()
    if _MODEL_STATE["endpoint"] == endpoint \
            and now - _MODEL_STATE["at"] < 3.0:
        return _MODEL_STATE["state"]
    state = _probe_model_state(endpoint)
    _MODEL_STATE.update({"at": now, "state": state,
                         "endpoint": endpoint})
    return state


def _not_ready_from_probe(endpoint):
    # The state to name when an upstream exchange produced no
    # answer: the probe's own word — except that a probe saying
    # "ready" beside an answer that was not an answer means the
    # failure is in the exchange itself, and its name is
    # backend-error.
    st = model_readiness(endpoint)
    return "backend-error" if st == "ready" else st


def model_state_payload(state):
    # The chat route's named-state answer: a 200 the page renders
    # as a system notice — never a model reply, never an error
    # string. The post-Apply face reads the same: a relaunched
    # bridge whose model is still loading says "warming" until
    # the first real round-trip proves otherwise.
    if state == "warming":
        note = ("Navi is warming up — her model is still loading "
                "on this machine. Give her a moment, then ask "
                "again.")
    elif state == "backend-error":
        note = ("The model server answered in a shape that was "
                "not an answer — the exchange failed, not the "
                "model. Your ask wasn't answered; try again.")
    else:
        state = "unreachable"
        note = ("Navi's model isn't answering — the llamafile "
                "server doesn't appear to be running on this "
                "machine. Commands still work; check the server, "
                "then ask again.")
    return {"reply": None, "exec": None, "mode": "model-state",
            "modelState": state,
            "llamafile": "warming" if state == "warming"
            else "running" if state == "backend-error"
            else "stopped",
            "modelStateNote": note}


def llamafile_port(endpoint):
    try:
        port = urllib.parse.urlparse(endpoint).port
    except Exception:
        port = None
    return port or 8080


def llamafile_binary(cfg):
    # Where the installer puts navi.llamafile: the configured install
    # dir, or right beside this bridge — the bridge ships in the
    # install root, so on a normal install those are the same place.
    dirs = []
    install_dir = cfg.get("install_dir")
    if install_dir:
        dirs.append(os.path.expanduser(install_dir))
    dirs.append(ROOT)
    for d in dirs:
        for name in ("navi.llamafile", "navi.llamafile.exe"):
            path = os.path.join(d, name)
            if os.path.isfile(path):
                return path
    return None


def wait_for_llamafile(endpoint, proc, log_path=None):
    # Loading a multi-GB model takes a while; give it two minutes.
    for _ in range(120):
        if llamafile_alive(endpoint):
            return True, None
        if proc is not None and proc.poll() is not None:
            tail = ""
            if log_path:
                try:
                    with open(log_path, "rb") as f:
                        data = f.read().decode(errors="replace").strip()
                    if data:
                        tail = data.splitlines()[-1]
                except Exception:
                    tail = ""
            msg = ("navi.llamafile exited (code " + str(proc.returncode) +
                   ") before it started answering.")
            if tail:
                msg += " Last log line: " + tail
            msg += " Full log: navi.llamafile.log beside the app."
            return False, msg
        time.sleep(1)
    return False, ("navi.llamafile is still loading after two minutes — "
                   "its output is in navi.llamafile.log beside the app.")


def hardware_tier_name(detected):
    # The plain tier names (Build 14, #157): "potato" / "standard"
    # / "beast", derived from the detected hardware alone. These
    # sit alongside the derivation table's own tier words (fluid /
    # balanced / performance / workstation / constrained, kept in
    # the stored profile and its tierLabel) — this class is the
    # one the warm-up default and the profile view speak in.
    # Beast is judged first: a small-core-count machine with a
    # real GPU or workstation RAM is not a potato.
    d = detected if isinstance(detected, dict) else {}
    try:
        ram = float(d.get("totalRamGB") or 0)
    except Exception:
        ram = 0.0
    try:
        cores = int(d.get("cpuCores") or 0)
    except Exception:
        cores = 0
    try:
        vram = float(d.get("gpuVramGB") or 0)
    except Exception:
        vram = 0.0
    discrete = d.get("gpuKind") == "discrete"
    if (discrete and vram >= 8) or ram >= 32:
        return "beast"
    if (ram <= 12 and not discrete) or (cores and cores <= 4):
        return "potato"
    return "standard"


def _warm_at_value(raw):
    # runtime.warm_at, validated: a "HH:MM" 24h string, else None
    # (absent / null / malformed all read as off) (Build 14, #157).
    if not isinstance(raw, str):
        return None
    raw = raw.strip()
    parts = raw.split(":")
    if len(parts) != 2:
        return None
    try:
        hh = int(parts[0]); mm = int(parts[1])
    except Exception:
        return None
    if not (0 <= hh <= 23 and 0 <= mm <= 59):
        return None
    return "%02d:%02d" % (hh, mm)


def runtime_settings(cfg):
    # Her llamafile runtime settings, from the hardware profile the
    # installer wrote into the config (hardware_profile + runtime).
    # No profile (a pre-.34 config) -> the fluid floor.
    rt = cfg.get("runtime") or {}
    hp = (cfg.get("hardware_profile") or {}).get("settings") or {}
    def pick(a, b, fallback):
        v = rt.get(a)
        if v is None:
            v = hp.get(b)
        try:
            return int(v)
        except Exception:
            return fallback
    # Warm-up (Build 14, #157): runtime.warmup always wins when
    # the operator set it; unset, warm-up is on for the potato and
    # standard tiers and off for beast (a beast loads fast enough
    # that the dead air is not the problem). No profile at all —
    # the fluid floor, a modest machine by definition — reads as
    # on. runtime.warm_at is the scheduled warm ("HH:MM" or off).
    if rt.get("warmup") is not None:
        warmup = bool(rt.get("warmup"))
    else:
        detected = (cfg.get("hardware_profile") or {}).get("detected")
        warmup = (not isinstance(detected, dict)
                  or hardware_tier_name(detected) in ("potato", "standard"))
    return {
        "threads": pick("threads", "threads", 4),
        "ctx_size": pick("ctx_size", "ctxSize", 4096),
        "batch_size": pick("batch_size", "batchSize", 512),
        "gpu_layers": pick("gpu_layers", "gpuLayers", 0),
        "warmup": warmup,
        "warm_at": _warm_at_value(rt.get("warm_at")),
    }


def llamafile_args(cfg):
    s = runtime_settings(cfg)
    args = ["--server", "--v2", "--ctx-size", str(s["ctx_size"]),
            "--threads", str(s["threads"]), "--batch-size", str(s["batch_size"])]
    if s["gpu_layers"] > 0:
        args += ["--n-gpu-layers", str(s["gpu_layers"])]
    return args


def detect_hardware():
    # Real detection for /api/hardware/redetect — stdlib only, per-OS.
    # Linux: /proc + lspci/nvidia-smi. macOS: sysctl + system_profiler.
    # Windows: CIM via PowerShell. Anything unconfirmable stays
    # "unknown" rather than guessed — derivation treats it CPU-only.
    import platform as _pf
    det = {"os": "unknown", "osLabel": _pf.platform(), "cpuModel": _pf.processor() or "unknown CPU",
           "cpuCores": os.cpu_count() or 1, "performanceCores": None,
           "totalRamGB": 0.0, "gpuPresent": False, "gpuName": "", "gpuKind": "none", "gpuVramGB": None}
    system = _pf.system().lower()
    try:
        if system == "linux":
            det["os"] = "linux"; det["osLabel"] = "Linux"
            mem_kb = 0
            cpu_name = ""
            with open("/proc/meminfo") as f:
                for line in f:
                    if line.startswith("MemTotal:"):
                        mem_kb = int(line.split()[1])
            with open("/proc/cpuinfo") as f:
                for line in f:
                    if line.startswith("model name"):
                        cpu_name = line.split(":", 1)[1].strip(); break
            if cpu_name:
                det["cpuModel"] = cpu_name
            det["totalRamGB"] = round(mem_kb / 1048576.0, 1) if mem_kb else 0.0
            # Intel hybrid: performance cores are hard to prove from
            # /proc alone; the derivation's logical-core rule covers it.
            try:
                out = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"],
                                     capture_output=True, text=True, timeout=5).stdout.strip()
                if out:
                    parts = [p.strip() for p in out.splitlines()[0].split(",")]
                    det["gpuPresent"] = True; det["gpuName"] = parts[0]; det["gpuKind"] = "discrete"
                    if len(parts) > 1:
                        det["gpuVramGB"] = int(round(float(parts[1].split()[0]) / 1024.0))
                else:
                    raise RuntimeError("no nvidia-smi output")
            except Exception:
                try:
                    out = subprocess.run(["lspci"], capture_output=True, text=True, timeout=5).stdout
                    for line in out.splitlines():
                        if "VGA compatible controller" in line or "3D controller" in line:
                            det["gpuPresent"] = True
                            det["gpuName"] = line.split(":", 2)[-1].strip()
                            low = det["gpuName"].lower()
                            det["gpuKind"] = "discrete" if ("nvidia" in low or "radeon rx" in low or "geforce" in low) else "integrated"
                            break
                except Exception:
                    pass
        elif system == "darwin":
            det["os"] = "macos"; det["osLabel"] = "macOS"
            def _sysctl(key):
                return subprocess.run(["sysctl", "-n", key], capture_output=True, text=True, timeout=5).stdout.strip()
            det["cpuModel"] = _sysctl("machdep.cpu.brand_string") or det["cpuModel"]
            det["cpuCores"] = int(_sysctl("hw.ncpu") or det["cpuCores"])
            try:
                det["performanceCores"] = int(_sysctl("hw.perflevel0.logicalcpu") or 0) or None
            except Exception:
                det["performanceCores"] = None
            det["totalRamGB"] = round(int(_sysctl("hw.memsize") or 0) / 1073741824.0, 1)
            det["gpuPresent"] = True; det["gpuName"] = det["cpuModel"] + " GPU"; det["gpuKind"] = "integrated"
        elif system == "windows":
            det["os"] = "windows"; det["osLabel"] = "Windows"
            def _ps(expr):
                return subprocess.run(["powershell", "-NoProfile", "-Command", expr],
                                      capture_output=True, text=True, timeout=10).stdout.strip()
            det["cpuModel"] = _ps("(Get-CimInstance Win32_Processor | Select-Object -First 1).Name") or det["cpuModel"]
            det["cpuCores"] = int(_ps("(Get-CimInstance Win32_Processor | Select-Object -First 1).NumberOfLogicalProcessors") or det["cpuCores"])
            det["totalRamGB"] = round(int(_ps("(Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory") or 0) / 1073741824.0, 1)
            gpu_name = _ps("(Get-CimInstance Win32_VideoController | Select-Object -First 1).Name")
            if gpu_name:
                det["gpuPresent"] = True; det["gpuName"] = gpu_name
                low = gpu_name.lower()
                if "nvidia" in low or "geforce" in low or "radeon rx" in low:
                    det["gpuKind"] = "discrete"
                    vram = _ps("(Get-CimInstance Win32_VideoController | Select-Object -First 1).AdapterRAM")
                    try:
                        det["gpuVramGB"] = int(round(int(vram) / 1073741824.0)) or None
                    except Exception:
                        det["gpuVramGB"] = None
                else:
                    det["gpuKind"] = "integrated"
    except Exception:
        pass
    return det


def derive_hardware_settings(d):
    # The bridge's copy of the derivation table (hardware.ts is the
    # source of truth; the installers carry the same table in shell).
    ram = float(d.get("totalRamGB") or 0)
    logical = max(1, int(d.get("cpuCores") or 1))
    perf = d.get("performanceCores")
    reasoning = []
    if perf:
        threads = max(2, min(12, int(perf)))
        reasoning.append(f"Threads {threads}: matched to the {perf} performance cores.")
    elif logical >= 16:
        threads = 8; reasoning.append(f"Threads 8: half of {logical} logical cores, capped.")
    elif logical >= 8:
        threads = 4; reasoning.append(f"Threads 4: half of {logical} logical cores.")
    elif logical >= 4:
        threads = max(2, logical - 1); reasoning.append(f"Threads {threads}: one short of the {logical} logical cores — a flat 2 measured a third of this class's speed in #310; one core stays for the OS and the UI.")
    else:
        threads = 1; reasoning.append("Threads 1: single-core floor.")
    if ram < 6:
        ctx = PROMPT_FLOOR_CTX; reasoning.append(f"Context {PROMPT_FLOOR_CTX}: under 6 GiB RAM — floored at the product's prompt floor (#310): a smaller window cannot hold her standing prompt.")
    elif ram < 12:
        ctx = 4096; reasoning.append(f"Context 4096: {ram:.1f} GiB RAM — the proven fluid size for this class.")
    elif ram < 20:
        ctx = 8192; reasoning.append(f"Context 8192: {ram:.1f} GiB RAM leaves comfortable headroom.")
    elif ram < 40:
        ctx = 16384; reasoning.append(f"Context 16384: {ram:.1f} GiB RAM.")
    else:
        ctx = 32768; reasoning.append(f"Context 32768: {ram:.1f} GiB RAM — workstation headroom.")
    batch = 256 if ram < 6 else (512 if ram < 20 else 1024)
    reasoning.append(f"Batch {batch}: sized to RAM ({ram:.1f} GiB).")
    gpu_layers = 0
    vram = d.get("gpuVramGB")
    if d.get("gpuKind") == "discrete" and vram is not None and vram >= 4:
        gpu_layers = 99 if vram >= 12 else (28 if vram >= 8 else (20 if vram >= 6 else 12))
        reasoning.append(f"GPU layers {gpu_layers}: discrete GPU with {vram} GiB VRAM.")
    elif d.get("gpuKind") == "integrated":
        reasoning.append("GPU layers 0: integrated graphics share system RAM — CPU inference is the fluid path.")
    else:
        reasoning.append("GPU layers 0: no confirmed discrete GPU — CPU-only.")
    if ram < 6 or logical <= 4:
        tier, tier_label = "constrained", "Constrained — small machine, fluid floor"
    elif gpu_layers > 0 and ram >= 16:
        tier, tier_label = ("workstation", "Workstation — discrete GPU + ample RAM") if ram >= 32 else ("performance", "Performance — discrete GPU acceleration")
    elif ram >= 20:
        tier, tier_label = "performance", "Performance — ample RAM, CPU inference scaled up"
    elif ram >= 12:
        tier, tier_label = "balanced", "Balanced — above the fluid baseline"
    else:
        tier, tier_label = "fluid", "Fluid — Framework-class baseline"
    return {"threads": threads, "ctxSize": ctx, "batchSize": batch, "gpuLayers": gpu_layers}, tier, tier_label, reasoning


def _profile_source(hp):
    # Who wrote this hardware profile (Build 14, #157), as best
    # the config itself can say: the startup auto-profile pass
    # marks its block with auto=True and only that block reads as
    # "auto"; a Settings override is the operator's; anything else
    # with a profile is the installer's — pre-Build-14 profiles
    # wrote source "auto" for both the installer and a Settings
    # re-detect, and those two cannot be told apart after the
    # fact, so they read as "installer", their original writer.
    if hp.get("auto") is True:
        return "auto"
    src = str(hp.get("source") or "")
    if src == "manual":
        return "operator"
    if src in ("auto", "installer"):
        return "installer"
    return None


def hardware_profile_view(cfg):
    hp = cfg.get("hardware_profile")
    if isinstance(hp, dict) and hp.get("detected") and hp.get("settings"):
        view = dict(hp)
        s = runtime_settings(cfg)
        view["settings"] = {"threads": s["threads"], "ctxSize": s["ctx_size"], "batchSize": s["batch_size"], "gpuLayers": s["gpu_layers"]}
        view["flags"] = " ".join(llamafile_args(cfg)[2:])
        # Tier naming (Build 14, #157): the view's "tier" is the
        # plain potato / standard / beast class derived from the
        # detected hardware; the derivation table's own tier word
        # stays readable alongside it as "derivedTier" (and in
        # tierLabel, which the dashboard already shows).
        view["derivedTier"] = hp.get("tier")
        view["tier"] = hardware_tier_name(hp.get("detected") or {})
        view["profileSource"] = _profile_source(hp)
        return view
    return {"detected": None, "settings": runtime_settings(cfg), "source": "auto",
            "tier": None, "profileSource": None,
            "note": "No hardware profile in this config (it predates build .34) — the fluid floor is in use. Re-detect to profile this machine."}


def auto_profile_on_startup(cfg):
    # Automatic profiling (Build 14, #157): a config with NO
    # hardware profile used to run the fluid floor (4096/4/512)
    # forever — the machine never profiled itself. On bridge
    # startup, profile it once: detect + derive, persist the
    # profile, and fill derived runtime defaults ONLY where the
    # runtime keys are absent — operator-set runtime values are
    # never overridden. Any failure leaves the floor behavior
    # exactly as it was before this pass existed.
    try:
        hp = cfg.get("hardware_profile") if isinstance(cfg, dict) else None
        if isinstance(hp, dict) and hp.get("detected") and hp.get("settings"):
            return cfg
        detected = detect_hardware()
        settings, tier, tier_label, reasoning = derive_hardware_settings(detected)
        tier_name = hardware_tier_name(detected)
        now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        profile = {"detected": detected, "settings": settings, "autoSettings": settings,
                   "source": "auto", "auto": True, "tier": tier, "tierLabel": tier_label,
                   "reasoning": reasoning, "detectedAt": now,
                   "installLog": [f"[hardware] {now} — automatic profiling on bridge startup (Build 14, #157): this config carried no hardware profile",
                                  f"[hardware] CPU: {detected['cpuModel']} — {detected['cpuCores']} logical cores",
                                  f"[hardware] RAM: {detected['totalRamGB']} GiB",
                                  f"[hardware] GPU: {detected['gpuName'] or 'none'} ({detected['gpuKind']})",
                                  f"[hardware] Tier class: {tier_name}"] + [f"[hardware] → {r}" for r in reasoning]}
        fresh = load_config()
        hp2 = fresh.get("hardware_profile") if isinstance(fresh, dict) else None
        if isinstance(hp2, dict) and hp2.get("detected") and hp2.get("settings"):
            return fresh
        fresh["hardware_profile"] = profile
        rt = fresh.get("runtime") if isinstance(fresh.get("runtime"), dict) else {}
        rt = dict(rt)
        defaults = {"threads": settings["threads"], "ctx_size": settings["ctxSize"],
                    "batch_size": settings["batchSize"], "gpu_layers": settings["gpuLayers"]}
        filled = []
        for key, val in defaults.items():
            if rt.get(key) is None:
                rt[key] = val
                filled.append(key)
        if rt.get("flags") is None and len(filled) == len(defaults):
            rt["flags"] = (f"--ctx-size {settings['ctxSize']} --threads {settings['threads']} "
                           f"--batch-size {settings['batchSize']}"
                           + (f" --n-gpu-layers {settings['gpuLayers']}" if settings["gpuLayers"] > 0 else ""))
        fresh["runtime"] = rt
        if not save_config(fresh):
            print("Hardware profile: this config had none saved and the automatic "
                  "profile could not be written to the config file — the fluid "
                  "floor settings stay in use for this run.", flush=True)
            return cfg
        try:
            with open(os.path.join(ROOT, "hardware-profile.log"), "a") as f:
                for line in profile.get("installLog") or []:
                    f.write(line + "\n")
        except Exception:
            pass
        gpu_words = (("discrete GPU " + str(detected.get("gpuName") or "")) if detected.get("gpuKind") == "discrete"
                     else ("integrated graphics" if detected.get("gpuKind") == "integrated" else "no discrete GPU"))
        print("Hardware profile: this config had none saved, so Apex profiled this "
              "machine on startup and saved the profile — " + tier_name + " tier: "
              + str(detected.get("totalRamGB")) + " GiB RAM, "
              + str(detected.get("cpuCores")) + " CPU cores, " + gpu_words + ". "
              "Navi will run with context " + str(settings["ctxSize"])
              + ", threads " + str(settings["threads"])
              + ", batch " + str(settings["batchSize"])
              + ". Any runtime settings you set yourself were left untouched.",
              flush=True)
        return fresh
    except Exception as e:
        print("Hardware profile: automatic profiling on startup did not run ("
              + str(e) + ") — the fluid floor settings stay in use, exactly as before.",
              flush=True)
        return cfg


def save_hardware_profile(profile):
    cfg = load_config()
    # Warm-up keys round-trip (Build 14, #157): a re-detect or an
    # override rewrites the runtime block from the profile below,
    # but runtime.warmup / runtime.warm_at are operator choices
    # that live only in that block — capture them before the
    # rewrite and carry them over, never drop them.
    _prev_rt = cfg.get("runtime") if isinstance(cfg.get("runtime"), dict) else {}
    cfg["hardware_profile"] = profile
    s = profile["settings"]
    cfg["runtime"] = {"threads": s["threads"], "ctx_size": s["ctxSize"], "batch_size": s["batchSize"], "gpu_layers": s["gpuLayers"],
                      "flags": f"--ctx-size {s['ctxSize']} --threads {s['threads']} --batch-size {s['batchSize']}" + (f" --n-gpu-layers {s['gpuLayers']}" if s["gpuLayers"] > 0 else "")}
    for _k in ("warmup", "warm_at"):
        if _k in _prev_rt:
            cfg["runtime"][_k] = _prev_rt[_k]
    with open(CONFIG_PATH, "w") as f:
        json.dump(cfg, f, indent=2)
    try:
        with open(os.path.join(ROOT, "hardware-profile.log"), "a") as f:
            for line in profile.get("installLog") or []:
                f.write(line + "\n")
    except Exception:
        pass
    # v0.7.3e (#402): a runtime change is a systems event —
    # this function is the single writer of the runtime
    # block, so the diff is known exactly, old against new.
    # A first save (no previous runtime) records nothing:
    # there was no change, only a beginning.
    try:
        if _prev_rt:
            _new_rt = cfg.get("runtime") or {}
            _diff = []
            for _k, _label in (("threads", "threads"),
                               ("batch_size", "batch"),
                               ("ctx_size", "context"),
                               ("gpu_layers", "gpu layers")):
                if _prev_rt.get(_k) != _new_rt.get(_k):
                    _diff.append(_label + " " + str(_prev_rt.get(_k))
                                 + " \u2192 " + str(_new_rt.get(_k)))
            if _diff:
                systems_event_append("runtime-change",
                                     "; ".join(_diff))
    except Exception:
        pass
    return cfg


def _warmup_completion(endpoint, cfg):
    # One throwaway completion (Build 14, #157): the same chat
    # completions shape llamafile_chat builds, capped at a single
    # token, with a one-word prompt that is never shown anywhere.
    # Its only job is to make the model do its first real work —
    # page in, caches hot — before the operator's first ask, so
    # the first-ask dead air happens here instead. A failure is a
    # log line, never an error: warm-up is a courtesy, not a gate.
    try:
        name = served_model(endpoint) or (cfg.get("live") or {}).get("model_name") or "navi"
        body = json.dumps({
            "model": name,
            "messages": [{"role": "user", "content": "Hi"}],
            "stream": False,
            "max_tokens": 1,
        }).encode()
        req = urllib.request.Request(
            endpoint.rstrip("/") + "/chat/completions",
            data=body,
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=120) as resp:
            resp.read()
        print("Warm-up: navi.llamafile answered a one-token warm-up "
              "completion — the model is warm for the first ask.", flush=True)
        return True
    except Exception as e:
        print("Warm-up: the warm-up completion did not finish (" + str(e)
              + ") — Navi will simply warm up on the first ask instead.",
              flush=True)
        return False


def _maybe_warmup_llamafile(cfg, endpoint):
    # Fire the warm-up on its own daemon thread (Build 14, #157):
    # the start that triggered it has already reported healthy and
    # must not wait on a generation, however small. Whether it
    # fires at all is runtime_settings' call (explicit
    # runtime.warmup wins; the tier decides when it is unset).
    try:
        if not runtime_settings(cfg)["warmup"]:
            return False
    except Exception:
        return False
    threading.Thread(target=_warmup_completion, args=(endpoint, cfg),
                     daemon=True).start()
    return True


def _warm_at_loop():
    # Scheduled warm (Build 14, #157): a lightweight timer that
    # checks once a minute for runtime.warm_at ("HH:MM", 24h;
    # absent/null = off). At the configured minute, a llamafile
    # that is not answering is started through the same start
    # path the dashboard's Connect uses — and that fresh start
    # warms it via the warm-on-start hook above. One fire per
    # configured minute per day. (Looked for an existing minute-
    # cadence thread to ride first: the backup loop sleeps 30
    # minutes and the update loop 3 hours, so this is its own.)
    fired_for = ""
    while True:
        time.sleep(60)
        try:
            cfg = load_config()
            warm_at = runtime_settings(cfg)["warm_at"]
            if not warm_at:
                continue
            now = time.localtime()
            if time.strftime("%H:%M", now) != warm_at:
                continue
            stamp = time.strftime("%Y-%m-%d", now) + " " + warm_at
            if fired_for == stamp:
                continue
            fired_for = stamp
            endpoint = cfg.get("live", {}).get("llamafile_endpoint", "http://localhost:8080/v1")
            if llamafile_alive(endpoint):
                continue
            if cfg.get("startup", "on-ui-launch") == "on-boot":
                # Boot mode owns the server (same rule as Connect):
                # the bridge never spawns a second copy behind the
                # service's back, scheduled or not.
                print("Scheduled warm (" + warm_at + "): navi.llamafile is not "
                      "answering, but this install starts it at system boot — "
                      "leaving it to the boot service.", flush=True)
                continue
            print("Scheduled warm (" + warm_at + "): navi.llamafile is not "
                  "answering — starting and warming it now.", flush=True)
            ok, error = start_llamafile(cfg, endpoint)
            if not ok:
                print("Scheduled warm (" + warm_at + "): the start did not "
                      "come up: " + str(error), flush=True)
        except Exception:
            pass


def start_llamafile(cfg, endpoint):
    # App-load mode owns the server process: the bridge starts it
    # with the app's one launch command — ./navi.llamafile --server
    # --v2 plus the runtime flags from the hardware profile in the
    # config (see runtime_settings) — never a hard-coded set.
    # Returns (ok, error). Output goes to navi.llamafile.log next to
    # the binary so a failed start is diagnosable, not silent.
    global _llamafile_proc
    if _llamafile_proc is not None and _llamafile_proc.poll() is None:
        return wait_for_llamafile(endpoint, _llamafile_proc)
    # Single-start ownership (v0.7.0e, #363): this bridge is not
    # the only launcher — navi-llamafile.service and start.sh
    # start the same engine, and on the 2026-11-21 boot both
    # spawned her at once and lost the 8080 bind. So before any
    # spawn: an endpoint that already answers is another owner's
    # server — defer through the wait path WITHOUT spawning,
    # without claiming _llamafile_proc, and without the warm-up
    # below (only the fresh-start path warms; this is a probe,
    # not a start).
    if llamafile_alive(endpoint):
        systems_event_append("engine-defer")
        return wait_for_llamafile(endpoint, None)
    # A foreign navi.llamafile process with a silent port is an
    # owner mid-start — the model is still loading, which is
    # exactly the window the old port-only check raced. Wait
    # for its endpoint up to the same load window
    # wait_for_llamafile uses; if it answers, defer (ok, not
    # ours). If the foreign process DIES without answering, its
    # owner is named and this call does NOT spawn: the dead
    # owner's launcher (the service's Restart, start.sh) owns
    # the retry, and a spawn here would be the race returning
    # through the back door.
    if not _llamafile_foreign_pids():
        # Look twice before spawning (v0.7.0e campaign
        # correction): a foreign owner between fork and exec
        # is invisible to one scan — its cmdline is not the
        # engine's yet. One short beat and a second look
        # closes that window; a genuine cold start pays a
        # fraction of a second, a race loses its teeth.
        time.sleep(0.3)
        if llamafile_alive(endpoint):
            systems_event_append("engine-defer")
            return wait_for_llamafile(endpoint, None)
    if _llamafile_foreign_pids():
        for _ in range(120):
            if llamafile_alive(endpoint):
                systems_event_append("engine-defer")
                return True, None
            if not _llamafile_foreign_pids():
                systems_event_append(
                    "engine-failed",
                    "a start by another owner (the service or "
                    "another launcher) died before answering")
                return False, (
                    "navi.llamafile was started by another owner "
                    "(the service or another launcher) and died "
                    "before answering — its output is in "
                    "navi.llamafile.log beside the app.")
            time.sleep(1)
        return False, ("navi.llamafile is still loading after two "
                       "minutes — its output is in "
                       "navi.llamafile.log beside the app.")
    binary = llamafile_binary(cfg)
    if not binary:
        searched = os.path.expanduser(cfg.get("install_dir") or ROOT)
        systems_event_append(
            "engine-failed",
            "navi.llamafile was not found in " + searched)
        return False, ("navi.llamafile was not found in " + searched +
                       " — run the installer so it can download the model server.")
    log_path = os.path.join(os.path.dirname(binary), "navi.llamafile.log")
    try:
        log = open(log_path, "ab")
    except Exception:
        log = subprocess.DEVNULL
    try:
        _llamafile_proc = subprocess.Popen(
            [binary] + llamafile_args(cfg),
            cwd=os.path.dirname(binary),
            stdout=log,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
    except Exception as e:
        systems_event_append("engine-failed",
                             "the spawn itself failed: " + str(e)[:160])
        return False, "Could not start navi.llamafile: " + str(e)
    ok, error = wait_for_llamafile(endpoint, _llamafile_proc, log_path)
    # v0.7.3e (#402): the fresh start is a systems event,
    # landed or failed — recorded from the outcome itself.
    if ok:
        systems_event_append("engine-start")
    else:
        systems_event_append("engine-failed", str(error or "")[:200])
    if ok:
        # Warm-on-start (Build 14, #157): this bridge just started
        # the server and it reports healthy — fire ONE warm-up
        # completion on a daemon thread so the model-load dead air
        # is spent now, not on the operator's first ask. Only the
        # fresh-start path warms: the already-running return at the
        # top of this function is a probe, not a start.
        _maybe_warmup_llamafile(cfg, endpoint)
    return ok, error


_served_model_cache = {}


def served_model(endpoint):
    # The model id the server itself reports (GET /v1/models). Asking
    # beats assuming: the name baked into a llamafile is whatever its
    # builder chose, and a server that validates the model string
    # rejects a guessed one. Cached per endpoint; None when the
    # server won't say (callers fall back to the configured name).
    if endpoint in _served_model_cache:
        return _served_model_cache[endpoint]
    found = None
    try:
        with urllib.request.urlopen(endpoint.rstrip("/") + "/models", timeout=5) as resp:
            data = json.loads(resp.read().decode())
        entries = data.get("data") or []
        if entries and entries[0].get("id"):
            found = str(entries[0]["id"])
    except Exception:
        found = None
    _served_model_cache[endpoint] = found
    return found


# A chat request is always bounded. Left unbounded, the server
# generates until the model emits its end token or the context
# fills — and a model that doesn't stop on its own (a base-style
# model in a chat template can ramble for thousands of tokens)
# keeps a CPU busy far past any reasonable wait while the
# dashboard shows "thinking…". That was the "she is not chatting"
# failure, reproduced against this bridge: no max_tokens rode
# along, the generation outran the old 120-second socket timeout,
# and the request died misreporting a healthy, answering server
# as "unreachable" — from the operator's chair, Navi simply never
# replied. max_tokens caps the work; the wait is sized to let a
# bounded reply finish even at slow CPU generation speeds.
CHAT_MAX_TOKENS = 1024
CHAT_HISTORY_MESSAGES = 24
CHAT_TIMEOUT = 600


def _chat_sanitize_messages(messages):
    # Build 6 (#224): the model server refuses a request carrying
    # ANY message with empty content (HTTP 400 "message must not
    # have empty content") — one hollow entry anywhere in the
    # history kills the whole answer. The field shape was a call:
    # a stored thread entry with no text (an exec-only or
    # placeholder row the dashboard's history builder passed
    # through) rode into the call's request and Navi's answer died
    # on it. The builder is the one funnel every chat request —
    # typed, called, or borrowed-back — passes through, so the
    # guard lives here: entries whose content is empty or
    # whitespace-only are dropped before the request is built.
    # A list with nothing left is a caller bug, and it is named
    # rather than sent on to be refused.
    out = []
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        content = m.get("content")
        if content is None or not str(content).strip():
            continue
        out.append(m)
    if not out:
        raise RuntimeError(
            "the conversation held nothing the model could answer "
            "— every message in it was empty. Nothing was sent.")
    return out


# ---------------------------------------------------------------------
# The local prompt budget (v0.6.7e, #310).
#
# Until this build the local chat path measured NOTHING: the
# assembly appended block after block every turn (persona,
# Guardian, vitals, the intel brief, awareness, shell and case
# teaching, the Row, the case brief) and handed the result to a
# context the hardware profile had derived from RAM alone —
# 4096 on the 6–12 GiB class. On such a seat the standing
# prompt alone overflowed the window and EVERY local chat died
# at the model with out_of_context_due_to_long_message. The
# lend door has measured since Build 8 (#154) — refused whole,
# never truncated; the local path now keeps the same discipline
# with the opposite hand: it sheds BACKGROUND, lowest-value
# first, and never the operator's words. Three instruments:
#
#   * conditional teaching — the shell teaching rides only a
#     machine-directed turn (the #240 gate's own read), the
#     case teaching only a case-shaped one (a case bound or
#     open, or the turn naming case work);
#   * per-block caps — no single dynamic brief may eat the
#     window; an over-cap block is trimmed and the trim named;
#   * the budget itself — assembled prompt vs the seat's own
#     ctx_size (the lend estimator, shared), a reply's room
#     reserved (CHAT_MAX_TOKENS), background segments shed in
#     a fixed order, then per-turn system extras, then the
#     oldest history — and if even the standing core does not
#     fit, an honest named refusal instead of a dead model
#     call. The accounting rides the turn's payload as its
#     readout (promptBudget), so the size of her prompt is a
#     fact on the record, not a mystery in the field.
PROMPT_FLOOR_CTX = 4096
PROMPT_BLOCK_CAP_CHARS = 6000


def estimate_messages_tokens(messages):
    # The one estimator: four chars to a token plus a small
    # per-message frame — the lend door's arithmetic, shared.
    total = 0
    for m in messages or []:
        if isinstance(m, dict):
            total += len(str(m.get("content") or "")) // 4 + 4
    return total


def prompt_budget_apply(segments, rest, ctx_size):
    # segments: [{name, text, shed, cap}] in standing order —
    # shed is the shedding order (1 sheds first) or None for
    # the standing core, which never sheds. rest: the messages
    # after the system message; per-turn system extras in it
    # carry a "_budget_name" tag naming their drop order.
    # Returns (messages, report).
    try:
        ctx = int(ctx_size or 0)
    except Exception:
        ctx = 0
    if ctx <= 0:
        msgs = [{"role": "system",
                 "content": "\n\n".join(s["text"] for s in segments if s.get("text"))}] + list(rest)
        return msgs, {"estTokens": estimate_messages_tokens(msgs),
                      "ctxSize": ctx, "budgetTokens": 0, "shed": [],
                      "overflow": False}
    reserve = CHAT_MAX_TOKENS
    budget = ctx - reserve if ctx > reserve else ctx
    segs = [dict(s) for s in segments]
    shed = []
    for s in segs:
        if s.get("cap") and len(s.get("text") or "") > PROMPT_BLOCK_CAP_CHARS:
            s["text"] = (s["text"][:PROMPT_BLOCK_CAP_CHARS]
                         + "\n… (trimmed to this seat's prompt budget)")
            shed.append(s["name"] + " (trimmed)")

    def compose():
        return "\n\n".join(s["text"] for s in segs if s.get("text"))

    def total():
        return estimate_messages_tokens(
            [{"role": "system", "content": compose()}] + list(rest))

    est = total()
    if est > budget:
        for s in sorted((s for s in segs if s.get("shed") is not None),
                        key=lambda s: s["shed"]):
            if est <= budget:
                break
            if s.get("text"):
                s["text"] = ""
                shed.append(s["name"])
                est = total()
    if est > budget:
        for name in ("intel-seam", "rag", "shelf-ref"):
            while est > budget:
                kept, dropped = [], False
                for m in rest:
                    if not dropped and isinstance(m, dict) \
                            and m.get("_budget_name") == name:
                        dropped = True
                        shed.append(name)
                        continue
                    kept.append(m)
                if not dropped:
                    break
                rest = kept
                est = total()
    if est > budget:
        # History sheds oldest-first; the operator's current
        # turn (the last conversation message) never sheds.
        while est > budget:
            conv = [i for i, m in enumerate(rest)
                    if isinstance(m, dict) and m.get("role") != "system"]
            if len(conv) <= 1:
                break
            rest = rest[:conv[0]] + rest[conv[0] + 1:]
            shed.append("history")
            est = total()
    for m in rest:
        if isinstance(m, dict):
            m.pop("_budget_name", None)
    msgs = [{"role": "system", "content": compose()}] + list(rest)
    # v0.7.10e (#429): the standing mass is measured and
    # named on every report — the never-shed core's own
    # weight, and its fraction of the seat's context. The
    # field failure was a standing prompt at ~89% of a 7k
    # seat, discovered only when a turn died on it; a
    # standing core past three-fifths of the context is
    # now a named warning on the report itself, before
    # any turn has to die.
    _standing_text = "\n\n".join(
        s["text"] for s in segs
        if s.get("shed") is None and s.get("text"))
    _standing_tokens = estimate_messages_tokens(
        [{"role": "system", "content": _standing_text}]) \
        if _standing_text else 0
    return msgs, {"estTokens": est, "ctxSize": ctx,
                  "budgetTokens": budget, "shed": shed,
                  "overflow": est > budget,
                  "standingTokens": _standing_tokens,
                  "standingFraction": round(_standing_tokens / ctx, 3) if ctx else 0,
                  "standingWarning": bool(ctx and _standing_tokens > 0.6 * ctx)}


def llamafile_chat(messages, endpoint, model, vitals_kind="turn"):
    # Guardian (Build 14, #156): every local generation is timed
    # and counted. The counter is what Guardian's is_generating
    # callback reads (pressure judges stricter mid-generation),
    # and the duration is what note_generation() learns slow-
    # generation collisions from. The return contract — the
    # reply text, or the same RuntimeErrors — is unchanged: this
    # wrapper only observes the call it wraps.
    messages = _chat_sanitize_messages(messages)
    _gen_t0 = time.time()
    with _GENERATION_LOCK:
        _GENERATION_ACTIVE["count"] += 1
    try:
        result, _gen_server = _llamafile_chat_impl(messages, endpoint, model)
    finally:
        with _GENERATION_LOCK:
            _GENERATION_ACTIVE["count"] = max(0, _GENERATION_ACTIVE["count"] - 1)
        try:
            GUARDIAN.note_generation(time.time() - _gen_t0)
        except Exception:
            pass
    # #187: the bridge's own stopwatch — the only numbers
    # about her speed that exist. Runs only on success (an
    # exception propagates past this point): a failed request
    # never replaces the last good measurement.
    try:
        _record_model_vitals(time.time() - _gen_t0,
                             server=_gen_server, kind=vitals_kind)
    except Exception:
        pass
    return result


def _llamafile_chat_impl(messages, endpoint, model):
    # The llamafile server rejects a chat request whose JSON has no
    # "model" string (400 "JSON missing model string"), so a model
    # name rides along on every request — the id the server reports
    # for itself when it will say, otherwise the configured name.
    name = served_model(endpoint) or model
    body = json.dumps({
        "model": name,
        "messages": messages,
        "stream": False,
        "max_tokens": CHAT_MAX_TOKENS,
    }).encode()
    req = urllib.request.Request(
        endpoint.rstrip("/") + "/chat/completions",
        data=body,
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=CHAT_TIMEOUT) as resp:
            data = json.loads(resp.read().decode())
    except ValueError:
        # v0.6.10e (#278): a 200 whose body is not JSON is not an
        # answer — the server (or something answering for it) sent
        # a page, not a completion. Name the state; never hand
        # the operator a parse error dressed as a reply.
        raise ModelNotReadyError(_not_ready_from_probe(endpoint))
    except urllib.error.HTTPError as e:
        # Surface the server's own words — a bare "HTTP Error 400"
        # hides the reason it actually gave.
        try:
            detail = e.read().decode(errors="replace").strip()
        except Exception:
            detail = ""
        if e.code == 503 or detail.startswith("<"):
            # v0.6.10e (#278): a loading server's 503, or an HTML
            # page standing where an API answer belongs, is not a
            # rejection — the model simply is not ready, and the
            # page is never passed through as the error's text.
            raise ModelNotReadyError(_not_ready_from_probe(endpoint))
        raise RuntimeError(
            "the llamafile server rejected the chat request (HTTP "
            + str(e.code) + ")" + ((": " + detail) if detail else "")
        )
    except TimeoutError:
        # The server is up — it was still generating when the wait
        # ran out. Saying "unreachable" here once sent the operator
        # hunting for a dead server that was never dead.
        raise RuntimeError(
            "navi.llamafile was still generating her answer after "
            + str(CHAT_TIMEOUT // 60) + " minutes, so the wait ran "
            "out — the server is up; the model is just slower than "
            "that on this machine right now. The request was "
            "bounded (" + str(CHAT_MAX_TOKENS) + " tokens at most), "
            "so sending the message again is safe."
        )
    except urllib.error.URLError as e:
        reason = getattr(e, "reason", e)
        if isinstance(reason, TimeoutError) or "timed out" in str(reason):
            raise RuntimeError(
                "navi.llamafile was still generating her answer "
                "when the wait ran out — the server is up; the "
                "model is just slower than the wait on this "
                "machine right now. Sending the message again "
                "is safe."
            )
        # v0.6.10e (#278): unreachable is a named state, not an
        # error string — the chat route renders it as itself.
        raise ModelNotReadyError("unreachable")
    except (http.client.HTTPException, ConnectionError):
        # v0.6.10e (#278): the server dropped the exchange
        # mid-flight (RemoteDisconnected and its kin arrive
        # unwrapped, past every handler above). The state is
        # the same: unreachable, named — never the raw string.
        raise ModelNotReadyError("unreachable")
    if not isinstance(data, dict):
        # Valid JSON in the wrong shape is still not an answer.
        raise ModelNotReadyError(_not_ready_from_probe(endpoint))
    # #187: the server's own account of the generation rides
    # home for the vitals record (llama.cpp servers report
    # timings — predicted_n/predicted_ms/prompt_ms — and the
    # OpenAI-shaped usage counts). Cleared as it is stashed,
    # so a response carrying neither never inherits the
    # previous request's figures.
    # v0.7.8e (#418): the figures also RETURN with the call,
    # so the wrapper records the generation that actually ran
    # — the shared snapshot below is kept as a witness, but
    # two calls in flight no longer wear each other's numbers
    # through it.
    _gen_server = {
        "timings": data.get("timings"),
        "usage": data.get("usage"),
    }
    _LAST_GEN_SERVER.clear()
    _LAST_GEN_SERVER.update(_gen_server)
    try:
        content = data["choices"][0]["message"]["content"]
    except Exception:
        # A completion-shaped reply with no completion in it:
        # the upstream did not really answer. Name the state.
        raise ModelNotReadyError(_not_ready_from_probe(endpoint))
    if not (content or "").strip():
        # An empty reply renders as silence in the thread — the
        # same "she is not chatting" symptom by another road. Name
        # it where the operator can see it instead.
        raise RuntimeError(
            "navi.llamafile answered with an empty reply — the "
            "model ended its turn without saying anything. Sending "
            "the message again usually gets a real answer."
        )
    return content, _gen_server


# --- Sync tombstones (0.2.0e Build 3, issues #176/#177) -------------
# A deletion on one machine must never resurrect from another
# machine's copy. Convergence (below) never deletes — it only
# merges — so a delete needs its own travelling record: the
# tombstone, {kind: {key: deletion epoch}}, kept in
# config/sync-state.json beside the store it describes and carried
# by every Quick Sync payload. The funnels that delete record
# here: chat_delete and the write-through's removals (chats),
# case_delete (cases), and the Vault's delete paths (notes).
# Stored backups are snapshots and are NEVER reached into — a
# tombstone governs convergence between live machines only; the
# copy inside an old backup stays in that backup (the #163 law).
# v0.8.2e (#467): the set also rides a GitHub backup
# (sync/tombstones.json, on the Vault's tick) and merges
# on import — the #163 law is untouched (a backup's
# stored bytes are never reached into), but a restore
# now JUDGES by the tombstones before it re-deals a
# vault file, and refuses the deleted ones by name.
# A tombstone yields to newer work: if the surviving copy carries
# a stamp LATER than the deletion, the copy wins and the tombstone
# is dropped — a thread genuinely continued after its deletion
# elsewhere is not a resurrection.
#
# v0.6.19e (#365): a CLEAR is a tombstone too — the "clears" kind.
# Emptying a thread is not a deletion (the thread stands; its
# history up to a point retires), so the entry is not a bare
# epoch: {key: {"at": epoch ms, "account": owner login, "seat":
# seat name}} — a point in the thread's history, ordered against
# message stamps on the same millisecond basis the page and the
# bridge both stamp, composing by max. The account rides the
# entry because the machinery is account gated (#337, ruled
# 2026-11-21): a clear is applied only by a seat signed in to
# the account that spoke it, and a refusal is named, never
# silent. Keys follow chat_delete's dual discipline — the
# thread's id and its conversation key; the main family also
# records under the canonical "1", since every seat's main is
# id "1" but each was born under its own conversation key.
SYNC_STATE_PATH = os.path.join(ROOT, "config", "sync-state.json")
_SYNC_TOMBSTONE_KEEP_SECONDS = 90 * 86400
_sync_state_cache = {"mtime": None, "state": None}


def _sync_state_load():
    # Read-through cache on the file's mtime: the state is small,
    # written rarely, and read by hot paths (every chat delete).
    try:
        mtime = os.path.getmtime(SYNC_STATE_PATH)
    except Exception:
        mtime = None
    if _sync_state_cache["state"] is not None and _sync_state_cache["mtime"] == mtime:
        return _sync_state_cache["state"]
    state = {"tombstones": {"chats": {}, "cases": {}, "vault": {}, "daybook": {},
                             "clears": {}},
             "lastSyncAt": None, "lastSyncEpoch": 0, "lastResult": "",
             "lastTrigger": "", "lastState": ""}
    try:
        with open(SYNC_STATE_PATH, encoding="utf-8") as f:
            raw = json.load(f)
        if isinstance(raw, dict):
            state.update({k: raw[k] for k in state if k in raw})
            tombs = raw.get("tombstones")
            if isinstance(tombs, dict):
                for kind in ("chats", "cases", "vault", "dossier", "daybook"):
                    if isinstance(tombs.get(kind), dict):
                        state["tombstones"][kind] = {
                            str(k): float(v) for k, v in tombs[kind].items()
                            if isinstance(v, (int, float))}
                if isinstance(tombs.get("clears"), dict):
                    kept = {}
                    for k, v in tombs["clears"].items():
                        e = _clear_entry_norm(v)
                        if e is not None:
                            kept[str(k)] = e
                    state["tombstones"]["clears"] = kept
    except Exception:
        pass
    _sync_state_cache["mtime"] = mtime
    _sync_state_cache["state"] = state
    return state


def _sync_state_save(state):
    try:
        os.makedirs(os.path.dirname(SYNC_STATE_PATH), exist_ok=True)
        tmp = SYNC_STATE_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)
        os.replace(tmp, SYNC_STATE_PATH)
        try:
            _sync_state_cache["mtime"] = os.path.getmtime(SYNC_STATE_PATH)
        except Exception:
            _sync_state_cache["mtime"] = None
        _sync_state_cache["state"] = state
    except Exception:
        pass


def _clear_entry_norm(v):
    # A clear tombstone's entry, normalized: the object shape
    # {"at": epoch ms, "account": login, "seat": name}; a bare
    # number is a legacy epoch with no account named (it will be
    # refused at the gate — unknown is not a pass). Anything
    # else is not an entry.
    if isinstance(v, dict):
        at = v.get("at")
        if isinstance(at, (int, float)) and not isinstance(at, bool) and at > 0:
            return {"at": float(at),
                    "account": str(v.get("account") or "")[:120],
                    "accountSeat": _account_clean(v.get("accountSeat")) if v.get("accountSeat") else "",
                    "seat": str(v.get("seat") or "")[:80]}
        return None
    if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0:
        return {"at": float(v), "account": "", "seat": ""}
    return None


def _sync_tombstones_pruned(tombs, now=None):
    now = now if now is not None else time.time()
    out = {}
    for kind in ("chats", "cases", "vault", "entries", "dossier", "daybook", "fedinets"):
        rows = tombs.get(kind) if isinstance(tombs, dict) else None
        out[kind] = {}
        if isinstance(rows, dict):
            for k, v in rows.items():
                if isinstance(v, (int, float)) and now - float(v) <= _SYNC_TOMBSTONE_KEEP_SECONDS:
                    out[kind][str(k)] = float(v)
    # The clears kind keeps on the same 90-day law, read on its
    # own millisecond basis.
    out["clears"] = {}
    rows = tombs.get("clears") if isinstance(tombs, dict) else None
    if isinstance(rows, dict):
        for k, v in rows.items():
            e = _clear_entry_norm(v)
            if e is not None and now * 1000.0 - e["at"] <= _SYNC_TOMBSTONE_KEEP_SECONDS * 1000.0:
                out["clears"][str(k)] = e
    return out


def sync_record_tombstone(kind, key, at=None):
    # The deletion funnels' one call. Best-effort by design: a
    # tombstone that fails to record must never fail the delete
    # the operator asked for — the delete itself already happened.
    if kind not in ("chats", "cases", "vault", "entries", "dossier", "daybook", "fedinets") or not key:
        return
    try:
        state = _sync_state_load()
        tombs = _sync_tombstones_pruned(state.get("tombstones") or {})
        when = float(at) if at else time.time()
        prev = tombs[kind].get(str(key))
        if prev is None or when > prev:
            tombs[kind][str(key)] = when
        state["tombstones"] = tombs
        _sync_state_save(state)
        sync_note_write("tombstone")
    except Exception:
        pass


def _sync_merge_tombstones(local, remote):
    # Union by key, newest deletion wins — a tombstone one machine
    # has not seen yet must survive every round until it ages out,
    # or the delete it guards could resurrect from the one machine
    # that missed it. Clears compose the same way, by their "at".
    merged = _sync_tombstones_pruned(local or {})
    for kind, rows in _sync_tombstones_pruned(remote or {}).items():
        for k, v in rows.items():
            if kind == "clears":
                cur = merged["clears"].get(k)
                if cur is None or v["at"] > cur["at"]:
                    merged["clears"][k] = v
                continue
            if k not in merged[kind] or v > merged[kind][k]:
                merged[kind][k] = v
    return merged


def _clear_keys_for(rec):
    # The keys a thread's clear tombstone is recorded — and read —
    # under: its id, its conversation key, and (main family) the
    # canonical main id, per the section header.
    keys = []
    if isinstance(rec, dict):
        cid = str(rec.get("id") or "")
        if cid:
            keys.append(cid)
        try:
            ck = _chat_conv_tomb_key(rec)
            if ck not in keys:
                keys.append(ck)
        except Exception:
            pass
        if _chat_is_main_family(rec) and MAIN_CHAT_ID not in keys:
            keys.append(MAIN_CHAT_ID)
    return keys


def _clear_epoch_for(rec, tombs=None):
    # The newest clear epoch a tombstone speaks for this thread,
    # or 0. Reads the local sync state unless a tombstone set is
    # handed in.
    try:
        if tombs is None:
            tombs = _sync_state_load().get("tombstones") or {}
        rows = _sync_tombstones_pruned(tombs).get("clears") or {}
        best = 0.0
        for key in _clear_keys_for(rec):
            e = rows.get(key)
            if e is not None and e["at"] > best:
                best = e["at"]
        return best
    except Exception:
        return 0.0


def sync_record_clear(rec, at=None, account="operator"):
    # A clear act's one recording call, from the store door
    # (chat_write) when a write advances a thread's clear epoch
    # outside a sync round. The entry is stamped with this
    # seat's account — the gate on the far side admits only its
    # own account's clears. Best-effort like every tombstone: a
    # record that fails must never fail the clear itself.
    try:
        when = float(at) if at else float(int(time.time() * 1000))
        login = ""
        try:
            login = str((github_auth() or {}).get("login") or "")
        except Exception:
            login = ""
        entry = {"at": when, "account": login,
                 "accountSeat": _account_clean(account),
                 "seat": _chat_seat_name()}
        state = _sync_state_load()
        tombs = _sync_tombstones_pruned(state.get("tombstones") or {})
        for key in _clear_keys_for(rec):
            prev = tombs["clears"].get(key)
            if prev is None or when > prev["at"]:
                tombs["clears"][key] = dict(entry)
        state["tombstones"] = tombs
        _sync_state_save(state)
        sync_note_write("tombstone")
    except Exception:
        pass


def _sync_gate_clears(rows):
    # The account gate on arriving clears (#365, #337): an entry
    # is admitted only when the account it is stamped with and
    # this seat's signed-in login are both present and equal —
    # the #323 doctrine, unknown is a refusal, never a pass.
    # Returns (admitted, refused[(key, stamped account)]).
    mine = ""
    try:
        mine = str((github_auth() or {}).get("login") or "")
    except Exception:
        mine = ""
    admitted, refused = {}, []
    for k, v in (rows or {}).items():
        e = _clear_entry_norm(v)
        if e is None:
            continue
        if e["account"] and mine and e["account"].lower() == mine.lower():
            admitted[str(k)] = e
        else:
            refused.append((str(k), e["account"]))
    return admitted, refused


def _sync_note_foreign_refusal(state, kind, account, key=""):
    # Name a foreign refusal in a sync state dict (the caller
    # saves): the latest stands on its own field, and the last
    # twenty ride a capped ledger — the sync log's record that
    # a foreign artifact knocked and was turned away, and whose
    # account it was stamped with.
    try:
        entry = {"at": time.time(), "kind": str(kind or ""),
                 "account": str(account or ""), "key": str(key or "")}
        state["lastForeignRefusal"] = entry
        rows = state.get("foreignRefusals")
        rows = list(rows) if isinstance(rows, list) else []
        rows.append(entry)
        state["foreignRefusals"] = rows[-20:]
    except Exception:
        pass


def _sync_foreign_refusal_note(kind, account, key=""):
    # _sync_note_foreign_refusal against the stored state, for
    # callers that hold no state of their own (the Mesh legs).
    try:
        state = _sync_state_load()
        _sync_note_foreign_refusal(state, kind, account, key)
        _sync_state_save(state)
    except Exception:
        pass


# --- Server-side chats (0.1.9e Build 12, issue #139) -----------------
# Chats lived only in browser localStorage (navi.chats) until this
# build: every install — and every browser origin — held its own
# set, and DHD into the server was continuous with the server only
# through the server's own browser. The store of record now lives
# HERE, in plain files under config/chats/ — one JSON file per chat
# (the Vault's plain-files rule), written atomically — so any door
# (the desktop window, a DHD session, a second browser) hydrates
# the same threads from the same install. localStorage is demoted
# to a cache and an offline fallback: the window writes through on
# every persist and hydrates back on load. Uploads follow chats:
# their index rides in config/chats/uploads.json beside the threads
# it belongs to (file bytes were always handed to the bridge
# inline; the index is the record).
# Convergence for foreign copies (a backup restore, #136's badge
# sync) is chats_converge: per chat, newest-wins by timestamp when
# one thread is the other's continuation — and when two copies of
# a thread have genuinely diverged, BOTH survive: the incoming one
# lands as a dated sibling thread, never a silent merge.

CHATS_DIR = os.path.join(ROOT, "config", "chats")

# v0.3.0e Build 1 (#200): the main chat is a named seat, not a
# deletable row. The page seeds it as id "1" ("Main session"); it
# may be EMPTIED (/clear or /cls) but never deleted — not from the
# page, not through the API, not by a wholesale replace, and never
# by a sync tombstone.
MAIN_CHAT_ID = "1"
CHATS_UPLOADS_PATH = os.path.join(CHATS_DIR, "uploads.json")


def _chat_clean_id(value):
    s = str(value if value is not None else "").strip()
    if not s or len(s) > 80:
        return None
    if not re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]*$", s):
        return None
    if s in (".", "..", "uploads"):
        return None
    return s


def _chat_normalize(rec):
    if not isinstance(rec, dict):
        return None
    cid = _chat_clean_id(rec.get("id"))
    if cid is None:
        return None
    msgs = rec.get("messages")
    clean_msgs = [m for m in msgs if isinstance(m, dict)] if isinstance(msgs, list) else []
    out = {
        "id": cid,
        "title": str(rec.get("title") or "Chat")[:200],
        "messages": clean_msgs,
        "createdAt": rec.get("createdAt") if isinstance(rec.get("createdAt"), (int, float)) else 0,
        "updatedAt": rec.get("updatedAt") if isinstance(rec.get("updatedAt"), (int, float)) else 0,
    }
    # Case-tied chats (Build 15, #161): a chat bound to a case
    # carries the case slug in "case" — a reference only; the
    # case's content stays the Vault's plain files. The binding
    # survives normalization (and therefore write-through and
    # convergence) exactly like the thread itself does.
    case_ref = rec.get("case")
    if isinstance(case_ref, str) and re.match(r"^[a-z0-9][a-z0-9-]*$", case_ref):
        out["case"] = case_ref
    # Import provenance (v0.3.0e Build 5, #218): a chat minted by
    # convergence as another conversation's imported copy carries
    # that conversation's id in "fromSyncOf". It is the record's
    # sync identity — convergence, dedupe, and the tombstones all
    # key on it — so it survives normalization exactly like the
    # case binding does.
    origin_ref = rec.get("fromSyncOf")
    if isinstance(origin_ref, str) and _chat_clean_id(origin_ref):
        out["fromSyncOf"] = origin_ref
    # Ecosystem feedstock (v0.7.9e, #426 §5): a session in
    # the ciel seat may be DESIGNATED as feedstock — the
    # flag survives normalization (and therefore write-
    # through and convergence) exactly like the case
    # binding does, cleaned to its three fields. Nothing
    # designates by default: an absent or malformed value
    # leaves no field behind.
    _fs = rec.get("feedstock")
    if isinstance(_fs, dict):
        out["feedstock"] = {
            "designated": _fs.get("designated") is True,
            "at": int(_fs["at"]) if isinstance(_fs.get("at"), (int, float))
                  and not isinstance(_fs.get("at"), bool) else 0,
            "by": str(_fs.get("by") or "")[:80],
        }
    # The reference shelf (v0.5.10e, #283): Wire cards pulled
    # into a case chat stand on the chat record itself, so the
    # shelf rides the chat store — and therefore Sync — exactly
    # like the thread does. It survives normalization (cleaned,
    # capped) exactly like the case binding does; an emptied
    # shelf leaves no field behind.
    shelf = rec.get("shelf")
    if isinstance(shelf, list):
        clean_shelf = _shelf_clean_list(shelf)
        if clean_shelf:
            out["shelf"] = clean_shelf
    # The clear epoch (v0.6.3e, #318): a main thread emptied by
    # /clear or /cls carries the moment it was emptied and the
    # seat that emptied it. The marker survives normalization —
    # and therefore write-through and convergence — exactly
    # like the case binding does; convergence honors it over
    # any content stamped at or before it (see chat_write).
    cleared = rec.get("clearedAt")
    if isinstance(cleared, (int, float)) and not isinstance(cleared, bool) \
            and cleared > 0:
        out["clearedAt"] = cleared
        by = rec.get("clearedBy")
        if isinstance(by, str) and by.strip():
            out["clearedBy"] = by.strip()[:80]
    return out


SHELF_TEXT_CAP = 20000
SHELF_MAX_REFS = 50


def _shelf_clean_list(shelf):
    out = []
    for ref in shelf:
        if not isinstance(ref, dict):
            continue
        rid = str(ref.get("id") or "")
        if not re.fullmatch(r"R\d+", rid):
            continue
        out.append({
            "id": rid,
            "tab": str(ref.get("tab") or "")[:20],
            "title": str(ref.get("title") or "")[:300],
            "link": str(ref.get("link") or "")[:1000],
            "source": str(ref.get("source") or "")[:120],
            "text": str(ref.get("text") or "")[:SHELF_TEXT_CAP],
            "pulledAt": ref.get("pulledAt") if isinstance(
                ref.get("pulledAt"), (int, float)) else 0,
            "pulledBy": "navi" if ref.get("pulledBy") == "navi" else "operator",
        })
        if len(out) >= SHELF_MAX_REFS:
            break
    return out


def _chat_path(cid, account="operator"):
    if _account_clean(account) == "ciel":
        return os.path.join(chats_dir_for("ciel"), cid + ".json")
    return os.path.join(CHATS_DIR, cid + ".json")


def _chat_clear_filter(rec, hard=False):
    # The messages a record's clear epoch retires: lines
    # stamped at or before the moment the thread was emptied.
    # Post-clear lines stand. Soft (the #318 default): a line
    # carrying no stamp is not timestamped content and the
    # epoch does not govern it — the writer who KNOWS the clear
    # keeps its own unstamped work. Hard (v0.6.19e, #365): the
    # filter is applied to a copy that does not know the newest
    # clear — a stale window's write, a peer's pre-clear
    # record, a tombstone's enforcement — and there an
    # unstamped line cannot prove it postdates the clear, so
    # it yields with the rest. (Every living writer stamps:
    # the page stamps Date.now(), the bridge stamps its lines
    # too — an unstamped line is legacy or receipt work from
    # before the clear in every case that exists.)
    epoch = rec.get("clearedAt") if isinstance(rec, dict) else None
    msgs = (rec or {}).get("messages") or []
    if not isinstance(epoch, (int, float)) or isinstance(epoch, bool) \
            or not epoch:
        return list(msgs)

    def _dies(m):
        if not isinstance(m, dict):
            return False
        ts = m.get("ts")
        if isinstance(ts, (int, float)) and not isinstance(ts, bool):
            return ts <= epoch
        return hard

    return [m for m in msgs if not _dies(m)]


def _chat_seat_name():
    # This seat's name for a clear marker: the Mesh node name
    # when one is minted, the machine's hostname otherwise —
    # the same fall-back the Mesh identity itself uses.
    try:
        name = mesh_settings(load_config())["nodeName"]
        if name:
            return str(name)[:80]
    except Exception:
        pass
    return socket.gethostname()[:80]


def _sync_in_round():
    # True on a sync round's own thread, where writes are the
    # round landing a peer's set — the guard sync_note_write
    # keeps, shared by the clear recording below.
    try:
        return _SYNC_ROUND["depth"] > 0 and \
            _SYNC_ROUND.get("thread") == threading.get_ident()
    except Exception:
        return False


def chat_write(rec, account="operator"):
    rec = _chat_normalize(rec)
    if rec is None:
        return None
    # v0.6.3e (#318): the clear epoch is enforced at the store
    # door, so NO write path — write-through, convergence, the
    # ghost fold, a restore — can land pre-clear content back
    # into an emptied main thread. The epoch only ever advances:
    # a stale window's copy, written without the marker (or with
    # an older one), adopts the stored epoch and is filtered by
    # it. When a write ADVANCES the epoch — a clear act landing
    # at this bridge — the marker takes this seat's name unless
    # the act already carries one.
    #
    # v0.6.19e (#365): the door's law now covers EVERY thread,
    # not the main family alone, and the epoch has a third
    # witness — the clear TOMBSTONE (see the tombstone section).
    # The governing epoch is the max of the record's own, the
    # stored copy's, and the tombstone's. A write that does not
    # know the governing clear (its epoch is older) is filtered
    # HARD — unstamped lines yield too — because it is exactly
    # the stale copy the clear exists to retire. A write that
    # advances the epoch outside a sync round is a clear act
    # landing at this seat: it is recorded as a tombstone,
    # account-stamped, so the clear travels as its own synced
    # event instead of as cargo inside the record it emptied.
    stored = None
    try:
        with open(_chat_path(rec["id"], account), encoding="utf-8") as f:
            stored = _chat_normalize(json.load(f))
    except Exception:
        stored = None
    in_epoch = rec.get("clearedAt") or 0
    old_epoch = (stored or {}).get("clearedAt") or 0
    tomb_epoch = _clear_epoch_for(rec)
    epoch = max(in_epoch, old_epoch, tomb_epoch)
    if epoch:
        if epoch > in_epoch:
            rec["clearedAt"] = epoch
            if old_epoch >= in_epoch and (stored or {}).get("clearedBy"):
                rec["clearedBy"] = stored["clearedBy"]
            rec["messages"] = _chat_clear_filter(rec, hard=True)
        else:
            if epoch > old_epoch and not rec.get("clearedBy"):
                rec["clearedBy"] = _chat_seat_name()
            rec["messages"] = _chat_clear_filter(rec)
        if in_epoch > old_epoch and not _sync_in_round():
            sync_record_clear(rec, at=in_epoch, account=account)
    os.makedirs(chats_dir_for(account), exist_ok=True)
    full = _chat_path(rec["id"], account)
    tmp = full + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(rec, f)
    os.replace(tmp, full)
    sync_note_write("chat")
    return rec


def chats_all(account="operator"):
    out = []
    if os.path.isdir(chats_dir_for(account)):
        for name in sorted(os.listdir(chats_dir_for(account))):
            if not name.endswith(".json") or name == "uploads.json":
                continue
            try:
                with open(os.path.join(chats_dir_for(account), name), encoding="utf-8") as f:
                    rec = json.load(f)
            except Exception:
                continue
            rec = _chat_normalize(rec)
            if rec is not None:
                out.append(rec)
    out.sort(key=lambda r: (r.get("updatedAt") or 0, str(r.get("id"))))
    return out


def chat_delete(cid, _record=True, account="operator"):
    cid = _chat_clean_id(cid)
    if cid is None:
        return False
    if cid == MAIN_CHAT_ID:
        return False
    rec = None
    try:
        with open(_chat_path(cid, account), encoding="utf-8") as f:
            rec = _chat_normalize(json.load(f))
    except Exception:
        rec = None
    try:
        os.remove(_chat_path(cid, account))
        # Build 3 (#177): the deletion is tombstoned, so a sync
        # with another machine's older copy cannot resurrect it.
        # Build 5 (#218): the tombstone is recorded for the
        # conversation as well as the id — an imported copy can
        # be re-derived under a different id by an older build's
        # convergence, and the conversation key is what refuses
        # its return. (_record=False is the sync apply path: the
        # merged tombstone set it applies already carries both,
        # and re-recording would creep the deletion time forward
        # on every seat that applies it.)
        if _record:
            sync_record_tombstone("chats", cid)
            if rec is not None:
                sync_record_tombstone("chats", _chat_conv_tomb_key(rec))
        return True
    except Exception:
        return False


def chats_uploads(account="operator"):
    try:
        with open(os.path.join(chats_dir_for(account), "uploads.json"), encoding="utf-8") as f:
            rows = json.load(f)
        if isinstance(rows, list):
            return [r for r in rows if isinstance(r, dict)]
    except Exception:
        pass
    return []


def chats_save_uploads(rows, account="operator"):
    _up = os.path.join(chats_dir_for(account), "uploads.json")
    os.makedirs(chats_dir_for(account), exist_ok=True)
    tmp = _up + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump([r for r in (rows or []) if isinstance(r, dict)], f)
    os.replace(tmp, _up)


def chats_payload(account="operator"):
    return {"chats": chats_all(account), "uploads": chats_uploads(account)}


def _chats_converge_record(events, account="operator"):
    # v0.7.10e (#435): the scar — a durable record of what
    # a convergence did to this seat's records, kept in the
    # sync state (last 20 rounds) and carried in the sync
    # response itself, so a loss-shaped event is never
    # something the seat discovers by finding a
    # conversation gone (the #278 named-state standard).
    # It is deliberately NOT a line in the main thread: a
    # notice written into the conversation would itself
    # sync to every seat and breed (the reply-leg law —
    # her lines travel in order, and a scar is not one of
    # her lines).
    try:
        st = _sync_state_load()
        conv = st.get("convergences") or []
        conv.append({"at": int(time.time() * 1000),
                     "account": account, "events": list(events)})
        st["convergences"] = conv[-20:]
        _sync_state_save(st)
    except Exception:
        pass


def chats_replace_all(records, uploads, account="operator"):
    # The write-through path — v0.7.10e (#435) REWRITTEN as
    # per-record convergence. The shipped law made the
    # writing window's whole set authoritative: a record
    # its set lacked was deleted here and tombstoned —
    # which silently destroyed a second writer's records
    # in the same seat store (the Shotgun first session: a
    # non-app client's put under the main id, replaced
    # when the operator's window hydrated and synced its
    # own set over it). Now the arriving set CONVERGES,
    # record by record, under the verdicts the foreign-
    # copy road (chats_converge) judges by:
    #   - the main family merges by message (the #251
    #     one-main union) — never replaced, never parked;
    #   - a same-conversation record is kept, replaced
    #     (this thread continued, and newer), or parked
    #     as a sibling when the copies genuinely diverged;
    #   - an id held by a DIFFERENT conversation parks
    #     the arrival as that conversation's sibling;
    #   - a local record the set never mentions SURVIVES —
    #     absence is not a deletion. Deletions travel as
    #     tombstones only: a record the tombstone store
    #     names (the main family never) is removed, and
    #     an arriving record a tombstone covers is refused
    #     (the #253 law, unchanged).
    # Every loss-shaped event — a merge carrying lines
    # from both copies, a parked sibling, a replacement
    # that dropped local lines, a tombstone removal —
    # leaves the recorded scar and rides the summary
    # in the response.
    summary = {"added": 0, "replaced": 0, "kept": 0,
               "siblings": 0, "mainMerged": 0,
               "mainMergedMessages": 0, "removedByTombstone": 0}
    events = []
    try:
        tombs = (_sync_state_load().get("tombstones") or {}).get("chats") or {}
    except Exception:
        tombs = {}
    rows = chats_all(account)
    local = {str(r["id"]): r for r in rows}
    held_keys = {_chat_msgs_key(r) for r in rows}
    written = 0
    for rec in (records or []):
        norm = _chat_normalize(rec)
        if norm is None:
            continue
        if tombs and not _chat_is_main_family(norm) and \
                (str(norm["id"]) in tombs or _chat_conv_tomb_key(norm) in tombs):
            continue
        if _chat_is_main_family(norm):
            cur_main = local.get(MAIN_CHAT_ID)
            if cur_main is not None and cur_main.get("case"):
                cur_main = None
            if cur_main is None:
                adopt = dict(norm)
                adopt["id"] = MAIN_CHAT_ID
                adopt.pop("fromSyncOf", None)
                saved = chat_write(adopt, account=account)
                if saved is not None:
                    local[MAIN_CHAT_ID] = saved
                    held_keys.add(_chat_msgs_key(saved))
                    written += 1
                summary["added"] += 1
            else:
                merged_msgs, added = _chat_merge_messages(
                    cur_main.get("messages"), norm.get("messages"))
                # Convergence notices ride the merge silently:
                # a scar about a scar is how the notice would
                # breed, so only real lines count as an event.
                real_added = sum(
                    1 for m in (norm.get("messages") or [])
                    if _chat_msg_id(m) not in
                    {_chat_msg_id(x) for x in (cur_main.get("messages") or [])}
                    and not str((m or {}).get("notice") or "")
                    .startswith("sync:converge"))
                # v0.7.12e (#400): an epoch-only change must
                # still write. The message key never sees
                # clearedAt, so a PURE clear — the arriving
                # record empty, carrying only a newer epoch —
                # union-merges to the stored lines exactly,
                # the keys compare equal, and the pre-.12e code
                # skipped this branch as "kept": the epoch
                # never reached the store, and the next sync
                # resurrected the thread on both seats (the
                # v0.7.10e field failure). When the governing
                # epoch — the arrival's, or a clear tombstone's
                # — outruns the stored record's, the write
                # happens on the epoch's word alone, and the
                # filter below retires the pre-clear lines.
                _gov_epoch = max(norm.get("clearedAt") or 0,
                                 _clear_epoch_for(cur_main))
                _epoch_advance = _gov_epoch > \
                    (cur_main.get("clearedAt") or 0)
                if _epoch_advance or _chat_msgs_key(cur_main) != \
                        _chat_msgs_key(dict(norm, messages=merged_msgs)):
                    nxt = dict(cur_main)
                    nxt["messages"] = merged_msgs
                    nxt["updatedAt"] = max(
                        cur_main.get("updatedAt") or 0,
                        norm.get("updatedAt") or 0)
                    _epochs = [r.get("clearedAt") or 0
                               for r in (cur_main, norm)]
                    _tomb = _clear_epoch_for(cur_main)
                    if max(_epochs + [_tomb]) > 0:
                        _winner = cur_main if _epochs[0] >= _epochs[1] else norm
                        nxt["clearedAt"] = max(_epochs + [_tomb])
                        if _winner.get("clearedBy"):
                            nxt["clearedBy"] = _winner["clearedBy"]
                        nxt["messages"] = _chat_clear_filter(
                            nxt, hard=nxt["clearedAt"] > _epochs[0]
                            or nxt["clearedAt"] > _epochs[1])
                    saved = chat_write(nxt, account=account)
                    if saved is not None:
                        local[MAIN_CHAT_ID] = saved
                        held_keys.add(_chat_msgs_key(saved))
                        written += 1
                    summary["mainMerged"] += 1
                    summary["mainMergedMessages"] += added
                    if real_added:
                        events.append(
                            "the main thread was merged from two "
                            "copies — " + str(real_added) + " line(s) "
                            "from the arriving copy joined it and "
                            "nothing was deleted")
                else:
                    summary["kept"] += 1
            continue
        cur = local.get(str(norm["id"]))
        if cur is not None and \
                _chat_conv_key(cur) != _chat_conv_key(norm):
            cur = None  # the id is held by another conversation
        if cur is not None and \
                (norm.get("clearedAt") or 0) > (cur.get("clearedAt") or 0):
            # v0.7.12e (#400): the verdict path's shape of
            # the same defect — a cleared (empty) record is a
            # prefix of the stored full copy, so the verdict
            # read "kept" and the epoch dropped here too. An
            # arriving epoch that outruns the stored record's
            # is a clear act landing through the write-
            # through: the union of both copies is filtered
            # HARD under the new epoch (the stored copy does
            # not know this clear, so its unstamped lines
            # cannot prove they postdate it — the #365
            # doctrine), the epoch and its name are carried,
            # and the record is written, so the store learns
            # the clear and chat_write's own door records it
            # as a tombstone that travels.
            _merged, _madded = _chat_merge_messages(
                cur.get("messages"), norm.get("messages"))
            nxt = dict(cur)
            nxt["clearedAt"] = norm.get("clearedAt")
            if norm.get("clearedBy"):
                nxt["clearedBy"] = norm["clearedBy"]
            nxt["messages"] = _merged
            nxt["messages"] = _chat_clear_filter(nxt, hard=True)
            nxt["updatedAt"] = max(cur.get("updatedAt") or 0,
                                   norm.get("updatedAt") or 0)
            saved = chat_write(nxt, account=account)
            if saved is not None:
                local[str(saved["id"])] = saved
                held_keys.add(_chat_msgs_key(saved))
                written += 1
            summary["replaced"] += 1
            continue
        if cur is None:
            if str(norm["id"]) not in local:
                saved = chat_write(norm, account=account)
                if saved is not None:
                    local[str(saved["id"])] = saved
                    held_keys.add(_chat_msgs_key(saved))
                    written += 1
                summary["added"] += 1
                continue
            holder = local.get(str(norm["id"]))
            if holder is not None and _chat_msgs_prefix(norm, holder):
                summary["kept"] += 1
                continue
            verdict = "sibling"
        else:
            verdict = _chat_merge_verdict(cur, norm)
        if verdict == "sibling" and _chat_msgs_key(norm) in held_keys:
            verdict = "kept"
        if verdict == "replaced":
            _cur_ids = {_chat_msg_id(m)
                        for m in (cur.get("messages") or [])}
            _lost = sum(1 for m in (norm.get("messages") or [])
                        if _chat_msg_id(m) not in _cur_ids)
            _dropped = len(_cur_ids) - sum(
                1 for m in (cur.get("messages") or [])
                if _chat_msg_id(m) in
                {_chat_msg_id(x) for x in (norm.get("messages") or [])})
            saved = chat_write(norm, account=account)
            if saved is not None:
                local[str(saved["id"])] = saved
                held_keys.add(_chat_msgs_key(saved))
                written += 1
            summary["replaced"] += 1
            if _dropped:
                events.append(
                    "a copy of \"" + str(norm.get("title") or "Chat")
                    + "\" replaced the local one and " + str(_dropped)
                    + " local line(s) did not survive — the "
                    "replacement is named here, never silent")
        elif verdict == "kept":
            summary["kept"] += 1
        else:
            sib = dict(norm)
            base = _chat_sibling_id(norm)
            nid = base
            n = 2
            while os.path.exists(_chat_path(nid, account)):
                holder = local.get(nid)
                if holder is not None and \
                        _chat_msgs_key(holder) == _chat_msgs_key(norm):
                    break
                nid = base + "-" + str(n)
                n += 1
            sib["id"] = nid
            sib["fromSyncOf"] = _chat_conv_key(norm)[0]
            day = time.strftime("%Y-%m-%d", time.localtime())
            sib["title"] = (str(norm.get("title") or "Chat")
                            .split(" (from sync ")[0]
                            + " (from sync " + day + ")")[:200]
            saved = chat_write(sib, account=account)
            if saved is not None:
                local[str(saved["id"])] = saved
                held_keys.add(_chat_msgs_key(saved))
                written += 1
            summary["siblings"] += 1
            events.append(
                "a diverged copy of \""
                + str(norm.get("title") or "Chat")
                + "\" was parked beside the original as a "
                "sibling — both copies survive")
    # Absence is not a deletion: records the set never
    # mentioned stand — except the ones a tombstone names,
    # removed by the tombstone's word alone.
    if tombs:
        for rid, lrec in list(local.items()):
            if _chat_is_main_family(lrec):
                continue
            if rid in tombs or _chat_conv_tomb_key(lrec) in tombs:
                if chat_delete(rid, _record=False, account=account):
                    summary["removedByTombstone"] += 1
                    events.append(
                        "a tombstoned thread (\""
                        + str(lrec.get("title") or "Chat")
                        + "\") was removed — the deletion "
                        "traveled as a tombstone, as it must")
                    local.pop(rid, None)
    if uploads is not None:
        chats_save_uploads(uploads)
    if events:
        _chats_converge_record(events, account)
    out = {"ok": True, "chats": written, "converged": summary}
    if events:
        out["scar"] = events
    return out


def _chat_msgs_key(rec):
    return json.dumps(rec.get("messages") or [], sort_keys=True)


def _chat_msgs_prefix(shorter, longer):
    a = shorter.get("messages") or []
    b = longer.get("messages") or []
    if len(a) > len(b):
        return False
    return json.dumps(a, sort_keys=True) == json.dumps(b[:len(a)], sort_keys=True)


def _chat_msg_id(m):
    # A message's identity for merge dedupe (v0.4.10e, #251):
    # the canonical bytes of the message itself. Two seats
    # holding the same line hold the same identity, wherever
    # the thread around it has forked.
    return hashlib.sha256(json.dumps(m, sort_keys=True).encode()).hexdigest()


def _chat_merge_messages(local_msgs, remote_msgs):
    # The one-main merge (v0.4.10e, #251): the union of two
    # copies of the main thread, each message exactly once.
    # When every message on both sides carries a timestamp the
    # union is ordered by it (a stable sort, so equal stamps
    # keep their side's order); otherwise the local copy is the
    # spine and the foreign-only lines append in their own
    # order. Returns (messages, added_count).
    local_msgs = local_msgs or []
    remote_msgs = remote_msgs or []
    seen = {_chat_msg_id(m) for m in local_msgs}
    out = list(local_msgs)
    added = 0
    for m in remote_msgs:
        k = _chat_msg_id(m)
        if k not in seen:
            seen.add(k)
            out.append(m)
            added += 1
    if added and all(isinstance(m.get("ts"), (int, float))
                     for m in out if isinstance(m, dict)) and \
            all(isinstance(m, dict) for m in out):
        out = sorted(out, key=lambda m: m.get("ts") or 0)
    return out, added


def _chat_is_main_family(rec):
    # v0.4.10e (#251): the main thread is a SEAT, not one
    # conversation among many — there is exactly one, and every
    # record of it belongs to it: the seat itself (id "1") and
    # the sync-born copies older rounds parked as its siblings
    # (an import whose origin is the main seat). A case-bound
    # chat is never family, whatever its id looks like.
    if not isinstance(rec, dict) or rec.get("case"):
        return False
    if str(rec.get("id")) == MAIN_CHAT_ID:
        return True
    return _chat_origin(rec) == MAIN_CHAT_ID


def _chat_merge_verdict(cur, rec):
    # What merging `rec` into a store holding `cur` (same id) does:
    # "kept" (nothing to do), "replaced" (the incoming thread is
    # this thread continued, and newer — newest-wins), or "sibling"
    # (the two copies genuinely diverged — both survive).
    if _chat_msgs_key(cur) == _chat_msgs_key(rec):
        return "replaced" if (rec.get("updatedAt") or 0) > (cur.get("updatedAt") or 0) else "kept"
    if _chat_msgs_prefix(cur, rec) and (rec.get("updatedAt") or 0) >= (cur.get("updatedAt") or 0):
        return "replaced"
    if _chat_msgs_prefix(rec, cur):
        return "kept"
    return "sibling"


def _chat_origin(rec):
    # The conversation a record belongs to, for sync identity
    # (Build 5, #218): a minted import carries its origin in
    # fromSyncOf; a legacy minted sibling (Build 4 and earlier)
    # carries it in its id ("<origin>-sync-<stamp>"); anything
    # else is its own origin.
    o = rec.get("fromSyncOf")
    if isinstance(o, str) and _chat_clean_id(o):
        return o
    cid = str(rec.get("id") or "")
    if "-sync-" in cid:
        base = cid.split("-sync-", 1)[0]
        if _chat_clean_id(base):
            return base
    return cid


def _chat_conv_key(rec):
    # A conversation's identity across seats and rounds: its
    # origin id plus its birth stamp. Two seats' main chats are
    # both id "1" but were born at different moments — different
    # conversations, and this key is what can tell them apart.
    created = rec.get("createdAt")
    return (_chat_origin(rec), created if isinstance(created, (int, float)) else 0)


def _chat_conv_tomb_key(rec):
    origin, created = _chat_conv_key(rec)
    return "conv:" + origin + "|" + repr(created)


def _chat_sibling_id(rec):
    # The deterministic import identity (Build 5, #218): the
    # same foreign conversation derives the same sibling id on
    # every round and on every seat, so a tombstone, a dedupe,
    # and the next convergence all recognize it. Build 4 and
    # earlier minted a fresh timestamp id per import event —
    # an identity nothing could recognize twice, which is
    # exactly how deleted "(from sync)" copies kept coming
    # back under new names.
    origin, created = _chat_conv_key(rec)
    digest = hashlib.sha256((origin + "|" + repr(created)).encode()).hexdigest()[:10]
    return origin + "-sync-" + digest


def _chat_local_maps(rows):
    local = {str(r["id"]): r for r in rows}
    by_conv = {}
    for r in rows:
        by_conv.setdefault(_chat_conv_key(r), r)
    return local, by_conv


def _chats_dedupe_imports():
    # Build 5 (#218): a seat that ran Build 4 or earlier can
    # hold several minted copies of ONE imported conversation
    # (a fresh timestamp id per round — Alex's store held
    # three copies of one main session, two byte-identical).
    # Group minted imports by conversation identity; where the
    # copies form one lineage (each a prefix of the richest),
    # keep the richest and remove the rest, tombstoning the
    # removed ids so the other seat's copies of them are
    # refused at the door. Copies that genuinely diverged (no
    # prefix relation) both survive, as they always have.
    rows = chats_all()
    groups = {}
    for r in rows:
        if str(r["id"]) == MAIN_CHAT_ID:
            continue
        if "-sync-" not in str(r["id"]) and not r.get("fromSyncOf"):
            continue
        groups.setdefault(_chat_conv_key(r), []).append(r)
    removed = 0
    for group in groups.values():
        if len(group) < 2:
            continue
        group.sort(key=lambda r: (len(r.get("messages") or []), r.get("updatedAt") or 0))
        richest = group[-1]
        for r in group[:-1]:
            if _chat_msgs_prefix(r, richest):
                try:
                    os.remove(_chat_path(str(r["id"])))
                    sync_record_tombstone("chats", str(r["id"]))
                    removed += 1
                except Exception:
                    pass
    return removed


def _chats_fold_main_ghosts():
    # v0.4.10e (#251): the one-time reconciliation, run at the
    # head of every convergence — a seat holding ghost mains
    # (sync-born siblings of the main seat, parked by rounds
    # that treated the main thread as one conversation among
    # many) folds them into the canonical main: messages merge
    # in by identity, nothing is lost, the ghost files go, and
    # the fold is receipted in the sync state — what folded,
    # and how many messages it carried. Ghost ids are
    # tombstoned so another seat's copy of the same ghost is
    # refused as a thread of its own (its messages, if any are
    # new, still arrive with the main seat's own record and
    # merge the same way).
    out = {"folded": 0, "messages": 0, "merged": 0}
    rows = chats_all()
    main = None
    ghosts = []
    for r in rows:
        if str(r["id"]) == MAIN_CHAT_ID and not r.get("case"):
            main = r
        elif _chat_is_main_family(r):
            ghosts.append(r)
    if main is None or not ghosts:
        return out
    ghosts.sort(key=lambda r: (r.get("updatedAt") or 0, str(r["id"])))
    receipt = []
    cur = main
    for g in ghosts:
        # v0.6.3e (#318): a ghost's own clear epoch retires its
        # pre-clear lines before the fold — the fold must never
        # resurrect content any seat emptied. (The main's own
        # epoch is enforced again at the write below.)
        # v0.6.19e (#365): the ghost is also filtered by the
        # MAIN's governing epoch (its record's and its clear
        # tombstone's), hard — a ghost is a copy that never
        # heard the main's clear, and its unstamped lines
        # cannot prove they postdate it.
        _gov = max(g.get("clearedAt") or 0, cur.get("clearedAt") or 0,
                   _clear_epoch_for(cur))
        _gview = dict(g)
        if _gov:
            _gview["clearedAt"] = _gov
        merged_msgs, added = _chat_merge_messages(cur.get("messages"), _chat_clear_filter(_gview, hard=True))
        nxt = dict(cur)
        nxt["messages"] = merged_msgs
        nxt["updatedAt"] = max(cur.get("updatedAt") or 0, g.get("updatedAt") or 0)
        saved = chat_write(nxt)
        if saved is None:
            continue
        cur = saved
        try:
            os.remove(_chat_path(str(g["id"])))
        except Exception:
            continue
        sync_record_tombstone("chats", str(g["id"]))
        receipt.append({"id": str(g["id"]), "title": str(g.get("title") or ""),
                        "messages": len(g.get("messages") or [])})
        out["folded"] += 1
        out["messages"] += len(g.get("messages") or [])
        out["merged"] += added
    if receipt:
        try:
            state = _sync_state_load()
            state["mainFold"] = {"at": time.time(), "folded": receipt,
                                 "messagesMerged": out["merged"]}
            _sync_state_save(state)
        except Exception:
            pass
    return out


def _chat_write_as(rec, target):
    # Land rec's thread under target's identity: the target
    # keeps its id, its title, and its import provenance — the
    # incoming conversation continues the copy that already
    # represents it here, instead of minting another.
    out = dict(rec)
    out["id"] = target["id"]
    out["title"] = target.get("title") or rec.get("title") or "Chat"
    if target.get("fromSyncOf"):
        out["fromSyncOf"] = target["fromSyncOf"]
    else:
        out.pop("fromSyncOf", None)
    return chat_write(out)


def chats_converge_preview(incoming):
    summary = {"added": 0, "replaced": 0, "kept": 0, "siblings": 0, "mainMerged": 0}
    rows = chats_all()
    local, by_conv = _chat_local_maps(rows)
    held_keys = {_chat_msgs_key(r) for r in rows}
    for raw in (incoming or []):
        rec = _chat_normalize(raw)
        if rec is None:
            continue
        if _chat_is_main_family(rec):
            summary["mainMerged"] += 1  # v0.4.10e (#251): mains merge, never park
            continue
        cur = local.get(str(rec["id"]))
        if cur is not None and _chat_conv_key(cur) != _chat_conv_key(rec):
            cur = None  # same id, different conversation (two seats' mains)
        if cur is None:
            rep = by_conv.get(_chat_conv_key(rec))
            if rep is not None and str(rep["id"]) != str(rec["id"]):
                cur = rep
        if cur is None and str(rec["id"]) not in local:
            summary["added"] += 1
        elif cur is None:
            holder = local.get(str(rec["id"]))
            if holder is not None and _chat_msgs_prefix(rec, holder):
                summary["kept"] += 1
            else:
                summary["siblings"] += 1  # the id is held by another conversation
        else:
            v = _chat_merge_verdict(cur, rec)
            if v == "sibling" and _chat_msgs_key(rec) in held_keys:
                v = "kept"
            summary["replaced" if v == "replaced" else "siblings" if v == "sibling" else "kept"] += 1
    return summary


def chats_converge(incoming, incoming_uploads=None):
    # Merging a FOREIGN copy (backup restore / badge sync) into
    # this store — see the section header for the rules. Returns a
    # summary the caller can speak out loud.
    # Build 5 (#218): identity is by CONVERSATION (origin id +
    # createdAt — see _chat_conv_key), not by chat id alone and
    # never by import event. A foreign copy whose id is held by a
    # different conversation (two seats' main chats) is judged
    # against its own conversation's representative here; a fork
    # parks under the deterministic _chat_sibling_id; and the
    # store first dedupes the timestamp-id copies older builds
    # minted of a single conversation.
    fold = _chats_fold_main_ghosts()
    summary = {"added": 0, "replaced": 0, "kept": 0, "siblings": 0, "uploads": 0,
               "deduped": _chats_dedupe_imports(),
               "mainFolded": fold["folded"], "mainFoldedMessages": fold["merged"],
               "mainMerged": 0, "mainMergedMessages": 0}
    rows = chats_all()
    local, by_conv = _chat_local_maps(rows)
    held_keys = {_chat_msgs_key(r) for r in rows}
    day = time.strftime("%Y-%m-%d", time.localtime())
    for raw in (incoming or []):
        rec = _chat_normalize(raw)
        if rec is None:
            continue
        if _chat_is_main_family(rec):
            # v0.4.10e (#251): a record of the main seat merges
            # INTO the canonical main — the union of the two
            # copies, each message exactly once — and never
            # parks as a sibling, never lands as another
            # thread. A seat holding no main yet adopts the
            # record AS its main.
            cur_main = local.get(MAIN_CHAT_ID)
            if cur_main is not None and cur_main.get("case"):
                cur_main = None
            if cur_main is None:
                adopt = dict(rec)
                adopt["id"] = MAIN_CHAT_ID
                adopt.pop("fromSyncOf", None)
                saved = chat_write(adopt)
                if saved is not None:
                    local[MAIN_CHAT_ID] = saved
                    by_conv.setdefault(_chat_conv_key(saved), saved)
                    held_keys.add(_chat_msgs_key(saved))
            else:
                merged_msgs, _added = _chat_merge_messages(
                    cur_main.get("messages"), rec.get("messages"))
                summary["mainMergedMessages"] += _added
                nxt = dict(cur_main)
                nxt["messages"] = merged_msgs
                nxt["updatedAt"] = max(cur_main.get("updatedAt") or 0,
                                       rec.get("updatedAt") or 0)
                # v0.6.3e (#318): the clear epoch converges
                # with the thread — the newer clear governs the
                # merged record, whichever seat spoke it, and
                # its pre-clear lines yield here (and again at
                # the store door, where chat_write enforces it).
                # v0.6.19e (#365): the clear TOMBSTONE is a third
                # witness to the epoch — when it outruns both
                # records it governs HARD, unstamped lines and
                # all, because neither record in hand has heard
                # the clear it speaks for.
                # v0.7.3e (#400): the hardness follows the
                # doctrine, not the witness: HARD whenever the
                # governing epoch outruns EITHER copy's own
                # stamp — a copy that has not heard the clear
                # cannot prove its unstamped lines postdate it.
                # The shipped law keyed hardness to the
                # tombstone alone, so a travelling clear left
                # unstamped pre-clear lines standing on the
                # receiving seat.
                _epochs = [r.get("clearedAt") or 0 for r in (cur_main, rec)]
                _tomb = _clear_epoch_for(cur_main)
                if max(_epochs + [_tomb]) > 0:
                    _winner = cur_main if _epochs[0] >= _epochs[1] else rec
                    nxt["clearedAt"] = max(_epochs + [_tomb])
                    if _winner.get("clearedBy"):
                        nxt["clearedBy"] = _winner["clearedBy"]
                    nxt["messages"] = _chat_clear_filter(
                        nxt, hard=nxt["clearedAt"] > _epochs[0]
                        or nxt["clearedAt"] > _epochs[1])
                    summary["mainCleared"] = summary.get("mainCleared", 0) + 1
                saved = chat_write(nxt)
                if saved is not None:
                    local[MAIN_CHAT_ID] = saved
                    held_keys.add(_chat_msgs_key(saved))
            summary["mainMerged"] += 1
            continue
        key = _chat_conv_key(rec)
        cur = local.get(str(rec["id"]))
        if cur is not None and _chat_conv_key(cur) != key:
            # The id is taken by a DIFFERENT conversation (the
            # standing case: two seats' main chats, both id "1").
            # This record is judged against its own conversation's
            # representative below, never against the id's holder.
            cur = None
        if cur is None:
            rep = by_conv.get(key)
            if rep is not None and str(rep["id"]) != str(rec["id"]):
                # This conversation already has a representative
                # here — an imported copy minted by an earlier
                # round, under whatever id that round gave it.
                # Converge into it: identity by conversation,
                # not by import event (Build 5, #218).
                cur = rep
        # v0.6.19e (#365): the clear law reaches convergence for
        # every thread, not the main alone. The governing epoch —
        # the incoming record's, the local copy's, the clear
        # tombstone's — filters the incoming copy BEFORE any
        # verdict judges it, and a local copy that has not heard
        # a newer clear is retired in place. Without this the
        # prefix verdict below hands an emptied thread back to
        # whichever copy is fuller — it un-clears it. When the
        # tombstone is the only witness that knows the clear,
        # the filter is hard: unstamped lines yield too.
        # v0.7.3e (#400): hardness is per copy — hard whenever
        # the governing epoch outruns that copy's own stamp,
        # tombstone or no tombstone. The shipped law keyed it
        # to the tombstone alone, so a clear carried by the
        # arriving record itself filtered the receiving seat
        # soft, and unstamped pre-clear lines survived the
        # trip and stood after the clear.
        _tomb = _clear_epoch_for(rec)
        _epoch = max(rec.get("clearedAt") or 0,
                     (cur.get("clearedAt") or 0) if cur else 0,
                     _tomb)
        if _epoch:
            _rec_heard = rec.get("clearedAt") or 0
            rec = dict(rec)
            rec["clearedAt"] = max(_rec_heard, _epoch)
            rec["messages"] = _chat_clear_filter(
                rec, hard=_epoch > _rec_heard)
            if cur is not None and _epoch > (cur.get("clearedAt") or 0):
                _nxt = dict(cur)
                _nxt["clearedAt"] = _epoch
                _nxt["messages"] = _chat_clear_filter(_nxt, hard=True)
                _saved = chat_write(_nxt)
                if _saved is not None:
                    local[str(_saved["id"])] = _saved
                    by_conv[_chat_conv_key(_saved)] = _saved
                    cur = _saved
                    summary["chatsCleared"] = summary.get("chatsCleared", 0) + 1
        if cur is None and str(rec["id"]) not in local:
            saved = chat_write(rec)
            if saved is not None:
                local[str(saved["id"])] = saved
                by_conv.setdefault(_chat_conv_key(saved), saved)
                held_keys.add(_chat_msgs_key(saved))
            summary["added"] += 1
            continue
        if cur is None:
            # No representative, but the id itself is held by a
            # different conversation — the record parks as this
            # conversation's sibling below; it never writes
            # under the held id. One exception: a record the
            # holder already contains line for line (an older
            # generation of the holder's own thread, arriving
            # under a rewritten birth stamp) is simply kept —
            # parking it would duplicate content the holder
            # already has.
            holder = local.get(str(rec["id"]))
            if holder is not None and _chat_msgs_prefix(rec, holder):
                summary["kept"] += 1
                continue
            verdict = "sibling"
        else:
            verdict = _chat_merge_verdict(cur, rec)
        if verdict == "sibling" and _chat_msgs_key(rec) in held_keys:
            # The same diverged copy was already converged once and
            # its sibling is on file — a repeated sync of the same
            # backup must not mint a fresh sibling every time.
            verdict = "kept"
        if verdict == "replaced":
            if str(cur["id"]) == str(rec["id"]):
                saved = chat_write(rec)
            else:
                saved = _chat_write_as(rec, cur)
            if saved is not None:
                local[str(saved["id"])] = saved
                held_keys.add(_chat_msgs_key(saved))
            summary["replaced"] += 1
        elif verdict == "kept":
            summary["kept"] += 1
        else:
            # A genuine fork parks as a sibling — under the
            # conversation's deterministic import id (Build 5,
            # #218), so the next round recognizes this exact
            # copy instead of minting another.
            sib = dict(rec)
            base = _chat_sibling_id(rec)
            nid = base
            n = 2
            while os.path.exists(_chat_path(nid)):
                holder = local.get(nid)
                if holder is not None and _chat_msgs_key(holder) == _chat_msgs_key(rec):
                    break  # this exact copy is already parked here
                nid = base + "-" + str(n)
                n += 1
            sib["id"] = nid
            sib["fromSyncOf"] = key[0]
            sib["title"] = (str(rec.get("title") or "Chat").split(" (from sync ")[0] + " (from sync " + day + ")")[:200]
            saved = chat_write(sib)
            if saved is not None:
                local[str(saved["id"])] = saved
                held_keys.add(_chat_msgs_key(saved))
            summary["siblings"] += 1
    if incoming_uploads is not None:
        def _up_key(r):
            return str(r.get("id") or (str(r.get("name") or "") + "|" + str(r.get("at") or "")))
        merged = {_up_key(r): r for r in chats_uploads()}
        for r in incoming_uploads:
            if not isinstance(r, dict):
                continue
            k = _up_key(r)
            if k not in merged:
                merged[k] = r
                summary["uploads"] += 1
        if summary["uploads"]:
            chats_save_uploads(list(merged.values()))
    summary["changed"] = summary["added"] + summary["replaced"] + summary["siblings"] + summary["uploads"] + summary["deduped"] + summary["mainFolded"] + summary["mainMerged"]
    return summary


# --- Quick Sync (0.2.0e Build 3, issue #176) -------------------------
# The Operator Badge backup round (#136) is proven and deliberate;
# Quick Sync is its fluid sibling, ruled by Alex the night the
# badge round passed in the field (2026-11-13): a Sync control in
# Apex | Utilities that opens nothing and pops a card — one tap
# runs the whole round (pull, converge, push) so work started on
# the laptop is pickable-up on the phone over DHD, and vice versa.
# Build 6 adds the second transport (phase 2): the Mesh carries
# the round whenever a paired peer's road is lit — see the sync
# handlers beside the Mesh server and _sync_mesh_round below;
# the repo remains the fallback and the convergence semantics
# are shared by both.
#
# The sync set is the living work: the chat store AND Case Files.
# Settings, Soul/Memory, chips and RAG packs stay with the full
# badge backup (chips and packs keep themselves synced through
# their own channels anyway). The transport is the backup repo,
# under a sync/ prefix the restore format never touches, riding
# the OPERATOR identity — per #173's separation, never the
# read-only Runtime PAT. The badge in its slot is the round's
# identity root and trigger, as #136 ruled: a pointer, never an
# authenticator; the Operator sign-in remains the only key, and a
# signed-out round is refused and NAMED, never silently skipped.
#
# Convergence is the badge round's semantics (chats_converge)
# plus the tombstones of the section above: deletions travel as
# records and yield only to genuinely newer work. Diverged chats
# park as dated siblings; a case file that diverged inside the
# same second parks its remote copy as a ".from-sync-<date>"
# sibling file — nothing is ever silently lost, and only a parked
# pair makes the card say "Needs your eyes", naming it.
#
# Pull triggers: the button (the full round), app start, and DHD
# session start (pull + converge each). No polling daemon; the
# Mesh peer-contact trigger is phase 2, with the Mesh transport.

SYNC_FORMAT = "navi-sync/2"
SYNC_PREFIX = "sync/"
_SYNC_LOCK = threading.Lock()
_SYNC_DHD_SEEN = {}
_SYNC_DHD_LOCK = threading.Lock()
_SYNC_DHD_SESSION_GAP = 300
_SYNC_TRIGGER_DEBOUNCE = 60


def _sync_now_iso():
    return _now_iso()


def _sync_fail(status, step):
    # Build 2's naming discipline (#173), applied to sync: every
    # failure the card can show is a classified sentence — held
    # offline, named auth, named rate with its wait.
    if status == 0:
        return {"kind": "offline", "state": "held",
                "error": "Can't reach GitHub — " + step + " did not happen. The round is held; the next trigger retries it."}
    if status in (401, 403, 429):
        rate = github_rate_state() or {}
        core = rate.get("core") if isinstance(rate, dict) else None
        spent = status == 429 or (isinstance(core, dict)
                                  and (core.get("remaining") or 0) == 0
                                  and (core.get("reset") or 0) > time.time())
        if spent:
            wait = _gh_reset_phrase(core.get("reset")) if isinstance(core, dict) else ""
            return {"kind": "rate", "state": "held",
                    "error": "GitHub's rate limit is spent." + wait + " The round is held until the bucket refills — nothing was half-written."}
        return {"kind": "auth", "state": "auth",
                "error": "GitHub refused the Operator credential (HTTP " + str(status) + ") while sync tried to " + step + " — the sign-in may have expired or been revoked. Sign in again in Settings → GitHub & Backup."}
    return {"kind": "error", "state": "held",
            "error": "GitHub answered HTTP " + str(status) + " while sync tried to " + step + ". The round is held; this step wrote nothing."}


def _sync_auth_error():
    return {"ok": False, "state": "auth", "kind": "auth", "route": "Backup repo",
            "error": "Not signed in to GitHub — sync is anchored to your GitHub account, and this machine isn't signed in. Sign in with the account your other machines use (Settings → GitHub & Backup) and the round carries chats, Case Files, the ChipDeck, her Soul and memory book, and your seat under it. Nothing was sent anywhere."}


def _sync_safe_rel(rel):
    # A remote-supplied relative path is jailed by construction:
    # no empty, dot, or parent parts, no backslashes, no NUL.
    parts = str(rel or "").split("/")
    if not parts:
        return None
    for p in parts:
        if p in ("", ".", "..") or "\\" in p or "\x00" in p:
            return None
    return "/".join(parts)


def _sync_case_files(slug, account="operator"):
    # {rel: {"sha": hex, "mtime": epoch}} for one case folder, or
    # None when the case is not on this machine.
    d = _case_dir(slug, account)
    if not d or not os.path.isdir(d):
        return None
    out = {}
    for base, dirs, names in os.walk(d):
        dirs.sort()
        for name in sorted(names):
            full = os.path.join(base, name)
            if not os.path.isfile(full):
                continue
            rel = os.path.relpath(full, d).replace(os.sep, "/")
            try:
                with open(full, "rb") as f:
                    data = f.read()
                out[rel] = {"sha": hashlib.sha256(data).hexdigest(),
                            "mtime": os.path.getmtime(full)}
            except Exception:
                continue
    return out


# ---------------------------------------------------------------
# Seat state (v0.3.0e Build 1, #200): what has always lived in the
# PAGE's local storage rather than on disk — her memory entries,
# the operator's picture and badge. The Sync Update carries them
# in the sync set (sync/seat.json), anchored to the account like
# everything else, so the conversation — and the face that
# started it — can be picked up on any screen. The bridge keeps
# the canonical merged copy here; a page pushes its state and
# adopts the converged answer.
SEAT_STATE_PATH = os.path.join(ROOT, "config", "seat-state.json")


def _json_bytes(obj):
    return json.dumps(obj, indent=2).encode()


def _atomic_write(path, data):
    # Write-then-rename, the pattern the codebase uses at every
    # state file: a reader never sees a half-written file.
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "wb") as f:
        f.write(data)
    os.replace(tmp, path)
_SEAT_LOCK = threading.Lock()


def _seat_clean_image(value):
    # The same discipline the dashboard image fields answer to:
    # a data-URL string under the cap, else "".
    if not isinstance(value, str):
        return ""
    return _dashboard_image_field(value)


def _seat_fact_id(text):
    # v0.5.1e (#256): a memory entry's identity for convergence.
    # memory_fact_key names the semantic facts (name / home /
    # work / favorite:*) — two texts under one semantic key are
    # the same fact, corrected. Everything else is its own fact,
    # identified by its normalized text (the page's seatFactKey
    # rule). Through v0.4.10e the seat machinery used
    # memory_fact_key ALONE as the dedupe key: it returns None
    # for ordinary facts, so every ordinary entry shared one
    # key — the cleaner kept only the first ordinary entry and
    # the merge refused the rest. That is the convicted heart
    # of the operator-class gap: the road existed, and the
    # identity function broke it.
    k = memory_fact_key(text)
    if k:
        return "fact:" + k
    return "text:" + re.sub(r"\s+", " ", str(text or "").lower()).strip()


_SEAT_ORIGINS = ("manual", "trigger", "autonomous", "correction",
                 "auto", "seed", "sync")


def _seat_clean_entries(rows):
    out = []
    seen = set()
    for row in (rows if isinstance(rows, list) else []):
        if not isinstance(row, dict):
            continue
        t = str(row.get("t") or "").strip()
        if not t:
            continue
        fid = _seat_fact_id(t)
        if fid in seen:
            continue
        seen.add(fid)
        o = str(row.get("o") or "manual")
        if o not in _SEAT_ORIGINS:
            o = "manual"
        out.append({"t": t[:600], "o": o})
    return out


def _seat_state_load(account="operator"):
    try:
        with open(seat_state_path_for(account), "r", encoding="utf-8") as fh:
            raw = json.load(fh)
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    try:
        picture_at = float(raw.get("pictureAt") or 0)
    except Exception:
        picture_at = 0
    try:
        badge_at = float(raw.get("badgeAt") or 0)
    except Exception:
        badge_at = 0
    try:
        name_at = float(raw.get("nameAt") or 0)
    except Exception:
        name_at = 0
    return {
        "entries": _seat_clean_entries(raw.get("entries")),
        "operatorPicture": _seat_clean_image(raw.get("operatorPicture")),
        "operatorBadge": _seat_clean_image(raw.get("operatorBadge")),
        "pictureAt": picture_at,
        "badgeAt": badge_at,
        "operatorName": str(raw.get("operatorName") or ""),
        "nameAt": name_at,
    }


def _seat_state_save(state, account="operator"):
    try:
        _atomic_write(seat_state_path_for(account), _json_bytes(state))
    except Exception:
        pass


def seat_state_payload(account="operator"):
    st = _seat_state_load(account)
    # v0.7.10e (#433): the registry (accounts_cfg, off the
    # config) is the one authority for the seat's name; the
    # seat-state store mirrors it through the page door's
    # own writes. When the two disagree, the payload NAMES
    # the divergence instead of letting two surfaces read
    # two names in silence (the "Seat · Elric" shape: the
    # chip read the config, the Operator page read the
    # store, and neither said they differed).
    try:
        _reg = accounts_cfg(load_config())[
            _account_clean(account)]["displayName"]
    except Exception:
        _reg = ""
    st["registryName"] = _reg
    st["nameDiverged"] = bool(
        st.get("operatorName") and _reg
        and st["operatorName"] != _reg)
    return st


def _seat_entry_tombstones():
    # The forgotten facts, as {fact id: epoch} — the "entries"
    # kind of the sync tombstone store (#256, on #253's model:
    # a tombstone is a fact at any timestamp, pruned only by
    # the standing 90-day rule).
    try:
        state = _sync_state_load()
        tombs = _sync_tombstones_pruned(state.get("tombstones") or {})
        rows = tombs.get("entries") or {}
        return {str(k): float(v) for k, v in rows.items()
                if isinstance(v, (int, float))}
    except Exception:
        return {}


def _seat_prune_tombstoned(st, tombs=None):
    # Drop the stored entries a tombstone covers; returns the
    # count. Runs on every merge, so a round carrying only a
    # tombstone still lands the forget on this seat's store.
    if tombs is None:
        tombs = _seat_entry_tombstones()
    if not tombs:
        return 0
    kept = [r for r in st["entries"] if _seat_fact_id(r["t"]) not in tombs]
    gone = len(st["entries"]) - len(kept)
    st["entries"] = kept
    return gone


def _seat_merge(incoming, source="page", account="operator",
                identity_ok=None):
    # Merge a page's (or a sync set's) seat state into the stored
    # one — the operator class (#256): her memory entries about
    # the operator, his name, his picture and his badge,
    # converging as one identifiable class, with the bridge's
    # copy the truth every page reads.
    # Entries union by fact identity (_seat_fact_id) and keep
    # their origins end-to-end — an arrival is never re-stamped
    # on the road. A same-fact arrival whose text differs is a
    # correction: its text wins. A forgotten fact is a
    # tombstone: stored copies are pruned and arrivals it
    # covers are refused, however fresh the offering seat's
    # copy claims to be. The name, picture and badge are single
    # values: last-writer-wins by the sender's stamp, and a
    # first fill (stored empty) always lands.
    # Returns (state, changes) with the movement counted.
    if not isinstance(incoming, dict):
        incoming = {}
    with _SEAT_LOCK:
        st = _seat_state_load(account)
        changes = {"entriesAdded": 0, "entriesRemoved": 0,
                   "pictureChanged": False, "badgeChanged": False,
                   "nameChanged": False, "identityRefused": False}
        # The forgets this offering carries land first, so an
        # entry offered and forgotten in the same breath is
        # judged by the forget.
        for row in (incoming.get("forgotten") or []):
            t = row.get("t") if isinstance(row, dict) else row
            t = str(t or "").strip()
            if t:
                sync_record_tombstone("entries", _seat_fact_id(t))
        tombs = _seat_entry_tombstones()
        changes["entriesRemoved"] += _seat_prune_tombstoned(st, tombs)
        have = {}
        for i, r in enumerate(st["entries"]):
            have.setdefault(_seat_fact_id(r["t"]), i)
        for row in _seat_clean_entries(incoming.get("entries")):
            fid = _seat_fact_id(row["t"])
            if fid in tombs:
                continue
            if fid not in have:
                st["entries"].append({"t": row["t"], "o": row["o"]})
                have[fid] = len(st["entries"]) - 1
                changes["entriesAdded"] += 1
            else:
                cur = st["entries"][have[fid]]
                if cur["t"] != row["t"]:
                    cur["t"] = row["t"]
                    if row["o"] == "correction":
                        cur["o"] = "correction"
        # v0.7.10e (#433): identity — the name, the picture,
        # the badge — is seat-local. A sync set carries it
        # only when the set is positively stamped as THIS
        # seat's own (the caller judges the manifest); a
        # legacy unstamped set, or another seat's set, has
        # its identity keys refused here, by count, while
        # its memory entries still merge. This is the door
        # the "Seat · Elric" contamination walked through:
        # a foreign seat's name, merged by stamp, used to
        # rewrite this seat's config operator_name below.
        if identity_ok is None:
            identity_ok = source != "sync"
        if not identity_ok:
            _id_offered = (
                str(incoming.get("operatorName") or "") != st["operatorName"]
                or _seat_clean_image(incoming.get("operatorPicture")) != st["operatorPicture"]
                or _seat_clean_image(incoming.get("operatorBadge")) != st["operatorBadge"])
            if _id_offered:
                changes["identityRefused"] = True
        else:
            for field, stamp_key, flag in (
                    ("operatorPicture", "pictureAt", "pictureChanged"),
                    ("operatorBadge", "badgeAt", "badgeChanged")):
                val = _seat_clean_image(incoming.get(field))
                if not val or val == st[field]:
                    continue
                try:
                    stamp = float(incoming.get(stamp_key) or 0)
                except Exception:
                    stamp = 0
                if not st[field] or stamp >= st[stamp_key]:
                    st[field] = val
                    st[stamp_key] = stamp or time.time()
                    changes[flag] = True
            name = str(incoming.get("operatorName") or "")
            if name and name != st["operatorName"]:
                try:
                    stamp = float(incoming.get("nameAt") or 0)
                except Exception:
                    stamp = 0
                if not st["operatorName"] or stamp >= st["nameAt"]:
                    st["operatorName"] = name
                    st["nameAt"] = stamp or time.time()
                    changes["nameChanged"] = True
        _seat_state_save(st, account)
        if changes["nameChanged"] and account == "operator":
            # The bridge's own config follows the converged
            # name, so her persona greets the operator by the
            # name every seat agreed on.
            try:
                cfg = load_config()
                if str(cfg.get("operator_name") or "") != st["operatorName"]:
                    cfg["operator_name"] = st["operatorName"]
                    save_config(cfg)
            except Exception:
                pass
        if source == "page" and account == "operator":
            # v0.6.30e (#377): a write through the page door
            # is this seat's operator authoring his own
            # store — the ledger attributes every entry the
            # page carries (and the identity) to this seat's
            # account, or "local" when the seat is signed
            # out, so locally authored facts are provable as
            # his at the sweep and at the prompt door.
            try:
                _lg = str((github_auth() or {}).get("login") or "")
                _ss = _sync_state_load()
                _at = _ss.get("attribution") if isinstance(_ss.get("attribution"), dict) else {}
                _sf = _at.get("seat") if isinstance(_at.get("seat"), dict) else {}
                for _r in st["entries"]:
                    _sf[_seat_fact_id(_r["t"])] = _lg if _lg else "local"
                _sf["@identity"] = _lg if _lg else "local"
                _at["seat"] = _sf
                _ss["attribution"] = _at
                _sync_state_save(_ss)
            except Exception:
                pass
        if source == "page" and (changes["entriesAdded"]
                                 or changes["entriesRemoved"]
                                 or changes["pictureChanged"]
                                 or changes["badgeChanged"]
                                 or changes["nameChanged"]):
            sync_note_write("seat")
        return st, changes


def _sync_deck_collect(cfg):
    # The ChipDeck as ONE sync unit (v0.3.0e Build 1, #200): the
    # chips (cartridges + their install record), the RAG packs
    # (files + their record), and the cards that tie machines
    # together — this node's own pairing card, one re-drawn per
    # paired peer, and a gateway card for every fedinet this node
    # keeps. Cards carry identity and public halves only, exactly
    # as they do in the backup; key material never rides.
    files = {}
    index = {}

    def put(rel, data, mtime):
        files[SYNC_PREFIX + "deck/" + rel] = data
        index[rel] = {"sha": hashlib.sha256(data).hexdigest(),
                      "size": len(data), "mtime": int(mtime)}

    try:
        raw = read_file(CHIP_INSTALLS_PATH)
        if raw:
            put("chips/installed.json", raw.encode(),
                os.path.getmtime(CHIP_INSTALLS_PATH))
    except Exception:
        pass
    for row in load_chip_installs():
        local_file = row.get("local_file") if isinstance(row, dict) else None
        if not local_file:
            continue
        base = os.path.basename(str(local_file))
        path = os.path.join(CHIPS_DIR, base)
        if os.path.isfile(path):
            try:
                with open(path, "rb") as f:
                    put("chips/" + base, f.read(), os.path.getmtime(path))
            except Exception:
                continue
    try:
        raw = read_file(RAG_INSTALLS_PATH)
        if raw:
            put("rag-packs/installed.json", raw.encode(),
                os.path.getmtime(RAG_INSTALLS_PATH))
    except Exception:
        pass
    if os.path.isdir(RAG_PACKS_DIR):
        for slug in sorted(os.listdir(RAG_PACKS_DIR)):
            pdir = os.path.join(RAG_PACKS_DIR, slug)
            if not os.path.isdir(pdir):
                continue
            for name in sorted(os.listdir(pdir)):
                fpath = os.path.join(pdir, name)
                if os.path.isfile(fpath):
                    try:
                        with open(fpath, "rb") as f:
                            put("rag-packs/" + slug + "/" + name,
                                f.read(), os.path.getmtime(fpath))
                    except Exception:
                        continue
    now = time.time()
    try:
        png = build_mesh_card_png(cfg)
        if png:
            put("cards/own.png", png, now)
    except Exception:
        pass
    for peer in mesh_settings(cfg)["borrow"]["peers"]:
        try:
            if not isinstance(peer, dict):
                continue
            png = build_mesh_peer_card_png(peer)
            nid = re.sub(r"[^A-Za-z0-9_-]", "", str(peer.get("nodeId") or ""))[:12]
            if png and nid:
                put("cards/peer-" + nid + ".png", png, now)
        except Exception:
            continue
    for fed in federation_settings(cfg):
        try:
            # v0.6.4e (#321): a departed fedinet's card is never
            # dealt again — even if a ghost copy of the record
            # stands in this node's settings, the tombstone
            # outranks it, so the ghost cannot spread by deck.
            if _fed_departed(fed.get("id")):
                continue
            png = build_gateway_card_png(cfg, fed)
            fid = re.sub(r"[^A-Za-z0-9_-]", "", str(fed.get("id") or ""))[:16]
            if png and fid:
                put("cards/gateway-" + fid + ".png", png, now)
        except Exception:
            continue
    return files, index


def _sync_deck_dest(rel):
    # The landing path for a deck FILE, or None when the name is
    # not one the deck deals in. Cards and install records are
    # handled by their own paths and never land here.
    parts = rel.split("/")
    if len(parts) == 2 and parts[0] == "chips" and parts[1] not in ("", "installed.json"):
        return os.path.join(CHIPS_DIR, os.path.basename(parts[1]))
    if len(parts) == 3 and parts[0] == "rag-packs":
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", parts[1]):
            return None
        return os.path.join(RAG_PACKS_DIR, parts[1], os.path.basename(parts[2]))
    return None


def _sync_deck_merge_installs(rel, data, summary):
    # installed.json records union-merge: a record this machine
    # lacks is adopted whole; a record it holds keeps the local
    # row (install facts are machine-local). Returns True when
    # the local record file changed.
    if rel == "chips/installed.json":
        path, loader = CHIP_INSTALLS_PATH, load_chip_installs
        keyf = lambda r: str(r.get("local_file") or r.get("name") or "")
    elif rel == "rag-packs/installed.json":
        path, loader = RAG_INSTALLS_PATH, load_rag_installs
        keyf = lambda r: str(r.get("slug") or r.get("name") or "")
    else:
        return False
    try:
        remote = json.loads(data.decode("utf-8", "replace"))
    except Exception:
        return False
    if not isinstance(remote, list):
        return False
    local = loader()
    have = {keyf(r) for r in local if isinstance(r, dict)}
    merged = list(local)
    added = 0
    for row in remote:
        if not isinstance(row, dict):
            continue
        k = keyf(row)
        if k and k not in have:
            merged.append(row)
            have.add(k)
            added += 1
    if added:
        try:
            _atomic_write(path, _json_bytes(merged))
            summary["deckFilesPulled"] += 1
            return True
        except Exception:
            return False
    return False


def _sync_apply_deck_card(cfg, name, data, summary, before_peers, before_feds):
    # A card in the deck is not a file to copy — it is an act to
    # perform. A pairing card pairs, idempotently, through the
    # same validation an operator's own import walks; a gateway
    # card admits this node to a fedinet it does not keep yet —
    # admission and introduction only, never trust (Build 8's
    # law), and never a fedinet already kept.
    if name.startswith("gateway-"):
        payload, _err = parse_gateway_card_png(data)
        if not payload:
            return
        fed = payload.get("fedinet") if isinstance(payload.get("fedinet"), dict) else {}
        fid = str(payload.get("fedinetId") or fed.get("id") or "")
        if not fid or fid in before_feds:
            return
        if _fed_departed(fid):
            # v0.6.4e (#321): refused BY NAME in the round's
            # summary — a departed fedinet's card does not
            # re-admit, and the refusal is a stated fact of
            # the round, not a silent skip. Only a manual
            # import at the Federation door clears it.
            summary.setdefault("ghostRefusals", []).append(
                str(payload.get("name") or fed.get("name") or fid))
            return
        got, err = _fed_import_gateway_payload(cfg, payload, trust_default=False)
        if got and not err:
            before_feds.add(fid)
            summary["cardsImported"] += 1
        return
    peer, _err = parse_mesh_card_png(data)
    if not peer:
        return
    nid = str(peer.get("nodeId") or "")
    if not nid or nid == mesh_node_id():
        return
    if mesh_add_peer(cfg, peer) == "" and nid not in before_peers:
        before_peers.add(nid)
        summary["cardsImported"] += 1


def _sync_apply_deck(cfg, fetched, summary):
    files = fetched["files"]
    raw = files.get(SYNC_PREFIX + "deck-index.json")
    if raw is None:
        return
    try:
        index = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return
    if not isinstance(index, dict):
        return
    before_peers = {str(p.get("nodeId") or "")
                    for p in mesh_settings(cfg)["borrow"]["peers"]
                    if isinstance(p, dict)}
    before_feds = {str(f.get("id") or "") for f in federation_settings(cfg)}
    gateway_cards = []
    for rel in sorted(index):
        ent = index[rel]
        if not isinstance(ent, dict):
            continue
        data = files.get(SYNC_PREFIX + "deck/" + rel)
        if data is None:
            continue
        if rel.startswith("cards/"):
            if rel.startswith("cards/gateway-"):
                # Gateway cards land LAST, each on a freshly
                # loaded config: the import saves the config
                # itself, and a pairing add working from this
                # round's earlier snapshot must not be able to
                # save over the admission (and vice versa).
                gateway_cards.append((rel.split("/", 1)[1], data))
                continue
            _sync_apply_deck_card(cfg, rel.split("/", 1)[1], data,
                                  summary, before_peers, before_feds)
            continue
        if rel in ("chips/installed.json", "rag-packs/installed.json"):
            _sync_deck_merge_installs(rel, data, summary)
            continue
        dest = _sync_deck_dest(rel)
        if dest is None:
            continue
        remote_sha = str(ent.get("sha") or "")
        try:
            remote_mtime = int(ent.get("mtime") or 0)
        except Exception:
            remote_mtime = 0
        if os.path.isfile(dest):
            try:
                with open(dest, "rb") as f:
                    local_raw = f.read()
                local_mtime = int(os.path.getmtime(dest))
            except Exception:
                continue
            if hashlib.sha256(local_raw).hexdigest() == remote_sha:
                continue
            if local_mtime > remote_mtime:
                continue
            if local_mtime == remote_mtime:
                # Same-second divergence: the arriving copy parks
                # beside the local one, as a case file would.
                stamp = time.strftime("%Y-%m-%d", time.localtime(remote_mtime or time.time()))
                parked = dest + ".from-sync-" + stamp
                n = 2
                while os.path.exists(parked):
                    parked = dest + ".from-sync-" + stamp + "-" + str(n)
                    n += 1
                try:
                    _atomic_write(parked, data)
                except Exception:
                    pass
                if "the ChipDeck" not in summary["eyes"]:
                    summary["eyes"].append("the ChipDeck")
                continue
        try:
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            _atomic_write(dest, data)
            summary["deckFilesPulled"] += 1
        except Exception:
            continue
    for name, data in gateway_cards:
        _sync_apply_deck_card(load_config(), name, data,
                              summary, before_peers, before_feds)


_SYNC_DOCS = (("soul", "Soul"), ("memory", "memory book"))


def _sync_doc_path(name, account="operator"):
    if _account_clean(account) == "ciel":
        return soul_path_for("ciel") if name == "soul" else memory_path_for("ciel")
    return SOUL_PATH if name == "soul" else MEMORY_PATH


def _sync_apply_docs(fetched, summary, state, account="operator"):
    # Her Soul and her memory book converge per document — never
    # a silent overwrite (v0.3.0e Build 1, #200). Same bytes:
    # nothing. One side untouched since the last sync (its hash
    # is the recorded one): the other side's text lands. Both
    # changed: the newer text wins, the losing text is parked
    # beside the document as a named conflict copy, and the
    # document is named for the operator's eyes.
    files = fetched["files"]
    raw = files.get(SYNC_PREFIX + "docs-index.json")
    if raw is None:
        return
    try:
        index = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return
    if not isinstance(index, dict):
        return
    doc_sync = state.get("docSync")
    if not isinstance(doc_sync, dict):
        doc_sync = {}
    for name, label in _SYNC_DOCS:
        data = files.get(SYNC_PREFIX + "docs/" + name + ".md")
        ent = index.get(name)
        if data is None or not isinstance(ent, dict):
            continue
        path = _sync_doc_path(name, account)
        remote_sha = hashlib.sha256(data).hexdigest()
        local_raw = b""
        local_mtime = 0
        if os.path.isfile(path):
            try:
                with open(path, "rb") as f:
                    local_raw = f.read()
                local_mtime = int(os.path.getmtime(path))
            except Exception:
                local_raw, local_mtime = b"", 0
        local_sha = hashlib.sha256(local_raw).hexdigest() if local_raw else ""
        last = str(doc_sync.get(name) or "")
        if remote_sha == local_sha:
            doc_sync[name] = remote_sha
            continue
        if local_sha == last:
            try:
                _atomic_write(path, data)
                doc_sync[name] = remote_sha
                summary["docsPulled"] += 1
            except Exception:
                pass
            continue
        if remote_sha == last:
            continue
        try:
            remote_mtime = int(ent.get("mtime") or 0)
        except Exception:
            remote_mtime = 0
        stamp = time.strftime("%Y-%m-%d", time.localtime())
        base = os.path.splitext(path)[0] + ".from-sync-" + stamp
        parked = base + ".md"
        n = 2
        while os.path.exists(parked):
            parked = base + "-" + str(n) + ".md"
            n += 1
        if remote_mtime >= local_mtime:
            loser = local_raw
            try:
                _atomic_write(path, data)
                doc_sync[name] = remote_sha
                summary["docsPulled"] += 1
            except Exception:
                continue
        else:
            loser = data
            doc_sync[name] = local_sha
        try:
            _atomic_write(parked, loser)
        except Exception:
            pass
        summary["eyes"].append("her " + label)
    state["docSync"] = doc_sync


def _sync_chat_substance(chat):
    # v0.5.13e (#262): a chat's substance, in the two numbers
    # the sync law verifies by — its message count and a digest
    # of the messages themselves. The digest is over the
    # canonical message list only, so envelope drift (titles,
    # stamps) never reads as lost substance.
    msgs = (chat or {}).get("messages") if isinstance(chat, dict) else None
    if not isinstance(msgs, list):
        msgs = []
    canon = json.dumps(msgs, sort_keys=True, default=str).encode("utf-8")
    return len(msgs), hashlib.sha256(canon).hexdigest()


def _sync_main_verdict(fetched):
    # v0.6.3e (#318): the post-round substance check on the main
    # thread. The converged main is a pure function of the two
    # copies and the clear epoch: the union of both sides'
    # messages, less whatever the newer epoch retires. After a
    # round, this seat's main must BE that thread — same count,
    # same digest (#262's measure). Anything else means the
    # flagship thread disagrees with the set the round just
    # converged, and the verdict must say so rather than print
    # "converged" over it. Returns None when the arriving set
    # holds no main to judge against, else
    # {"ok": bool, "ours": n, "theirs": m}.
    files = (fetched or {}).get("files") or {}
    raw = files.get(SYNC_PREFIX + "chats.json")
    if raw is None:
        return None
    try:
        parsed = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return None
    remote_main = None
    for c in (parsed.get("chats") or []) if isinstance(parsed, dict) else []:
        rec = _chat_normalize(c)
        if rec is not None and _chat_is_main_family(rec):
            if str(rec["id"]) == MAIN_CHAT_ID or remote_main is None:
                remote_main = rec
    if remote_main is None:
        return None
    local_main = None
    for c in chats_all():
        if str(c.get("id")) == MAIN_CHAT_ID and not c.get("case"):
            local_main = c
            break
    epoch = max((local_main or {}).get("clearedAt") or 0,
                remote_main.get("clearedAt") or 0,
                _clear_epoch_for(local_main or remote_main))
    expected, _added = _chat_merge_messages(
        (local_main or {}).get("messages"), remote_main.get("messages"))
    if epoch:
        expected = _chat_clear_filter(
            {"clearedAt": epoch, "messages": expected})
    ours = _sync_chat_substance(local_main or {})
    want = _sync_chat_substance({"messages": expected})
    return {"ok": ours == want, "ours": ours[0],
            "theirs": len(remote_main.get("messages") or [])}


def _sync_apply_pulse(fetched, summary):
    # v0.5.13e (#287): the pulse store converges like every
    # other citizen — watches by id (the newer updatedAt wins),
    # seen-sets and greeted sets unioned, hits merged by digest
    # (the newer read wins), batches by id.
    # v0.8.2e (#461): a removal is a tombstone in the store
    # itself ({watch id: removal epoch}, pulse.json's own
    # citizen, so it rides the same set). The unioned set
    # judges every arrival and every local watch against
    # the watch's updatedAt: a tombstone at or after it
    # strikes/refuses; a genuinely NEWER edit beats the
    # removal, drops the tombstone, and returns as an act.
    # Every judgment is named in the summary — pulseRemoved,
    # pulseRefused, pulseResurrected — never silent.
    raw = fetched["files"].get(SYNC_PREFIX + "pulse.json")
    if raw is None:
        return
    try:
        incoming = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return
    if not isinstance(incoming, dict):
        return
    inc = {"watches": [], "batches": [], "lastRun": 0, "greetedBatches": []}
    for w in (incoming.get("watches") or []):
        cw = _pulse_clean_watch(w)
        if cw is not None:
            inc["watches"].append(cw)
    for b in (incoming.get("batches") or []):
        cb = _pulse_clean_batch(b)
        if cb is not None:
            inc["batches"].append(cb)
    inc["greetedBatches"] = [str(x)[:160] for x in (incoming.get("greetedBatches") or [])]
    changed = 0
    with _pulse_lock:
        store = _pulse_load()
        # Tombstones union first — newest removal wins —
        # and every judgment below reads the unioned set,
        # so a removal either seat recorded governs here.
        tombs = _pulse_tombstones_pruned(store.get("tombstones"))
        for _k, _v in _pulse_tombstones_pruned(
                incoming.get("tombstones")).items():
            if _k not in tombs or _v > tombs[_k]:
                tombs[_k] = _v
        refused = summary.setdefault("pulseRefused", [])
        removed = summary.setdefault("pulseRemoved", [])
        resurrected = summary.setdefault("pulseResurrected", [])

        def _pname(w):
            return ("\u201c" + str(w.get("topic") or w["id"])
                    + "\u201d (" + w["id"] + ")")

        # A local watch a tombstone covers is struck — the
        # removal traveled here, and its batches go with
        # it. A local copy NEWER than the removal is the
        # operator's later act: it stands, the tombstone
        # drops, and the win is named.
        struck = set()
        kept = []
        for w in store["watches"]:
            t = tombs.get(w["id"])
            if t is not None and t >= (w.get("updatedAt") or 0):
                struck.add(w["id"])
                removed.append(_pname(w))
                changed += 1
                continue
            if t is not None:
                resurrected.append(_pname(w))
                tombs.pop(w["id"], None)
            kept.append(w)
        store["watches"] = kept
        if struck:
            store["batches"] = [b for b in store["batches"]
                                if b["watchId"] not in struck]
        by_id = {w["id"]: w for w in store["watches"]}
        for w in inc["watches"]:
            _t = tombs.get(w["id"])
            if _t is not None:
                if _t >= (w.get("updatedAt") or 0):
                    # The removal is the newer act: refused,
                    # and named — never a silent drop.
                    refused.append(_pname(w))
                    continue
                # A genuinely newer edit beats the removal:
                # the watch returns AS AN ACT, named, and
                # the tombstone it beat is dropped.
                resurrected.append(_pname(w))
                tombs.pop(w["id"], None)
            cur = by_id.get(w["id"])
            if cur is None:
                store["watches"].append(w)
                by_id[w["id"]] = w
                changed += 1
                continue
            base = w if (w.get("updatedAt") or 0) >= (cur.get("updatedAt") or 0) else cur
            merged = dict(base)
            seen = list(base.get("seen") or [])
            for d in (cur.get("seen") or []) + (w.get("seen") or []):
                if d not in seen:
                    seen.append(d)
            merged["seen"] = seen
            hits = {h["digest"]: h for h in (cur.get("hits") or [])}
            for h in (w.get("hits") or []):
                old = hits.get(h["digest"])
                if old is None or str(h.get("readAt") or "") >= str(old.get("readAt") or ""):
                    hits[h["digest"]] = h
            merged["hits"] = sorted(hits.values(),
                                    key=lambda h: str(h.get("readAt") or ""))[-PULSE_HITS_CAP:]
            merged["lastCheck"] = max(cur.get("lastCheck") or 0, w.get("lastCheck") or 0)
            if merged != cur:
                changed += 1
            store["watches"] = [merged if x["id"] == w["id"] else x
                                for x in store["watches"]]
            by_id[w["id"]] = merged
        have_batches = {b["id"] for b in store["batches"]}
        for b in inc["batches"]:
            _bt = tombs.get(b["watchId"])
            if _bt is not None and _bt >= (b.get("at") or 0):
                # A removed watch's batches stay removed.
                refused.append("a batch for the removed watch "
                               + b["watchId"])
                continue
            if b["id"] not in have_batches:
                store["batches"].append(b)
                have_batches.add(b["id"])
                changed += 1
        store["batches"] = store["batches"][-PULSE_BATCHES_CAP:]
        greeted = list(store.get("greetedBatches") or [])
        for g in inc["greetedBatches"]:
            if g not in greeted:
                greeted.append(g)
        store["greetedBatches"] = greeted[-PULSE_BATCHES_CAP:]
        store["lastRun"] = max(store.get("lastRun") or 0,
                                incoming.get("lastRun") or 0)
        store["tombstones"] = _pulse_tombstones_pruned(tombs)
        _pulse_save(store)
    summary["pulseChanged"] = summary.get("pulseChanged", 0) + changed


def _sync_apply_seat(fetched, summary, account="operator"):
    raw = fetched["files"].get(SYNC_PREFIX + "seat.json")
    if raw is None:
        return
    try:
        incoming = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return
    if not isinstance(incoming, dict):
        return
    # v0.7.10e (#433): identity rides a sync set only when
    # the set's manifest positively stamps it as THIS
    # seat's own (accountSeat naming this account). A
    # legacy unstamped set — the pre-.9e shape that reads
    # as the operator's own — carries its entries but
    # never its identity.
    _id_ok = False
    try:
        _mf = json.loads(
            fetched["files"][SYNC_PREFIX + "manifest.json"]
            .decode("utf-8", "replace"))
        _stamp = str((_mf or {}).get("accountSeat") or "")
        _id_ok = bool(_stamp) and \
            _account_clean(_stamp) == _account_clean(account)
    except Exception:
        _id_ok = False
    _st, changes = _seat_merge(incoming, source="sync", account=account,
                               identity_ok=_id_ok)
    summary["entriesPulled"] += changes["entriesAdded"]
    summary["entriesRemoved"] = summary.get("entriesRemoved", 0) + changes.get("entriesRemoved", 0)
    if changes.get("identityRefused"):
        summary["identityRefused"] = \
            summary.get("identityRefused", 0) + 1
        summary.setdefault("foreignRefusals", []).append(
            "identity fields (name, picture, badge) in a sync "
            "set not stamped as this seat's own")
    if changes["pictureChanged"] or changes["badgeChanged"]:
        summary["seatChanged"] = True


def _sync_collect_ciel(cfg):
    # v0.7.9e (#426): her sync set, collected from HER
    # funnels — her chats, her cases, her two documents,
    # her seat book, her daybook — in the operator set's
    # own shapes, stamped accountSeat "ciel" so every gate
    # downstream can judge it. The deck and the pulse store
    # are the operator seat's citizens and do not ride.
    payload = chats_payload("ciel")
    export_chats = [c for c in payload["chats"]
                    if not c.get("case")
                    or _sync_case_files(str(c["case"]), "ciel") is not None]
    files = {}
    files[SYNC_PREFIX + "chats.json"] = json.dumps(
        {"chats": export_chats, "uploads": payload["uploads"],
         "exportedAt": _sync_now_iso()}, indent=2).encode()
    state = _sync_state_load()
    files[SYNC_PREFIX + "tombstones.json"] = json.dumps(
        _sync_tombstones_pruned(state.get("tombstones") or {}), indent=2).encode()
    index = {}
    cases_root = os.path.join(vault_dir_for("ciel"), "cases")
    if os.path.isdir(cases_root):
        for slug in sorted(os.listdir(cases_root)):
            if not os.path.isdir(os.path.join(cases_root, slug)):
                continue
            entries = _sync_case_files(slug, "ciel")
            if entries is None:
                continue
            _smeta = _case_manifest(slug, "ciel") or {}
            index[slug] = {"files": entries,
                           "sensitive": str(_smeta.get("sensitive") or "").lower() in ("yes", "true", "1")}
            d = _case_dir(slug, "ciel")
            for rel in entries:
                try:
                    with open(os.path.join(d, *rel.split("/")), "rb") as f:
                        files[SYNC_PREFIX + "cases/" + slug + "/" + rel] = f.read()
                except Exception:
                    continue
    files[SYNC_PREFIX + "cases-index.json"] = json.dumps(index, indent=2).encode()
    files[SYNC_PREFIX + "deck-index.json"] = json.dumps({}, indent=2).encode()
    docs_index = {}
    for name, _label in _SYNC_DOCS:
        path = _sync_doc_path(name, "ciel")
        try:
            with open(path, "rb") as f:
                data = f.read()
            files[SYNC_PREFIX + "docs/" + name + ".md"] = data
            docs_index[name] = {"sha": hashlib.sha256(data).hexdigest(),
                                "mtime": int(os.path.getmtime(path))}
        except Exception:
            continue
    files[SYNC_PREFIX + "docs-index.json"] = json.dumps(docs_index, indent=2).encode()
    files[SYNC_PREFIX + "seat.json"] = json.dumps(_seat_state_load("ciel"), indent=2).encode()
    try:
        with open(daybook_path_for("ciel"), "rb") as f:
            files[SYNC_PREFIX + "daybook.json"] = f.read()
    except Exception:
        pass
    account = ""
    try:
        account = str((github_auth() or {}).get("login") or "")
    except Exception:
        account = ""
    chat_digests = {}
    for c in export_chats:
        _n, _sha = _sync_chat_substance(c)
        chat_digests[str(c.get("id") or "")] = {"messages": _n, "sha": _sha}
    daybook_meta = {}
    if SYNC_PREFIX + "daybook.json" in files:
        try:
            _dw = json.loads(files[SYNC_PREFIX + "daybook.json"].decode("utf-8", "replace"))
            daybook_meta = {"entries": len((_dw or {}).get("entries") or []),
                            "sha": hashlib.sha256(files[SYNC_PREFIX + "daybook.json"]).hexdigest()}
        except Exception:
            daybook_meta = {}
    main_clear = {}
    for c in export_chats:
        if _chat_is_main_family(c) and c.get("clearedAt"):
            main_clear = {"clearedAt": c["clearedAt"],
                          "seat": c.get("clearedBy") or ""}
            break
    manifest = {"format": SYNC_FORMAT, "app": "Apex",
                "bridgeBuild": BRIDGE_BUILD, "syncedAt": _sync_now_iso(),
                "account": account, "accountSeat": "ciel",
                "mainClear": main_clear,
                "chats": len(export_chats), "cases": len(index),
                "deckFiles": 0, "docs": len(docs_index),
                "chatDigests": chat_digests,
                "chatsSha": hashlib.sha256(files[SYNC_PREFIX + "chats.json"]).hexdigest(),
                "seatSha": hashlib.sha256(files[SYNC_PREFIX + "seat.json"]).hexdigest(),
                "pulse": {},
                "daybook": daybook_meta}
    files[SYNC_PREFIX + "manifest.json"] = json.dumps(manifest, indent=2).encode()
    return files, manifest, index


def sync_collect(cfg=None, account="operator"):
    if _account_clean(account) == "ciel":
        if cfg is None:
            cfg = load_config()
        return _sync_collect_ciel(cfg)
    # The local sync set as {path: bytes} plus the case index the
    # convergence reads the other side by.
    payload = chats_payload()
    # v0.4.10e (#252): the set carries a case and its chat
    # together — a chat whose case is not on this machine does
    # not ride at all, since it could only land on the far seat
    # as an orphan.
    export_chats = [c for c in payload["chats"]
                    if not c.get("case")
                    or _sync_case_files(str(c["case"])) is not None]
    files = {}
    files[SYNC_PREFIX + "chats.json"] = json.dumps(
        {"chats": export_chats, "uploads": payload["uploads"],
         "exportedAt": _sync_now_iso()}, indent=2).encode()
    state = _sync_state_load()
    files[SYNC_PREFIX + "tombstones.json"] = json.dumps(
        _sync_tombstones_pruned(state.get("tombstones") or {}), indent=2).encode()
    index = {}
    cases_root = os.path.join(VAULT_DIR, "cases")
    if os.path.isdir(cases_root):
        for slug in sorted(os.listdir(cases_root)):
            if not os.path.isdir(os.path.join(cases_root, slug)):
                continue
            entries = _sync_case_files(slug)
            if entries is None:
                continue
            # Build 2 (#199): the index badges a sensitive case
            # as sensitive — the receiving side (and any preview
            # of what a sync carries) can see the flag without
            # opening the manifest. The flag itself also rides
            # case.md, so it survives the round trip either way.
            _smeta = _case_manifest(slug) or {}
            index[slug] = {"files": entries,
                           "sensitive": str(_smeta.get("sensitive") or "").lower() in ("yes", "true", "1")}
            d = _case_dir(slug)
            for rel in entries:
                try:
                    with open(os.path.join(d, *rel.split("/")), "rb") as f:
                        files[SYNC_PREFIX + "cases/" + slug + "/" + rel] = f.read()
                except Exception:
                    continue
    files[SYNC_PREFIX + "cases-index.json"] = json.dumps(index, indent=2).encode()
    # The Sync Update's widened set (v0.3.0e Build 1, #200): the
    # ChipDeck as one unit, her two documents, and the seat state
    # — all anchored to the GitHub account, named in the
    # manifest so a set from a different account is refused at
    # the door, never half-applied.
    if cfg is None:
        cfg = load_config()
    deck_files, deck_index = _sync_deck_collect(cfg)
    files.update(deck_files)
    files[SYNC_PREFIX + "deck-index.json"] = json.dumps(deck_index, indent=2).encode()
    docs_index = {}
    for name, _label in _SYNC_DOCS:
        path = _sync_doc_path(name)
        try:
            with open(path, "rb") as f:
                data = f.read()
            files[SYNC_PREFIX + "docs/" + name + ".md"] = data
            docs_index[name] = {"sha": hashlib.sha256(data).hexdigest(),
                                "mtime": int(os.path.getmtime(path))}
        except Exception:
            continue
    files[SYNC_PREFIX + "docs-index.json"] = json.dumps(docs_index, indent=2).encode()
    files[SYNC_PREFIX + "seat.json"] = json.dumps(_seat_state_load(), indent=2).encode()
    # v0.5.13e (#287): the pulse store rides as account data.
    try:
        with open(PULSE_PATH, "rb") as f:
            files[SYNC_PREFIX + "pulse.json"] = f.read()
    except Exception:
        pass
    # v0.6.0e (#294): the day book rides as account data too —
    # one store, every seat, converged by identity with its
    # deletions tombstoned (see _sync_apply_daybook).
    try:
        with open(DAYBOOK_PATH, "rb") as f:
            files[SYNC_PREFIX + "daybook.json"] = f.read()
    except Exception:
        pass
    account = ""
    try:
        account = str((github_auth() or {}).get("login") or "")
    except Exception:
        account = ""
    # v0.5.13e (#262): the manifest declares SUBSTANCE, not
    # just counts — per-chat message counts and digests, and a
    # digest of the seat and pulse payloads — so the receiving
    # side verifies what arrived against what was sent, names
    # a shell a shell, and a later full arrival heals it.
    chat_digests = {}
    for c in export_chats:
        _n, _sha = _sync_chat_substance(c)
        chat_digests[str(c.get("id") or "")] = {"messages": _n, "sha": _sha}
    pulse_meta = {}
    if SYNC_PREFIX + "pulse.json" in files:
        try:
            _pw = json.loads(files[SYNC_PREFIX + "pulse.json"].decode("utf-8", "replace"))
            pulse_meta = {"watches": len((_pw or {}).get("watches") or []),
                          "sha": hashlib.sha256(files[SYNC_PREFIX + "pulse.json"]).hexdigest()}
        except Exception:
            pulse_meta = {}
    daybook_meta = {}
    if SYNC_PREFIX + "daybook.json" in files:
        try:
            _dw = json.loads(files[SYNC_PREFIX + "daybook.json"].decode("utf-8", "replace"))
            daybook_meta = {"entries": len((_dw or {}).get("entries") or []),
                            "sha": hashlib.sha256(files[SYNC_PREFIX + "daybook.json"]).hexdigest()}
        except Exception:
            daybook_meta = {}
    # v0.6.3e (#318): the main thread's clear marker rides the
    # manifest as well as the record, so a receiving seat can
    # read the epoch off the set's face before it converges.
    main_clear = {}
    for c in export_chats:
        if _chat_is_main_family(c) and c.get("clearedAt"):
            main_clear = {"clearedAt": c["clearedAt"],
                          "seat": c.get("clearedBy") or ""}
            break
    manifest = {"format": SYNC_FORMAT, "app": "Apex",
                "bridgeBuild": BRIDGE_BUILD, "syncedAt": _sync_now_iso(),
                "account": account, "accountSeat": "operator",
                "mainClear": main_clear,
                "chats": len(export_chats), "cases": len(index),
                "deckFiles": len(deck_index), "docs": len(docs_index),
                "chatDigests": chat_digests,
                "chatsSha": hashlib.sha256(files[SYNC_PREFIX + "chats.json"]).hexdigest(),
                "seatSha": hashlib.sha256(files[SYNC_PREFIX + "seat.json"]).hexdigest(),
                "pulse": pulse_meta,
                "daybook": daybook_meta}
    files[SYNC_PREFIX + "manifest.json"] = json.dumps(manifest, indent=2).encode()
    return files, manifest, index


def _sync_repo(cfg):
    # (auth, base) for the operator's backup repo, ensuring it
    # exists — the same ensure github_run_backup performs. Returns
    # (None, fail) on a classified failure.
    auth = github_auth()
    if not auth:
        return None, None
    s = github_settings(cfg)
    login, token, repo = auth["login"], auth["token"], s["backup_repo"]
    base = "https://api.github.com/repos/" + login + "/" + repo
    st, _ = github_api("GET", base, token)
    if st == 404:
        st, created = github_api("POST", "https://api.github.com/user/repos", token, {
            "name": repo, "private": s["backup_private"],
            "description": "Apex backup — her ready-to-fly essentials (Soul, Memory, settings, chips, RAG packs, workflows, the Vault, Mesh pairing cards, chats).",
            "auto_init": True})
        if st not in (200, 201):
            return None, _sync_fail(st, "create the backup repo")
    elif st != 200:
        return None, _sync_fail(st, "read the backup repo")
    return (auth, base), None


def sync_fetch(cfg, account="operator"):
    # The remote sync set, through git trees/blobs like the backup
    # import (so large evidence files still arrive whole). A repo
    # with no sync/ tree yet is an EMPTY remote, not an error.
    # Returns ({"files": {...}, "manifest": {...}|None}, None) or
    # (None, fail).
    got = _sync_repo(cfg)
    if got[0] is None:
        return None, got[1] or _sync_auth_error()
    auth, base = got[0]
    token = auth["token"]
    st, repo_j = github_api("GET", base, token)
    if st != 200 or not isinstance(repo_j, dict):
        return None, _sync_fail(st, "read the backup repo")
    branch = str(repo_j.get("default_branch") or "main")
    st, tree = github_api("GET", base + "/git/trees/" + urllib.parse.quote(branch, safe="") + "?recursive=1", token)
    if st != 200 or not isinstance(tree, dict):
        return None, _sync_fail(st, "list the backup repo's files")
    blobs = {}
    for entry in tree.get("tree") or []:
        if entry.get("type") == "blob" and str(entry.get("path") or "").startswith(SYNC_PREFIX):
            blobs[str(entry["path"])] = entry.get("sha")
    files = {}
    for path, sha in blobs.items():
        bst, blob = github_api("GET", base + "/git/blobs/" + str(sha), token)
        if bst == 200 and isinstance(blob, dict) and blob.get("content"):
            try:
                files[path] = base64.b64decode(str(blob["content"]))
            except Exception:
                continue
    manifest = None
    if SYNC_PREFIX + "manifest.json" in files:
        try:
            parsed = json.loads(files[SYNC_PREFIX + "manifest.json"].decode("utf-8", "replace"))
            if isinstance(parsed, dict) and parsed.get("format") in (SYNC_FORMAT, "navi-sync/1"):
                manifest = parsed
        except Exception:
            manifest = None
    if manifest is not None:
        acct = str(manifest.get("account") or "")
        mine = str((github_auth() or {}).get("login") or "")
        if not acct or not mine:
            # v0.6.4e (#323): defense in depth on the repo road —
            # a set the door cannot attribute to an account is
            # not passed through on the strength of repo access
            # alone. (A repo with no manifest at all is still an
            # empty remote, above; this is a set that NAMES
            # itself sync and names no owner.)
            return None, {"ok": False, "kind": "auth", "state": "auth",
                          "route": "Backup repo",
                          "error": "That sync set names no GitHub account, so it cannot be attributed — sync is anchored to the account, and a set that cannot be attributed does not cross. Nothing was applied."}
        if acct.lower() != mine.lower():
            return None, {"ok": False, "kind": "auth", "state": "auth",
                          "route": "Backup repo",
                          "error": "That sync set belongs to a different GitHub account (" + acct + ") — sync is anchored to the account, and this machine is signed in as " + mine + ". Nothing crossed. Sign in with the account that owns the set, or let this machine start a set of its own."}
        # v0.7.9e (#426): the seat stamp is judged at the
        # same door — a set collected for another seat does
        # not cross into this one. Absent = the operator's.
        _seat_stamp = str(manifest.get("accountSeat") or "")
        if _seat_stamp and _account_clean(_seat_stamp) != _account_clean(account):
            return None, {"ok": False, "kind": "auth", "state": "auth",
                          "route": "Backup repo",
                          "error": "That sync set was collected for a different seat — sync stays inside one seat's account, and a set stamped for another seat does not cross. Nothing was applied."}
    return {"files": files, "manifest": manifest}, None


def _sync_reconcile_case_chats(remote_case_slugs, summary):
    # v0.4.10e (#252): a case and its chat travel together, so
    # a seat never HOLDS a case chat whose case is not on its
    # desk — the field proof was a "Case — Test" chat listed
    # while the desk read empty. Once the arriving cases have
    # landed, any chat whose case is absent folds away — not
    # listed, not offered — with a receipt in the sync state
    # naming the gap: the case, the chat, and whether the case
    # was in the arriving set and failed to land or never
    # crossed at all. No tombstone is recorded: the fold is
    # not the operator's delete, and if a later set brings the
    # case whole, the chat rides with it and the pair stands
    # again. An identical repeat arrival folds again but does
    # not receipt twice.
    remote_case_slugs = remote_case_slugs or set()
    state = _sync_state_load()
    receipts = state.get("orphanCaseChats") or []
    known = {(str(r.get("chatId")), r.get("updatedAt")) for r in receipts}
    gap_slugs = {str(r.get("case")) for r in receipts}
    dirty = False
    for chat in chats_all():
        slug = chat.get("case")
        if not slug:
            continue
        if _sync_case_files(str(slug)) is not None:
            summary["casePairsWhole"] += 1
            if str(slug) in gap_slugs:
                # v0.4.10e (#254's receipt): a gap an earlier
                # round receipted is healed — the pair stands
                # whole again. A repair is a delta, counted
                # once; the old receipt is cleared.
                summary["casePairsRepaired"] += 1
                receipts = [r for r in receipts if str(r.get("case")) != str(slug)]
                gap_slugs.discard(str(slug))
                dirty = True
            continue
        key = (str(chat["id"]), chat.get("updatedAt"))
        chat_delete(str(chat["id"]), _record=False)
        summary["orphanedCaseChats"] += 1
        summary["caseChatGapTitles"].append(str(chat.get("title") or slug))
        if key not in known:
            receipts.append({
                "chatId": str(chat["id"]), "case": str(slug),
                "title": str(chat.get("title") or ""),
                "messages": len(chat.get("messages") or []),
                "updatedAt": chat.get("updatedAt"),
                "at": time.time(),
                "reason": ("case-in-set-failed-to-land"
                           if str(slug) in remote_case_slugs
                           else "case-not-in-set")})
            known.add(key)
            dirty = True
        summary["eyes"].append("the chat of a case that did not cross: “" +
                               str(chat.get("title") or slug) + "”")
    if dirty:
        state["orphanCaseChats"] = receipts[-20:]
        _sync_state_save(state)
    return summary


def _sync_apply_tombstones(tombs, summary):
    # Deletions land BEFORE anything converges in — and only over
    # copies no newer than the deletion itself. Returns the set of
    # tombstone keys that were SUPERSEDED by newer local work (the
    # caller drops them from the stored set).
    dropped = {"chats": set(), "cases": set(), "vault": set(),
               "dossier": set()}
    chat_tombs = tombs.get("chats") or {}
    if MAIN_CHAT_ID in {str(k) for k in chat_tombs}:
        # v0.3.0e Build 1 (#200): the main chat cannot be
        # deleted, so its tombstone can never land — drop it
        # from the set rather than retry it every round.
        dropped["chats"].add(MAIN_CHAT_ID)
    for rec in chats_all():
        cid = str(rec["id"])
        if cid == MAIN_CHAT_ID:
            continue
        # v0.4.10e (#253): a chat tombstone is a fact, not a
        # suggestion weighed against timestamps. The named
        # thread dies, and so does any local representative of
        # its conversation (the "conv:" keys chat_delete
        # records), however new its last line is — newer work
        # inside a deleted conversation is not a resurrection
        # door. The operator deleted the conversation, not a
        # snapshot of it. (Build 5 weighed updatedAt here and
        # let the newer copy keep the thread — and the delete
        # the operator watched happen quietly undone itself.)
        if cid in chat_tombs or _chat_conv_tomb_key(rec) in chat_tombs:
            if chat_delete(cid, _record=False):
                summary["removedChats"] += 1
    for slug, at in (tombs.get("cases") or {}).items():
        entries = _sync_case_files(slug)
        if entries is None:
            continue
        newest = max([e["mtime"] for e in entries.values()] or [0])
        if newest <= at:
            res, _err = case_delete(slug)
            if res is not None:
                summary["removedCases"] += 1
        else:
            dropped["cases"].add(str(slug))
    for rel, at in (tombs.get("vault") or {}).items():
        safe = _sync_safe_rel(rel)
        if safe is None:
            continue
        # A stale local copy goes (case files included — and the
        # converge below vetoes re-writing this same file from
        # the remote copy it was deleted against); a file edited
        # after the deletion is newer work and keeps its copy,
        # dropping the tombstone.
        full = vault_fs_path(safe)
        try:
            if os.path.isfile(full):
                if os.path.getmtime(full) <= at:
                    vault_delete_note(safe)
                    summary["removedNotes"] += 1
                else:
                    dropped["vault"].add(safe)
                    # v0.8.2e (#467): the newer local work
                    # wins — and the win is named, not silent.
                    summary.setdefault(
                        "vaultResurrected", []).append(safe)
        except Exception:
            continue
    # v0.5.9e (#280): dossier element tombstones — an element
    # deleted on the other seat dies here too, everywhere it
    # stands (the store, this seat's case findings, the
    # formations), with custody lines written by the same
    # funnel a local delete uses. An element tombstone is a
    # fact, like a chat's (#253): it is never superseded by
    # newer work, because a re-run mints a NEW element — the
    # deleted one's identity never legitimately returns. The
    # finding files the purge removes are vault-tombstoned in
    # the same act, and those tombstones join this round's set
    # so the converge below cannot re-write the files from the
    # remote copy in the very round that deleted them.
    dossier_tombs = tombs.get("dossier") or {}
    if dossier_tombs:
        try:
            with DOSSIER_LOCK:
                _dz_store = _dossier_store()
                _dz_held = {e["id"] for d in _dz_store["dossiers"]
                            for e in d.get("elements") or []}
                for eid in dossier_tombs:
                    if eid not in _dz_held:
                        continue
                    _res, _err = element_delete(
                        eid, "sync", "", record_tombstone=False)
                    if _res:
                        summary["removedElements"] = \
                            summary.get("removedElements", 0) + 1
                        for _rel in _res.get("vaultTombstones") or []:
                            tombs.setdefault("vault", {})[_rel] = \
                                time.time()
        except Exception:
            pass
    return dropped


def _sync_apply_cases(fetched, tombs, summary):
    files = fetched["files"]
    remote_index = {}
    if SYNC_PREFIX + "cases-index.json" in files:
        try:
            parsed = json.loads(files[SYNC_PREFIX + "cases-index.json"].decode("utf-8", "replace"))
            if isinstance(parsed, dict):
                remote_index = parsed
        except Exception:
            remote_index = {}
    day = time.strftime("%Y-%m-%d", time.localtime())
    vault_tombs = tombs.get("vault") or {}
    for slug in sorted(remote_index):
        if not re.match(r"^[a-z0-9][a-z0-9-]*$", str(slug)):
            continue
        if str(slug) in (tombs.get("cases") or {}):
            # Tombstoned in the phase above; nothing lands —
            # and the refusal is named in the summary (#467).
            summary.setdefault("vaultRefused", []).append(
                "cases/" + str(slug))
            continue
        remote_files = (remote_index.get(slug) or {}).get("files") or {}
        local_before = _sync_case_files(slug)
        d = _case_dir(slug)
        if d is None:
            continue
        wrote = 0
        for rel in sorted(remote_files):
            safe = _sync_safe_rel(rel)
            if safe is None:
                continue
            meta = remote_files.get(rel) or {}
            rsha = str(meta.get("sha") or "")
            rmtime = float(meta.get("mtime") or 0)
            veto = vault_tombs.get("cases/" + slug + "/" + safe)
            if veto is not None and veto >= rmtime:
                # Deleted here after that copy was made —
                # refused, and named in the summary (#467).
                summary.setdefault("vaultRefused", []).append(
                    "cases/" + slug + "/" + safe)
                continue
            if veto is not None:
                # A copy NEWER than the deletion: the edit is
                # an act and the file returns as one — named,
                # never a silent resurrection (#467).
                summary.setdefault("vaultResurrected", []).append(
                    "cases/" + slug + "/" + safe)
            data = files.get(SYNC_PREFIX + "cases/" + slug + "/" + safe)
            if data is None:
                continue
            full = os.path.join(d, *safe.split("/"))
            local_meta = (local_before or {}).get(safe)
            if local_meta and local_meta["sha"] == rsha:
                continue
            if local_meta and local_meta["mtime"] > rmtime + 1:
                continue  # this machine's copy is the newer work
            if local_meta and rmtime <= local_meta["mtime"] + 1:
                # Same-second divergence: park the remote copy as
                # a dated sibling — both survive, the case is
                # named to the operator's eyes.
                sib = full + ".from-sync-" + day
                try:
                    with open(sib, "rb") as f:
                        if f.read() == data:
                            continue
                except Exception:
                    pass
                os.makedirs(os.path.dirname(full), exist_ok=True)
                with open(sib, "wb") as f:
                    f.write(data)
                if slug not in summary["caseEyes"]:
                    summary["caseEyes"].append(slug)
                continue
            os.makedirs(os.path.dirname(full), exist_ok=True)
            with open(full, "wb") as f:
                f.write(data)
            try:
                os.utime(full, (rmtime, rmtime))
            except Exception:
                pass
            wrote += 1
        if wrote:
            if local_before is None:
                summary["casesAdded"] += 1
            else:
                summary["casesUpdated"] += 1
            summary["caseFilesPulled"] += wrote


def _sync_apply_ciel(cfg, fetched):
    # v0.7.9e (#426): a ciel set lands in HER root only —
    # her chats through her chat funnel, her case files
    # into her vault, her docs, her seat book, her daybook.
    # The operator's stores are never read or written here.
    # A set stamped for another seat is foreign, refused in
    # the summary like the operator gate refuses its own.
    summary = {"removedChats": 0, "removedCases": 0, "removedNotes": 0,
               "chatsAdded": 0, "chatsReplaced": 0, "chatsSiblings": 0,
               "chatsCleared": 0, "foreignRefusals": [],
               "chatsDeduped": 0, "chatsMainMerged": 0, "chatsMainFolded": 0,
               "chatsMainMergedMessages": 0, "chatsMainFoldedMessages": 0,
               "orphanedCaseChats": 0, "casePairsWhole": 0,
               "casePairsRepaired": 0, "caseChatGapTitles": [],
               "casesAdded": 0, "casesUpdated": 0, "caseFilesPulled": 0,
               "deckFilesPulled": 0, "cardsImported": 0, "docsPulled": 0,
               "entriesPulled": 0, "seatChanged": False,
               "pulseChanged": 0, "daybookChanged": 0, "incomplete": [],
               "pulseRefused": [], "pulseRemoved": [],
               "pulseResurrected": [], "vaultRefused": [],
               "vaultResurrected": [],
               "eyes": [], "caseEyes": []}
    files = fetched["files"]
    manifest = fetched.get("manifest") if isinstance(fetched.get("manifest"), dict) else {}
    if not manifest and SYNC_PREFIX + "manifest.json" in files:
        try:
            _pm = json.loads(files[SYNC_PREFIX + "manifest.json"].decode("utf-8", "replace"))
            if isinstance(_pm, dict):
                manifest = _pm
        except Exception:
            manifest = {}
    _stamp = str(manifest.get("accountSeat") or "")
    if _stamp and _account_clean(_stamp) != "ciel":
        summary["foreignRefusals"].append(
            "a whole sync set, stamped for another seat")
        summary["changed"] = 0
        return summary
    before_ids = {str(c["id"]) for c in chats_all("ciel")}
    if SYNC_PREFIX + "chats.json" in files:
        try:
            parsed = json.loads(files[SYNC_PREFIX + "chats.json"].decode("utf-8", "replace"))
        except Exception:
            parsed = {}
        for rec in (parsed.get("chats") or []) if isinstance(parsed, dict) else []:
            saved = chat_write(rec, account="ciel")
            if saved is not None:
                if saved["id"] in before_ids:
                    summary["chatsReplaced"] += 1
                else:
                    summary["chatsAdded"] += 1
    for path, data in files.items():
        if not path.startswith(SYNC_PREFIX + "cases/"):
            continue
        rest = path[len(SYNC_PREFIX + "cases/"):]
        slug, _, rel = rest.partition("/")
        if not rel or _case_dir(slug, "ciel") is None:
            continue
        safe = _sync_safe_rel(rel)
        if safe is None:
            continue
        full = os.path.join(_case_dir(slug, "ciel"), *safe.split("/"))
        try:
            os.makedirs(os.path.dirname(full), exist_ok=True)
            with open(full, "wb") as f:
                f.write(data)
            summary["caseFilesPulled"] += 1
        except Exception:
            continue
    _doc_state = {"docSync": dict(
        (_sync_state_load().get("docSyncCiel") or {}))}
    _sync_apply_docs(fetched, summary, _doc_state, account="ciel")
    try:
        _st = _sync_state_load()
        _st["docSyncCiel"] = _doc_state.get("docSync") or {}
        _sync_state_save(_st)
    except Exception:
        pass
    _sync_apply_seat(fetched, summary, account="ciel")
    _sync_apply_daybook(fetched, summary, None, account="ciel")
    summary["changed"] = (
        summary["chatsAdded"] + summary["chatsReplaced"]
        + summary["caseFilesPulled"] + summary["docsPulled"]
        + summary["entriesPulled"] + summary["daybookChanged"])
    return summary


def sync_apply(cfg, fetched, account="operator"):
    # Converge a fetched remote sync set into this machine:
    # tombstones, then chats, then case files. Returns the round
    # summary the card speaks.
    if _account_clean(account) == "ciel":
        return _sync_apply_ciel(cfg, fetched)
    summary = {"removedChats": 0, "removedCases": 0, "removedNotes": 0,
               "chatsAdded": 0, "chatsReplaced": 0, "chatsSiblings": 0,
               "chatsCleared": 0, "foreignRefusals": [],
               "chatsDeduped": 0, "chatsMainMerged": 0, "chatsMainFolded": 0,
               "chatsMainMergedMessages": 0, "chatsMainFoldedMessages": 0,
               "orphanedCaseChats": 0, "casePairsWhole": 0,
               "casePairsRepaired": 0, "caseChatGapTitles": [],
               "casesAdded": 0, "casesUpdated": 0, "caseFilesPulled": 0,
               "deckFilesPulled": 0, "cardsImported": 0, "docsPulled": 0,
               "entriesPulled": 0, "seatChanged": False,
               "pulseChanged": 0, "daybookChanged": 0, "incomplete": [],
               "pulseRefused": [], "pulseRemoved": [],
               "pulseResurrected": [], "vaultRefused": [],
               "vaultResurrected": [],
               "eyes": [], "caseEyes": []}
    files = fetched["files"]
    remote_tombs = {}
    if SYNC_PREFIX + "tombstones.json" in files:
        try:
            parsed = json.loads(files[SYNC_PREFIX + "tombstones.json"].decode("utf-8", "replace"))
            if isinstance(parsed, dict):
                remote_tombs = parsed
        except Exception:
            remote_tombs = {}
    state = _sync_state_load()
    # v0.6.19e (#365): the account gate, at the shared funnel.
    # The set's manifest names its account; when it names one
    # and this seat is signed in to a DIFFERENT one, the set is
    # foreign here — nothing of it lands: not its chat push,
    # not its tombstones, not its clears. The refusal is named
    # in the summary the card speaks and in the sync state's
    # refusal record. A set naming no account (an older build's)
    # is taken as it comes, as before — but its CLEARS are
    # judged one by one at the per-artifact gate below, since
    # every clear carries its own stamp. A seat that cannot
    # name its own account does not refuse whole sets here:
    # the doors (Mesh admission, the repo's own ownership)
    # already govern that road, and #323's unknown-is-a-refusal
    # law applies in full to the clears.
    _early_manifest = {}
    if SYNC_PREFIX + "manifest.json" in files:
        try:
            _pm0 = json.loads(files[SYNC_PREFIX + "manifest.json"].decode("utf-8", "replace"))
            if isinstance(_pm0, dict):
                _early_manifest = _pm0
        except Exception:
            _early_manifest = {}
    _mine_login = ""
    try:
        _mine_login = str((github_auth() or {}).get("login") or "")
    except Exception:
        _mine_login = ""
    _set_account = str(_early_manifest.get("account") or "")
    _foreign_set = bool(_set_account and _mine_login
                        and _set_account.lower() != _mine_login.lower())
    # v0.7.9e (#426): the seat gate rides the same verdict —
    # a set stamped for a different seat than the one
    # syncing is foreign here, exactly as a different
    # account's set is. Absent stamp = the operator's set
    # (pre-.9e sets keep working).
    _seat_stamp = str(_early_manifest.get("accountSeat") or "")
    if _seat_stamp and _account_clean(_seat_stamp) != _account_clean(account):
        _foreign_set = True
    # v0.6.30e (#377): the round's account verdict is recorded
    # whatever road it takes from here — the whole-set refusal
    # below, the payload gate further down, or a clean apply.
    # The sweep reads it as its arming proof (gateProof).
    try:
        _stg0 = _sync_state_load()
        _stg0["gateProof"] = {"account": _mine_login,
                              "setAccount": _set_account,
                              "foreignSet": bool(_foreign_set),
                              "at": int(time.time())}
        _sync_state_save(_stg0)
    except Exception:
        pass
    _raw_clears = remote_tombs.pop("clears", {}) \
        if isinstance(remote_tombs, dict) else {}
    if not isinstance(_raw_clears, dict):
        _raw_clears = {}
    if _foreign_set:
        _sync_note_foreign_refusal(state, "set", _set_account)
        summary["foreignRefusals"].append(
            "a whole sync set, stamped " + _set_account)
        for _k in sorted(_raw_clears):
            _e = _clear_entry_norm(_raw_clears[_k])
            if _e is not None:
                summary["foreignRefusals"].append(
                    "a clear for a chat, stamped "
                    + (_e["account"] or "with no account"))
        if _raw_clears:
            _sync_note_foreign_refusal(state, "clear", _set_account)
        summary["changed"] = 0
        _sync_state_save(state)
        return summary
    _admitted_clears, _refused_clears = _sync_gate_clears(_raw_clears)
    for _k, _acct in _refused_clears:
        _sync_note_foreign_refusal(state, "clear", _acct, _k)
        summary["foreignRefusals"].append(
            "a clear for a chat, stamped " + (_acct or "with no account"))
    if _admitted_clears:
        remote_tombs["clears"] = _admitted_clears
    merged = _sync_merge_tombstones(state.get("tombstones") or {}, remote_tombs)
    dropped = _sync_apply_tombstones(merged, summary)
    remote_chats, remote_uploads = [], None
    if SYNC_PREFIX + "chats.json" in files:
        try:
            parsed = json.loads(files[SYNC_PREFIX + "chats.json"].decode("utf-8", "replace"))
            if isinstance(parsed, dict):
                if isinstance(parsed.get("chats"), list):
                    remote_chats = parsed["chats"]
                if isinstance(parsed.get("uploads"), list):
                    remote_uploads = parsed["uploads"]
        except Exception:
            remote_chats, remote_uploads = [], None
    # v0.5.13e (#262): the substance law. The sender's manifest
    # declares what the set SHOULD hold; arrivals are verified
    # against it before anything converges. A payload whose
    # bytes do not match its declared digest arrived as a
    # shell: it is named incomplete, and for the seat and the
    # pulse — single documents, merged destructively — the
    # shell is refused outright rather than merged over good
    # local substance. Sets from older builds declare nothing
    # and are taken as they come, as before.
    remote_manifest = {}
    if SYNC_PREFIX + "manifest.json" in files:
        try:
            _pm = json.loads(files[SYNC_PREFIX + "manifest.json"].decode("utf-8", "replace"))
            if isinstance(_pm, dict):
                remote_manifest = _pm
        except Exception:
            remote_manifest = {}
    declared_chats = remote_manifest.get("chatDigests")
    if not isinstance(declared_chats, dict):
        declared_chats = {}
    _seat_shell = False
    if remote_manifest.get("seatSha") and SYNC_PREFIX + "seat.json" in files:
        if hashlib.sha256(files[SYNC_PREFIX + "seat.json"]).hexdigest() != remote_manifest["seatSha"]:
            _seat_shell = True
            summary["incomplete"].append(
                {"kind": "seat", "id": "seat",
                 "name": "Settings & theme (the seat)"})
    _pulse_shell = False
    _pulse_decl = remote_manifest.get("pulse") if isinstance(remote_manifest.get("pulse"), dict) else {}
    if _pulse_decl.get("sha") and SYNC_PREFIX + "pulse.json" in files:
        if hashlib.sha256(files[SYNC_PREFIX + "pulse.json"]).hexdigest() != _pulse_decl["sha"]:
            _pulse_shell = True
            summary["incomplete"].append(
                {"kind": "pulse", "id": "pulse", "name": "Pulse watches"})
    _daybook_shell = False
    _daybook_decl = remote_manifest.get("daybook") if isinstance(remote_manifest.get("daybook"), dict) else {}
    if _daybook_decl.get("sha") and SYNC_PREFIX + "daybook.json" in files:
        if hashlib.sha256(files[SYNC_PREFIX + "daybook.json"]).hexdigest() != _daybook_decl["sha"]:
            _daybook_shell = True
            summary["incomplete"].append(
                {"kind": "daybook", "id": "daybook", "name": "Her working day"})
    # The tombstone's other half: a chat ABSENT here but present
    # in the remote set is not an "add" when a tombstone covers
    # it — it is the resurrection the tombstone exists to refuse.
    # (The phase above only deletes copies that exist locally;
    # without this filter, convergence would faithfully re-add
    # every deleted thread from the other machine's store.)
    # A tombstone covers its CONVERSATION as well as its id
    # (the "conv:" keys chat_delete records). Through
    # v0.4.9e a copy stamped newer than the tombstone was let
    # back in as a revival generation; v0.4.10e (#253) retires
    # that door — covered is covered, at any stamp.
    chat_tombs = merged.get("chats") or {}
    if chat_tombs:
        kept = []
        for raw in remote_chats:
            rec = _chat_normalize(raw)
            if rec is None:
                continue
            if _chat_is_main_family(rec):
                # v0.4.10e (#251): the main seat is governed by
                # the merge, never by tombstones — it cannot be
                # deleted, and its records fold into the one
                # thread at convergence below.
                kept.append(raw)
                continue
            if str(rec["id"]) in chat_tombs or \
                    _chat_conv_tomb_key(rec) in chat_tombs:
                # v0.4.10e (#253): covered by a tombstone —
                # refused, however new its last line claims to
                # be. Build 5's revival generation is retired:
                # a deleted conversation does not come back
                # wearing a "(from sync)" coat, and a seat that
                # was away when the delete happened cannot undo
                # it by syncing late. The tombstones themselves
                # are kept: they are the record of the
                # operator's act, pruned only by the standing
                # 90-day rule in _sync_tombstones_pruned.
                continue
            kept.append(raw)
        remote_chats = kept
    for kind in ("chats", "cases", "vault", "dossier"):
        for key in dropped[kind]:
            merged[kind].pop(key, None)
    state["tombstones"] = merged
    _sync_state_save(state)
    # v0.5.13e (#262): per-chat verification. A remote chat
    # whose substance (count + digest) does not match what the
    # manifest declared for it arrived as a shell. Where this
    # seat already holds MORE of that conversation, the shell
    # is refused — convergence never trades substance for a
    # husk; where it holds nothing, the shell lands (a husk is
    # better than a hole) and is still named, so the bar and
    # the record say plainly that it is incomplete until a
    # fuller arrival heals it.
    if declared_chats:
        _local_counts = {}
        for _c in chats_all():
            _local_counts[str(_c.get("id") or "")] = len(_c.get("messages") or [])
        _kept = []
        for _raw in remote_chats:
            _rec = _chat_normalize(_raw)
            if _rec is None:
                _kept.append(_raw)
                continue
            _decl = declared_chats.get(str(_rec["id"]))
            if not isinstance(_decl, dict):
                _kept.append(_raw)
                continue
            _n, _sha = _sync_chat_substance(_rec)
            if _n == _decl.get("messages") and _sha == _decl.get("sha"):
                _kept.append(_raw)
                continue
            summary["incomplete"].append(
                {"kind": "chat", "id": str(_rec["id"]),
                 "name": "Chat \u201c" + str(_rec.get("title") or _rec["id"]) + "\u201d"})
            if _local_counts.get(str(_rec["id"]), 0) > _n:
                continue
            _kept.append(_raw)
        remote_chats = _kept
    before_ids = {str(c["id"]) for c in chats_all()}
    conv = chats_converge(remote_chats, remote_uploads)
    summary["chatsAdded"] = conv["added"]
    summary["chatsReplaced"] = conv["replaced"]
    summary["chatsSiblings"] = conv["siblings"]
    summary["chatsCleared"] = conv.get("chatsCleared", 0)
    summary["chatsDeduped"] = conv.get("deduped", 0)
    summary["chatsMainMerged"] = conv.get("mainMerged", 0)
    summary["chatsMainFolded"] = conv.get("mainFolded", 0)
    summary["chatsMainMergedMessages"] = conv.get("mainMergedMessages", 0)
    summary["chatsMainFoldedMessages"] = conv.get("mainFoldedMessages", 0)
    if conv["siblings"]:
        for c in chats_all():
            if str(c["id"]) not in before_ids and "-sync-" in str(c["id"]):
                summary["eyes"].append(str(c.get("title") or c["id"]))
    # v0.5.13e (#262): the arrival proof, read back off the
    # local store — after convergence, every declared chat
    # must stand here with at least the messages it was sent
    # with. Convergence unions and never deletes, so a short
    # count means the substance genuinely did not cross.
    if declared_chats:
        _after = {str(c.get("id") or ""): len(c.get("messages") or [])
                  for c in chats_all()}
        _named = {e["id"] for e in summary["incomplete"] if e["kind"] == "chat"}
        for _cid, _decl in declared_chats.items():
            if not isinstance(_decl, dict) or _cid in _named:
                continue
            if _after.get(_cid, 0) < int(_decl.get("messages") or 0):
                _ttl = next((str(c.get("title") or _cid) for c in chats_all()
                             if str(c.get("id") or "") == _cid), _cid)
                summary["incomplete"].append(
                    {"kind": "chat", "id": _cid,
                     "name": "Chat \u201c" + _ttl + "\u201d"})
    _sync_apply_cases(fetched, merged, summary)
    # v0.4.10e (#252): the pairing check runs once the arriving
    # cases have landed — a chat whose case is not on this desk
    # folds away with a receipt and the gap is named, rather
    # than listing as a case chat whose case is missing.
    _remote_case_slugs = set()
    if SYNC_PREFIX + "cases-index.json" in files:
        try:
            _parsed_index = json.loads(files[SYNC_PREFIX + "cases-index.json"].decode("utf-8", "replace"))
            if isinstance(_parsed_index, dict):
                _remote_case_slugs = {str(k) for k in _parsed_index}
        except Exception:
            pass
    _sync_reconcile_case_chats(_remote_case_slugs, summary)
    _sync_apply_deck(cfg, fetched, summary)
    _sync_apply_docs(fetched, summary, state, account=account)
    _sync_state_save(state)
    # v0.6.30e (#377, on #337): the account-level payloads —
    # the seat state (the "About you" memories and the
    # operator's name, picture and badge), the daybook (the
    # personal reminders ride it) and the pulse — converge
    # ONLY when the arriving set names its account AND this
    # seat is signed in to that same account. The .19e funnel
    # above refuses a whole set only when both sides name
    # DIFFERENT accounts; it fails open for an unnamed set
    # and for a seat that cannot name its own account, and
    # through that opening one operator's memories and
    # reminders landed on another operator's seat (the field
    # report behind #377). Here the payloads fail CLOSED and
    # BY NAME: chats, cases, docs and the deck still converge
    # as before (they carry their own gates, and the sweep
    # judges them), but account-level material that cannot
    # prove it belongs to this seat's account does not land.
    # The gate's verdict — either way — is recorded in the
    # sync state as the sweep's arming proof (gateProof):
    # material already spread is judged by
    # sync_account_gate_sweep once this seat's account has
    # been proven on a live round.
    _acct_gate_ok = bool(_set_account and _mine_login
                         and _set_account.lower() == _mine_login.lower())
    if not _pulse_shell:
        if _acct_gate_ok:
            _sync_apply_pulse(fetched, summary)
        else:
            _sync_foreign_refusal_note("pulse", _set_account)
            summary["foreignRefusals"].append(
                "a pulse payload, stamped "
                + (_set_account or "with no account"))
    if not _daybook_shell:
        if _acct_gate_ok:
            _sync_apply_daybook(fetched, summary, merged, account=account)
        else:
            _sync_foreign_refusal_note("daybook", _set_account)
            summary["foreignRefusals"].append(
                "a day book payload, stamped "
                + (_set_account or "with no account"))
    if not _seat_shell:
        if _acct_gate_ok:
            _sync_apply_seat(fetched, summary, account=account)
        else:
            _sync_foreign_refusal_note("seat", _set_account)
            summary["foreignRefusals"].append(
                "a seat payload — memories about the operator, "
                "stamped " + (_set_account or "with no account"))
    # v0.6.4e (#323): attribution — the apply path records, per
    # item it converged, the account the arriving set named as
    # its own ("" when it named none). The ledger is the purge's
    # evidence (see sync_account_gate_sweep): from this build
    # on, every converged item can be attributed to the set
    # that carried it, exactly, at the moment it landed.
    try:
        _src_acct = str(remote_manifest.get("account") or "")
        if not _src_acct and isinstance(fetched.get("manifest"), dict):
            _src_acct = str(fetched["manifest"].get("account") or "")
        _st3 = _sync_state_load()
        _attr = _st3.get("attribution") if isinstance(_st3.get("attribution"), dict) else {}
        for _fam in ("chats", "cases", "docs", "daybook", "seat", "pulse"):
            if not isinstance(_attr.get(_fam), dict):
                _attr[_fam] = {}
        for _c in remote_chats:
            _rec = _chat_normalize(_c)
            if _rec is not None:
                _attr["chats"][str(_rec["id"])] = _src_acct
        for _slug in _remote_case_slugs:
            _attr["cases"][str(_slug)] = _src_acct
        for _name, _label in _SYNC_DOCS:
            if SYNC_PREFIX + "docs/" + _name + ".md" in files:
                _attr["docs"][_name] = _src_acct
        _db_raw = files.get(SYNC_PREFIX + "daybook.json")
        if _db_raw and _acct_gate_ok:
            try:
                _db = json.loads(_db_raw.decode("utf-8", "replace"))
                for _e in ((_db or {}).get("entries") or []):
                    if isinstance(_e, dict) and _e.get("id"):
                        _attr["daybook"][str(_e["id"])] = _src_acct
            except Exception:
                pass
        # v0.6.30e (#377): the seat and the pulse join the
        # ledger — recorded only when the payload actually
        # landed (the gate above): a refused set attributes
        # nothing here, so a foreign set can never re-stamp
        # this seat's own facts with its account.
        if _acct_gate_ok:
            _seat_raw = files.get(SYNC_PREFIX + "seat.json")
            if _seat_raw:
                try:
                    _sb = json.loads(_seat_raw.decode("utf-8", "replace"))
                    if isinstance(_sb, dict):
                        for _e in (_sb.get("entries") or []):
                            if isinstance(_e, dict) and _e.get("t"):
                                _attr["seat"][_seat_fact_id(str(_e["t"]))] = _src_acct
                        _attr["seat"]["@identity"] = _src_acct
                except Exception:
                    pass
            _pulse_raw = files.get(SYNC_PREFIX + "pulse.json")
            if _pulse_raw:
                try:
                    _pb = json.loads(_pulse_raw.decode("utf-8", "replace"))
                    if isinstance(_pb, dict):
                        for _w in (_pb.get("watches") or []):
                            if isinstance(_w, dict) and _w.get("id"):
                                _attr["pulse"][str(_w["id"])] = _src_acct
                except Exception:
                    pass
        _st3["attribution"] = _attr
        _sync_state_save(_st3)
    except Exception:
        pass
    summary["changed"] = (summary["removedChats"] + summary["removedCases"]
                          + summary["removedNotes"] + summary["chatsAdded"]
                          + summary["chatsReplaced"] + summary["chatsSiblings"]
                          + summary["chatsDeduped"] + summary["chatsMainMerged"]
                          + summary["chatsMainFolded"] + summary["orphanedCaseChats"]
                          + summary["casesAdded"] + summary["casesUpdated"]
                          + summary["deckFilesPulled"] + summary["cardsImported"]
                          + summary["docsPulled"] + summary["entriesPulled"]
                          + summary.get("entriesRemoved", 0)
                          + (1 if summary["seatChanged"] else 0)
                          + summary.get("pulseChanged", 0)
                          + summary.get("daybookChanged", 0))
    # v0.5.13e (#262): the incomplete record persists in the
    # sync state — the bar names shells until a later round's
    # full arrival heals them, which is simply a round where
    # they are not named again.
    try:
        _st2 = _sync_state_load()
        _prev = [e for e in (_st2.get("incomplete") or [])
                 if isinstance(e, dict) and e.get("id")]
        _now_ids = {(e["kind"], e["id"]) for e in summary["incomplete"]}
        _still = [e for e in _prev
                  if (e.get("kind"), e.get("id")) in _now_ids]
        _have = {(e.get("kind"), e.get("id")) for e in _still}
        for e in summary["incomplete"]:
            if (e["kind"], e["id"]) not in _have:
                _still.append(e)
                _have.add((e["kind"], e["id"]))
        _st2["incomplete"] = _still
        _sync_state_save(_st2)
    except Exception:
        pass
    # v0.6.3e (#318): the main thread's verdict, judged AFTER
    # everything landed — the finish summary renames the round
    # on a mismatch, so no road (repo, Mesh, pull, receive) can
    # print a clean "converged" over a divergent main thread.
    try:
        summary["mainVerdict"] = _sync_main_verdict(fetched)
    except Exception:
        summary["mainVerdict"] = None
    return summary


def _tombstoned_repo_paths(tombs, repo_paths):
    # v0.8.4e (#472): the repo paths the tombstone set
    # condemns — a tombstoned vault path's backup copy
    # (vault/<rel>) and every file of a tombstoned case
    # (sync/cases/<slug>/…). Judged by the tombstone, never
    # by absence: a path missing from the new set for any
    # other reason (a partial backup, an unticked item)
    # is NOT condemned, and the repo keeps it.
    vault_tombs = (tombs or {}).get("vault") or {}
    case_tombs = (tombs or {}).get("cases") or {}
    out = []
    for p in repo_paths:
        if p.startswith("vault/") \
                and p[len("vault/"):] in vault_tombs:
            out.append(p)
        elif p.startswith(SYNC_PREFIX + "cases/"):
            slug = p[len(SYNC_PREFIX + "cases/"):].split("/", 1)[0]
            if slug in case_tombs:
                out.append(p)
    return sorted(out)


def _github_delete_path(base, token, path, sha=None):
    # One file out of the backup repo (the Contents API's
    # DELETE). True when the file went — or was already
    # gone, which is the verdict the deletion leg wants
    # either way.
    url = base + "/contents/" + urllib.parse.quote(path, safe="/")
    if sha is None:
        gst, existing = github_api("GET", url, token)
        if gst == 404:
            return True
        if gst == 200 and isinstance(existing, dict):
            sha = existing.get("sha")
        else:
            return False
    dst, _resp = github_api("DELETE", url, token, {
        "message": "Apex — a tombstoned file leaves the backup: "
                   + path,
        "sha": sha})
    return dst in (200, 201)


def _sync_push(cfg, base, token, files, fetched_files):
    # Publish the converged local set. Files the remote already
    # holds byte-identical are not rewritten. Returns the count
    # of files actually written, or (None, fail).
    # v0.4.10e (#254): the write phase reports its counts to
    # the sync bar — the differing-file total is known before
    # the loop, and the written count as it goes (throttled:
    # at most twice a second, plus the final state).
    total = sum(1 for p in files if fetched_files.get(p) != files[p])
    _sync_progress_set("write", counts={"filesTotal": total, "filesWritten": 0})
    written = 0
    last_note = 0.0
    for path in sorted(files):
        if fetched_files.get(path) == files[path]:
            continue
        url = base + "/contents/" + urllib.parse.quote(path, safe="/")
        sha = None
        gst, existing = github_api("GET", url, token)
        if gst == 200 and isinstance(existing, dict):
            sha = existing.get("sha")
        elif gst not in (200, 404):
            return None, _sync_fail(gst, "check " + path + " in the backup repo")
        body = {"message": "Apex Quick Sync " + _sync_now_iso(),
                "content": base64.b64encode(files[path]).decode()}
        if sha:
            body["sha"] = sha
        pst, _resp = github_api("PUT", url, token, body)
        if pst not in (200, 201):
            return None, _sync_fail(pst, "write " + path + " to the backup repo")
        written += 1
        if time.time() - last_note >= 0.5 or written == total:
            last_note = time.time()
            _sync_progress_set("write", counts={"filesTotal": total, "filesWritten": written})
    # v0.8.4e (#472): the deletion leg — tombstoned
    # vault/cases paths LEAVE the repo in this same push.
    # Until now a tombstone only refused at restore: the
    # transports stopped carrying the file, but its bytes
    # sat in the backup's HEAD indefinitely (the field's
    # manual purge of 2026-11-23 removed 27 dossier paths
    # by hand). Judged by the tombstone set, over the paths
    # the repo was just read holding and this round does
    # not re-publish.
    tombs = _sync_state_load().get("tombstones") or {}
    condemned = _tombstoned_repo_paths(
        tombs, [p for p in fetched_files if p not in files])
    deleted = 0
    for path in condemned:
        if _github_delete_path(base, token, path):
            deleted += 1
        else:
            return None, _sync_fail(0, "remove tombstoned " + path
                                    + " from the backup repo")
    return written + deleted, None


def _sync_record_result(state, trigger, result):
    state["lastSyncAt"] = _sync_now_iso()
    state["lastSyncEpoch"] = time.time()
    state["lastTrigger"] = trigger
    state["lastState"] = result.get("state") or ""
    state["lastResult"] = result.get("message") or result.get("error") or ""
    # v0.4.10e (#254): the durable receipt — the sync bar's
    # landing face reads this record, and the #242 producer
    # announces from it. Counts ride the finish summary's
    # receipt; failure verdicts carry their message and no
    # counts. The record is the copy that outlives the bar.
    receipt = result.get("receipt") if isinstance(result.get("receipt"), dict) else {}
    state["lastReceipt"] = {
        "at": state["lastSyncEpoch"],
        "trigger": trigger,
        "route": result.get("route") or "",
        "ok": result.get("ok") is True,
        "state": result.get("state") or "",
        "message": result.get("message") or result.get("error") or "",
        "counts": receipt,
        # v0.6.2e (#303): a directional round (Send / Receive)
        # names its direction on the durable receipt too.
        "direction": result.get("direction") or "",
        # v0.6.3e (#317): a round the operator's choice stopped
        # names the supersession on its record.
        "preempted": bool(result.get("preempted")),
        # v0.6.3e (#318): a renamed verdict carries the main
        # thread's disagreement on the receipt too.
        "mainThread": result.get("mainThread") or None,
        # v0.6.4e (#323): a Mesh-road account refusal the round
        # met is named on the receipt — the fall-through to the
        # repo road is never a silent success shape.
        "meshRefusal": result.get("meshRefusal") or _sync_mesh_refusal_take(),
        "material": bool(receipt.get("material")),
        "roundId": result.get("roundId") or "",
        # v0.5.1e (#257): the round's measured duration rides
        # the receipt — the bar names the road and the time it
        # actually took, measured, never asserted.
        "durationMs": (result.get("durationMs")
                       if isinstance(result.get("durationMs"), (int, float)) else None),
    }
    _sync_state_save(state)


def _sync_finish_summary(summary, pushed_files, open_chat_id, collected_chats):
    eyes = list(summary["eyes"])
    for slug in summary["caseEyes"]:
        meta = _case_manifest(slug)
        eyes.append("the case “" + str((meta or {}).get("title") or slug) + "”")
    pulled_chats = summary["chatsAdded"] + summary["chatsReplaced"]
    result = {
        "ok": True,
        "state": "eyes" if eyes else "synced",
        "route": "Backup repo",
        "pulledChats": pulled_chats,
        "pushedFiles": pushed_files,
        "caseFilesPulled": summary["caseFilesPulled"],
        "deckFilesPulled": summary.get("deckFilesPulled", 0),
        "cardsImported": summary.get("cardsImported", 0),
        "ghostRefusals": list(summary.get("ghostRefusals") or []),
        "foreignRefused": list(summary.get("foreignRefusals") or []),
        "docsPulled": summary.get("docsPulled", 0),
        "entriesPulled": summary.get("entriesPulled", 0),
        "entriesRemoved": summary.get("entriesRemoved", 0),
        "seatChanged": bool(summary.get("seatChanged")),
        "incomplete": [str(e.get("name") or e.get("id") or "")
                       for e in (summary.get("incomplete") or [])],
        "removed": summary["removedChats"] + summary["removedCases"] + summary["removedNotes"],
        "needsEyes": eyes,
        "openIncluded": bool(open_chat_id) and str(open_chat_id) in collected_chats,
    }
    if eyes:
        result["message"] = ("Synced — but " + str(len(eyes)) + " item"
                             + ("s" if len(eyes) != 1 else "")
                             + " parked both copies and need your eyes: "
                             + "; ".join(eyes[:3]) + ".")
    elif result["incomplete"]:
        result["message"] = ("Synced — but " + str(len(result["incomplete"]))
                             + " item" + ("s" if len(result["incomplete"]) != 1 else "")
                             + " arrived incomplete: "
                             + "; ".join(result["incomplete"][:3])
                             + ". A fuller copy heals "
                             + ("them" if len(result["incomplete"]) != 1 else "it")
                             + " on a later round.")
    elif result["foreignRefused"]:
        # v0.6.19e (#365): a foreign artifact was turned away
        # this round — named, never silent (#337).
        result["message"] = ("Synced — and refused "
                             + "; ".join(result["foreignRefused"][:3])
                             + ". Nothing stamped with another "
                             "account lands on this seat.")
    elif pulled_chats or summary["chatsSiblings"] or summary["changed"]:
        result["message"] = "Synced — the machines converged."
    else:
        result["message"] = "Synced — already in step."
    # v0.6.3e (#318): the verdict honesty gate. When the main
    # thread disagrees with the converged set after the round,
    # the verdict is RENAMED — never a clean "converged", never
    # a plain "Synced" — on this result, and therefore on the
    # durable receipt and the Sync card's last-round line that
    # read it back. The direction is named in counts: theirs is
    # the arriving set's main, ours is this seat's.
    _mv = summary.get("mainVerdict")
    if isinstance(_mv, dict) and not _mv.get("ok"):
        result["mainThread"] = {"ours": _mv.get("ours"),
                                 "theirs": _mv.get("theirs")}
        result["state"] = "partial"
        result["message"] = (
            "Mostly synced — the main thread disagrees (theirs "
            + str(_mv.get("theirs")) + " messages, ours "
            + str(_mv.get("ours")) + "). The rest of the set "
            "converged; the main thread did not, and this round "
            "will not call it converged.")
    # v0.4.10e (#254): the round's receipt, in the operator's
    # terms — what the sync bar hangs off the bar on landing
    # and what the #242 announcement is composed from. A round
    # is MATERIAL when the sync family actually moved the
    # room's shape: ghost threads folded (#251), a case/chat
    # pairing repaired or a gap folded away (#252), or another
    # seat's tombstone honored here (#253). Ordinary arrivals
    # and departures are traffic, not material.
    receipt = {
        "mergedMessages": summary.get("chatsMainMergedMessages", 0),
        "foldedGhosts": summary.get("chatsMainFolded", 0),
        "foldedMessages": summary.get("chatsMainFoldedMessages", 0),
        "pairsWhole": summary.get("casePairsWhole", 0),
        "pairsRepaired": summary.get("casePairsRepaired", 0),
        "gapTitles": list(summary.get("caseChatGapTitles") or []),
        "tombstones": summary.get("removedChats", 0),
        "removedCases": summary.get("removedCases", 0),
        "removedNotes": summary.get("removedNotes", 0),
        "chatsAdded": summary.get("chatsAdded", 0),
        "chatsReplaced": summary.get("chatsReplaced", 0),
        "chatsCleared": summary.get("chatsCleared", 0),
        "foreignRefused": len(summary.get("foreignRefusals") or []),
        "changed": summary.get("changed", 0),
    }
    receipt["incomplete"] = list(result["incomplete"])
    receipt["material"] = bool(receipt["foldedGhosts"] or receipt["gapTitles"]
                               or receipt["pairsRepaired"] or receipt["tombstones"]
                               or receipt["incomplete"] or receipt["foreignRefused"])
    result["receipt"] = receipt
    return result


# -- Quick Sync's Mesh transport, borrower side (Build 6, #176) ------
# A round tries the Mesh first: for each paired peer this machine
# borrows from, in card order, a probe asks whether the road is
# lit; the first answering peer gets the exchange — one whole
# signed request carrying this machine's set out and the peer's
# set back, converged on arrival. Any failure at any step falls
# through to the backup-repo round, unchanged. The set is capped:
# past the cap the repo (built for bulk) carries the round.
_SYNC_MESH_MAX_BYTES = 96 * 1024 * 1024


def _sync_mesh_peers():
    ms = mesh_settings(load_config())
    if not ms["enabled"]:
        return []
    return [p for p in ms["borrow"]["peers"] if p["canBorrow"]]


# -- The account gate, initiator side (v0.6.4e, #323) -------------
# A set is offered to a peer only after the handshake proves
# the peer is a SEAT OF THIS ACCOUNT: the peer states its
# GitHub login at /mesh/sync/hello, and the logins must be
# present and equal. Pairing proves the road, never the
# account — peers are other operators by design; seats are
# this operator's own machines. A refusal is remembered for
# the round's receipt (the fall-through to the repo road is
# correct behavior for the operator's own seats, but it is
# never silent about why the Mesh road was not used).
_SYNC_MESH_REFUSAL = {"text": ""}


def _sync_mesh_refusal_note(text):
    if text and not _SYNC_MESH_REFUSAL["text"]:
        _SYNC_MESH_REFUSAL["text"] = text


def _sync_mesh_refusal_take():
    text = _SYNC_MESH_REFUSAL["text"]
    _SYNC_MESH_REFUSAL["text"] = ""
    return text


def _sync_mesh_hello(peer):
    # The peer's stated account, or None when the handshake
    # itself did not answer (a dark road, or a build too old
    # to state one — either way, nothing it says can prove it
    # a seat, and no set is offered to it).
    payload = _sync_mesh_ask(peer, "/mesh/sync/hello", {})
    if payload is None:
        return None
    return str(payload.get("account") or "")


def _sync_mesh_peer_gate(peer):
    # "" when the peer is proven a seat of this account; else
    # the refusal sentence the receipt carries. Called only
    # for peers whose road probed lit.
    mine = str((github_auth() or {}).get("login") or "")
    if not mine:
        return ("Mesh road refused: this seat's own account is "
                "unknown — sign in so Sync can prove which "
                "machines are its seats.")
    theirs = _sync_mesh_hello(peer)
    if theirs is None or not theirs:
        return ("Mesh road refused: " + str(peer.get("name") or "the peer")
                + " would not state an account — Sync cannot "
                "prove it is a seat of this account.")
    if theirs.lower() != mine.lower():
        return ("Mesh road refused: " + str(peer.get("name") or "the peer")
                + " is not a seat of this account.")
    return ""


def _sync_mesh_ask(peer, path, body):
    # One signed sync request; the peer's parsed payload, or None
    # for every failure shape (unlit, refused, misshapen) — the
    # caller treats them all the same: try the next road.
    body = dict(body or {})
    body["requestId"] = uuid.uuid4().hex
    auth = github_auth()
    body["operatorLogin"] = auth["login"] if auth else ""
    # The Mesh wire signs and sends exact bytes (the borrow path
    # passes bytes); the payload is serialized ONCE, here, so the
    # signed bytes are the sent bytes.
    wire = json.dumps(body).encode()
    try:
        status, raw = _mesh_request(peer, "POST", path, wire,
                                     body["requestId"], 120)
    except Exception:
        return None
    if status != 200:
        return None
    try:
        payload = json.loads(raw.decode("utf-8", "replace"))
    except Exception:
        return None
    if not isinstance(payload, dict) or not payload.get("ok"):
        return None
    return payload


# -- The foreign-data purge (v0.6.4e, #323) -----------------------
# The gate stops new crossings; this cleans up what crossed
# before it existed. Attribution is the evidence: sync_apply
# records, per converged item, the account the arriving set
# named as its own ("" when it named none). On the first gated
# run the standing corpus gets a ledger too — a seat signed in
# adopts its corpus to its own account (the normal upgrade:
# one operator, their machines, their data); a seat NOT signed
# in ledgers "" (unattributed), except day book entries born
# on this very machine, which ledger "local".
#
# Judgment runs only when the seat HAS an account to judge
# against — an unsigned seat purges nothing, ever. An item is
# purgeable when its ledger entry names a DIFFERENT account,
# or names none AND the item carries no local proof. Local
# proof for an unattributed item: a day book entry whose
# origin names this host, or a file whose mtime predates this
# seat's first recorded Mesh sync arrival — material older
# than the first crossing cannot have come through it. With
# NO recorded arrival, unattributed items are NOT purgeable:
# the fail-safe leans toward keeping data, always. Items with
# no ledger entry at all are never touched — they were
# created on this seat after the ledger began.

def _sync_first_mesh_arrival():
    ts = []
    for r in mesh_ledger_read():
        if r.get("direction") == "sync" and r.get("outcome") in ("exchange", "pull"):
            t = r.get("ts")
            if isinstance(t, (int, float)) and not isinstance(t, bool):
                ts.append(t)
    return min(ts) if ts else None


def _purge_predates(path, first_arrival):
    if first_arrival is None:
        return False
    try:
        return os.path.getmtime(path) < first_arrival
    except Exception:
        return False


def sync_account_gate_sweep():
    # The purge judgment. Returns its receipt dict when a
    # judgment ran, else None. Idempotent; safe at bridge
    # start and on sign-in — the two moments the answer can
    # change. Never raises.
    try:
        state = _sync_state_load()
        mine = str((github_auth() or {}).get("login") or "")
        attr = state.get("attribution")
        if not isinstance(attr, dict):
            attr = {"chats": {}, "cases": {}, "docs": {}, "daybook": {}, "seat": {}, "pulse": {}}
            host = socket.gethostname()[:80]
            for c in chats_all():
                attr["chats"][str(c["id"])] = mine
            croot = os.path.join(VAULT_DIR, "cases")
            if os.path.isdir(croot):
                for slug in sorted(os.listdir(croot)):
                    if os.path.isdir(os.path.join(croot, slug)):
                        attr["cases"][str(slug)] = mine
            for name, _label in _SYNC_DOCS:
                if os.path.isfile(_sync_doc_path(name)):
                    attr["docs"][name] = mine
            try:
                for e in _daybook_load().get("entries") or []:
                    oseat = str((e.get("origin") or {}).get("seat") or "")
                    if mine:
                        attr["daybook"][str(e["id"])] = mine
                    else:
                        attr["daybook"][str(e["id"])] = "local" if oseat == host else ""
            except Exception:
                pass
            state["attribution"] = attr
            state["gateLedgerAt"] = int(time.time())
            _sync_state_save(state)
        # v0.6.30e (#377): the seat and the pulse join the
        # ledger. A family this build meets for the first
        # time is built UNVERIFIED (""): seat entries carry
        # no birth-seat proof (their origins are preserved
        # on the road by design), so nothing already sitting
        # in the store can be claimed as this account's on
        # sight — it is judged by the arming rule below.
        _seat_fam_new = not isinstance(attr.get("seat"), dict)
        _pulse_fam_new = not isinstance(attr.get("pulse"), dict)
        for fam in ("chats", "cases", "docs", "daybook", "seat", "pulse"):
            if not isinstance(attr.get(fam), dict):
                attr[fam] = {}
        if _seat_fam_new:
            try:
                for e in (_seat_state_load().get("entries") or []):
                    attr["seat"][_seat_fact_id(e["t"])] = ""
                attr["seat"]["@identity"] = ""
            except Exception:
                pass
        if _pulse_fam_new:
            try:
                for w in (_pulse_load().get("watches") or []):
                    if isinstance(w, dict) and w.get("id"):
                        attr["pulse"][str(w["id"])] = ""
            except Exception:
                pass
        if not mine:
            return None
        foreign_named = any(
            isinstance(v, str) and v and v != "local" and v.lower() != mine.lower()
            for fam in attr.values() if isinstance(fam, dict)
            for v in fam.values())
        # v0.6.30e (#377): the standing early return gains a
        # second look — when a gated round has armed the
        # proof and account-level material still stands
        # unattributed, the judgment runs again: the arming
        # is exactly the event that can change its verdict.
        _gate_proof0 = state.get("gateProof") if isinstance(state.get("gateProof"), dict) else {}
        _armed0 = bool(_gate_proof0.get("account")
                       and str(_gate_proof0.get("account")).lower() == mine.lower())
        _unattributed_account = False
        if _armed0:
            try:
                for _e in (_seat_state_load().get("entries") or []):
                    _v = attr.get("seat", {}).get(_seat_fact_id(_e["t"]))
                    if _v is None or _v == "":
                        _unattributed_account = True
                        break
            except Exception:
                pass
            if not _unattributed_account:
                try:
                    for _w in (_pulse_load().get("watches") or []):
                        _v = attr.get("pulse", {}).get(str(_w.get("id") or ""))
                        if _v is None or _v == "":
                            _unattributed_account = True
                            break
                except Exception:
                    pass
        if state.get("purgeJudgedFor") == mine and not foreign_named \
                and not _unattributed_account:
            return None
        first_arrival = _sync_first_mesh_arrival()
        host = socket.gethostname()[:80]

        def verdict(fam, key):
            # "purge" / "keep" / None (unattributed — the
            # caller decides on local proof).
            if key not in attr.get(fam, {}):
                return "keep"
            v = attr[fam][key]
            if v == "local":
                return "keep"
            if v:
                return "keep" if str(v).lower() == mine.lower() else "purge"
            return None

        purged = {"chats": [], "cases": [], "docs": [], "daybook": [], "seat": [], "pulse": []}
        main_reset = False
        main_held = False
        main_rec = None
        for c in chats_all():
            if str(c["id"]) == "1":
                main_rec = c
        for c in chats_all():
            cid = str(c["id"])
            j = verdict("chats", cid)
            if j is None:
                j = "keep" if _purge_predates(_chat_path(cid), first_arrival) else "purge"
            if j != "purge":
                continue
            if cid == "1":
                # The main thread is never deleted. A main
                # wholly adopted from a foreign set is reset
                # under a fresh clear epoch; a locally-born
                # main with foreign lines merged in cannot be
                # unmerged honestly, so it is HELD and named.
                if _purge_predates(_chat_path("1"), first_arrival):
                    main_held = True
                else:
                    # v0.6.19e (#365): the reset's stamps are
                    # MILLISECONDS — the basis every chat stamp
                    # (the page's Date.now(), the bridge's own)
                    # already keeps. This block stood in seconds
                    # through .18e: an epoch that retired nothing.
                    now = int(time.time() * 1000)
                    chat_write({"id": "1",
                                "title": (main_rec or {}).get("title") or "Main session",
                                "messages": [],
                                "createdAt": (main_rec or {}).get("createdAt") or now,
                                "updatedAt": now,
                                "clearedAt": now,
                                "clearedBy": _chat_seat_name()})
                    main_reset = True
                continue
            if chat_delete(cid):
                purged["chats"].append(cid)
        croot = os.path.join(VAULT_DIR, "cases")
        if os.path.isdir(croot):
            for slug in sorted(os.listdir(croot)):
                d = os.path.join(croot, slug)
                if not os.path.isdir(d):
                    continue
                j = verdict("cases", slug)
                if j is None:
                    j = "keep" if _purge_predates(d, first_arrival) else "purge"
                if j != "purge":
                    continue
                case_delete(slug)
                if not os.path.isdir(d):
                    purged["cases"].append(slug)
                    legacy = os.path.join(croot, slug + ".md")
                    try:
                        if os.path.isfile(legacy):
                            os.remove(legacy)
                    except Exception:
                        pass
        for name, _label in _SYNC_DOCS:
            j = verdict("docs", name)
            if j is None:
                j = "keep" if _purge_predates(_sync_doc_path(name), first_arrival) else "purge"
            if j != "purge":
                continue
            try:
                if os.path.isfile(_sync_doc_path(name)):
                    os.remove(_sync_doc_path(name))
                    purged["docs"].append(name)
            except Exception:
                pass
        try:
            for e in list(_daybook_load().get("entries") or []):
                eid = str(e["id"])
                j = verdict("daybook", eid)
                if j is None:
                    oseat = str((e.get("origin") or {}).get("seat") or "")
                    j = "keep" if oseat == host else "purge"
                if j != "purge":
                    continue
                gone, _err = daybook_delete_entry(eid)
                if gone is not None:
                    purged["daybook"].append(eid)
        except Exception:
            pass
        # v0.6.30e (#377): the seat and the pulse are judged.
        # Attributed to another account: purge, exactly like
        # the families above — seat facts are tombstoned as
        # they go, so the merge refuses their return.
        # Unattributed: kept while this seat's account is
        # unproven on a live round; once a gated round has
        # spoken for this account (gateProof — its own set
        # applied, or a foreign payload refused by name), an
        # unattributed seat fact is material this account's
        # roster never named, and it is purged the same way.
        # (This account's own facts re-converge attributed
        # on its next round; locally authored facts are
        # attributed at the page door when they are written.)
        _gate_proof = state.get("gateProof") if isinstance(state.get("gateProof"), dict) else {}
        _armed = bool(_gate_proof.get("account")
                      and str(_gate_proof.get("account")).lower() == mine.lower())
        seat_identity_purged = False
        try:
            _sb = _seat_state_load()
            _kept = []
            _gone = []
            for _e in (_sb.get("entries") or []):
                _fid = _seat_fact_id(_e["t"])
                # Judged here, not by verdict(): a seat fact
                # with NO ledger key at all is as unattributed
                # as one stamped "" — verdict()'s absent-key
                # "keep" serves the older families, whose
                # bootstrap claims their material; the seat
                # family claims nothing (see the backfill).
                _v = attr.get("seat", {}).get(_fid)
                if _v is None or _v == "":
                    _j = "purge" if _armed else "keep"
                elif _v == "local" or str(_v).lower() == mine.lower():
                    _j = "keep"
                else:
                    _j = "purge"
                if _j == "purge":
                    _gone.append(_fid)
                else:
                    _kept.append(_e)
            _vid = attr.get("seat", {}).get("@identity")
            if _vid is None or _vid == "":
                _jid = "purge" if (_gone or (_armed and not any(
                    isinstance(v, str) and v and v.lower() == mine.lower()
                    for v in attr.get("seat", {}).values()))) else "keep"
            elif _vid == "local" or str(_vid).lower() == mine.lower():
                _jid = "keep"
            else:
                _jid = "purge"
            _old_name = str(_sb.get("operatorName") or "")
            if _jid == "purge" and (_old_name
                                    or _sb.get("operatorPicture")
                                    or _sb.get("operatorBadge")):
                _sb["operatorName"] = ""
                _sb["operatorPicture"] = ""
                _sb["operatorBadge"] = ""
                seat_identity_purged = True
            if _gone:
                _sb["entries"] = _kept
                purged["seat"] = _gone
            if _gone or seat_identity_purged:
                _seat_state_save(_sb)
            if seat_identity_purged and _old_name:
                try:
                    _cfg2 = load_config()
                    if str(_cfg2.get("operator_name") or "") == _old_name:
                        _cfg2["operator_name"] = ""
                        save_config(_cfg2)
                except Exception:
                    pass
            if _gone:
                try:
                    for _fid in _gone:
                        sync_record_tombstone("entries", _fid)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            _pb = _pulse_load()
            _keptw = []
            _gonew = []
            for _w in (_pb.get("watches") or []):
                _wid = str((_w or {}).get("id") or "")
                _v = attr.get("pulse", {}).get(_wid) if _wid else "local"
                if _v is None or _v == "":
                    _j = "purge" if _armed else "keep"
                elif _v == "local" or str(_v).lower() == mine.lower():
                    _j = "keep"
                else:
                    _j = "purge"
                if _j == "purge":
                    _gonew.append(_wid)
                else:
                    _keptw.append(_w)
            if _gonew:
                _pb["watches"] = _keptw
                _pulse_save(_pb)
                purged["pulse"] = _gonew
        except Exception:
            pass
        for fam, keys in purged.items():
            for k in keys:
                attr.get(fam, {}).pop(k, None)
        if seat_identity_purged:
            attr.get("seat", {}).pop("@identity", None)
        if main_reset:
            attr.get("chats", {}).pop("1", None)
        parts = []
        if purged["chats"]:
            parts.append(str(len(purged["chats"])) + " chat" + ("s" if len(purged["chats"]) != 1 else ""))
        if purged["cases"]:
            parts.append(str(len(purged["cases"])) + " case file" + ("s" if len(purged["cases"]) != 1 else ""))
        if purged["docs"]:
            parts.append(str(len(purged["docs"])) + " synced note" + ("s" if len(purged["docs"]) != 1 else ""))
        if purged["daybook"]:
            parts.append(str(len(purged["daybook"])) + " day book entr" + ("ies" if len(purged["daybook"]) != 1 else "y"))
        if purged["seat"]:
            parts.append(str(len(purged["seat"])) + " memor" + ("ies" if len(purged["seat"]) != 1 else "y") + " about you")
        if seat_identity_purged:
            parts.append("the operator name, picture and badge that rode with them")
        if purged["pulse"]:
            parts.append(str(len(purged["pulse"])) + " pulse watch" + ("es" if len(purged["pulse"]) != 1 else ""))
        if main_reset:
            parts.append("the main thread, which had been adopted whole from the foreign set")
        receipt = {"at": int(time.time()), "account": mine,
                   "chats": len(purged["chats"]), "cases": len(purged["cases"]),
                   "docs": len(purged["docs"]), "daybook": len(purged["daybook"]),
                   "seat": len(purged["seat"]), "seatIdentity": seat_identity_purged,
                   "pulse": len(purged["pulse"]),
                   "mainReset": main_reset, "mainHeld": main_held,
                   "fact": ("Sync's account gate removed material that could not be "
                            "attributed to your account: " + ", ".join(parts) + ".")
                   if parts else ""}
        state = _sync_state_load()
        state["attribution"] = attr
        state["purgeJudgedFor"] = mine
        if parts or main_held:
            state["lastPurge"] = receipt
        _sync_state_save(state)
        return receipt
    except Exception:
        return None


def _sync_mesh_round(cfg, open_chat_id):
    # A finished round result (route named for the peer) when a
    # Mesh exchange completes, else None. Runs under sync_round's
    # lock; the lender serializes its own side the same way.
    peers = _sync_mesh_peers()
    if not peers:
        return None
    collected, manifest, _index = sync_collect()
    if sum(len(b) for b in collected.values()) > _SYNC_MESH_MAX_BYTES:
        return None
    files = {}
    for path, blob in collected.items():
        files[path] = base64.b64encode(blob).decode("ascii")
    local_ids = set(str(c["id"]) for c in chats_payload()["chats"])
    for peer in peers:
        if mesh_probe_peer(peer) is None:
            continue
        refusal = _sync_mesh_peer_gate(peer)
        if refusal:
            _sync_mesh_refusal_note(refusal)
            continue
        payload = _sync_mesh_ask(peer, "/mesh/sync/exchange",
                                 {"files": files, "manifest": manifest})
        if payload is None:
            continue
        theirs = _mesh_sync_decode(payload)
        if theirs is None:
            continue
        if _mesh_sync_foreign_account(payload):
            # v0.6.19e (#365): the skip is named in the sync
            # record, as the serving door already names its
            # refusals — a foreign set turned away is a fact
            # of the road, not a silent nothing.
            _fman = payload.get("manifest") if isinstance(payload.get("manifest"), dict) else {}
            _sync_foreign_refusal_note("chats", str(_fman.get("account") or ""), peer["name"])
            continue
        _sync_preempt_checkpoint("merge")
        _sync_progress_set("merge")
        summary = sync_apply(cfg, {
            "files": theirs,
            "manifest": payload.get("manifest") if isinstance(payload.get("manifest"), dict) else {},
        }, account=_account_clean((payload.get("manifest") or {}).get("accountSeat") or "operator"))
        # The exchange's first leg parked its own divergences on
        # the LENDER — same operator, same eyes: the borrower's
        # card names them too, or the lender's parked copies
        # would wait for a round that machine never runs.
        applied = payload.get("applied")
        if isinstance(applied, dict):
            for e in (applied.get("eyes") or []):
                if e not in summary["eyes"]:
                    summary["eyes"].append(e)
            for s in (applied.get("caseEyes") or []):
                if s not in summary["caseEyes"]:
                    summary["caseEyes"].append(s)
            summary["changed"] = (summary.get("changed") or 0) + (applied.get("changed") or 0)
        result = _sync_finish_summary(summary, len(files),
                                      open_chat_id, local_ids)
        result["route"] = "Mesh — " + peer["name"]
        result["pushedChats"] = 0
        return result
    return None


def _mesh_sync_foreign_account(payload, account="operator"):
    # The account anchor on the Mesh road (v0.3.0e Build 1,
    # #200; inverted v0.6.4e, #323): a set is applied only when
    # it is ATTRIBUTABLE to this machine's own account — its
    # manifest names an account, this machine knows its own,
    # and the two are equal. Anything else is foreign for this
    # door's purpose: a different account, or a set (or a seat)
    # that cannot be named at all. The handshake is the road's
    # gate; this is the same law read off the set itself, kept
    # as defense in depth against a peer that states one
    # account at the hello and ships another's set.
    manifest = payload.get("manifest") if isinstance(payload, dict) else None
    if not isinstance(manifest, dict):
        return True
    acct = str(manifest.get("account") or "")
    mine = str((github_auth() or {}).get("login") or "")
    if not acct or not mine:
        return True
    if acct.lower() != mine.lower():
        return True
    # v0.7.9e (#426): the seat stamp, judged the same way —
    # present and not the syncing account's seat = foreign.
    _seat_stamp = str(manifest.get("accountSeat") or "")
    if _seat_stamp and _account_clean(_seat_stamp) != _account_clean(account):
        return True
    return False


def _sync_mesh_pull(cfg):
    # A trigger pull over the Mesh: (route, summary) or None —
    # apply a peer's set, push nothing, mirroring the repo pull.
    for peer in _sync_mesh_peers():
        if mesh_probe_peer(peer) is None:
            continue
        refusal = _sync_mesh_peer_gate(peer)
        if refusal:
            _sync_mesh_refusal_note(refusal)
            continue
        payload = _sync_mesh_ask(peer, "/mesh/sync/pull", {})
        if payload is None:
            continue
        theirs = _mesh_sync_decode(payload)
        if theirs is None:
            continue
        if _mesh_sync_foreign_account(payload):
            # v0.6.19e (#365): named, not silent — see the
            # exchange leg above.
            _fman = payload.get("manifest") if isinstance(payload.get("manifest"), dict) else {}
            _sync_foreign_refusal_note("chats", str(_fman.get("account") or ""), peer["name"])
            continue
        _sync_preempt_checkpoint("merge")
        _sync_progress_set("merge")
        summary = sync_apply(cfg, {
            "files": theirs,
            "manifest": payload.get("manifest") if isinstance(payload.get("manifest"), dict) else {},
        }, account=_account_clean((payload.get("manifest") or {}).get("accountSeat") or "operator"))
        return ("Mesh — " + peer["name"]), summary
    return None


def _sync_progress_set(phase, trigger="", round_id="", counts=None):
    # v0.4.10e (#254): the round's live phase, recorded in the
    # sync state as it happens — fetch, merge, write, done —
    # so the status rail's sync bar can show the phase the
    # bridge is actually in, never a guessed percentage. The
    # write phase carries file counts because the push loop
    # knows them; the fetch leg carries none, because a network
    # wait has no honest fraction. Best-effort by design: a
    # progress write must never fail a round.
    try:
        state = _sync_state_load()
        prog = state.get("syncProgress") if isinstance(state.get("syncProgress"), dict) else {}
        if round_id and prog.get("roundId") != round_id:
            prog = {"roundId": round_id, "startedAt": time.time()}
        prog["active"] = phase != "done"
        prog["phase"] = phase
        prog["phaseAt"] = time.time()
        if trigger:
            prog["trigger"] = trigger
        if counts is not None:
            prog["counts"] = counts
        state["syncProgress"] = prog
        _sync_state_save(state)
    except Exception:
        pass


def _sync_fail_record(trigger, out):
    # v0.4.10e (#254): a failed round lands as a receipt too —
    # the bar names the failure from the record rather than
    # going dark. Mirrors _sync_record_result's save shape.
    try:
        state = _sync_state_load()
        _sync_record_result(state, trigger, out)
        _sync_state_save(state)
    except Exception:
        pass


# -- Push-on-write (v0.5.1e, #257) --------------------------------
# Occasions (the button, app start, a DHD session, Mesh
# contact) cannot meet a ten-second standard by construction:
# a change waits for the other seat's next occasion. So a
# WRITE on this seat asks for a round of its own: the note
# coalesces a burst of writes into one round; the round rides
# the Mesh when a peer's road is lit and the repo otherwise;
# its landing is receipted like any other round's, with the
# road and the measured duration on the bar. No new daemon:
# the note rides the bridge's own life, in a timer thread off
# the write's path. A seat with no road (Mesh dark, signed
# out) notes nothing and names nothing — the occasions carry
# its writes, as they always have. A push that cannot land
# names its stall through the same fail record a failed round
# uses, rather than silently aging.
#
# v0.6.19e (#365): the note fires for BOTH authors (operator
# ruling, 2026-11-21). The funnel is the store door itself —
# chat_write — and her writes land through it exactly as his
# do: her bridge-side appends call it directly, and a borrowed
# reply lands through the writing window's write-through like
# any of her lines. A device switch mid-chat is usually
# waiting on HER half of the conversation; a push that fired
# only on the operator's writes would leave the thread
# half-stale. The fire's discipline also changes: a failed
# push re-arms on a bounded backoff (_SYNC_PUSH_BACKOFF)
# instead of dropping its note after one retry.
_SYNC_ROUND = {"depth": 0, "thread": None}
_SYNC_PUSH = {"lock": threading.Lock(), "timer": None,
              "attempts": 0, "kinds": set()}
_SYNC_PUSH_COALESCE = 1.25
_SYNC_PUSH_RETRY = 3.0
# v0.6.19e (#365): the push fire's re-arm ladder — a failed
# push retries behind the round it collided with, across the
# span a slow road needs, before it names its stall.
_SYNC_PUSH_BACKOFF = (3.0, 15.0, 45.0, 90.0)


# -- Sync preemption (v0.6.3e, #317) ------------------------------
# The override's missing half, named in the field: the operator
# chose Send and the card answered "Held — the running round's
# verdict is the one that counts." An operator's word does not
# queue behind machinery. When a direction is chosen while a
# round is in flight, the choice is NOTED here; the running
# round reads the note at its next phase boundary (the phases
# are already the round's own — fetch, merge, write) and stops
# there, cleanly: rounds converge idempotently, so its partial
# work stands, and its record names the supersession. The
# chosen direction then runs at once. Machine triggers (push-
# on-write, occasions) never note a preemption — the hold stays
# theirs. A newer choice replaces an older one wholesale: the
# newest direction is the one that runs, and a direction
# superseded before it could run says so on its own receipt.


class _SyncSuperseded(Exception):
    # Raised inside a round at a phase boundary when a newer
    # operator direction outranks it. Carries the phase it
    # stopped at and the direction that replaced it.
    def __init__(self, phase, direction):
        super().__init__(phase)
        self.phase = phase
        self.direction = direction


_SYNC_PREEMPT = {"lock": threading.Lock(), "seq": 0, "current": None,
                 "doneSeq": 0, "doneDir": ""}


def _sync_preempt_note(direction, trigger):
    # The operator's choice, recorded. Returns its sequence —
    # the round that runs it holds the sequence so only a NEWER
    # choice can stop it in turn.
    with _SYNC_PREEMPT["lock"]:
        _SYNC_PREEMPT["seq"] += 1
        seq = _SYNC_PREEMPT["seq"]
        _SYNC_PREEMPT["current"] = {"seq": seq, "direction": direction,
                                    "trigger": trigger}
        return seq


def _sync_preempt_checkpoint(phase, own_seq=0):
    # A round's phase boundary: stop here when a newer operator
    # direction stands noted. Legacy and machine rounds hold no
    # sequence (0), so any noted choice stops them; a directional
    # round is stopped only by a newer choice than its own.
    cur = _SYNC_PREEMPT["current"]
    if cur and cur["seq"] > (own_seq or 0):
        raise _SyncSuperseded(phase, cur["direction"])


def _sync_preempt_clear(seq):
    with _SYNC_PREEMPT["lock"]:
        cur = _SYNC_PREEMPT["current"]
        if cur and cur["seq"] == seq:
            _SYNC_PREEMPT["current"] = None


def _sync_superseded_result(direction, phase, own_direction=""):
    # The stopped round's verdict — on its return, its durable
    # record, and the card that reads them back. It names who
    # outranked it and where it stopped; the work it landed
    # before the boundary stands, and says so.
    named = {"send": "Send", "receive": "Receive"}.get(direction, "")
    if own_direction and own_direction != direction:
        message = ("Overridden — a newer choice ("
                   + (named or "a directional round")
                   + ") replaced this "
                   + {"send": "Send", "receive": "Receive"}.get(
                       own_direction, "round")
                   + " at the " + phase + " boundary before it "
                     "finished. Work it had already landed stands.")
    else:
        message = ("Overridden — this round stopped at the "
                   + phase + " boundary: the operator's "
                   + (named or "directional round")
                   + " runs instead. Work it had already landed "
                     "stands; nothing was raced.")
    return {"ok": False, "state": "superseded", "preempted": True,
            "phase": phase, "route": "Backup repo",
            "message": message}


def _sync_preempt_acquire(direction, trigger):
    # A directional round's door (v0.6.3e, #317): note the
    # choice FIRST (the note is the signal the running round
    # reads at its next boundary), then take the round lock —
    # at once when it stands free, or as soon as the stopped
    # (or finished) round releases it. Returns (seq, None) with
    # the lock held, or (seq, result) when a NEWER choice
    # superseded this one while it waited: the newest direction
    # is the one that runs, and this one names its replacement.
    seq = _sync_preempt_note(direction, trigger)
    if _SYNC_LOCK.acquire(False):
        with _SYNC_PREEMPT["lock"]:
            if seq > _SYNC_PREEMPT["doneSeq"]:
                _SYNC_PREEMPT["doneSeq"] = seq
                _SYNC_PREEMPT["doneDir"] = direction
        return seq, None
    _SYNC_LOCK.acquire()
    with _SYNC_PREEMPT["lock"]:
        cur = _SYNC_PREEMPT["current"]
        newer = cur["direction"] if cur and cur["seq"] > seq else None
        dead = newer is not None or seq < _SYNC_PREEMPT["doneSeq"]
        if not dead:
            _SYNC_PREEMPT["doneSeq"] = seq
            _SYNC_PREEMPT["doneDir"] = direction
    if dead:
        _SYNC_LOCK.release()
        out = _sync_superseded_result(
            newer or _SYNC_PREEMPT["doneDir"] or direction,
            "the queue", direction)
        out["direction"] = direction
        return seq, out
    return seq, None


def sync_note_write(kind=""):
    _bump_state_rev()
    # The write funnels' one call (chat_write, the seat merge,
    # the case mutators, the tombstone record). Best-effort by
    # design: noting a write must never fail the write itself.
    # Writes that happen INSIDE a round, on the round's own
    # thread (convergence landing the other seat's set), note
    # nothing — that round already is the propagation. A write
    # landing on another thread while a round runs is an
    # independent act: it notes, and its push fires behind the
    # round (or retries past it).
    try:
        if _SYNC_ROUND["depth"] > 0 and _SYNC_ROUND.get("thread") == threading.get_ident():
            return
        with _SYNC_PUSH["lock"]:
            _SYNC_PUSH["kinds"].add(str(kind or "write"))
            if _SYNC_PUSH["timer"] is not None:
                return
            t = threading.Timer(_SYNC_PUSH_COALESCE, _sync_push_fire)
            t.daemon = True
            _SYNC_PUSH["timer"] = t
            t.start()
    except Exception:
        pass


def _sync_push_fire():
    with _SYNC_PUSH["lock"]:
        _SYNC_PUSH["timer"] = None
        kinds = set(_SYNC_PUSH["kinds"])
        _SYNC_PUSH["kinds"] = set()
    if not kinds:
        return
    if not _sync_mesh_peers() and not github_auth():
        with _SYNC_PUSH["lock"]:
            _SYNC_PUSH["attempts"] = 0
        return
    result = None
    try:
        result = sync_round(load_config(), "push")
    except Exception:
        result = None
    if isinstance(result, dict) and result.get("ok"):
        with _SYNC_PUSH["lock"]:
            _SYNC_PUSH["attempts"] = 0
        return
    # A failure re-arms on a bounded backoff (v0.6.19e, #365;
    # through .18e a first failure earned exactly one retry and
    # a second dropped the note whole). The commonest causes —
    # a collision with a round already in flight on one seat or
    # the other (the lender answers "busy" rather than waiting),
    # a slow road — both pass with time, and a write whose push
    # evaporated otherwise waits for an occasion that may be
    # hours away: that is how a cleared thread outlived fifteen
    # clears. The kinds stay noted across the retries; only the
    # last failure lets go, and names its stall below (the held
    # shape, which no round records — a busy round returns
    # before recording).
    with _SYNC_PUSH["lock"]:
        _SYNC_PUSH["attempts"] += 1
        attempts = _SYNC_PUSH["attempts"]
        if attempts <= len(_SYNC_PUSH_BACKOFF):
            _SYNC_PUSH["kinds"] |= kinds
    if attempts <= len(_SYNC_PUSH_BACKOFF):
        with _SYNC_PUSH["lock"]:
            if _SYNC_PUSH["timer"] is None:
                t = threading.Timer(_SYNC_PUSH_BACKOFF[attempts - 1],
                                    _sync_push_fire)
                t.daemon = True
                _SYNC_PUSH["timer"] = t
                t.start()
        return
    with _SYNC_PUSH["lock"]:
        _SYNC_PUSH["attempts"] = 0
        _SYNC_PUSH["kinds"] = set()
    held = result is None or (isinstance(result, dict)
                              and (result.get("state") == "held"
                                   or result.get("kind") == "busy"))
    if held:
        _sync_fail_record("push", {
            "ok": False, "state": "held",
            "route": (result or {}).get("route") or "",
            "error": "Push stalled — the retries could not land a round either. The write is safe on this seat; the next occasion carries it."})


def sync_round(cfg, trigger="button", open_chat_id="", account="operator"):
    # The full round behind the Sync control: pull, converge,
    # push. One round at a time, across every trigger — a second
    # caller is held, never raced.
    if not _SYNC_LOCK.acquire(False):
        return {"ok": False, "state": "held", "kind": "busy", "route": "Backup repo",
                "error": "A sync round is already running — this one is held, and the running round's verdict is the one that counts."}
    round_id = uuid.uuid4().hex[:12]
    if _SYNC_ROUND["depth"] == 0:
        _SYNC_ROUND["thread"] = threading.get_ident()
    _SYNC_ROUND["depth"] += 1
    _round_t0 = time.time()
    _sync_progress_set("fetch", trigger, round_id)
    try:
        # Build 6 (#176 phase 2): a lit Mesh road carries the
        # round before the repo is asked. v0.6.4e (#323): the
        # Mesh road is account-gated — the exchange runs only
        # with a peer the handshake proved a seat of this
        # account, which needs the sign-in the old comment here
        # said it did not. Anything less than a completed
        # exchange falls through to the repo round below, which
        # keeps its own sign-in gate and wording.
        mesh_result = None
        try:
            mesh_result = _sync_mesh_round(cfg, open_chat_id)
        except Exception:
            mesh_result = None
        if mesh_result is not None:
            mesh_result["roundId"] = round_id
            mesh_result["durationMs"] = int((time.time() - _round_t0) * 1000)
            state = _sync_state_load()
            _sync_record_result(state, trigger, mesh_result)
            state["lastRoute"] = mesh_result["route"]
            _sync_state_save(state)
            return mesh_result
        if not github_auth():
            out = _sync_auth_error()
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _round_t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        fetched, fail = sync_fetch(cfg, account)
        if fail:
            out = {"ok": False, "route": "Backup repo"}
            out.update(fail)
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _round_t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        _sync_preempt_checkpoint("merge")
        _sync_progress_set("merge")
        summary = sync_apply(cfg, fetched, account=account)
        _sync_preempt_checkpoint("write")
        got = _sync_repo(cfg)
        if got[0] is None:
            out = {"ok": False, "route": "Backup repo"}
            out.update(got[1] or _sync_auth_error())
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _round_t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        auth, base = got[0]
        local_files, _manifest, _index = sync_collect(cfg, account)
        # What the push changes for the other side, counted in
        # chats: local threads the remote does not hold, or holds
        # older.
        remote_chats = {}
        if SYNC_PREFIX + "chats.json" in fetched["files"]:
            try:
                parsed = json.loads(fetched["files"][SYNC_PREFIX + "chats.json"].decode("utf-8", "replace"))
                if isinstance(parsed, dict):
                    for c in parsed.get("chats") or []:
                        rec = _chat_normalize(c)
                        if rec:
                            remote_chats[str(rec["id"])] = rec
            except Exception:
                remote_chats = {}
        pushed_chats = 0
        local_ids = set()
        for c in chats_payload()["chats"]:
            cid = str(c["id"])
            local_ids.add(cid)
            rc = remote_chats.get(cid)
            if rc is None or (c.get("updatedAt") or 0) > (rc.get("updatedAt") or 0) or _chat_msgs_key(c) != _chat_msgs_key(rc):
                pushed_chats += 1
        written, fail = _sync_push(cfg, base, auth["token"], local_files, fetched["files"])
        if fail:
            out = {"ok": False, "route": "Backup repo"}
            out.update(fail)
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _round_t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        result = _sync_finish_summary(summary, written, open_chat_id, local_ids)
        result["pushedChats"] = pushed_chats
        result["roundId"] = round_id
        result["durationMs"] = int((time.time() - _round_t0) * 1000)
        state = _sync_state_load()
        _sync_record_result(state, trigger, result)
        state["lastRoute"] = "Backup repo"
        _sync_state_save(state)
        return result
    except _SyncSuperseded as e:
        # v0.6.3e (#317): the operator's choice outranked this
        # round at a phase boundary. The stopped round records
        # its own supersession; the direction runs behind it.
        out = _sync_superseded_result(e.direction, e.phase)
        out["roundId"] = round_id
        out["durationMs"] = int((time.time() - _round_t0) * 1000)
        _sync_fail_record(trigger, out)
        return out
    finally:
        _sync_progress_set("done")
        _SYNC_ROUND["depth"] = max(0, _SYNC_ROUND["depth"] - 1)
        if _SYNC_ROUND["depth"] == 0:
            _SYNC_ROUND["thread"] = None
        _SYNC_LOCK.release()


def sync_pull_round(cfg, trigger, account="operator"):
    # The trigger round: pull + converge, no push — the door
    # opening refreshes the room; publishing stays the button's
    # (and the next full round's) act. Quiet by design: verdicts
    # land in the sync state, never in a popup.
    if not _SYNC_LOCK.acquire(False):
        return None
    round_id = uuid.uuid4().hex[:12]
    if _SYNC_ROUND["depth"] == 0:
        _SYNC_ROUND["thread"] = threading.get_ident()
    _SYNC_ROUND["depth"] += 1
    _round_t0 = time.time()
    _sync_progress_set("fetch", trigger, round_id)
    try:
        # Build 6 (#176 phase 2): a lit Mesh road answers a
        # trigger pull before the repo is asked — same quiet
        # shape: apply what arrived, push nothing.
        mesh_hit = None
        try:
            mesh_hit = _sync_mesh_pull(cfg)
        except Exception:
            mesh_hit = None
        if mesh_hit is not None:
            result = _sync_finish_summary(mesh_hit[1], 0, "", set())
            result["route"] = mesh_hit[0]
            result["roundId"] = round_id
            result["durationMs"] = int((time.time() - _round_t0) * 1000)
            state = _sync_state_load()
            _sync_record_result(state, trigger, result)
            state["lastRoute"] = mesh_hit[0]
            _sync_state_save(state)
            return result
        if not github_auth():
            return None
        fetched, fail = sync_fetch(cfg, account)
        if fail:
            state = _sync_state_load()
            _sync_record_result(state, trigger, {"state": fail.get("state") or "held",
                                                 "message": fail.get("error") or ""})
            return None
        _sync_preempt_checkpoint("merge")
        _sync_progress_set("merge")
        summary = sync_apply(cfg, fetched, account=account)
        result = _sync_finish_summary(summary, 0, "", set())
        result["roundId"] = round_id
        result["durationMs"] = int((time.time() - _round_t0) * 1000)
        state = _sync_state_load()
        _sync_record_result(state, trigger, result)
        return result
    except _SyncSuperseded as e:
        # v0.6.3e (#317): even a quiet trigger pull yields to
        # the operator's choice — and names it on the record,
        # though the pull itself stays popup-quiet as ever.
        out = _sync_superseded_result(e.direction, e.phase)
        out["roundId"] = round_id
        out["durationMs"] = int((time.time() - _round_t0) * 1000)
        _sync_fail_record(trigger, out)
        return out
    except Exception:
        return None
    finally:
        _sync_progress_set("done")
        _SYNC_ROUND["depth"] = max(0, _SYNC_ROUND["depth"] - 1)
        if _SYNC_ROUND["depth"] == 0:
            _SYNC_ROUND["thread"] = None
        _SYNC_LOCK.release()


# -- The sync override (v0.6.2e, #303) ---------------------------
# A setting such that hitting the Sync button — the one control,
# wherever it is tapped — offers a choice: Send a sync or
# Receive a sync, a manual override that moves NOW, on demand,
# rather than at the automatic cadence's pace. The directions
# are not a second sync system: Send is the full round's publish
# half standing alone (this seat's set goes out; nothing is
# applied), Receive is the trigger pull with its verdict spoken
# (the converged set comes down; nothing is published). Both
# ride the standing roads — the Mesh first when a peer's road is
# lit, the backup repo otherwise (#257) — and the standing
# convergence law (#251-#253) is untouched. The setting governs
# the button's behavior only: ON (the default — the feature IS
# the behavior), a press offers the choice; OFF, a press runs
# the legacy full round at once. The automatic cadence — app
# start, DHD sessions, Mesh contact, push-on-write — never
# consults the setting.


def sync_choice_enabled(cfg=None):
    # The setting's read: config's sync block, default ON. An
    # absent block, or a value that is not plainly false, reads
    # as the feature standing.
    if cfg is None:
        cfg = load_config()
    try:
        block = cfg.get("sync") if isinstance(cfg, dict) else None
        if isinstance(block, dict) and "choiceOnPress" in block:
            return block.get("choiceOnPress") is not False
    except Exception:
        pass
    return True


def sync_set_choice(on, cfg=None):
    # The setting's stored half: the sync block in the config,
    # written through save_config like every operator setting.
    # Returns the value that now stands, or None when the save
    # itself failed — the caller names that refusal rather than
    # letting the switch pretend.
    if cfg is None:
        cfg = load_config()
    block = cfg.get("sync") if isinstance(cfg.get("sync"), dict) else {}
    block = dict(block)
    block["choiceOnPress"] = bool(on)
    cfg["sync"] = block
    if not save_config(cfg):
        return None
    return bool(on)


def _sync_send_mesh(cfg, files, manifest):
    # Send's Mesh road: the exchange's first leg IS the publish
    # — the peer applies this seat's set at its own door. The
    # set it sends back is deliberately NOT applied here: a
    # Send moves one way. Returns (route, None) on a completed
    # publish, (None, None) when no peer's road is lit.
    peers = _sync_mesh_peers()
    if not peers:
        return None, None
    if sum(len(b) for b in files.values()) > _SYNC_MESH_MAX_BYTES:
        return None, None
    wire = {}
    for path, blob in files.items():
        wire[path] = base64.b64encode(blob).decode("ascii")
    for peer in peers:
        if mesh_probe_peer(peer) is None:
            continue
        refusal = _sync_mesh_peer_gate(peer)
        if refusal:
            _sync_mesh_refusal_note(refusal)
            continue
        payload = _sync_mesh_ask(peer, "/mesh/sync/exchange",
                                 {"files": wire, "manifest": manifest})
        if payload is None:
            continue
        return "Mesh — " + peer["name"], None
    return None, None


_SYNC_STAMP_KEYS = ("exportedAt", "syncedAt", "mtime", "bridgeBuild")


def _sync_substance(path, data):
    # A sync file's substance, with the collect stamps stripped:
    # the set's bookkeeping files restamp themselves on every
    # collect (an exportedAt here, a syncedAt there, a card's
    # mtime), so a byte diff alone would claim movement where
    # nothing of the operator's moved. JSON files compare
    # parsed, with stamp keys dropped at any depth (and the
    # manifest's derived digests, which only echo those
    # stamps); everything else compares byte for byte.
    if data is None:
        return None
    if not str(path).endswith(".json"):
        return data
    try:
        obj = json.loads(data.decode("utf-8", "replace"))
    except Exception:
        return data

    def strip(x, top=False):
        if isinstance(x, dict):
            out = {}
            for k, v in x.items():
                if k in _SYNC_STAMP_KEYS:
                    continue
                if top and str(k).endswith("Sha"):
                    continue
                out[k] = strip(v)
            return out
        if isinstance(x, list):
            return [strip(v) for v in x]
        return x

    try:
        return json.dumps(strip(obj, top=True), sort_keys=True).encode()
    except Exception:
        return data


def sync_send_round(cfg, trigger="button", open_chat_id="", account="operator"):
    # SEND: publish this seat's set, now — and apply nothing.
    # The receipt names what went up: files written on the repo
    # road; on the Mesh road, the set carried to the named peer.
    # A seat with nothing new to publish says so plainly.
    # v0.6.3e (#317): a Send never queues behind a round in
    # flight — the choice preempts it (see _sync_preempt_acquire).
    _seq, _pre = _sync_preempt_acquire("send", trigger)
    if _pre is not None:
        _pre["roundId"] = uuid.uuid4().hex[:12]
        _sync_fail_record(trigger, _pre)
        return _pre
    round_id = uuid.uuid4().hex[:12]
    if _SYNC_ROUND["depth"] == 0:
        _SYNC_ROUND["thread"] = threading.get_ident()
    _SYNC_ROUND["depth"] += 1
    _t0 = time.time()
    _sync_progress_set("write", trigger, round_id)
    try:
        files, manifest, _index = sync_collect(cfg, account)
        _sync_preempt_checkpoint("write", _seq)
        route, _none = _sync_send_mesh(cfg, files, manifest)
        if route is not None:
            result = {"ok": True, "state": "synced", "direction": "send",
                      "route": route, "filesCarried": len(files),
                      "pushedFiles": len(files), "pushedChats": 0,
                      "message": "Sent — this seat's set ("
                                 + str(len(files)) + " files) went to "
                                 + route + ". Nothing was pulled down."}
            result["roundId"] = round_id
            result["durationMs"] = int((time.time() - _t0) * 1000)
            state = _sync_state_load()
            _sync_record_result(state, trigger, result)
            state["lastRoute"] = route
            _sync_state_save(state)
            return result
        if not github_auth():
            out = _sync_auth_error()
            out["direction"] = "send"
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        got = _sync_repo(cfg)
        if got[0] is None:
            out = {"ok": False, "route": "Backup repo"}
            out.update(got[1] or _sync_auth_error())
            out["direction"] = "send"
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        auth, base = got[0]
        fetched, fail = sync_fetch(cfg, account)
        if fail:
            out = {"ok": False, "route": "Backup repo"}
            out.update(fail)
            out["direction"] = "send"
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        # What of the operator's actually moves, stamps aside.
        moved = [p for p in files
                 if _sync_substance(p, files[p])
                 != _sync_substance(p, fetched["files"].get(p))]
        if not moved:
            result = {"ok": True, "state": "synced",
                      "direction": "send", "route": "Backup repo",
                      "filesWritten": 0, "pushedFiles": 0,
                      "pushedChats": 0,
                      "message": "Send — nothing to move: this "
                                 "seat's set is already the "
                                 "published set."}
            result["roundId"] = round_id
            result["durationMs"] = int((time.time() - _t0) * 1000)
            state = _sync_state_load()
            _sync_record_result(state, trigger, result)
            state["lastRoute"] = "Backup repo"
            _sync_state_save(state)
            return result
        _sync_preempt_checkpoint("write", _seq)
        written, fail = _sync_push(cfg, base, auth["token"], files,
                                   fetched["files"])
        if fail:
            out = {"ok": False, "route": "Backup repo"}
            out.update(fail)
            out["direction"] = "send"
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        message = ("Sent — " + str(len(moved)) + " file"
                   + ("s" if len(moved) != 1 else "")
                   + " published to the backup repo. Nothing "
                     "was pulled down.")
        result = {"ok": True, "state": "synced", "direction": "send",
                  "route": "Backup repo", "filesWritten": len(moved),
                  "pushedFiles": written, "pushedChats": 0,
                  "message": message}
        result["roundId"] = round_id
        result["durationMs"] = int((time.time() - _t0) * 1000)
        state = _sync_state_load()
        _sync_record_result(state, trigger, result)
        state["lastRoute"] = "Backup repo"
        _sync_state_save(state)
        return result
    except _SyncSuperseded as e:
        # v0.6.3e (#317): a newer operator choice replaced this
        # Send mid-flight; it stops at the boundary and says so.
        out = _sync_superseded_result(e.direction, e.phase, "send")
        out["direction"] = "send"
        out["roundId"] = round_id
        out["durationMs"] = int((time.time() - _t0) * 1000)
        _sync_fail_record(trigger, out)
        return out
    finally:
        _sync_preempt_clear(_seq)
        _sync_progress_set("done")
        _SYNC_ROUND["depth"] = max(0, _SYNC_ROUND["depth"] - 1)
        if _SYNC_ROUND["depth"] == 0:
            _SYNC_ROUND["thread"] = None
        _SYNC_LOCK.release()


def sync_receive_round(cfg, trigger="button", account="operator"):
    # RECEIVE: pull + converge, publish nothing — the trigger
    # pull's machinery with the button's spoken verdict. The
    # receipt names what came down (the finish summary's own
    # counts); a round where nothing new arrived says so.
    # v0.6.3e (#317): like Send, a Receive preempts a round in
    # flight rather than queueing behind it.
    _seq, _pre = _sync_preempt_acquire("receive", trigger)
    if _pre is not None:
        _pre["roundId"] = uuid.uuid4().hex[:12]
        _sync_fail_record(trigger, _pre)
        return _pre
    round_id = uuid.uuid4().hex[:12]
    if _SYNC_ROUND["depth"] == 0:
        _SYNC_ROUND["thread"] = threading.get_ident()
    _SYNC_ROUND["depth"] += 1
    _t0 = time.time()
    _sync_progress_set("fetch", trigger, round_id)
    try:
        mesh_hit = None
        try:
            mesh_hit = _sync_mesh_pull(cfg)
        except Exception:
            mesh_hit = None
        if mesh_hit is not None:
            result = _sync_finish_summary(mesh_hit[1], 0, "", set())
            result["route"] = mesh_hit[0]
        elif not github_auth():
            out = _sync_auth_error()
            out["direction"] = "receive"
            out["roundId"] = round_id
            out["durationMs"] = int((time.time() - _t0) * 1000)
            _sync_fail_record(trigger, out)
            return out
        else:
            fetched, fail = sync_fetch(cfg, account)
            if fail:
                out = {"ok": False, "route": "Backup repo"}
                out.update(fail)
                out["direction"] = "receive"
                out["roundId"] = round_id
                out["durationMs"] = int((time.time() - _t0) * 1000)
                _sync_fail_record(trigger, out)
                return out
            _sync_preempt_checkpoint("merge", _seq)
            _sync_progress_set("merge")
            summary = sync_apply(cfg, fetched, account=account)
            result = _sync_finish_summary(summary, 0, "", set())
            result["route"] = "Backup repo"
        result["direction"] = "receive"
        if (result.get("state") == "synced"
                and not result.get("receipt", {}).get("changed")
                and not result.get("needsEyes")):
            result["message"] = ("Receive — nothing new came down: "
                                 "this seat already holds the "
                                 "converged set.")
        elif result.get("state") == "synced":
            result["message"] = ("Received — the converged set came "
                                 "down and landed. Nothing was "
                                 "published.")
        result["roundId"] = round_id
        result["durationMs"] = int((time.time() - _t0) * 1000)
        state = _sync_state_load()
        _sync_record_result(state, trigger, result)
        state["lastRoute"] = result["route"]
        _sync_state_save(state)
        return result
    except _SyncSuperseded as e:
        # v0.6.3e (#317): a newer operator choice replaced this
        # Receive mid-flight; it stops at the boundary.
        out = _sync_superseded_result(e.direction, e.phase, "receive")
        out["direction"] = "receive"
        out["roundId"] = round_id
        out["durationMs"] = int((time.time() - _t0) * 1000)
        _sync_fail_record(trigger, out)
        return out
    finally:
        _sync_preempt_clear(_seq)
        _sync_progress_set("done")
        _SYNC_ROUND["depth"] = max(0, _SYNC_ROUND["depth"] - 1)
        if _SYNC_ROUND["depth"] == 0:
            _SYNC_ROUND["thread"] = None
        _SYNC_LOCK.release()


def sync_override_round(cfg, direction, trigger="button",
                        open_chat_id="", account="operator"):
    # The button's dispatch (#303): a named direction runs its
    # one-way round; anything else is the legacy full round,
    # exactly as the button always ran it.
    if direction == "send":
        return sync_send_round(cfg, trigger, open_chat_id, account=account)
    if direction == "receive":
        return sync_receive_round(cfg, trigger, account=account)
    return sync_round(cfg, trigger, open_chat_id, account=account)


def sync_state_payload():
    auth = github_auth()
    state = _sync_state_load()
    return {
        "signedIn": bool(auth),
        "login": (auth or {}).get("login") or "",
        "route": state.get("lastRoute") or "Backup repo",
        "lastSyncAt": state.get("lastSyncAt"),
        "lastSyncEpoch": state.get("lastSyncEpoch") or 0,
        "lastResult": state.get("lastResult") or "",
        "lastState": state.get("lastState") or "",
        "lastTrigger": state.get("lastTrigger") or "",
        # v0.4.10e (#254): the sync bar's two faces — the live
        # progress while a round runs, the durable receipt
        # after it lands.
        "progress": state.get("syncProgress") or {"active": False, "phase": "done"},
        "receipt": state.get("lastReceipt") or None,
        # v0.5.13e (#262): shells still standing, named — the
        # record clears as fuller arrivals heal them.
        "incomplete": state.get("incomplete") or [],
        # v0.6.2e (#303): the override setting, so every sync
        # surface renders the button's behavior from the bridge.
        "choiceOnPress": sync_choice_enabled(),
        # v0.6.4e (#323): the last Mesh-road account refusal,
        # and the foreign-data purge's standing record.
        "meshRefusal": (state.get("lastReceipt") or {}).get("meshRefusal") or "",
        "lastPurge": state.get("lastPurge") or None,
    }


def _sync_trigger_pull(trigger):
    try:
        cfg = load_config()
        # Build 6: the pull round itself gates the repo path on
        # sign-in; the Mesh path needs none, so triggers no longer
        # pre-gate on the sign-in here.
        sync_pull_round(cfg, trigger)
    except Exception:
        pass


def sync_startup_pull():
    # App start (the __main__ thread beside the backup loop):
    # a short grace for the bridge to finish coming up, then the
    # pull. Inert when signed out.
    time.sleep(10)
    _sync_trigger_pull("app-start")


def _sync_note_session(trigger, key):
    # A session starting at any seat refreshes the room — once,
    # with a global debounce so a door in heavy use pulls at most
    # every debounce window. A device (or window) whose last
    # accepted note is older than the session gap, or which has
    # never been seen, counts as a session starting.
    now = time.time()
    key = str(key or "device")
    with _SYNC_DHD_LOCK:
        last = _SYNC_DHD_SEEN.get(key, 0)
        any_recent = any(now - v < _SYNC_TRIGGER_DEBOUNCE for v in _SYNC_DHD_SEEN.values())
        if now - last < _SYNC_DHD_SESSION_GAP or any_recent:
            if now - last >= _SYNC_DHD_SESSION_GAP:
                _SYNC_DHD_SEEN[key] = now
            return
        _SYNC_DHD_SEEN[key] = now
    threading.Thread(target=_sync_trigger_pull, args=(trigger,), daemon=True).start()


def sync_note_dhd_session(device_key):
    # DHD session start: the proxy calls this for every accepted
    # request from an approved device.
    _sync_note_session("dhd-session", device_key)


def sync_note_app_session(seat_key):
    # v0.3.0e Build 1 (#200): the desktop/app seat notes itself
    # the same way. The bridge is long-lived (boot-armed), so its
    # own app-start pull can be hours stale by the time a window
    # opens; the page notes the seat and the room refreshes for
    # it — the desk side of "pick it up where you left off".
    _sync_note_session("app-session", "seat:" + str(seat_key or "window"))


# --- Boot mode (0.1.9e Build 12, issue #142) -------------------------
# Whether this install is armed to come up headless at boot is read
# from the system every time it is shown — the systemd user units'
# enabled state and the user's linger state — never assumed from
# what an installer once did. Cached briefly: /api/status is polled
# and systemctl is not free.
_BOOT_CACHE = {"at": 0, "payload": None}


def _systemd_user_state(unit):
    try:
        r = subprocess.run(["systemctl", "--user", "is-enabled", unit],
                           capture_output=True, text=True, timeout=3)
        out = (r.stdout or "").strip()
        return out or "unknown"
    except Exception:
        return "unknown"


def _linger_state():
    user = os.environ.get("USER") or ""
    if not user:
        try:
            import pwd
            user = pwd.getpwuid(os.getuid()).pw_name
        except Exception:
            user = ""
    if user:
        try:
            r = subprocess.run(["loginctl", "show-user", user, "--property=Linger", "--value"],
                               capture_output=True, text=True, timeout=3)
            out = (r.stdout or "").strip().lower()
            if out in ("yes", "no"):
                return out == "yes"
        except Exception:
            pass
        try:
            if os.path.exists("/var/lib/systemd/linger/" + user):
                return True
        except Exception:
            pass
    return None


def boot_mode_payload():
    now = time.time()
    if _BOOT_CACHE["payload"] is not None and now - _BOOT_CACHE["at"] < 30:
        return _BOOT_CACHE["payload"]
    bridge_unit = _systemd_user_state("navi-bridge.service")
    llama_unit = _systemd_user_state("navi-llamafile.service")
    linger = _linger_state()
    payload = {
        "bridgeUnit": bridge_unit,
        "llamafileUnit": llama_unit,
        "linger": linger,
        "armed": bridge_unit == "enabled" and llama_unit == "enabled" and linger is True,
        # v0.4.10e (#250): the mode Settings itself holds — the
        # installer's startup choice, kept in the config by the
        # installer and by the Settings → System card alike.
        # The status pane reads it to decide whether a BOOT
        # section belongs there at all: the section follows
        # Settings, and the states inside it still read from
        # the system, never assumed.
        "settingsMode": str((load_config() or {}).get("startup") or ""),
    }
    _BOOT_CACHE["at"] = now
    _BOOT_CACHE["payload"] = payload
    return payload


# --- Arm / disarm at boot from inside the app (Build 14, #159) -----
# The Boot row read the state live from Build 12 on; this is the
# hand that goes with the eyes. Arming does exactly what the
# installer's "At system boot" choice does — install both unit
# files from the templates this package ships (with this install
# folder substituted), daemon-reload, enable --now both units —
# and then tries linger the one way the app honestly can: a plain
# loginctl call, no sudo (the bridge has no sudo channel and does
# not borrow the parked sudo toggle). When linger cannot be
# enabled from here, the result carries the exact command for a
# terminal, the way the installer prints it. Disarming disables
# both units (never --now: what is running keeps running — it
# simply will not come up at boot) and deliberately leaves linger
# alone. Both directions are idempotent, and the verdict is never
# the steps' word: the state is re-read from the system at the
# end and reported as found — partial shows as partial.

_BOOT_UNITS = ("navi-llamafile.service", "navi-bridge.service")


def _boot_user():
    user = os.environ.get("USER") or ""
    if not user:
        try:
            import pwd
            user = pwd.getpwuid(os.getuid()).pw_name
        except Exception:
            user = ""
    return user


def _boot_run(argv, timeout=25):
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
        return r.returncode, ((r.stdout or "") + (r.stderr or "")).strip()
    except Exception as e:
        return None, str(e)


def _unit_aim_problems():
    # v0.7.8e (#363 Part A): the managed units' aim, judged
    # from the unit files themselves — the only witnesses
    # that survive a dead seat. Every managed unit that
    # EXISTS must carry an ExecStart resolving to a file
    # present and executable; a unit aiming into a deleted
    # tree is the 2026-11-21 dark seat (203/EXEC on both
    # units). A unit that does not exist is not a defect.
    # The apply helper carries the same judgment for its
    # rollback and confirmation legs.
    problems = []
    unit_dir = os.path.join(os.path.expanduser("~"),
                            ".config", "systemd", "user")
    for name in _BOOT_UNITS:
        path = os.path.join(unit_dir, name)
        if not os.path.isfile(path):
            continue
        aim = ""
        try:
            with open(path) as f:
                for line in f:
                    line = line.strip()
                    if line.startswith("ExecStart="):
                        rest = line[len("ExecStart="):].strip()
                        if rest:
                            aim = rest.split()[0]
                        break
        except Exception:
            problems.append(name + " cannot be read")
            continue
        if not aim:
            problems.append(name + " carries no ExecStart to resolve")
        elif not os.path.isfile(aim):
            problems.append(name + " aims at " + aim
                            + ", which does not exist")
        elif not os.access(aim, os.X_OK):
            problems.append(name + " aims at " + aim
                            + ", which is not executable")
    return problems


def boot_set_armed(want_armed):
    # v0.7.8e (#363 Part A): a bridge running from a TRANSIENT
    # tree — a parked previous install (.apex-prev), a staging
    # or failed tree, the rollback park — must never write the
    # boot units: it would aim them at itself, and the tree it
    # names is deleted by the very operations that park it
    # (the 2026-11-21 rollback's second wound: the parked
    # tree's bridge armed the units into .apex-prev, which the
    # disk guard then removed). The refusal is named, and
    # nothing is written.
    if want_armed and os.path.basename(ROOT).startswith(".apex-"):
        return {"ok": False, "partial": False, "armed": False,
                "boot": boot_mode_payload(), "steps": [],
                "lingerCommand": None,
                "message": "Refused: this bridge is running from "
                + ROOT + ", a temporary tree (a parked, staged or "
                "failed install). Arming boot services from here "
                "would aim them at a tree that is about to be "
                "removed, and the seat would come back dark. Open "
                "Apex from the installed tree and arm it there."}
    steps = []
    user = _boot_user()
    linger_cmd = ("sudo loginctl enable-linger " + user) if user else None
    unit_dir = os.path.join(os.path.expanduser("~"), ".config", "systemd", "user")
    if want_armed:
        for unit in _BOOT_UNITS:
            try:
                with open(os.path.join(ROOT, "systemd", unit)) as f:
                    text = f.read().replace("__INSTALL_DIR__", ROOT)
                os.makedirs(unit_dir, exist_ok=True)
                with open(os.path.join(unit_dir, unit), "w") as f:
                    f.write(text)
                steps.append({"step": "install " + unit, "ok": True})
            except Exception as e:
                steps.append({"step": "install " + unit, "ok": False, "detail": str(e)})
        rc, out = _boot_run(["systemctl", "--user", "daemon-reload"])
        steps.append({"step": "daemon-reload", "ok": rc == 0, "detail": out if rc != 0 else ""})
        for unit in _BOOT_UNITS:
            rc, out = _boot_run(["systemctl", "--user", "enable", "--now", unit])
            steps.append({"step": "enable " + unit, "ok": rc == 0, "detail": out if rc != 0 else ""})
        if _linger_state() is True:
            steps.append({"step": "linger", "ok": True, "detail": "already on"})
        elif user:
            rc, out = _boot_run(["loginctl", "enable-linger", user])
            steps.append({"step": "linger", "ok": rc == 0, "detail": out if rc != 0 else ""})
        else:
            steps.append({"step": "linger", "ok": False, "detail": "no user name to enable linger for"})
        try:
            cfg = load_config()
            cfg["startup"] = "on-boot"
            save_config(cfg)
        except Exception:
            pass
    else:
        for unit in reversed(_BOOT_UNITS):
            rc, out = _boot_run(["systemctl", "--user", "disable", unit])
            steps.append({"step": "disable " + unit, "ok": rc == 0, "detail": out if rc != 0 else ""})
        _boot_run(["systemctl", "--user", "daemon-reload"])
        try:
            cfg = load_config()
            cfg["startup"] = "on-ui-launch"
            save_config(cfg)
        except Exception:
            pass
    _BOOT_CACHE["at"] = 0
    _BOOT_CACHE["payload"] = None
    boot = boot_mode_payload()
    if want_armed:
        units_on = boot["bridgeUnit"] == "enabled" and boot["llamafileUnit"] == "enabled"
        if boot["armed"]:
            return {"ok": True, "partial": False, "armed": True, "boot": boot,
                    "steps": steps, "lingerCommand": None,
                    "message": "Armed — the system confirms both services are enabled and linger is on. Apex will come up headless at boot."}
        if units_on:
            return {"ok": False, "partial": True, "armed": False, "boot": boot,
                    "steps": steps, "lingerCommand": linger_cmd,
                    "message": "Half-armed: both services are enabled, but linger is still off, so for now they start at login, not at boot. One command in a terminal finishes it:"}
        return {"ok": False, "partial": False, "armed": False, "boot": boot,
                "steps": steps, "lingerCommand": None,
                "message": "Arming did not take — the system does not report the services enabled. The steps above say where it stopped; the installer remains the fallback."}
    still_on = boot["bridgeUnit"] == "enabled" or boot["llamafileUnit"] == "enabled"
    if not still_on:
        return {"ok": True, "partial": False, "armed": False, "boot": boot,
                "steps": steps, "lingerCommand": None,
                "message": "Disarmed — Apex will not come up at boot. What is running now keeps running; linger was left as it is, on purpose."}
    return {"ok": False, "partial": True, "armed": bool(boot["armed"]), "boot": boot,
            "steps": steps, "lingerCommand": None,
            "message": "Disarming only half-took — the system still reports a service enabled. The steps above say which."}


# --- Case Files (0.1.9e Build 12, issues #137/#138) ------------------
# The first Apex | App. A case is a folder of plain markdown in the
# Vault — cases/<slug>/ — so cases ride the Vault's backups and
# sync like every other note on the desk, and open in Obsidian as
# they lie. case.md carries the manifest as frontmatter; findings
# are notes in findings/ with their own frontmatter (severity,
# internal); evidence is whatever lands in evidence/; the timeline
# is one newest-first markdown file. The report (#138) is composed
# from those same files — internal findings are withheld AND
# counted, never silently omitted.

CASE_SEVERITIES = ["critical", "high", "medium", "low", "info"]

# Build 15 (#162): the image evidence a case report embeds.
CASE_IMAGE_MIMES = {
    ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
    ".gif": "image/gif", ".webp": "image/webp",
}
CASE_EMBED_MAX_BYTES = 8 * 1024 * 1024


def _fm_parse(text):
    meta = {}
    body = text or ""
    if body.startswith("---\n"):
        end = body.find("\n---\n", 3)
        if end != -1:
            head = body[4:end]
            body = body[end + 5:]
            for ln in head.split("\n"):
                if ":" in ln:
                    k, v = ln.split(":", 1)
                    meta[k.strip().lower()] = v.strip()
    return meta, body


def _fm_render(meta_pairs, body):
    lines = ["---"]
    for k, v in meta_pairs:
        lines.append(k + ": " + str(v))
    lines.append("---")
    lines.append("")
    return "\n".join(lines) + body


def _case_slug(name):
    s = re.sub(r"[^A-Za-z0-9]+", "-", str(name or "")).strip("-").lower()
    return s or "case"


def _case_dir(slug, account="operator"):
    if not re.match(r"^[a-z0-9][a-z0-9-]*$", str(slug or "")):
        return None
    rel = vault_join("cases/" + slug)
    if rel is None:
        return None
    return vault_fs_path(rel, account)


def _case_manifest(slug, account="operator"):
    d = _case_dir(slug, account)
    if not d or not os.path.isdir(d):
        return None
    try:
        with open(os.path.join(d, "case.md"), encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return None
    meta, _body = _fm_parse(text)
    return meta


def _case_findings(slug, account="operator"):
    d = _case_dir(slug, account)
    out = []
    fdir = os.path.join(d, "findings") if d else ""
    if fdir and os.path.isdir(fdir):
        for name in sorted(os.listdir(fdir)):
            if not name.lower().endswith(".md"):
                continue
            try:
                with open(os.path.join(fdir, name), encoding="utf-8") as f:
                    text = f.read()
            except Exception:
                continue
            meta, body = _fm_parse(text)
            # v0.6.6e (#329): the read every surface shares —
            # the file's own "# title" line is structure, not
            # body, and comes off; the body's own opening line
            # is the author's text and stands (#291 verbatim).
            # The renderings that print the heading separately
            # (the formed document, the report export) dedupe
            # the opener at their own hand. The stored file is
            # never touched by a read.
            _ttl = str(meta.get("title") or name[:-3])
            _blines = body.split("\n")
            for _i, _ln in enumerate(_blines):
                if not _ln.strip():
                    continue
                if _ln.lstrip().startswith("#") and _opener_norm(_ln) == _opener_norm(_ttl):
                    body = "\n".join(_blines[_i + 1:]).lstrip("\n")
                break
            sev = str(meta.get("severity") or "info").lower()
            if sev not in CASE_SEVERITIES:
                sev = "info"
            out.append({
                "file": name,
                "title": str(meta.get("title") or name[:-3]),
                "severity": sev,
                "internal": str(meta.get("internal") or "").lower() in ("yes", "true", "1"),
                "filed": str(meta.get("filed") or ""),
                # Build 15 (#161): who filed this — Navi's own
                # filings are marked as hers in the frontmatter;
                # notes from before the marking existed are the
                # operator's, which is what they always were.
                "author": "navi" if str(meta.get("author") or "").lower() == "navi" else "operator",
                # Build 2 (#199): the review state. Findings
                # filed before it existed take the default their
                # author implies — the operator's are confirmed,
                # Navi's are leads — which is what they always
                # were in practice.
                "state": (str(meta.get("state") or "").lower()
                          if str(meta.get("state") or "").lower() in ("lead", "confirmed")
                          else ("lead" if str(meta.get("author") or "").lower() == "navi" else "confirmed")),
                # v0.5.9e (#280): the identity stamps a filing
                # was born with — a dossier element's id, its
                # dossier, or the element ids a whole-dossier
                # filing carries.
                # v0.5.15e (#291): the destination the filing
                # declared — a finding unless its frontmatter
                # says it landed as a lead.
                "part": (str(meta.get("part") or "").lower()
                         if str(meta.get("part") or "").lower() in ("lead", "finding")
                         else "finding"),
                "element": str(meta.get("element") or ""),
                "dossierId": str(meta.get("dossier") or ""),
                "elements": [p.strip() for p in str(meta.get("elements") or "").split(",") if p.strip()],
                "body": body.strip(),
            })
    out.sort(key=lambda f: (CASE_SEVERITIES.index(f["severity"]), f["file"]))
    return out


def _sha256_file(path):
    h = hashlib.sha256()
    try:
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 256), b""):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ""


def _evidence_register_sync(slug, account="operator"):
    # Build 2 (#199): every file in evidence/ gets its custody
    # register entry. Files filed before the register existed
    # are backfilled on first sight — hash computed now and the
    # entry says so honestly (acquired unknown, custody noting
    # the backfill) — so the register the operator reviews is
    # always the whole folder, and Sync carries it whole.
    d = _case_dir(slug, account)
    if not d:
        return
    edir = os.path.join(d, "evidence")
    if not os.path.isdir(edir):
        return
    have = {e["key"] for e in _case_register(slug, "evidence", account)}
    now = time.strftime("%Y-%m-%d %H:%M", time.localtime())
    for name in sorted(os.listdir(edir)):
        full = os.path.join(edir, name)
        if not os.path.isfile(full) or _register_key(name) in have:
            continue
        _register_append(slug, "evidence", name, {
            "sha256": _sha256_file(full),
            "size": str(os.path.getsize(full)),
            "acquired": "not recorded — the file predates the evidence register",
            "custody": "Backfilled by the bridge when the register was introduced (v0.3.0e — Build 2); the hash is the file's hash as found.",
            "author": "operator", "filed": now,
        }, "", account=account)


def _case_evidence(slug, account="operator"):
    # Files on disk, joined with their custody register entries
    # (description, acquired, custody note, and the SHA-256 the
    # bridge computed at filing time). A file whose entry is
    # missing (a read racing a backfill) still lists, hashless
    # and plainly marked unregistered.
    d = _case_dir(slug, account)
    out = []
    edir = os.path.join(d, "evidence") if d else ""
    reg = {e["key"]: e for e in _case_register(slug, "evidence", account)}
    seen = set()
    if edir and os.path.isdir(edir):
        for name in sorted(os.listdir(edir)):
            full = os.path.join(edir, name)
            if os.path.isfile(full):
                e = reg.get(_register_key(name))
                f = e["fields"] if e else {}
                seen.add(_register_key(name))
                out.append({
                    "name": name, "size": os.path.getsize(full),
                    "sha256": str(f.get("sha256") or ""),
                    "description": (e["body"] if e else ""),
                    "acquired": str(f.get("acquired") or ""),
                    "custody": str(f.get("custody") or ""),
                    "registered": e is not None,
                })
    # v0.6.6e (#326): text exhibits — register entries with no
    # file behind them, filed from chat as evidence. They
    # stand in the evidence list as exhibits: the text itself
    # is the item, its custody fields on its face.
    for e in _case_register(slug, "evidence", account):
        if e["key"] in seen:
            continue
        f = e["fields"]
        if "text exhibit" not in str(f.get("custody") or "").lower():
            continue
        out.append({
            "name": e["heading"], "size": int(f.get("size") or 0),
            "sha256": str(f.get("sha256") or ""),
            "description": e["body"],
            "acquired": str(f.get("acquired") or ""),
            "custody": str(f.get("custody") or ""),
            "registered": True, "exhibit": True,
        })
    return out


def _case_timeline(slug, account="operator"):
    d = _case_dir(slug, account)
    out = []
    if not d:
        return out
    try:
        with open(os.path.join(d, "timeline.md"), encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return out
    cur = None
    for ln in text.split("\n"):
        if ln.startswith("## "):
            head = ln[3:].strip()
            date, sep, title = head.partition(" — ")
            cur = {"date": date.strip(), "title": (title if sep else head).strip(), "body": ""}
            out.append(cur)
        elif cur is not None:
            cur["body"] += ln + "\n"
    for e in out:
        e["body"] = e["body"].strip()
    return out


# --- Deep search + the conversational pull (v0.5.10e, #282/#283) --
# The Wire digs deeper, from chat. #282's routes are the #259
# discipline one level down: a named source or a named hit is
# a deterministic route; anything less specific is PROPOSED in
# the open, never wandered into. #283's pull is the intent
# doctrine at the shelf: an operator instruction in a case
# chat has Navi find the card across the Wire's corpora and
# land it on that case's reference shelf, receipted from what
# the bridge actually did — never unbidden.

_DEEP_SOURCE_WORDS = {"nvd": "nvd", "epss": "epss",
                      "exploit-db": "edb", "exploitdb": "edb", "edb": "edb"}


def deep_search_chat_reply(last):
    """#282's deterministic routes. Returns the reply text, or
    None when the words are not a deep ask."""
    text = (last or "").strip()
    if not text:
        return None
    # Move 2 — a named hit to follow outward.
    m = (re.search(r"\b(?:dig|go)\s+deeper\b[^.]*?\b(CVE-\d{4}-\d{4,7})\b", text, re.I)
         or re.search(r"\bdig\s+into\s+(CVE-\d{4}-\d{4,7})\b", text, re.I)
         or re.search(r"\bfollow\s+(CVE-\d{4}-\d{4,7})\b[^.]*?\b(?:outward|out|deeper)\b", text, re.I)
         or re.search(r"\bwhat\s+(?:else|more)\b[^.]*?\b(CVE-\d{4}-\d{4,7})\b", text, re.I))
    if m:
        try:
            return INTEL.deep_follow_text(m.group(1).upper())
        except Exception:
            return ("The dig could not run just now — the store could not "
                    "be read. The Wire page (Apex | Apps → The Wire) shows "
                    "its state.")
    # Move 1 — a named source's own door.
    src, q = None, ""
    m = re.search(r"\b(?:search|check|query|dig(?:\s+into)?)\s+(?:the\s+)?(nvd|epss|exploit-?db|edb)\b[^.]*?\bfor\s+(.+)", text, re.I)
    if m:
        src = _DEEP_SOURCE_WORDS.get(m.group(1).lower().replace(" ", ""), "nvd")
        q = m.group(2)
    else:
        m = re.search(r"\bkev\b[^.]*?\b(?:live|directly|at\s+the\s+source|itself)\b[^.]*?\bfor\s+(.+)", text, re.I)
        if m:
            src, q = "kev", m.group(1)
    if src:
        q = (q or "").strip().rstrip("?").strip()
        if q:
            try:
                return INTEL.deep_search_text(src, q)
            except Exception:
                return ("The source could not be read just now — the Wire "
                        "page (Apex | Apps → The Wire) shows its state.")
    # No door named: propose the dig in the open. Nothing is
    # fetched on a proposal — the fetch waits for a named door.
    if re.search(r"\b(?:dig|search|go)\s+deeper\b", text, re.I) or \
            re.search(r"\bdig\s+into\s+the\s+sources?\b", text, re.I):
        return ("I can dig past the catalog, into the sources themselves — "
                "name the door and I'll go: “search NVD for <terms>”, "
                "“search the KEV live for <terms>”, “check EPSS for "
                "<CVE id>”, or name a record — “dig deeper into CVE-…” — "
                "and I'll follow it outward from its own page (at most six "
                "pages, two hops, every claim cited to its page). Nothing "
                "is fetched until you name the door.")
    return None


def _wire_card_candidates(descriptor):
    # Every card the Wire's corpora can offer for a descriptor,
    # scored: (score, card). The corpora are the ones the Wire
    # page's tabs carry — the Center's catalog, the wire's own
    # items, the CTF board.
    desc = (descriptor or "").strip()
    out = []
    if not desc:
        return out
    ids = intel_mod.CVE_ID_RE.findall(desc) if intel_mod else []
    words = [w for w in re.findall(r"[a-z0-9][a-z0-9._-]{2,}", desc.lower())
             if w not in intel_mod.STOPWORDS] if intel_mod else []

    def score_of(title, body):
        hay = ((title or "") + " " + (body or "")).lower()
        s = 0
        for w in words:
            if w in (title or "").lower():
                s += 3
            elif w in hay:
                s += 1
        return s

    if ids:
        try:
            full = INTEL.item(ids[0].upper())
        except Exception:
            full = None
        if full:
            tab = "kev" if full.get("kev") else "cve"
            text = (full["id"] + " — " + (full.get("title") or "")
                    + "\n" + (full.get("description") or ""))
            out.append((100, {"tab": tab, "title": full["id"] + " — "
                              + (full.get("title") or ""),
                              "link": "https://nvd.nist.gov/vuln/detail/" + full["id"],
                              "source": "CISA KEV" if full.get("kev") else "NVD",
                              "text": text}))
    try:
        res = INTEL.search(desc, limit=5)
        for lite in res.get("results") or []:
            if ids and lite["id"] == ids[0].upper():
                continue
            tab = "kev" if lite.get("kev") else "cve"
            out.append((40 + (10 if lite.get("kev") else 0),
                        {"tab": tab,
                         "title": lite["id"] + " — " + (lite.get("title") or ""),
                         "link": "https://nvd.nist.gov/vuln/detail/" + lite["id"],
                         "source": "CISA KEV" if lite.get("kev") else "NVD",
                         "text": INTEL._lite_line(lite)}))
    except Exception:
        pass
    try:
        for it in (WIRE.state().get("items") or []):
            s = score_of(it.get("title"), it.get("excerpt"))
            if s:
                out.append((s, {"tab": it.get("kind") or "news",
                                "title": it.get("title") or "",
                                "link": it.get("link") or "",
                                "source": it.get("sourceLabel") or "",
                                "text": (it.get("title") or "") + "\n"
                                        + (it.get("sourceLabel") or "")
                                        + "\n\n" + (it.get("excerpt") or "")}))
    except Exception:
        pass
    try:
        st = CTF.state()
        for e in (st.get("running") or []) + (st.get("upcoming") or []):
            s = score_of(e.get("title"), e.get("description"))
            if s:
                paras = [(e.get("format") or "Format unlisted") + " · "
                         + ("On-site — " + (e.get("location") or "place unlisted")
                            if e.get("onsite") else "Online"),
                         (e.get("description") or "")]
                out.append((s, {"tab": "ctfs", "title": e.get("title") or "",
                                "link": e.get("ctftimeUrl") or e.get("url") or "",
                                "source": "CTFtime",
                                "text": (e.get("title") or "") + "\n"
                                        + "\n".join(p for p in paras if p)}))
    except Exception:
        pass
    out.sort(key=lambda t: -t[0])
    return out


def wire_pull_chat_reply(last, chat_id, cfg, account="operator"):
    """#283's conversational pull: “pull that KEV card in”,
    spoken in a case chat (or with a case open), lands the
    card on that case's reference shelf. Returns the reply
    text, or None when the words are not a pull instruction."""
    text = (last or "").strip()
    if not text:
        return None
    m = (re.match(r"(?i)pull\s+(?:in\s+)?(?:that\s+|the\s+)?(CVE-\d{4}-\d{4,7})\b[^.]*?(?:\bcard\b)?[^.]*?(?:\bin\b)?\s*$", text)
         or re.match(r"(?i)pull\s+(?:in\s+)?(?:that\s+|the\s+)?(.+?)\s+cards?\s+in(?:to\s+this\s+case)?\s*$", text)
         or re.match(r"(?i)pull\s+(?:in\s+)?(?:that\s+|the\s+)?(.+?)\s+in(?:to\s+this\s+case)\s*$", text))
    if not m:
        return None
    descriptor = (m.group(1) or "").strip().rstrip(".")
    slug = ""
    if chat_id is not None:
        for rec in chats_all(account):
            if str(rec.get("id")) == str(chat_id) and rec.get("case"):
                slug = str(rec["case"])
                break
    if not slug:
        slug = case_open_slug(cfg, account) or ""
    if not slug:
        return ("There's no case room for that pull — open a case (or speak "
                "from its chat) and the card will land on its reference shelf.")
    meta = _case_manifest(slug, account)
    case_name = str((meta or {}).get("title") or slug)
    cands = _wire_card_candidates(descriptor)
    if not cands:
        return ("No Wire card answers to “" + descriptor[:80] + "” — the "
                "catalog, the wire and the board were all asked. Nothing "
                "was pulled.")
    top_score, top = cands[0]
    tied = [c for s, c in cands[1:] if s >= top_score - 5 and s > 0]
    if tied and not (intel_mod and intel_mod.CVE_ID_RE.search(descriptor)):
        names = ["“" + top["title"][:70] + "”"] + \
                ["“" + c["title"][:70] + "”" for c in tied[:2]]
        return ("More than one card answers to that: " + "; ".join(names)
                + ". Name the one you mean — a title word or its CVE id — "
                "and I'll pull it.")
    ref, note, err = case_shelf_add(slug, top, by="navi", account=account)
    if err:
        return "The pull did not land: " + err
    if note == "duplicate":
        return ("“" + (top.get("title") or "")[:90] + "” is already on "
                "this case's shelf — as " + ref["id"] + ". No second copy "
                "was made.")
    return ("Pulled onto the reference shelf of “" + case_name + "” as "
            + ref["id"] + " — “" + (top.get("title") or "")[:90] + "” ("
            + SHELF_TAB_LABELS.get(top.get("tab") or "", top.get("tab") or "")
            + " · " + (top.get("source") or "") + "). It stands as "
            "reference for this case's work — not a finding; the case file "
            "is untouched. Name it (“use reference " + ref["id"] + "”) or "
            "ask me to pull it in a reply and I'll read it in full.")


# --- Case birth from the Wire, and the live briefing -------------
# v0.6.6e (#330, as amended): one act — a button on a Wire
# card, or the words in chat — pulls a story together into a
# case: the article read WHOLE onto the case's reference
# shelf, one cited lead per CVE the article names (resolved
# through the intel catalog; an id the catalog cannot answer
# is a named gap, never a silent skip), related coverage from
# the Wire's other stories shelved beside it, the case set
# open — and the case chat opens on HER BRIEFING, composed
# from the case's live state, with her recommended next tasks
# staged as PROPOSALS on the Tasks register: badged as hers,
# awaiting the operator's word. Approve opens the task;
# dismiss strikes it, the strike on the record. Nothing here
# files a finding: leads are leads, proposals are proposals,
# and the operator's own filings (#326) stay operator acts.

BIRTH_CVE_CAP = 12
BIRTH_RELATED_CAP = 5


def case_stage_task(slug, heading, source, account="operator"):
    """Stage one of Navi's recommended tasks as a proposal.
    Returns the standing entry, or None when it could not be
    staged. A heading already on the register — proposed,
    open or done — is never duplicated."""
    heading = " ".join(str(heading or "").split()).strip()
    if not heading:
        return None
    key = _register_key(heading)
    for e in _case_register(slug, "tasks", account):
        if e["key"] == key:
            return e
    now = time.strftime("%Y-%m-%d %H:%M", time.localtime())
    fields = {"done": "no", "state": "proposed", "author": "navi",
              "filed": now, "source": str(source or "recommended by Navi")}
    if not _register_append(slug, "tasks", heading, fields, "", account=account):
        return None
    return {"heading": heading, "key": key, "fields": fields, "body": ""}


def _birth_cve_ids(text):
    ids = []
    if intel_mod:
        for m in intel_mod.CVE_ID_RE.findall(str(text or "")):
            u = m.upper()
            if u not in ids:
                ids.append(u)
    return ids


def _birth_cve_leads(slug, text, source_line, account="operator"):
    """One cited lead per CVE id the text names, resolved
    through the intel catalog. Returns (leads, gaps, overflow):
    leads carry the catalog's own line and description; an id
    the catalog cannot answer lands in gaps — named, never
    silently skipped; ids past the cap land in overflow, also
    named."""
    ids = _birth_cve_ids(text)
    capped, overflow = ids[:BIRTH_CVE_CAP], ids[BIRTH_CVE_CAP:]
    leads, gaps = [], []
    for cid in capped:
        full = None
        try:
            full = INTEL.item(cid)
        except Exception:
            full = None
        if not full:
            gaps.append(cid)
            continue
        try:
            line = INTEL._lite_line(full)
        except Exception:
            line = cid + ((" — " + str(full.get("title"))) if full.get("title") else "")
        body = line
        desc = str(full.get("description") or "").strip()
        if desc:
            body += "\n\n" + desc[:600]
        body += "\n\n— " + source_line
        title = cid + ((" — " + str(full.get("title"))) if full.get("title") else "")
        filed, err = case_land_part(
            slug, "lead", title[:160], body, author="navi",
            source="pulled together at the case's birth from the Wire",
            account=account)
        if err:
            gaps.append(cid)
        else:
            leads.append({"id": cid, "line": line})
    return leads, gaps, overflow


def case_recommended_tasks(slug, leads=None, gaps=None, related=None):
    """Her recommended next tasks for a case, derived from
    what the case actually holds — one per lead (verify it
    against the estate), one per gap (run the id down),
    one for the related coverage (read it for overlap), one
    off the first finding when findings exist. Capped, and
    never duplicating a heading already standing."""
    out = []
    for ld in (leads or []):
        out.append("Verify " + ld["id"] + " against the estate — "
                   "confirm whether anything we run is exposed")
    for g in (gaps or []):
        out.append("Run down " + g + " — the catalog could not "
                   "answer it; pull its record from the source")
    if related:
        out.append("Read the related coverage on the shelf for "
                   "overlap with this case's leads")
    detail = case_detail_payload(slug)
    if detail and detail.get("findings"):
        f0 = detail["findings"][0]
        out.append("Work the first finding: " + str(f0.get("title") or "")[:90])
    if not out:
        out.append("Read the birth article end to end and name "
                   "the first thread to pull")
    return out[:5]


def case_briefing_text(slug, account="operator"):
    """The briefing, composed fresh from the case's live
    state every time it is drawn: what the case was born
    from, what stands on its shelf, its leads and findings,
    its people and machines, its open work — and the tasks
    standing as her proposals. Nothing cached, nothing
    remembered: the case as it stands NOW."""
    detail = case_detail_payload(slug, account)
    if detail is None:
        return None
    name = str(detail.get("name") or slug)
    lines = ["**Briefing — " + name + "**", ""]
    chat = _case_chat_rec_raw(slug, account)
    birth = str((chat or {}).get("birthArticle") or "")
    shelf = case_shelf(slug, account)
    if birth:
        lines.append("Born from the Wire: **" + birth + "**.")
    elif shelf:
        lines.append("Born from the Wire — its first reference "
                     "stands on the shelf.")
    if detail.get("opened"):
        lines.append("Opened " + str(detail["opened"])
                     + " · status " + str(detail.get("status") or "open")
                     + " · type " + str(detail.get("type") or "investigation") + ".")
    lines.append("")
    if shelf:
        lines.append("**On the shelf (" + str(len(shelf)) + "):**")
        for ref in shelf[:8]:
            lines.append("- " + str(ref.get("id") or "") + " — “"
                         + str(ref.get("title") or "")[:100] + "” ("
                         + str(ref.get("source") or "the Wire") + ")")
        lines.append("")
    leads = [f for f in detail.get("findings") or []
             if str(f.get("part") or "") == "lead"
             or str(f.get("state") or "") == "lead"]
    finds = [f for f in detail.get("findings") or [] if f not in leads]
    if leads:
        lines.append("**Leads standing (" + str(len(leads)) + ") — unverified:**")
        for f in leads[:8]:
            lines.append("- " + str(f.get("title") or "")[:130])
        lines.append("")
    if finds:
        lines.append("**Findings (" + str(len(finds)) + "):**")
        for f in finds[:6]:
            lines.append("- " + str(f.get("title") or "")[:130])
        lines.append("")
    for reg, label in (("entities", "Entities"), ("observables", "Observables")):
        ents = detail.get(reg) or []
        if ents:
            lines.append("**" + label + " (" + str(len(ents)) + "):** "
                         + "; ".join(str(e.get("heading") or "")[:60]
                                     for e in ents[:6]))
    tasks = detail.get("tasks") or []
    proposed = [t for t in tasks
                if str((t.get("fields") or {}).get("state") or "") == "proposed"]
    open_tasks = [t for t in tasks
                  if str((t.get("fields") or {}).get("state") or "") != "proposed"
                  and str((t.get("fields") or {}).get("done") or "") != "yes"]
    if open_tasks:
        lines.append("")
        lines.append("**Open tasks (" + str(len(open_tasks)) + "):**")
        for t in open_tasks[:6]:
            lines.append("- " + str(t.get("heading") or "")[:110])
    if proposed:
        lines.append("")
        lines.append("**My recommended next tasks — staged as proposals, "
                     "awaiting your word:**")
        for t in proposed[:6]:
            lines.append("- " + str(t.get("heading") or "")[:110])
        lines.append("")
        lines.append("Approve one and it stands as an open task; dismiss "
                     "one and the strike stands on the record. Both live "
                     "on the case's Tasks register.")
    return "\n".join(lines).strip()


def _chat_append_navi(chat_id, text, extra=None, account="operator"):
    """Append one of her messages to a stored chat — the
    bridge receipt idiom: the room shows it because the
    bridge put it there."""
    for rec in chats_all(account):
        if str(rec.get("id")) == str(chat_id):
            rec = dict(rec)
            msgs = list(rec.get("messages") or [])
            # v0.6.19e (#365): her receipt lines carry a stamp
            # like every other writer's — an unstamped line
            # cannot be ordered against a clear epoch, and the
            # bridge's own handwriting must not be immune to
            # the clear it may one day need to honor.
            msg = {"who": "NAVI", "text": text, "exec": None,
                   "ts": int(time.time() * 1000)}
            if extra:
                msg.update(extra)
            msgs.append(msg)
            rec["messages"] = msgs
            rec["updatedAt"] = int(time.time() * 1000)
            chat_write(rec, account=account)
            return True
    return False


def case_birth_from_wire(link, account="operator"):
    """#330's one act. Returns (result, error): the case
    created from a Wire story, its article shelved whole, a
    cited lead per CVE named, related coverage shelved, the
    case set open, and her briefing — with its staged
    proposals — standing as the case chat's opening word."""
    link = str(link or "").strip()
    item = None
    try:
        item = WIRE.item_for_link(link)
    except Exception:
        item = None
    if not item:
        return None, ("That link is not a story the wire is carrying — "
                      "a case is born from a Wire story, by its link.")
    title = str(item.get("title") or "").strip() or "Wire story"
    source_label = str(item.get("sourceLabel") or item.get("source") or "the Wire")
    got = None
    try:
        got = WIRE.read_article(link)
    except Exception:
        got = None
    article_text = ""
    if got and got.get("ok"):
        article_text = "\n\n".join(got.get("paragraphs") or [])
    excerpt = str(item.get("excerpt") or "")
    detail, err = case_create(
        title[:120], "", "Born from the Wire story: " + title,
        {"type": "investigation",
         "summary": "Opened from the Wire story “" + title + "” ("
                    + source_label + ")."}, account=account)
    if err:
        return None, err
    slug = detail["slug"]
    chat = case_chat_ensure(slug, account)
    chat_id = (chat or {}).get("id")
    # The birth article's identity rides the chat record, so
    # every later briefing can name what the case was born
    # from without a shelf-shape guess.
    rec = _case_chat_rec_raw(slug, account)
    if rec is not None:
        rec = dict(rec)
        rec["birthArticle"] = title
        chat_write(rec, account=account)
    card = {"tab": str(item.get("kind") or "news"), "title": title,
            "link": link, "source": source_label,
            "text": article_text or excerpt}
    ref, note, serr = case_shelf_add(slug, card, by="navi", account=account)
    gaps = []
    if not article_text:
        gaps.append("The article's full text could not be read — "
                    "its excerpt stands on the shelf in its place.")
    leads, cve_gaps, overflow = _birth_cve_leads(
        slug, (article_text or excerpt) + "\n" + title,
        "Named in “" + title + "” (" + source_label + "), read at "
        "the case's birth from the Wire.", account=account)
    gaps += ["The intel catalog has no record for " + g + " — named "
             "here as a gap, not skipped." for g in cve_gaps]
    if overflow:
        gaps.append(str(len(overflow)) + " further CVE id"
                    + ("s" if len(overflow) != 1 else "")
                    + " named in the article stand past the birth "
                    "cap of " + str(BIRTH_CVE_CAP) + ": "
                    + ", ".join(overflow) + ".")
    # Related coverage: the Wire's other STORIES scored
    # against this one's title and text — the standing
    # candidates read, one hop, capped. Two filters keep the
    # shelf honest: only cards that are Wire stories count
    # (the catalog's CVE cards are the leads' ground, not
    # coverage), and a story must share at least one title
    # word with the birth story (the scorer's title weight) —
    # body-word echoes alone do not shelve a story at a birth.
    related = []
    try:
        cands = _wire_card_candidates(title + " " + (article_text or excerpt)[:1200])
        story_links = {str(it.get("link") or "")
                       for it in (WIRE.state().get("items") or [])}
    except Exception:
        cands, story_links = [], set()
    for _score, cand in cands:
        if len(related) >= BIRTH_RELATED_CAP:
            break
        if str(cand.get("link") or "") == link:
            continue
        if str(cand.get("link") or "") not in story_links:
            continue
        if _score < 3:
            continue
        r2, n2, e2 = case_shelf_add(slug, cand, by="navi", account=account)
        if not e2 and n2 == "added":
            related.append({"title": str(cand.get("title") or ""),
                            "link": str(cand.get("link") or "")})
    if _account_clean(account) == "operator":
        _case_set_open(slug)
    case_file_entry(
        slug, "timeline", "Case born from the Wire",
        "Born from “" + title + "” (" + source_label + "): the "
        "article stands on the reference shelf, " + str(len(leads))
        + " cited lead" + ("s" if len(leads) != 1 else "")
        + " filed from the CVEs it names, " + str(len(related))
        + " related stor" + ("ies" if len(related) != 1 else "y")
        + " shelved beside it.", account=account)
    staged = []
    for h in case_recommended_tasks(slug, leads=leads, gaps=cve_gaps,
                                    related=related):
        if case_stage_task(slug, h, "recommended at the case's birth", account):
            staged.append(h)
    briefing = case_briefing_text(slug, account)
    if briefing and chat_id is not None:
        if gaps:
            briefing += ("\n\n**Gaps named at birth:**\n"
                         + "\n".join("- " + g for g in gaps))
        _chat_append_navi(chat_id, briefing, account=account)
    sync_note_write("case")
    return {"slug": slug, "name": detail.get("name") or title,
            "chatId": chat_id, "leads": [ld["id"] for ld in leads],
            "gaps": gaps, "related": related, "staged": staged,
            "shelfRef": (ref or {}).get("id")}, None


_CASE_BIRTH_TRIGGER = re.compile(
    r"(?i)\b(?:start|open|begin|spin up)\s+(?:a\s+|an\s+|the\s+)?"
    r"(?:new\s+)?(?:investigation|case)\b")


def _case_birth_resolve_link(text, chat_id):
    """The article a birth instruction means: a link in the
    words themselves, else the newest Wire link standing in
    this chat's own history, else a quoted title fragment
    matched against the Wire's items."""
    for m in re.findall(r"https?://[^\s\"'<>\)]+", str(text or "")):
        try:
            if WIRE.item_for_link(m):
                return m
        except Exception:
            pass
    if chat_id is not None:
        for rec in chats_all():
            if str(rec.get("id")) == str(chat_id):
                for msg in reversed(rec.get("messages") or []):
                    for m in re.findall(r"https?://[^\s\"'<>\)]+",
                                         str((msg or {}).get("text") or "")):
                        try:
                            if WIRE.item_for_link(m):
                                return m
                        except Exception:
                            pass
                break
    frag = ""
    m = re.search(r"[\"“]([^\"”]{8,})[\"”]", str(text or ""))
    if m:
        frag = m.group(1).strip().lower()
    if frag:
        try:
            for it in (WIRE.state().get("items") or []):
                if frag in str(it.get("title") or "").lower():
                    return str(it.get("link") or "")
        except Exception:
            pass
    return ""


def case_birth_chat_reply(chat_id, text, account="operator"):
    """The words door for #330: 'start an investigation on
    <that story>' in any chat that is not already a case room.
    Returns her reply text, or None when the words are not a
    birth instruction."""
    raw = str(text or "").strip()
    if not raw or not _CASE_BIRTH_TRIGGER.search(raw):
        return None
    if chat_id is not None:
        for rec in chats_all(account):
            if str(rec.get("id")) == str(chat_id) and rec.get("case"):
                return None
    link = _case_birth_resolve_link(raw, chat_id)
    if not link:
        return ("I can start that case — name the Wire story: paste "
                "its link, quote its title, or speak from a chat "
                "where its card stands. A case is born from a "
                "story I can point at, not from a description.")
    result, err = case_birth_from_wire(link, account)
    if err:
        return "The case was not started: " + err
    out = ("Case started: **" + str(result["name"]) + "** — born from "
           "that Wire story. The article stands on its reference "
           "shelf, " + str(len(result["leads"])) + " cited lead"
           + ("s" if len(result["leads"]) != 1 else "")
           + " filed from the CVEs it names, "
           + str(len(result["related"])) + " related stor"
           + ("ies" if len(result["related"]) != 1 else "y")
           + " shelved, and my briefing — with "
           + str(len(result["staged"])) + " recommended task"
           + ("s" if len(result["staged"]) != 1 else "")
           + " staged as proposals — opens its case chat.")
    if result["gaps"]:
        out += " Gaps named at its birth: " + " ".join(result["gaps"])
    return out


def case_brief_chat_reply(chat_id, text, account="operator"):
    """'Brief me' inside a case chat draws a FRESH briefing
    from the case's live state and posts it in the room.
    Returns the briefing text, or None when the words are not
    a briefing ask or this is not a case room."""
    raw = str(text or "").strip()
    if not raw or chat_id is None:
        return None
    if not re.match(r"(?i)^(please\s+)?brief\s+me\b", raw):
        return None
    slug = ""
    for rec in chats_all(account):
        if str(rec.get("id")) == str(chat_id) and rec.get("case"):
            slug = str(rec["case"])
            break
    if not slug:
        return None
    return case_briefing_text(slug, account)


# --- The Dossier (v0.5.6e, #260) --------------------------------
# Apex | Apps -> The Dossier: the people-finding app. One
# dossier, many doors — Person / Username / Email / Phone /
# Photo are keys into the SAME dossier object; runs attach to
# the open dossier, merges are operator acts, and every key,
# source, merge and case inclusion is stored as a TYPED LINK
# on the dossier (links are data from birth — the Web View
# the operator sketched on #260 will have something true to
# draw; that view is NOT built here).
#
# Doctrine (LOWC is the model): public sources, passive
# first, keyless first; anything active crosses the LOWC
# line and is not in this build; EVERY result is cited to
# its source; absence is named exactly — "no public record
# found" — never dressed up; no credential material ever
# (breach PRESENCE only). Where a source cannot be
# machine-read (CAPTCHA-walled registries, paywalled
# records), the runner returns the cited pointer as the
# result — a pointer is a result, stated as one.
#
# Both doors run the same machinery: the page (POST
# /api/dossier) and Navi conversationally (the deterministic
# routes in the chat handler + the context block below).
# Fetched material is untrusted data for her — cited, never
# instructions. Runs are logged either way and show in the
# page's run history.
DOSSIER_PATH = os.path.join(ROOT, "config", "dossier.json")
DOSSIER_KEY_TYPES = ("person", "username", "email", "phone", "photo", "courts", "business", "license", "archive", "address")
DOSSIER_LOCK = threading.Lock()
DOSSIER_RUN_CAP = 300

_DOSSIER_SECRETS = re.compile(
    r"\b(password|passwd|passcode|credential|credentials|"
    r"social\s+security|ssn\b|login\s+details|account\s+password)\b", re.I)


def dossier_fetch(url, timeout=12, cap=400000, data=None,
                  headers=None):
    """The kit's one fetch door — polite, named, and the
    benches' stub point. Returns (status, text, error):
    status None means the door did not answer at all.
    v0.5.15e (#290): a request body, extra headers and a
    larger read cap ride the same door — USAspending asks
    by POST, and the OFAC lists are publications, not
    pages."""
    try:
        hdrs = {"User-Agent": "Apex-Dossier/0.5.6 (public-records "
                              "lookup; operator-initiated)",
                "Accept": "text/html,application/json,*/*"}
        if headers:
            hdrs.update(headers)
        req = urllib.request.Request(url, headers=hdrs, data=data)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read(cap)
            return resp.status, body.decode("utf-8", "replace"), ""
    except urllib.error.HTTPError as e:
        try:
            body = e.read(200000).decode("utf-8", "replace")
        except Exception:
            body = ""
        return e.code, body, ""
    except Exception as e:
        return None, "", str(e)[:160]


def _dossier_store():
    try:
        with open(DOSSIER_PATH, encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            data.setdefault("dossiers", [])
            data.setdefault("runs", [])
            for d in data["dossiers"]:
                if isinstance(d, dict) and "elements" not in d:
                    _dossier_elements_migrate(data, d)
            return data
    except Exception:
        pass
    return {"dossiers": [], "runs": [], "openId": ""}


def _dossier_save(store):
    os.makedirs(os.path.dirname(DOSSIER_PATH), exist_ok=True)
    tmp = DOSSIER_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(store, f, indent=1)
    os.replace(tmp, DOSSIER_PATH)
    # v0.6.4e (#320): the Dossiers shelf stays true on every
    # save — formed documents re-form, and a dossier that left
    # the store (a merge's dropped half, a deletion) loses its
    # shelf file in the same act. Gone means gone.
    try:
        dossier_form_all()
    except Exception:
        pass


def dossier_formed_rel(d, store):
    # A dossier's one file on the Dossiers shelf, named simply
    # for the dossier. Collisions resolve as the cases' do:
    # first by sorted id keeps the plain name.
    safe = _vault_safe_name(d.get("title"), d["id"])
    for other in sorted(store.get("dossiers") or [], key=lambda x: x["id"]):
        if other["id"] >= d["id"]:
            break
        if _vault_safe_name(other.get("title"), other["id"]) == safe:
            return DOSSIERS_FOLDER + "/" + safe + " (" + str(d["id"])[-6:] + ").md"
    return DOSSIERS_FOLDER + "/" + safe + ".md"


def dossier_form_document(d):
    # The dossier's Vault document: its head facts and the
    # document the store derives from its elements — the same
    # text the dossier view shows, standing on the shelf.
    lines = ["# " + str(d.get("title") or "Untitled dossier"), ""]
    facts = []
    if d.get("created"):
        facts.append("- **Opened:** " + str(d["created"]))
    if d.get("updated"):
        facts.append("- **Updated:** " + str(d["updated"]))
    keys = d.get("keys") or []
    if keys:
        facts.append("- **Keys:** " + ", ".join(
            str(k.get("type") or "") + ": " + str(k.get("value") or "")
            for k in keys if isinstance(k, dict)))
    if d.get("caseSlug"):
        facts.append("- **Filed into case:** " + str(d["caseSlug"]))
    facts.append("- **Elements:** " + str(len(d.get("elements") or [])))
    lines += facts + [""]
    body = ""
    if d.get("elements"):
        try:
            body = _dossier_replay_markdown(d["elements"])
        except Exception:
            body = ""
    if not body:
        body = str(d.get("markdown") or "")
    # v0.6.6e (#329): a dossier document whose body opens with
    # the dossier's own title line opens after it — the title
    # stands at the document's head, once.
    body = case_dedupe_opener(str(d.get("title") or ""), body.strip())
    lines += [body.strip() if body.strip() else "No material gathered yet.", ""]
    return "\n".join(lines).rstrip("\n") + "\n"


def dossier_form_all():
    # The Dossiers shelf sweep: form every dossier in the
    # store (writing only when the text actually changed), and
    # prune shelf files no living dossier claims. Run at
    # bridge start and after every store save.
    formed = []
    try:
        store = _dossier_store()
        # v0.8.4e (#472): the vault tombstones judge formation
        # too — a dossier another seat deleted (its tombstone
        # stands in the sync set) is not re-formed here while
        # its record still stands on this seat. A file that
        # stands is left standing for the sync tombstone
        # phase to judge by its own law (a newer local edit
        # still wins there); formation simply never prints
        # over a tombstone.
        try:
            _vault_tombs = ((_sync_state_load().get("tombstones")
                             or {}).get("vault") or {})
        except Exception:
            _vault_tombs = {}
        keep = set()
        for d in store.get("dossiers") or []:
            rel = dossier_formed_rel(d, store)
            keep.add(rel)
            if rel in _vault_tombs:
                continue
            text = dossier_form_document(d)
            full = vault_fs_path(rel)
            cur = None
            try:
                if os.path.isfile(full):
                    with open(full, encoding="utf-8") as f:
                        cur = f.read()
            except Exception:
                cur = None
            if cur != text:
                try:
                    vault_write(rel, text)
                except Exception:
                    continue
            formed.append(rel)
        spot = os.path.join(VAULT_DIR, DOSSIERS_FOLDER)
        if os.path.isdir(spot):
            for name in sorted(os.listdir(spot)):
                if not name.lower().endswith(".md"):
                    continue
                rel = DOSSIERS_FOLDER + "/" + name
                if rel not in keep:
                    vault_delete_note(rel)
    except Exception:
        pass
    return formed


def _dossier_now():
    return time.strftime("%Y-%m-%d %H:%M", time.localtime())


def _dossier_id(prefix):
    return prefix + "-" + hashlib.sha256(
        (prefix + str(time.time()) + os.urandom(8).hex()).encode()
    ).hexdigest()[:12]


def dossier_get(store, dossier_id):
    for d in store["dossiers"]:
        if d["id"] == dossier_id:
            return d
    return None


def dossier_new(store, title):
    d = {"id": _dossier_id("dossier"), "title": str(title or "").strip()
         or "Untitled dossier", "created": _dossier_now(),
         "updated": _dossier_now(), "keys": [], "links": [],
         "runIds": [], "markdown": "", "caseSlug": "",
         "mergedFrom": [], "elements": []}
    store["dossiers"].append(d)
    store["openId"] = d["id"]
    return d


# -- Elements (v0.5.9e, #280) ------------------------------------
# A dossier's content is ELEMENTS: one per run, each with a
# stable identity (the run's id), a kind (the key type that
# produced it), its provenance (key, door, sources, when) and
# its markdown section. The dossier's document is DERIVED —
# the sections joined in order, exactly the append
# dossier_record_run has always performed — so what the view
# shows is what the store holds, and deleting an element
# re-derives the document without it. Dossiers born before
# elements existed are migrated on load: their runs become
# their elements, and any document text no surviving run
# accounts for (a run pruned by the history cap) is carried
# as one "record" element, labeled as what it is.

def _dossier_replay_markdown(elements):
    blob = ""
    for e in elements or []:
        section = str(e.get("markdown") or "").strip()
        if not section:
            continue
        blob = (blob.rstrip("\n") + "\n\n" + section
                + "\n").strip() + "\n"
    return blob


def _dossier_elements_migrate(store, d):
    runs = {r["id"]: r for r in store.get("runs") or []}
    elements = []
    seen = set()
    for rid in d.get("runIds") or []:
        r = runs.get(rid)
        if r is None or rid in seen:
            continue
        seen.add(rid)
        elements.append({
            "id": rid, "kind": str(r.get("keyType") or "record"),
            "key": str(r.get("key") or ""), "at": str(r.get("at") or ""),
            "door": str(r.get("door") or ""),
            "sources": r.get("sources") or [],
            "markdown": str(r.get("markdown") or "")})
    blob = str(d.get("markdown") or "")
    if _dossier_replay_markdown(elements) != blob:
        rest = blob
        for e in elements:
            section = str(e.get("markdown") or "").strip()
            if section and section in rest:
                rest = rest.replace(section, "", 1)
        rest = re.sub(r"\n{3,}", "\n\n", rest).strip()
        if rest:
            elements.append({
                "id": "record-" + hashlib.sha256(
                    d["id"].encode()).hexdigest()[:12],
                "kind": "record", "key": d["title"],
                "at": str(d.get("created") or ""), "door": "record",
                "sources": [], "markdown": rest})
            d["markdown"] = _dossier_replay_markdown(elements)
    d["elements"] = elements
    return d


def dossier_element_label(e):
    return str(e.get("kind") or "record") + ": " + str(e.get("key") or "")


def _dossier_link(d, kind, frm, to, label):
    d["links"].append({"kind": kind, "from": frm, "to": to,
                       "label": label, "at": _dossier_now()})


def _dossier_touch_key(d, key_type, value, door):
    for k in d["keys"]:
        if k["type"] == key_type and k["value"].lower() == value.lower():
            return k
    k = {"type": key_type, "value": value, "door": door,
         "at": _dossier_now()}
    d["keys"].append(k)
    _dossier_link(d, "key", "dossier:" + d["id"],
                  key_type + ":" + value, "opened by the " + key_type
                  + " key (" + door + " door)")
    return k


def dossier_record_run(store, d, run):
    """A finished run lands on its dossier: the markdown
    section is appended to the dossier's own document, the
    sources become typed links, the run joins the history."""
    run["id"] = _dossier_id("run")
    run["dossierId"] = d["id"]
    run["at"] = _dossier_now()
    store["runs"].append(run)
    store["runs"] = store["runs"][-DOSSIER_RUN_CAP:]
    d["runIds"].append(run["id"])
    # v0.5.9e (#280): the run is also the dossier's element —
    # the same act, recorded once, in the shape the view and
    # the delete doors consume.
    d.setdefault("elements", []).append({
        "id": run["id"], "kind": str(run.get("keyType") or "record"),
        "key": str(run.get("key") or ""), "at": run["at"],
        "door": str(run.get("door") or ""),
        "sources": run.get("sources") or [],
        "markdown": str(run.get("markdown") or "")})
    for s in run.get("sources") or []:
        _dossier_link(d, "source", "run:" + run["id"],
                      s.get("url") or s.get("name") or "",
                      (s.get("name") or "source") + " — "
                      + (s.get("verdict") or ""))
    # v0.5.15e (#290): names a run's records carried — a
    # caption's other side, an officer of record — land as
    # ASSOCIATION links: the record named them, the label
    # says where, and the link claims nothing more. They are
    # the pivot proposals' raw material.
    for a in run.get("associations") or []:
        if isinstance(a, dict) and str(a.get("name") or "").strip():
            _dossier_link(d, "association", "dossier:" + d["id"],
                          "person:" + str(a["name"]).strip(),
                          "named on the same record — "
                          + str(a.get("via") or "a record")
                          + " (a lead, not a relationship)")
    section = run.get("markdown") or ""
    if section:
        d["markdown"] = (d["markdown"].rstrip("\n") + "\n\n"
                         + section.strip() + "\n").strip() + "\n"
    d["updated"] = _dossier_now()
    return run


def dossier_merge(store, keep_id, drop_id):
    """The merge is an operator act, receipted: the dropped
    dossier's keys, links, runs and document move into the
    kept one, and the merge itself is a typed link."""
    keep = dossier_get(store, keep_id)
    drop = dossier_get(store, drop_id)
    if keep is None or drop is None:
        return None, "No such dossier to merge."
    if keep is drop:
        return None, "A dossier cannot merge into itself."
    for k in drop["keys"]:
        if not any(x["type"] == k["type"]
                   and x["value"].lower() == k["value"].lower()
                   for x in keep["keys"]):
            keep["keys"].append(k)
    keep["links"].extend(drop["links"])
    keep["runIds"].extend(drop["runIds"])
    for r in store["runs"]:
        if r.get("dossierId") == drop["id"]:
            r["dossierId"] = keep["id"]
    # v0.5.9e (#280): the dropped dossier's elements move with
    # everything else, and the kept document is re-derived
    # from them — the same join the append order produced.
    _kept_ids = {e["id"] for e in keep.get("elements") or []}
    for e in drop.get("elements") or []:
        if e["id"] not in _kept_ids:
            keep.setdefault("elements", []).append(e)
    keep["markdown"] = _dossier_replay_markdown(keep.get("elements"))
    keep["mergedFrom"].append({"id": drop["id"],
                               "title": drop["title"],
                               "at": _dossier_now()})
    _dossier_link(keep, "merge", "dossier:" + drop["id"],
                  "dossier:" + keep["id"],
                  "operator merge: '" + drop["title"]
                  + "' folded into '" + keep["title"] + "'")
    keep["updated"] = _dossier_now()
    store["dossiers"] = [d for d in store["dossiers"]
                         if d["id"] != drop["id"]]
    if store.get("openId") == drop["id"]:
        store["openId"] = keep["id"]
    return keep, None


